def from_clause(cls, clause):
        """ Factory method """
        [field, vals] = clause
        return cls(field, resolve(vals))

def from_clause(cls, clause):
        """ Factory method """
        if isinstance(clause, cls):
            return clause
        elif isinstance(clause, str):
            return cls(clause)
        elif isinstance(clause, (list, tuple)):
            return cls(*clause)
        else:
            raise TypeError("Invalid type for clause: %s" % type(clause))

