def extended(self, new_leaves: List[bytes]):
        """Returns a new tree equal to this tree extended with new_leaves."""
        if len(new_leaves) == 0:
            return self
        if len(new_leaves) == 1:
            return self.extended_by_one(new_leaves[0])
        return self.extended_by_many(new_leaves)

