def _clear_interrupt(self, intbit):
        """Clear the specified interrupt bit in the interrupt status register.
        """
        int_status = self._device.readU8(VCNL4010_INTSTAT);
        int_status &= ~intbit;
        self._device.write8(VCNL4010_INTSTAT, int_status);

