def decode(col, charset):
    """
    Computes the first argument into a string from a binary using the provided character set
    (one of 'US-ASCII', 'ISO-8859-1', 'UTF-8', 'UTF-16BE', 'UTF-16LE', 'UTF-16').
    """
    if charset == 'US-ASCII':
        return col.decode('US-ASCII')
    elif charset == 'ISO-8859-1':
        return col.decode('ISO-8859-1')
    elif charset == 'UTF-8':
        return col.decode('UTF-8')
    elif charset == 'UTF-16BE':
        return col.decode('UTF-16BE')
    elif charset == 'UTF-16LE':
        return col.decode('UTF-16LE')
    else:
        raise ValueError('Invalid charset: {}'.format(charset))

