def similar(obj1, obj2):
    """Calculate similarity between two (Comparable) objects."""
    if not isinstance(obj1, type(obj2)):
        raise TypeError("Cannot compare objects of different types.")
    if not isinstance(obj1, Comparable):
        raise TypeError("Cannot compare objects that are not Comparable.")
    return obj1.similarity(obj2)

