def str2rsi(key):
    """
    Convert a string of the form 'rlz-XXXX/sid-YYYY/ZZZ'
    into a triple (XXXX, YYYY, ZZZ)
    """
    if key.startswith('rlz-'):
        key = key[4:]
    if key.startswith('sid-'):
        key = key[4:]
    if key.startswith('ZZZ'):
        key = key[3:]
    return key.split('/')

