def _GetPurgeMessage(most_recent_step, most_recent_wall_time, event_step,
                     event_wall_time, num_expired):
  """Return the string message associated with TensorBoard purges."""
  if event_step is None:
    event_step = most_recent_step
  if event_wall_time is None:
    event_wall_time = most_recent_wall_time
  return (
      'Purged %d events from TensorBoard. '
      'Most recent event was step %d at %s. '
      'Purged event was step %d at %s.' %
      (num_expired, event_step, event_wall_time,
       most_recent_step, most_recent_wall_time))

