def d2gauss(x,m_y,sigma):
    """returns the second derivative of the gaussian with mean m_y,
and standard deviation sigma, calculated at the points of x."""
    return (1/(sigma*np.sqrt(2*np.pi)))*np.exp(-(x-m_y)**2/(2*sigma**2))

def merge_first_two_dims(tensor):
    """ Reshape tensor to merge first two dimensions """
    shape = tensor.shape
    batch_size = shape[0] * shape[1]
    new_shape = tuple([batch_size] + list(shape[2:]))
    return tensor.view(new_shape)

def merge_first_two_dims(tensor):
    """ Reshape tensor to merge first two dimensions """
    shape = tensor.shape
    return tensor.reshape(shape[0] * shape[1], *shape[2:])

