def reduce_l1(attrs, inputs, proto_obj):
    """Reduce input tensor by l1 normalization."""
    if len(inputs) != 1:
        raise ValueError("L1 normalization only supports one input.")
    if len(attrs) != 1:
        raise ValueError("L1 normalization only supports one attribute.")
    axis = attrs[0]
    if not isinstance(axis, int):
        raise ValueError("L1 normalization only supports integer axis.")
    if axis < 0:
        raise ValueError("L1 normalization only supports non-negative axis.")
    return [tf.math.reduce_sum(tf.math.abs(inputs[0]), axis=axis)]

def drop_primary_key(self, table):
