def _set_vibration_win(self, left_motor, right_motor, duration):
        """Control the motors on Windows."""
        if left_motor == 0:
            left_motor = 0
        elif left_motor == 1:
            left_motor = 1
        else:
            left_motor = 2

        if right_motor == 0:
            right_motor = 0
        elif right_motor == 1:
            right_motor = 1
        else:
            right_motor = 2

        if duration == 0:
            duration = 0
        elif duration == 1:
            duration = 1
        else:
            duration = 2

        self.vibration_win.leftMotor = left_motor
        self.vibration_win.rightMotor = right_motor
        self.vibration_win.duration = duration

