def pad(text, length):
    """Pads text to given length, taking into account wide characters."""
    text_length = wcswidth(text)

    if text_length < length:
        return text + ' ' * (length - text_length)

    return text

def pad(text, length):
    """Pads text to given length, taking into account wide characters."""
    if len(text) >= length:
        return text
    else:
        return text + (length - len(text)) * ' '

