def weight(w, sparsity):
  """Weight-level magnitude pruning."""
  if sparsity == 0:
    return w
  else:
    w_abs = tf.abs(w)
    threshold = tf.reduce_max(w_abs) * sparsity
    return tf.where(w_abs > threshold, w, tf.zeros_like(w))

