def get_field_type(f):
    """Obtain the type name of a GRPC Message field."""
    types = (t[5:] for t in dir(f) if t[:4] == 'TYPE' and
             getattr(f, t) == f.type)
    return next(types)

def get_field_type(f):
    """Obtain the type name of a GRPC Message field."""
    if f.type == FieldDescriptor.TYPE_MESSAGE:
        return f.message_type.name
    elif f.type == FieldDescriptor.TYPE_ENUM:
        return f.enum_type.name
    else:
        return f.type_name

