def compare_3PC_keys(key1, key2) -> int:
    """
    Return >0 if key2 is greater than key1, <0 if lesser, 0 otherwise
    """
    if key1[0] == key2[0]:
        return key2[1] - key1[1]
    else:
        return key2[0] - key1[0]

def compare_3PC_keys(key1, key2) -> int:
    """
    Return >0 if key2 is greater than key1, <0 if lesser, 0 otherwise
    """
    if key1[0] != key2[0]:
        return key1[0] - key2[0]
    else:
        return key1[1] - key2[1]

def to_unicode(text):
    """
    Return *text* as a unicode string. All text in Python 3 is unicode, so
    this just returns *text* unchanged.
    """
    if isinstance(text, str):
        return text
    else:
        return text.decode('utf-8')

def now(cls, tzinfo=None):
    """[tz] -> new datetime with tz's local day and time."""
    obj = cls.utcnow()
    if tzinfo is None:
      tzinfo = localtz()
    return obj.astimezone(tzinfo)

def now(cls, tzinfo=None):
    """[tz] -> new datetime with tz's local day and time."""
    if tzinfo is None:
        tzinfo = cls.local_tz
    return cls.combine(cls.now(tzinfo), cls.local_time(tzinfo))

