def _compute_magnitude(self, rup, C):
        """
        Compute the first term of the equation described on p. 199:

        ``b1 + b2 * M + b3 * M**2``
        """
        return C['b1'] + (C['b2'] * rup.mag) + (C['b3'] * (rup.mag ** 2))

def decensor_iter(posts_info: Iterable[dict], site_url: str = DEFAULT_SITE
                 ) -> Generator[dict, None, None]:
    """Apply decensoring on an iterable of posts info dicts from Danbooru API.
    Any censored post is automatically decensored if needed."""
    for info in posts_info:
        yield decensor(info, site_url)

def decensor_iter(posts_info: Iterable[dict], site_url: str = DEFAULT_SITE
                 ) -> Generator[dict, None, None]:
    """Apply decensoring on an iterable of posts info dicts from Danbooru API.
    Any censored post is automatically decensored if needed."""
    for post_info in posts_info:
        if post_info['censored']:
            post_info['file_url'] = decensor_url(post_info['file_url'], site_url)
            post_info['preview_url'] = decensor_url(post_info['preview_url'], site_url)
            post_info['censored'] = False
        yield post_info

