def union(*argv):
        """Returns union of sets as a new set. basically it's
        Items are ordered by set1, set2, ...

        **中文文档**

        求多个有序集合的并集, 按照第一个集合, 第二个, ..., 这样的顺序。
        """
        if len(argv) == 0:
            return set()
        if len(argv) == 1:
            return argv[0]
        if len(argv) == 2:
            return argv[0] | argv[1]
        return union(*(argv[0] | argv[1]), *argv[2:])

