def str(self,local=False,ifempty=None):
        """ Returns the string representation of the datetime
        """
        ts = self.get(local)
        if not ts: return ifempty
        return ts.strftime('%Y-%m-%d %H:%M:%S')

def str(self,local=False,ifempty=None):
        """ Returns the string representation of the datetime
        """
        if self.isempty():
            if ifempty is None:
                return ''
            else:
                return ifempty
        if local:
            return self.dt.strftime(self.format)
        else:
            return self.dt.astimezone(pytz.utc).strftime(self.format)

def str_def(self):
