def list(self, search_opts=None, limit=None,
             marker=None, sort_by=None, reverse=None):
        """Get a list of Jobs."""
        if search_opts is None:
            search_opts = {}

        qparams = {}

        if limit:
            qparams['limit'] = min(limit, CONF.api.max_limit)
        if marker:
            qparams['marker'] = marker
        if sort_by:
            qparams['sort_by'] = sort_by
        if reverse:
            qparams['reverse'] = reverse

        path = '/jobs'

        if qparams:
            path += '?%s' % urllib.urlencode(qparams)

        return self._list(path, 'jobs')

