def iuniq(ible):
    """Get an iterator over unique items of `ible`."""
    items = set()
    for item in ible:
        if item not in items:
            items.add(item)
            yield item

def iuniq(ible):
    """Get an iterator over unique items of `ible`."""
    seen = set()
    for item in ible:
        if item not in seen:
            seen.add(item)
            yield item

def gaussian(self, x, p):
        """Gaussian fitting function in 1D.  Makes a sine function with
        amplitude determined by maxv.  See calc_fwhm().

        p[0]==mean, p[1]==sdev, p[2]=maxv
        """
        return p[2] * np.exp(-(x - p[0])**2 / (2 * p[1]**2))

