def cartesian_lists(d):
    """
    turns a dict of lists into a list of dicts that represents
    the cartesian product of the initial lists

    Example
    -------
    cartesian_lists({'a':[0, 2], 'b':[3, 4, 5]}
    returns
    [ {'a':0, 'b':3}, {'a':0, 'b':4}, ... {'a':2, 'b':5} ]

    """
    if len(d) == 1:
        return [dict([(k, v[i]) for k, v in d.items()]) for i in range(len(d[list(d.keys())[0]]))]
    else:
        return [dict([(k, v[i]) for k, v in d.items()]) for i in range(len(d[list(d.keys())[0]]))] + cartesian_lists({k: v for k, v in d.items() if k != list(d.keys())[0]})

