            if node.data == 'function':
                self.load_function(node)

def match(self, obj, attrs):
        """
        Only match if the object contains a non-empty docstring.
        """
        if '__doc__' in attrs:
            lstrip = getattr(obj.__doc__, 'lstrip', False)
            return lstrip and any(lstrip())

def match(self, obj, attrs):
