def Timestamp():
    """ Get the current datetime in UTC """
    return datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")

def split_pdb_residue(s):
    """Splits a PDB residue into the numeric and insertion code components."""
    if s.isdigit():
        return (int(s), ' ')
    else:
        assert(s[:-1].isdigit())
        return ((s[:-1], s[-1]))

def split_pdb_residue(s):
    """Splits a PDB residue into the numeric and insertion code components."""
    if s[0].isdigit():
        return s[0], s[1:]
    else:
        return s[0], ''

def _clear_dict(endpoint_props):
    """
    Eliminates None entries from the features of the endpoint dict.
    """
    return dict(
        (prop_name, prop_val)
        for prop_name, prop_val in six.iteritems(endpoint_props)
        if prop_val is not None
    )

def _clear_dict(endpoint_props):
    """
    Eliminates None entries from the features of the endpoint dict.
    """
    for key, value in endpoint_props.items():
        if value is None:
            endpoint_props.pop(key)

def _add_to_docstring(string):
    """Private wrapper function. Appends ``string`` to the
    docstring of the wrapped function.

    """
    def wrapper(method):
        if method.__doc__ is not None:
            method.__doc__ += string
        else:
            method.__doc__ = string
        return method
    return wrapper

def match(self, *args):
        """Whether or not to enter a given case statement"""
        if len(args) == 1:
            return self.value == args[0]
        elif len(args) == 2:
            return self.value >= args[0] and self.value <= args[1]
        else:
            raise ValueError("Invalid number of arguments")

def cancel(self):
        """Cancel a long-running transaction.

        If the underlying driver supports this method, it will be called.

        """
        self._transaction = False
        try:
            cancel = self._con.cancel
        except AttributeError:
            pass
        else:
            cancel()

