def verifyCert(self, cert):
        """ Verifies either a Cert or an X509_Cert. """
        if isinstance(cert, X509_Cert):
            return self.verifyCert(cert.cert)
        elif isinstance(cert, Cert):
            return self.verifyCert(cert.cert)
        else:
            raise TypeError("verifyCert() requires a Cert or an X509_Cert")

