def _action_enabled(self, event, action):
        """Check if an action for a notification is enabled."""
        event_actions = self._aconfig.get(event)
        if event_actions is None:
            return True
        if event_actions is False:
            return False
        return action in event_actions

def _action_enabled(self, event, action):
        """Check if an action for a notification is enabled."""
        if action.get('enabled') is False:
            return False

        if action.get('when') == 'always':
            return True

        if action.get('when') == 'never':
            return False

        if action.get('when') == 'failed' and event.get('failed') is True:
            return True

        if action.get('when') == 'success' and event.get('failed') is False:
            return True

        return False

def evaluate(self, verbose=False, decode=True, passes=None, num_threads=1, apply_experimental=True):
        """Evaluates by creating an Index containing evaluated data.

        See `LazyResult`

        Returns
        -------
        Index
            Index with evaluated data.

        """
        if passes is None:
            passes = self.passes
        if num_threads == 1:
            return self._evaluate_single_thread(verbose, decode, passes)
        else:
            return self._evaluate_multi_thread(verbose, decode, passes, num_threads)

def flush(self):
        """
        Flush input buffers.
        """
        if self.debug:
            sys.stderr.write("%s: FLUSH INPUT (%i bytes waiting)\n" %(
                    self.__class__.__name__,
                    self.ser.inWaiting()
                    ))
        self.ser.flushInput()

