def _find_library(lib, path):
    """Find a library"""
    for d in path[::-1]:
        real_lib = os.path.join(d, lib)
        if os.path.exists(real_lib):
            return real_lib

def _find_library(lib, path):
    """Find a library"""
    for p in path:
        f = os.path.join(p, lib)
        if os.path.exists(f):
            return f
    return None

def any2utf8(text, errors='strict', encoding='utf8'):
    """Convert a string (unicode or bytestring in `encoding`), to bytestring in utf8."""
    if isinstance(text, unicode):
        return text.encode('utf8')
    # do bytestring -> unicode -> utf8 full circle, to ensure valid utf8
    return unicode(text, encoding, errors=errors).encode('utf8')

def any2utf8(text, errors='strict', encoding='utf8'):
    """Convert a string (unicode or bytestring in `encoding`), to bytestring in utf8."""
    if isinstance(text, unicode):
        return text.encode('utf8')
    elif isinstance(text, bytes):
        return text
    else:
        raise TypeError('not expecting type %s' % type(text))

def to_bytes(s, encoding="utf8"):
    """Converts str s to bytes"""
    if PY_VERSION == 2:
        b = bytes(s)
    elif PY_VERSION == 3:
        b = bytes(s, encoding)
    else:
        raise ValueError("Is Python 4 out already?")

    return b

def to_bytes(s, encoding="utf8"):
    """Converts str s to bytes"""
    if isinstance(s, bytes):
        return s
    return s.encode(encoding)

