def _strip_counters(self, sub_line):
        """Find the codeline end by taking out the counters and durations."""
        try:
            end = sub_line.rindex('}')
        except ValueError:
            return sub_line
        else:
            return sub_line[:(end + 1)]

def _strip_counters(self, sub_line):
        """Find the codeline end by taking out the counters and durations."""
        if sub_line.startswith('('):
            sub_line = sub_line[1:]
        if sub_line.endswith(')'):
            sub_line = sub_line[:-1]
        return sub_line

def insert(self, index, value):
        """
        Insert *value* into the collection at *index*.
        """
        if index == 0:
            return self._insert_left(value)

        def insert_middle_trans(pipe):
            self._insert_middle(index, value, pipe=pipe)

        return self._transaction(insert_middle_trans)

