                return True
        return False

def expose(url_rule, endpoint=None, **kwargs):
    """Expose this function to the web layer."""
    if endpoint is None:
        endpoint = url_rule

    def decorator(f):
        """Decorator function."""
        if not hasattr(f, 'exposed'):
            f.exposed = True
            f.url_rule = url_rule
            f.endpoint = endpoint
            f.kwargs = kwargs

        return f

    return decorator

