def _path_hash(path, transform, kwargs):
    """
    Generate a hash of source file path + transform + args
    """
    return hashlib.md5(
        "{}{}{}".format(path, transform, json.dumps(kwargs)).encode("utf-8")
    ).hexdigest()

def _load_url(url):
    """
    Loads a URL resource from a remote server
    """
    try:
        response = requests.get(url)
        return BytesIO(response.content)
    except IOError as ex:
        parser.error("{url} could not be loaded remotely! ({ex})".format(url=url, ex=ex))

def _load_url(url):
    """
    Loads a URL resource from a remote server
    """
    try:
        return urllib.request.urlopen(url).read()
    except urllib.error.HTTPError as e:
        print("HTTP Error:", e.code, url)
        return None
    except urllib.error.URLError as e:
        print("URL Error:", e.reason, url)
        return None

