def _chk_hdrgoids(hdrgos):
        """Check that hdrgo set is a set of GO IDs."""
        goid = next(iter(hdrgos))
        if isinstance(goid, str) and goid[:3] == "GO:":
            return
        assert False, "HDRGOS DO NOT CONTAIN GO IDs: {E}".format(E=goid)

def _chk_hdrgoids(hdrgos):
        """Check that hdrgo set is a set of GO IDs."""
        if not isinstance(hdrgos, set):
            raise TypeError("hdrgos must be a set of GO IDs")
        for goid in hdrgos:
            if not isinstance(goid, str):
                raise TypeError("hdrgos must be a set of GO IDs")
            if not re.match(r"GO:\d+", goid):
                raise ValueError("hdrgos must be a set of GO IDs")

