def permission_set(self, name, func=None):
        """Define a new permission set (directly, or as a decorator).

        E.g.::

            @authz.permission_set('HTTP')
            def is_http_perm(perm):
                return perm.startswith('http.')

        """
        if func is None:
            return functools.partial(self.predicate, name)
        self.permission_sets[name] = func
        return func

def permission_set(self, name, func=None):
        """Define a new permission set (directly, or as a decorator).

        E.g.::

            @authz.permission_set('HTTP')
            def is_http_perm(perm):
                return perm.startswith('http.')

        """
        if func is None:
            return lambda func: self.permission_set(name, func)
        self.permission_sets[name] = func

def lnprior(self, X):
        """
        Use a uniform, bounded prior.
        """
        if np.any(X < self._lower_left) or np.any(X > self._upper_right):
            return -np.inf
        else:
            return 0.0

def key(
        seq: Sequence,
        tooth: Callable[[Sequence], str] = (
            lambda seq: str(random.SystemRandom().choice(seq)).strip()
        ),
        nteeth: int = 6,
        delimiter: str = ' ',
) -> str:
    """Concatenate strings generated by the tooth function."""
    return delimiter.join(tooth(seq) for _ in range(nteeth))

