def _get_css_classes(self, ttype):
        """Return the css classes of this token type prefixed with
        the classprefix option."""
        css_classes = []
        if ttype in self.css_classes:
            css_classes.append(self.css_classes[ttype])
        if ttype in self.css_classes_extra:
            css_classes.extend(self.css_classes_extra[ttype])
        if self.classprefix:
            css_classes = [self.classprefix + c for c in css_classes]
        return css_classes

