def delete_by_external_id(self, api_objects):
        """
        Delete (DELETE) one or more API objects by external_id.

        :param api_objects:
        """
        if not isinstance(api_objects, list):
            api_objects = [api_objects]

        for api_object in api_objects:
            if not isinstance(api_object, self.api_object_class):
                raise TypeError(
                    "api_objects must be a list of {0} objects".format(
                        self.api_object_class.__name__
                    )
                )

            if not api_object.external_id:
                raise ValueError(
                    "api_objects must have an external_id set"
                )

            self.delete_by_external_id_single(api_object)

