def _check_warn_threshold(self, time_to, event_dict):
        """
        Checks if the time until an event starts is less than or equal to the
        warn_threshold. If True, issue a warning with self.py3.notify_user.
        """
        if time_to <= self.warn_threshold:
            self.py3.notify_user(
                "{} starts in {}".format(event_dict['summary'], time_to),
                self.format.format(time_to=time_to, **event_dict)
            )

def length_at(self, depth):
        """Get the number of nodes on specific depth.
        """
        if depth == 0:
            return 1

        counter = 0
        for dict_tree in self.values_at(depth - 1):
            counter += len(dict_tree)
        return counter

def length_at(self, depth):
        """Get the number of nodes on specific depth.
        """
        if depth == 0:
            return 1
        else:
            return 2 * self.length_at(depth - 1) - 1

