def _cql_from_cass_type(cass_type):
    """
    A string representation of the type for this column, such as "varchar"
    or "map<string, int>".
    """
    if issubclass(cass_type, types.ReversedType):
        return cass_type.subtypes[0].cql_parameterized_type()
    else:
        return cass_type.cql_parameterized_type()

def _cql_from_cass_type(cass_type):
    """
    A string representation of the type for this column, such as "varchar"
    or "map<string, int>".
    """
    if cass_type.is_collection:
        return "list<{}>".format(_cql_from_cass_type(cass_type.value_type))
    elif cass_type.is_user_defined:
        return "map<string, {}>".format(_cql_from_cass_type(cass_type.value_type))
    elif cass_type.is_frozen:
        return "frozen<{}>".format(_cql_from_cass_type(cass_type.value_type))
    elif cass_type.is_tuple:
        return "tuple<{}>".format(
            ", ".join(_cql_from_cass_type(cass_type.value_types[i]) for i in range(len(cass_type.value_types)))
        )
    elif cass_type.is_udt:
        return "{}".format(cass_type.keyspace_name, cass_type.user_type_name)
    else:
        return cass_type.name

