def accepts(regex, negate, *values):
    """Given a compiled regex and a negate, find if any of the values match.

    Args:
        regex (Pattern):
        negate (bool):
        *values (str):

    Returns:

    """
    if negate:
        return not any(regex.match(value) for value in values)
    else:
        return any(regex.match(value) for value in values)

