def subtractprivkeys(p1,p2):
    """
    Input must be 64-char hex string
    """

    return dechex(((int(p1,16) + (N - int(p2,16))) % N),32)

def find_subdomains(domain):
    """Find subdomains according to the TLD."""
    result = set()
    response = get('https://findsubdomains.com/subdomains-of/' + domain).text
    matches = findall(r'(?s)<div class="domains js-domain-name">(.*?)</div>', response)
    for match in matches:
        result.add(match.replace(' ', '').replace('\n', ''))
    return list(result)

def find_subdomains(domain):
    """Find subdomains according to the TLD."""
    subdomains = []
    for tld in TLD_LIST:
        if tld in domain:
            subdomains.append(domain.replace(tld, ''))
    return subdomains

def rotated(self, rotation_center, angle):
        """Returns a RotatedBox that is obtained by rotating this box around a given center by a given angle.

        >>> assert RotatedBox([2, 2], 2, 1, 0.1).rotated([1, 1], np.pi/2).approx_equal([0, 2], 2, 1, np.pi/2+0.1)
        """
        return RotatedBox(self.center, self.length, self.width, self.angle + angle, rotation_center)

def list_vpnservices(retrieve_all=True, profile=None, **kwargs):
    """
    Fetches a list of all configured VPN services for a tenant

    CLI Example:

    .. code-block:: bash

        salt '*' neutron.list_vpnservices

    :param retrieve_all: True or False, default: True (Optional)
    :param profile: Profile to build on (Optional)
    :return: List of VPN service
    """
    if profile:
        _profile = __salt__["config.beacons"](profile)
        if "neutron" in _profile:
            _profile = _profile["neutron"]
        else:
            return {}
        if "auth" in _profile:
            _profile = _profile["auth"]
        else:
            return {}
        if "username" in _profile:
            kwargs["username"] = _profile["username"]
        if "password" in _profile:
            kwargs["password"] = _profile["password"]
        if "auth_url" in _profile:
            kwargs["auth_url"] = _profile["auth_url"]
        if "project_name" in _profile:
            kwargs["project_name"] = _profile["project_name"]
        if "user_domain_name" in _profile:
            kwargs["user_domain_name"] = _profile["user_domain_name"]
        if "project_domain_name" in _profile:
            kwargs["project_domain_name"] = _profile["project_domain_name"]
        if "insecure" in _profile:
            kwargs["insecure"] = _profile["insecure"]
        if "ca_cert" in _profile:
            kwargs["ca_cert"] = _profile["ca_cert"]
    return __salt__["neutron.list_vpnservices"](retrieve_all, **kwargs)

