        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        for key in dict_path.split('.'):
            if key in metrics_json:
                metrics_json = metrics_json.get(key)
            else:
                return None
        return metrics_json

def logical_not_expr(self):
        """
        logical_not_expr: 'not' logical_not_expr
                        | comparison
        """
        if self.token.nature == Nature.NOT:
            token = self.token
            self._process(Nature.NOT)
            return UnaryOperation(op=token, right=self.logical_not_expr())
        else:
            return self.comparison()

def logical_not_expr(self):
        """
        logical_not_expr: 'not' logical_not_expr
                        | comparison
        """
        if self.token.type == 'not':
            self.next_token()
            return ast.UnaryOp(ast.Not(), self.logical_not_expr())
        else:
            return self.comparison()

