        around."""
        return {v: k for k, v in subj_dict.items()}

def wav_length(fn: str) -> float:
    """ Returns the length of the WAV file in seconds."""
    with wave.open(fn, 'r') as f:
        frames = f.getnframes()
        rate = f.getframerate()
        return frames / float(rate)

