    CLI Example:

    .. code-block:: bash

        salt '*' pyenv.install
    """
    if path is None:
        path = _pyenv_root()

    cmd = "PYENV_ROOT={0} pyenv install".format(path)
    if runas:
        cmd = "su - {0} -c '{1}'".format(runas, cmd)

    return __salt__["cmd.run_all"](cmd)

