def get_pubmed_citation_response(pubmed_identifiers: Iterable[str]):
    """Get the response from PubMed E-Utils for a given list of PubMed identifiers.

    :param pubmed_identifiers:
    :rtype: dict
    """
    pubmed_identifiers = list(pubmed_identifiers)
    if not pubmed_identifiers:
        return {}

    url = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
    params = {
        'db': 'pubmed',
        'id': ','.join(pubmed_identifiers),
        'retmode': 'json',
        'rettype': 'abstract',
        'tool': 'pubmed_citation_response',
    }
    response = requests.get(url, params=params)
    response.raise_for_status()
    return response.json()

def populate_class_members(self, element_cls, prop_name):
        """
        Add the appropriate methods to *element_cls*.
        """
        super(ZeroOrOneChoice, self).populate_class_members(
            element_cls, prop_name
        )
        self._add_choice_getter()
        for choice in self._choices:
            choice.populate_class_members(
                element_cls, self._prop_name, self._successors
            )
        self._add_group_remover()

def populate_class_members(self, element_cls, prop_name):
        """
        Add the appropriate methods to *element_cls*.
        """
        # Add the property getter.
        def getter(self):
            return self._get_property(prop_name)
        setattr(element_cls, prop_name, property(getter))

        # Add the property setter.
        def setter(self, value):
            self._set_property(prop_name, value)
        setattr(element_cls, prop_name + '=', setter)

def pop(self):
        """Removes the topmost item from the stack, will return the
        old value or `None` if the stack was already empty.
        """
        stack = getattr(self._local, "stack", None)
        if stack is None:
            return None
        elif len(stack) == 1:
            release_local(self._local)
            return stack[-1]
        else:
            return stack.pop()

def pop(self):
        """Removes the topmost item from the stack, will return the
        old value or `None` if the stack was already empty.
        """
        if self.is_empty():
            return None
        else:
            self.size -= 1
            return self.data[self.size]

def run(self):
        """Run the callback periodically"""
        while not self.wait(self.delay()):
            try:
                logger.info('Invoking callback %s', self.callback)
                self.callback()
            except StandardError:
                logger.exception('Callback failed')

def run(self):
        """Run the callback periodically"""
        while True:
            self.callback()
            time.sleep(self.interval)

def dimensions(filenames):
    """given a filename or list of filenames,
    return a tuple or sequence of tuples (x, y, filename)"""

    single = type(filenames) is str
    if single:
        filenames = [filenames]
    dims = get_dimensions(filenames)
    if single:
        dims = dims[0]
    return dims

def dimensions(filenames):
    """given a filename or list of filenames,
    return a tuple or sequence of tuples (x, y, filename)"""
    if isinstance(filenames, str):
        filenames = [filenames]
    return [(im.size[0], im.size[1], f) for f in filenames for im in [Image.open(f)]]

