def add(self, coro, args=(), kwargs={}, first=True):
        """Add a coroutine in the scheduler. You can add arguments
        (_args_, _kwargs_) to init the coroutine with."""
        assert callable(coro), "'%s' not a callable object" % coro
        coro = coro(*args, **kwargs)
        if first:
            self.active.append( (None, coro) )
        else:
            self.active.appendleft( (None, coro) )
        return coro

def add(self, coro, args=(), kwargs={}, first=True):
        """Add a coroutine in the scheduler. You can add arguments
        (_args_, _kwargs_) to init the coroutine with."""
        if first:
            self.coros = [coro]
        else:
            self.coros.append(coro)
        self.args.append(args)
        self.kwargs.append(kwargs)

def emphasis_sub(match):
    """Substitutes <strong>, <em>, and <strong><em> tags."""
    level = len(match.group(1))
    content = match.group(2)
    if level == 3:
        return '<strong><em>{0}</em></strong>'.format(content)
    elif level == 2:
        return '<strong>{0}</strong>'.format(content)
    elif level == 1:
        return '<em>{0}</em>'.format(content)

def emphasis_sub(match):
    """Substitutes <strong>, <em>, and <strong><em> tags."""
    match = match.group(1)
    if match.startswith('<strong>'):
        return '<b>' + emphasis_sub(match[8:]) + '</b>'
    elif match.startswith('<em>'):
        return '<i>' + emphasis_sub(match[4:]) + '</i>'
    elif match.startswith('<strong><em>'):
        return '<b><i>' + emphasis_sub(match[12:]) + '</i></b>'
    else:
        return match

