def set_port_info(self, webport, mediaport, httpsport,
                                      onvifport, callback=None):
        """
        Set http port and media port of camera.
        """
        if not self.is_connected:
            raise Exception("Camera is not connected.")

        if not isinstance(webport, int):
            raise Exception("Web port must be an integer.")
        if not isinstance(mediaport, int):
            raise Exception("Media port must be an integer.")
        if not isinstance(httpsport, int):
            raise Exception("Https port must be an integer.")
        if not isinstance(onvifport, int):
            raise Exception("Onvif port must be an integer.")

        if webport < 0 or webport > 65535:
            raise Exception("Web port must be between 0 and 65535.")
        if mediaport < 0 or mediaport > 65535:
            raise Exception("Media port must be between 0 and 65535.")
        if httpsport < 0 or httpsport > 65535:
            raise Exception("Https port must be between 0 and 65535.")
        if onvifport < 0 or onvifport > 65535:
            raise Exception("Onvif port must be between 0 and 65535.")

        if callback is None:
            callback = self.default_callback

        self.send_request(
            "set_port_info",
            {
                "web_port": webport,
                "media_port": mediaport,
                "https_port": httpsport,
                "onvif_port": onvifport
            },
            callback
        )

def delete_many(self, uris):
        """
        Simple implementation,
        could be better implemented by backend not hitting db for every uri.
        """
        deleted_nodes = {}

        for uri in uris:
            node = self.delete(uri)
            if node:
                deleted_nodes[uri] = node

        return deleted_nodes

