def handle(cls, value, context, **kwargs):
        """Returns the value of a key for a given hook in hook_data.

        Format of value:

            <hook_name>::<key>
        """
        hook_name, key = value.split('::')
        hook_data = context.hook_data.get(hook_name)
        if not hook_data:
            raise ValueError('No hook data found for hook %s' % hook_name)
        return hook_data.get(key)

