def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    matching_parameters = filter_parameters(parameters, **kwargs)
    if len(matching_parameters) == 1:
        return matching_parameters[0]
    elif len(matching_parameters) > 1:
        raise MultipleParametersFound()
    raise NoParameterFound()

def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    for parameter in parameters:
        if parameter.name == kwargs['name']:
            return parameter

    return None

def _write_values(kwargs, variables):
    """Write values of kwargs and return thus-satisfied closures."""
    writeto = []
    for var_name, value in kwargs.items():
        var = variables[var_name]
        var.notify_will_write()
        var.write(value)
        writeto.append(var)
    return _notify_reader_writes(writeto)

def _write_values(kwargs, variables):
    """Write values of kwargs and return thus-satisfied closures."""
    closures = []
    for key, value in kwargs.items():
        if key in variables:
            closures.append(variables[key].set(value))
    return closures

async def _set_greeting_text(self):
        """
        Set the greeting text of the page
        """

        page = self.settings()

        if 'greeting' in page:
            await self._send_to_messenger_profile(page, {
                'greeting': page['greeting'],
