def fsplit(pred, objs):
    """Split a list into two classes according to the predicate."""
    t = []
    f = []
    for obj in objs:
        if pred(obj):
            t.append(obj)
        else:
            f.append(obj)
    return (t, f)

def fsplit(pred, objs):
    """Split a list into two classes according to the predicate."""
    return [o for o in objs if pred(o)], [o for o in objs if not pred(o)]

