def QA_util_to_json_from_pandas(data):
    """需要对于datetime 和date 进行转换, 以免直接被变成了时间戳"""
    if 'datetime' in data.columns:
        data.datetime = data.datetime.apply(str)
    if 'date' in data.columns:
        data.date = data.date.apply(str)
    return json.loads(data.to_json(orient='records'))

def QA_util_to_json_from_pandas(data):
    """需要对于datetime 和date 进行转换, 以免直接被变成了时间戳"""
    if isinstance(data, pd.DataFrame):
        data = data.to_dict(orient='records')
    elif isinstance(data, pd.Series):
        data = data.to_dict()
    elif isinstance(data, pd.Index):
        data = data.to_dict()
    elif isinstance(data, pd.MultiIndex):
        data = data.to_frame().to_dict(orient='records')
    else:
        raise TypeError('data must be pandas.DataFrame, pandas.Series, pandas.Index, pandas.MultiIndex')
    return data

def convert_machine_list_value(name: str, value: str) -> \
        Union[datetime.datetime, str, int]:
    """Convert sizes and time values.

    Size will be ``int`` while time value will be :class:`datetime.datetime`.
    """
    if name == 'modify':
        return convert_machine_list_time_val(value)
    elif name == 'size':
        return int(value)
    else:
        return value

def convert_machine_list_value(name: str, value: str) -> \
        Union[datetime.datetime, str, int]:
    """Convert sizes and time values.

    Size will be ``int`` while time value will be :class:`datetime.datetime`.
    """
    if name == 'size':
        return int(value)
    elif name == 'time':
        return datetime.datetime.strptime(value, '%Y-%m-%d %H:%M:%S')
    else:
        return value

