def _getobjs_higher(self, idobj):
        """Get all parents/relationships on this GOTerm."""
        idobjs_higher = set(idobj.parents)
        for reltyp, relidobjs in idobj.relationship.items():
            if self.relationships is True or reltyp in self.relationships:
                idobjs_higher.update(relidobjs)
        return idobjs_higher

def _getobjs_higher(self, idobj):
        """Get all parents/relationships on this GOTerm."""
        objs = []
        if idobj in self.parents:
            objs.extend(self.parents[idobj])
        if idobj in self.children:
            objs.extend(self.children[idobj])
        if idobj in self.relationships:
            objs.extend(self.relationships[idobj])
        return objs

def _split_line(self, line_str):
        """Split line and check number of columns"""
        arr = line_str.rstrip().split("\t")
        if len(arr) != self.expected_fields:
            raise exceptions.InvalidRecordException(
                (
                    "The line contains an invalid number of fields. Was "
                    "{} but expected {}\n{}".format(len(arr), 9 + len(self.samples.names), line_str)
                )
            )
        return arr

def _split_line(self, line_str):
        """Split line and check number of columns"""
        line = line_str.split()
        if len(line) != self.n_cols:
            raise ValueError(
                "Number of columns in line {} does not match number of "
                "columns in header {}".format(len(line), self.n_cols)
            )
        return line

def _build_client(self, name=None):
        """Make a new Client object

        :param name: Name of the url segment
        :type name: string
        :return: A Client object
        """
        if name is None:
            name = self.name
        return Client(self.url, name, self.token)

def middleware(self, middleware_or_request):
        """
        Decorate and register middleware to be called before a request.
        Can either be called as *@app.middleware* or
        *@app.middleware('request')*

        :param: middleware_or_request: Optional parameter to use for
            identifying which type of middleware is being registered.
        """
        # Detect which way this was called, @middleware or @middleware('AT')
        if callable(middleware_or_request):
            return self.register_middleware(middleware_or_request)

        else:
            return partial(
                self.register_middleware, attach_to=middleware_or_request
            )

def cd_to(path, mkdir=False):
    """make a generator like cd, but use it for function

    Usage::

        >>> @cd_to("/")
        ... def say_where():
        ...     print(os.getcwd())
        ...
        >>> say_where()
        /

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if mkdir:
                os.makedirs(path, exist_ok=True)
            old_path = os.getcwd()
            os.chdir(path)
            try:
                return func(*args, **kwargs)
            finally:
                os.chdir(old_path)
        return wrapper
    return decorator

def validate_session(self, session_ts):
        """
        检查Session是否过期, 验证Session可用性
        """
        now = time()
        ts = session_ts / 1000;
        if ts > ( now + 60 * 10 ) or now > ( ts + 60 * 30 ):
            return False
        return True

def validate_session(self, session_ts):
        """
        检查Session是否过期, 验证Session可用性
        """
        if session_ts is None:
            return False
        if session_ts < time.time() - self.session_timeout:
            return False
        return True

