def combinations(self):
        """Returns a generator of all possible combinations.
        """
        keys = self._vars.keys()
        for result in product(*self._vars.values()):
            possible_solution = {}
            for i, v in enumerate(result):
                possible_solution[keys[i]] = v
            yield possible_solution

def combinations(self):
        """Returns a generator of all possible combinations.
        """
        return self._combinations()

def _put_buffers(state, buffer_paths, buffers):
    """The inverse of _remove_buffers, except here we modify the existing dict/lists.
    Modifying should be fine, since this is used when state comes from the wire.
    """
    for buffer_path, buffer in zip(buffer_paths, buffers):
        _put_buffer(state, buffer_path, buffer)

def get(self, name, failobj=None):
        """Get a header value.

        Like __getitem__() but return failobj instead of None when the field
        is missing.
        """
        name = name.lower()
        for k, v in self._headers:
            if k.lower() == name:
                return self.policy.header_fetch_parse(k, v)
        return failobj

def _has(self, key, exact=0):

        """Returns false if key is not found or is ambiguous"""

        if not exact:
            try:
                key = self.getfullkey(key)
                return 1
            except KeyError:
                return 0
        else:
            return key in self.data

def _has(self, key, exact=0):

        """Returns false if key is not found or is ambiguous"""

        if exact:
            return key in self.keys()
        else:
            return key in self.keys() or key in self.aliases()

def construct_parameter_pattern(parameter):
    """
    Given a parameter definition returns a regex pattern that will match that
    part of the path.
    """
    if parameter.get('required', True):
        return '(?P<%s>%s)' % (parameter['name'], parameter['pattern'])
    else:
        return '(?P<%s>%s)?' % (parameter['name'], parameter['pattern'])

def outgoing(self, node):
        """Returns nodes connecting out of the given node (or list of nodes)."""
        if isinstance(node, list):
            return [outgoing(n) for n in node]
        else:
            return [n for n in self.nodes if node in self.outgoing(n)]

def _get_relationship_value(self, obj, column):
        """
        Compute datas produced for a given relationship
        """
        if column['__col__'].uselist:
            value = self._get_to_many_relationship_value(obj, column)
        else:
            value = self._get_to_one_relationship_value(obj, column)

        return value

def _get_relationship_value(self, obj, column):
        """
        Compute datas produced for a given relationship
        """
        if column.is_relationship:
            if column.is_many_to_many:
                return [
                    {
                        "id": getattr(item, column.related_id_column),
                        "name": getattr(item, column.related_name_column),
                    }
                    for item in getattr(obj, column.name)
                ]
            else:
                return {
                    "id": getattr(getattr(obj, column.name), column.related_id_column),
                    "name": getattr(getattr(obj, column.name), column.related_name_column),
                }
        else:
            return getattr(obj, column.name)

def get(self, idx, default=''):
        """Returns the element at idx, or default if idx is beyond the length of the list"""
        # if the index is beyond the length of the list, return ''
        if isinstance(idx, int) and (idx >= len(self) or idx < -1 * len(self)):
            return default
        # else do the regular list function (for int, slice types, etc.)
        return super().__getitem__(idx)

def get(self, idx, default=''):
        """Returns the element at idx, or default if idx is beyond the length of the list"""
        if idx < len(self):
            return self[idx]
        else:
            return default

def update_metadata(self, dataset_identifier, update_fields, content_type="json"):
        """
        Update the metadata for a particular dataset.
            update_fields is a dictionary containing [metadata key:new value] pairs.

        This method performs a full replace for the key:value pairs listed in `update_fields`, and
        returns all of the metadata with the updates applied.
        """
        if content_type == "json":
            return self._update_metadata_json(dataset_identifier, update_fields)
        elif content_type == "xml":
            return self._update_metadata_xml(dataset_identifier, update_fields)
        else:
