def checksum_file(scheme, path):
    """Return the checksum (hex digest) of a file"""
    h = getattr(hashlib, scheme)()

    with open(path, 'rb') as f:
        chunk = f.read(65535)
        while chunk:
            h.update(chunk)
            chunk = f.read(65535)
    return h.hexdigest()

def checksum_file(scheme, path):
    """Return the checksum (hex digest) of a file"""
    with open(path, 'rb') as f:
        return scheme.hexdigest(f.read())

def ui_open(*files):
  """Attempts to open the given files using the preferred desktop viewer or editor.

  :raises :class:`OpenError`: if there is a problem opening any of the files.
  """
  if files:
    osname = get_os_name()
    opener = _OPENER_BY_OS.get(osname)
    if opener:
      opener(files)
    else:
      raise OpenError('Open currently not supported for ' + osname)

def ui_open(*files):
  """Attempts to open the given files using the preferred desktop viewer or editor.

  :raises :class:`OpenError`: if there is a problem opening any of the files.
  """
  for file in files:
    try:
      subprocess.check_call(['xdg-open', file])
    except subprocess.CalledProcessError:
      try:
        subprocess.check_call(['open', file])
      except subprocess.CalledProcessError:
        raise OpenError(file)

