def cleanup():
    """Cleanup the output directory"""
    import os
    import shutil
    import glob
    import logging

    logging.info("Cleaning up output directory")
    for f in glob.glob("output/*"):
        if os.path.isdir(f):
            shutil.rmtree(f)
        else:
            os.remove(f)

