def daisy_chain_graph(self):
        """ Directed graph with edges from knob residue to each hole residue for each KnobIntoHole in self. """
        g = networkx.DiGraph()
        for x in self.get_monomers():
            for h in x.hole:
                g.add_edge(x.knob, h)
        return g

def daisy_chain_graph(self):
        """ Directed graph with edges from knob residue to each hole residue for each KnobIntoHole in self. """
        graph = nx.DiGraph()
        for knob_into_hole in self.knob_into_holes:
            graph.add_edge(knob_into_hole.knob.residue, knob_into_hole.hole.residue)
        return graph

