def _get_certificate_obj(cert):
    """
    Returns a certificate object based on PEM text.
    """
    if isinstance(cert, M2Crypto.X509.X509):
        return cert

    text = _text_or_file(cert)
    text = get_pem_entry(text, pem_type='CERTIFICATE')
    return M2Crypto.X509.load_cert_string(text)

def _get_certificate_obj(cert):
    """
    Returns a certificate object based on PEM text.
    """
    if cert.startswith('-----BEGIN CERTIFICATE-----'):
        return x509.load_pem_x509_certificate(cert.encode('utf-8'), default_backend())
    elif cert.startswith('-----BEGIN RSA PRIVATE KEY-----'):
        return x509.load_pem_private_key(cert.encode('utf-8'), default_backend())
    elif cert.startswith('-----BEGIN PRIVATE KEY-----'):
        return serialization.load_pem_private_key(cert.encode('utf-8'), None, default_backend())
    elif cert.startswith('-----BEGIN PUBLIC KEY-----'):
        return serialization.load_pem_public_key(cert.encode('utf-8'), default_backend())
    else:
        raise ValueError('Invalid certificate format')

def default_index(func):
    """Decorator assuring the wrapped method may only run if we are the default
    repository index. This is as we rely on git commands that operate
    on that index only. """

    @wraps(func)
    def check_default_index(self, *args, **kwargs):
        if self._file_path != self._index_path():
            raise AssertionError(
                "Cannot call %r on indices that do not represent the default git index" % func.__name__)
        return func(self, *args, **kwargs)
    # END wrapper method

    return check_default_index

def default_index(func):
    """Decorator assuring the wrapped method may only run if we are the default
    repository index. This is as we rely on git commands that operate
    on that index only. """
    def wrapper(self, *args, **kwargs):
        if self.index != 'default':
            raise RuntimeError(
                'This method may only be run on the default repository index'
            )
        return func(self, *args, **kwargs)
    return wrapper

