def folding_model_gradient(rvec, rcut):
    r"""computes the potential's gradient at point rvec"""
    rnorm = np.linalg.norm(rvec)
    if rnorm == 0.0:
        return np.zeros(rvec.shape)
    r = rnorm - rcut
    if r < 0.0:
        return -5.0 * r * rvec / rnorm
    return (1.5 * r - 2.0) * rvec / rnorm

def folding_model_gradient(rvec, rcut):
    r"""computes the potential's gradient at point rvec"""
    r = np.linalg.norm(rvec)
    if r > rcut:
        return np.zeros(3)
    else:
        return rvec / r

def flatten(self, l):
        """Turn a list of lists into a list."""
        if l == []:
            return l
        if isinstance(l[0], list):
            return self.flatten(l[0]) + self.flatten(l[1:])
        return l[:1] + self.flatten(l[1:])

