def find_disulfide_bridges(self, representatives_only=True):
        """Run Biopython's disulfide bridge finder and store found bridges.

        Annotations are stored in the protein structure's chain sequence at:
        ``<chain_prop>.seq_record.annotations['SSBOND-biopython']``

        Args:
            representative_only (bool): If analysis should only be run on the representative structure

        """
        if representatives_only:
            for chain in self.representatives:
                self._find_disulfide_bridges(chain)
        else:
            for chain in self.chains:
                self._find_disulfide_bridges(chain)

def variable_device(device, name):
  """Fix the variable device to colocate its ops."""
  if callable(device):
    var_name = tf.get_variable_scope().name + '/' + name
    var_def = tf.NodeDef(name=var_name, op='Variable')
    device = device(var_def)
  if device is None:
    device = ''
  return device

def variable_device(device, name):
  """Fix the variable device to colocate its ops."""
  if device is None:
    return None
  if not device.startswith("CPU"):
    return device
  return "/job:localhost/replica:0/task:0/device:CPU:0"

