def _compute_relative_probs(self, prob_dict):
        """ computes the relative probabilities for every state """
        for transition_counts in prob_dict.values():
            summed_occurences = sum(transition_counts.values())
            if summed_occurences > 0:
                for token in transition_counts.keys():
                    transition_counts[token] = transition_counts[
                        token] * 1.0 / summed_occurences

def _compute_relative_probs(self, prob_dict):
        """ computes the relative probabilities for every state """
        total_prob = sum(prob_dict.values())
        for state in prob_dict:
            prob_dict[state] = prob_dict[state] / total_prob

def getItemLocals(item):
    """
    Iterate the locals of an item and yield (name,valu) pairs.

    Example:

        for name,valu in getItemLocals(item):
            dostuff()

    """
    for name in dir(item):
        try:
            valu = getattr(item, name, None)
            yield name, valu
        except Exception:
            pass

def getItemLocals(item):
    """
    Iterate the locals of an item and yield (name,valu) pairs.

    Example:

        for name,valu in getItemLocals(item):
            dostuff()

    """
    for name in dir(item):
        if name.startswith('_'):
            continue
        valu = getattr(item, name)
        yield name, valu

