def method_header(method_name, nogil=False, idx_as_arg=False):
    """Returns the Cython method header for methods without arguments except
    `self`."""
    if nogil:
        return "def %s(self, nogil=True):" % method_name
    elif idx_as_arg:
        return "def %s(self, idx):" % method_name
    else:
        return "def %s(self):" % method_name

