def single_traj_from_n_files(file_list, top):
    """ Creates a single trajectory object from a list of files

    """
    traj = None
    for ff in file_list:
        if traj is None:
            traj = md.load(ff, top=top)
        else:
            traj = traj.join(md.load(ff, top=top))

    return traj

def greenhall_BasicSum(J, M, S, F, alpha, d):
    """ Eqn (10) from Greenhall2004 """
    return (J * M * S * F) / (alpha * d)

def hash(mapping, bind, values):
    """ Generate a sha1 for each of the given values. """
    for v in values:
        if v is None:
            continue
        if not isinstance(v, six.string_types):
            v = six.text_type(v)
        yield sha1(v.encode('utf-8')).hexdigest()

def hash(mapping, bind, values):
    """ Generate a sha1 for each of the given values. """
    return [
        hashlib.sha1(
            json.dumps(
                {
                    "mapping": mapping,
                    "bind": bind,
                    "values": values,
                }
            ).encode("utf-8")
        ).hexdigest()
    ]

