            return sorted(go2nt.items(), key=lambda t: _fnc(t[1]))
        if sortby:
            return sorted(go2nt.items(), key=lambda t: sortby(t[1]))
        return go2nt.items()

def _get_sorted_go2nt(self, go2nt, sortby):
        """Return sorted list of tuples."""
        if sortby == 'name':
            return sorted(go2nt.items(), key=lambda x: x[0])
        elif sortby == 'count':
            return sorted(go2nt.items(), key=lambda x: x[1], reverse=True)
        else:
            raise ValueError('sortby must be either "name" or "count"')

def getObjectForProxy(self, proxy):
        """
        Returns the unproxied version of C{proxy} as stored in the context, or
        unproxies the proxy and returns that 'raw' object.

        @see: L{pyamf.flex.unproxy_object}
        @since: 0.6
        """
        obj = self.proxied_objects.get(id(proxy))

        if obj is None:
            from pyamf import flex

            obj = flex.unproxy_object(proxy)

            self.addProxyObject(obj, proxy)

        return obj

def getObjectForProxy(self, proxy):
        """
        Returns the unproxied version of C{proxy} as stored in the context, or
        unproxies the proxy and returns that 'raw' object.

        @see: L{pyamf.flex.unproxy_object}
        @since: 0.6
        """

        if isinstance(proxy, Proxy):
            return unproxy_object(proxy, self)

        return proxy

def _update_keycache(self, *args, forward):
        """Add or remove a key in the set describing the keys that exist."""
        entity, key, branch, turn, tick, value = args[-6:]
        parent = args[:-6]
        kc = self._get_keycache(parent + (entity,), branch, turn, tick, forward=forward)
        if value is None:
            kc = kc.difference((key,))
        else:
            kc = kc.union((key,))
        self.keycache[parent+(entity, branch)][turn][tick] = kc

def _update_keycache(self, *args, forward):
        """Add or remove a key in the set describing the keys that exist."""
        if forward:
            self._keycache.add(args[0])
        else:
            self._keycache.remove(args[0])

