        # TODO [TM:3/21/17] clean it up after WAL-634. Clean up service settings update tests as well.
        if obj.customer and not obj.shared:
            return permissions.is_owner(request, view, obj)
        else:
            return permissions.is_staff(request, view, obj)

def can_user_update_settings(request, view, obj=None):
        """ Only staff can update shared settings, otherwise user has to be an owner of the settings."""
        if request.user.is_staff:
            return True
        if obj is None:
            return False
        return request.user.is_authenticated and obj.user == request.user

def require_axis(f):
    """ Check if the object of the function has axis and sel_axis members """

    @wraps(f)
    def _wrapper(self, *args, **kwargs):
        if None in (self.axis, self.sel_axis):
            raise ValueError('%(func_name) requires the node %(node)s '
                    'to have an axis and a sel_axis function' %
                    dict(func_name=f.__name__, node=repr(self)))

        return f(self, *args, **kwargs)

    return _wrapper

def require_axis(f):
    """ Check if the object of the function has axis and sel_axis members """
    def wrapper(self, *args, **kwargs):
        if not hasattr(self, 'axis'):
            raise AttributeError('The object has no axis attribute')
        if not hasattr(self, 'sel_axis'):
            raise AttributeError('The object has no sel_axis attribute')
        return f(self, *args, **kwargs)
    return wrapper

