def rupdate(source, target):
    """ recursively update nested dictionaries
        see: http://stackoverflow.com/a/3233356/1289080
    """
    for k, v in target.iteritems():
        if isinstance(v, Mapping):
            r = rupdate(source.get(k, {}), v)
            source[k] = r
        else:
            source[k] = target[k]
    return source

def rupdate(source, target):
    """ recursively update nested dictionaries
        see: http://stackoverflow.com/a/3233356/1289080
    """
    for key, value in source.items():
        if isinstance(value, dict):
            # get node or create one
            node = target.setdefault(key, {})
            rupdate(value, node)
        else:
            target[key] = value

def _validate_allof(self, definitions, field, value):
        """ {'type': 'list', 'logical': 'allof'} """
        if not isinstance(value, list):
            raise ValidationError(
                '{} must be a list'.format(field),
                field,
                value,
            )
        for i, item in enumerate(value):
            try:
                self._validate_type(definitions, field, item)
            except ValidationError as e:
                raise ValidationError(
                    '{} must be a list of {}'.format(field, e.message),
                    field,
                    value,
                )

