def flatten(nested):
    """ Return a flatten version of the nested argument """
    flat_return = list()

    def __inner_flat(nested,flat):
        for i in nested:
            __inner_flat(i, flat) if isinstance(i, list) else flat.append(i)
        return flat

    __inner_flat(nested,flat_return)

    return flat_return

def flatten(nested):
    """ Return a flatten version of the nested argument """
    if isinstance(nested, list):
        return [flatten(item) for item in nested]
    elif isinstance(nested, dict):
        return {key: flatten(value) for key, value in nested.items()}
    else:
        return nested

def _lookup(cls: str) -> LdapObjectClass:
    """ Lookup module.class. """
    if isinstance(cls, str):
        module_name, _, name = cls.rpartition(".")
        module = importlib.import_module(module_name)
        try:
            cls = getattr(module, name)
        except AttributeError:
            raise AttributeError("%s reference cannot be found" % cls)
    return cls

def _lookup(cls: str) -> LdapObjectClass:
    """ Lookup module.class. """
    return LdapObjectClass(cls)

def extract_keypairs(lines, regexer):
    """Given some lines of text, extract key-value pairs from them"""
    updates = {}
    for line in lines:
        # for consistency we must match the replacer and strip whitespace / newlines
        match = regexer.match(line.strip())
        if not match:
            continue
        k_v = match.groupdict()
        updates[k_v[Constants.KEY_GROUP]] = k_v[Constants.VALUE_GROUP]
    return updates

def extract_keypairs(lines, regexer):
    """Given some lines of text, extract key-value pairs from them"""
    keypairs = []
    for line in lines:
        match = regexer.match(line)
        if match:
            keypairs.append((match.group(1), match.group(2)))
    return keypairs

def adjustPlot(self, readsAx):
        """
        Add a horizontal line to the plotted reads if we're plotting e-values
        and a zero e-value was found.

        @param readsAx: A Matplotlib sub-plot instance, as returned by
            matplotlib.pyplot.subplot.
        """
        # If we're using bit scores, there's nothing to do.
        if self.scoreClass is HigherIsBetterScore:
