def consume(self, event):
        """
        process the current event, setup new state and teardown current state
        """
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_ESCAPE:
                self.quit()
            elif event.key == pygame.K_SPACE:
                self.paused = not self.paused
            elif event.key == pygame.K_r:
                self.reset()
            elif event.key == pygame.K_p:
                self.paused = not self.paused
            elif event.key == pygame.K_s:
                self.save()
            elif event.key == pygame.K_l:
                self.load()
            elif event.key == pygame.K_UP:
                self.speed += 1
            elif event.key == pygame.K_DOWN:
                self.speed = max(self.speed - 1, 1)
            elif event.key == pygame.K_LEFT:
                self.zoom -= 1
            elif event.key == pygame.K_RIGHT:
                self.zoom += 1
            elif event.key == pygame.K_1:
                self.zoom = 1
            elif event.key == pygame.K_2:
                self.zoom = 2
            elif event.key == pygame.K_3:
                self.zoom = 3
            elif event.key == pygame.K_4:
                self.zoom = 4
            elif event.key == pygame.K_5:
                self.zoom = 5
            elif event.key == pygame.K_6:
                self.zoom = 6
            elif event.key == pygame.K_7:
                self.zoom = 7
            elif event.key == pygame.K_8:
                self.zoom = 8
            elif event.key == pygame.K_9:
                self.zoom = 9
            elif event.key == pygame.K_0:
                self.zoom = 10
            elif event.key == pygame.K_F1:
                self.show_fps = not self.show_fps
            elif event.key == pygame.K_F2:
                self.show_

def _man_args(self, f):
        """
        Returns number of mandatory arguments required by given function.
        """
        argcount = f.func_code.co_argcount

        # account for "self" getting passed to class instance methods
        if isinstance(f, types.MethodType):
            argcount -= 1

        if f.func_defaults is None:
            return argcount

        return argcount - len(f.func_defaults)

def _man_args(self, f):
        """
        Returns number of mandatory arguments required by given function.
        """
        return len(inspect.getargspec(f).args) - len(inspect.getargspec(f).defaults or [])

def resolve(self, graph):
        """
        Resolve a scoped component, respecting the graph cache.

        """
        if self.component is None:
            return None
        if self.component in graph.cache:
            return graph.cache[self.component]
        else:
            graph.cache[self.component] = self.component
            return self.component

def reversed_graph(graph:dict) -> dict:
    """Return given graph reversed"""
    ret = defaultdict(set)
    for node, succs in graph.items():
        for succ in succs:
            ret[succ].add(node)
    return dict(ret)

def reversed_graph(graph:dict) -> dict:
    """Return given graph reversed"""
    reversed_graph = {}
    for key, value in graph.items():
        for item in value:
            if item not in reversed_graph:
                reversed_graph[item] = [key]
            else:
                reversed_graph[item].append(key)
    return reversed_graph

def convert_language_code(django_lang):
    """
    Converts Django language codes "ll-cc" into ISO codes "ll_CC" or "ll"

    :param django_lang: Django language code as ll-cc
    :type django_lang: str
    :return: ISO language code as ll_CC
    :rtype: str
    """
    lang_and_country = django_lang.split('-')
    try:
        return '_'.join((lang_and_country[0], lang_and_country[1].upper()))
    except IndexError:
        return lang_and_country[0]

def convert_language_code(django_lang):
    """
    Converts Django language codes "ll-cc" into ISO codes "ll_CC" or "ll"

    :param django_lang: Django language code as ll-cc
    :type django_lang: str
    :return: ISO language code as ll_CC
    :rtype: str
    """
    if django_lang == 'en':
        return 'en'
    else:
        return django_lang.replace('-', '_')

def select(self, table, cols, mode='list', key_filter=True):
        """
        Yield selected rows from *table*. This method just calls
        select_rows() on the rows read from *table*.
        """
        if cols is None:
            cols = [c.name for c in self.relations[table]]
        rows = self.read_table(table, key_filter=key_filter)
        for row in select_rows(cols, rows, mode=mode):
            yield row

def select(self, table, cols, mode='list', key_filter=True):
        """
        Yield selected rows from *table*. This method just calls
        select_rows() on the rows read from *table*.
        """
        if key_filter:
            key_filter = self.key_filter
        else:
            key_filter = None
        for row in self.select_rows(table, cols, mode, key_filter):
            yield row

def from_stream(cls, stream, marker_code, offset):
        """
