def _validate_min(self, proposal):
        """Enforce min <= value <= max"""
        min = proposal['value']
        if min > self.max:
            raise TraitError('Setting min > max')
        if min > self.value:
            self.value = min
        return min

def _validate_min(self, proposal):
        """Enforce min <= value <= max"""
        if proposal.value < self.min:
            raise ValueError(
                "Value must be greater than or equal to min (%s)" % self.min
            )
        if self.max is not None and proposal.value > self.max:
            raise ValueError(
                "Value must be less than or equal to max (%s)" % self.max
            )

def parse_duration(self):
        """
        Corrects for any offsets that may have been created by loop and skip
        events
        """
        for edit in self.track_edits:
            if edit.edit_type == 'loopPlugin':
                self.duration += (
                    (edit.options['end'] -
                     edit.options['start']) *
                    float(edit.options['loop'])
                )

def parse_duration(self):
        """
        Corrects for any offsets that may have been created by loop and skip
        events
        """
        if self.duration is None:
            return
        if self.duration < 0:
            self.duration = 0
        if self.duration > self.end_time:
            self.duration = self.end_time

def interp_head_addr(self):
        """Returns PtrTo(PtrTo(PyInterpreterState)) value"""
        if self._interp_head_addr is not None:
            return self._interp_head_addr
        try:
            interp_head_addr = self.get_interp_head_addr_through_symbol()
        except SymbolNotFound:
            logger.debug("Could not find interp_head symbol")
            # Hard way
            interp_head_addr = self.get_interp_head_addr_through_PyInterpreterState_Head()
        self._interp_head_addr = interp_head_addr
        return interp_head_addr

def interp_head_addr(self):
        """Returns PtrTo(PtrTo(PyInterpreterState)) value"""
        return self.interp_head_addr

def mask_umi(umi, umi_quals, quality_encoding,  quality_filter_threshold):
    """ Mask all positions where quals < threshold with "N" """
    below_threshold = get_below_threshold(
        umi_quals, quality_encoding, quality_filter_threshold)
    new_umi = ""

    for base, test in zip(umi, below_threshold):
        if test:
            new_umi += "N"
        else:
            new_umi += base

    return new_umi

def mask_umi(umi, umi_quals, quality_encoding,  quality_filter_threshold):
    """ Mask all positions where quals < threshold with "N" """
    umi_masked = umi
    umi_quals_masked = umi_quals
    for i in range(len(umi)):
        if umi_quals[i] < quality_filter_threshold:
            umi_masked = umi_masked[:i] + "N" + umi_masked[i+1:]
            umi_quals_masked = umi_quals_masked[:i] + [quality_encoding["N"]] + umi_quals_masked[i+1:]
    return umi_masked, umi_quals_masked

def key_from_password(password):
    """This method just hashes self.password."""
    if isinstance(password, unicode):
        password = password.encode('utf-8')
    if not isinstance(password, bytes):
        raise TypeError("password must be byte string, not %s" % type(password))

    sha = SHA256.new()
    sha.update(password)
    return sha.digest()

def key_from_password(password):
    """This method just hashes self.password."""
    return hashlib.sha256(password.encode()).hexdigest()

