def _get_parent(root):
    """Returns root element for a list.

    :Args:
      root (Element): lxml element of current location

    :Returns:
      lxml element representing list      
    """
    if root.getparent() is None:
        return root
    else:
        return _get_parent(root.getparent())

def create(self, handle, title=None, description=None):
        """ Create a role """
        if not title:
            title = handle
        if not description:
            description = handle
        role = Role(handle=handle, title=title, description=description)
        self.session.add(role)
        self.session.commit()
        return role

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    backup_base = '/var/local/woven-backup'
    backup_path = ''.join([backup_base,path])
    if exists(backup_path):
        if delete_backup:
            sudo('mv -f %s %s'% (backup_path,path))
        else:
            sudo('cp -f %s %s'% (backup_path,path))

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    if os.path.exists(path):
        if delete_backup:
            os.remove(path + '.bak')
        else:
            shutil.copyfile(path + '.bak', path)

def day(year, month, day, home=None, away=None):
    """Return a list of games for a certain day.

    If the home and away team are the same,
    it will return the game(s) for that team.
    """
    if home == away:
        return [game for game in games(year, month, day) if game['home'] == home]
    else:
        return [game for game in games(year, month, day) if game['home'] == home or game['away'] == away]

def _hl_as_string(self, highlight):
        """
        Given a solr string of highlighted text, returns the
        str representations
        For example:
        "Foo <em>Muscle</em> bar <em>atrophy</em>, generalized"
        Returns:
        "Foo Muscle bar atrophy, generalized"
        :return: str
        """
        return ' '.join(
            [
                part.strip()
                for part in highlight.split('<em>')
                if part.strip()
            ]
        )

def mssql_transaction_count(engine_or_conn: Union[Connection, Engine]) -> int:
    """
    For Microsoft SQL Server specifically: fetch the value of the ``TRANCOUNT``
    variable (see e.g.
    https://docs.microsoft.com/en-us/sql/t-sql/functions/trancount-transact-sql?view=sql-server-2017).
    Returns ``None`` if it can't be found (unlikely?).
    """
    if isinstance(engine_or_conn, Connection):
        conn = engine_or_conn
    else:
        conn = engine_or_conn.connect()
    try:
        return conn.execute("SELECT @@TRANCOUNT").scalar()
    finally:
        conn.close()

