def user_return(self, frame, return_value):
    """This function is called when a return trap is set here."""
    # This is useful when debugging in an active interpreter (otherwise,
    # the debugger will stop before reaching the target file)
    if self._wait_for_mainpyfile:
        if (self.mainpyfile != self.canonic(frame.f_code.co_filename)
            or frame.f_lineno<= 0):
            return
        self._wait_for_mainpyfile = 0
    self._old_Pdb_user_return(frame, return_value)

def accumulate(self, axis: AxisIdentifier) -> HistogramBase:
        """Calculate cumulative frequencies along a certain axis.

        Returns
        -------
        new_hist: Histogram of the same type & size
        """
        if axis == Axis.CHANNEL:
            return self.accumulate_channel()
        elif axis == Axis.BIN:
            return self.accumulate_bin()
        elif axis == Axis.X:
            return self.accumulate_x()
        elif axis == Axis.Y:
            return self.accumulate_y()
        elif axis == Axis.Z:
            return self.accumulate_z()
        else:
            raise ValueError(f"Unknown axis {axis}")

def add_media(self, mrl):
        """Add media instance to media list.

        The L{lock} should be held upon entering this function.
        @param mrl: a media instance or a MRL.
        @return: 0 on success, -1 if the media list is read-only.
        """
        if isinstance(mrl, basestring):
            mrl = (self.get_instance() or get_default_instance()).media_new(mrl)
        return libvlc_media_list_add_media(self, mrl)

def add_media(self, mrl):
        """Add media instance to media list.

        The L{lock} should be held upon entering this function.
        @param mrl: a media instance or a MRL.
        @return: 0 on success, -1 if the media list is read-only.
        """
        if self.read_only:
            return -1
        if isinstance(mrl, Media):
            self.media_list.append(mrl)
        else:
            self.media_list.append(Media(mrl))
        return 0

def find_by_reference_ids(reference_ids, _connection=None, page_size=100,
        page_number=0, sort_by=enums.DEFAULT_SORT_BY,
        sort_order=enums.DEFAULT_SORT_ORDER):
        """
        List all videos identified by a list of reference ids
        """
        if not reference_ids:
            raise ValueError('reference_ids must not be empty')

        if not isinstance(reference_ids, list):
            raise ValueError('reference_ids must be a list')

        if not isinstance(page_size, int):
            raise ValueError('page_size must be an integer')

        if not isinstance(page_number, int):
            raise ValueError('page_number must be an integer')

        if not isinstance(sort_by, str):
            raise ValueError('sort_by must be a string')

        if not isinstance(sort_order, str):
            raise ValueError('sort_order must be a string')

        if sort_by not in enums.SORT_BY:
            raise ValueError('sort_by must be one of {}'.format(
                enums.SORT_BY))

        if sort_order not in enums.SORT_ORDER:
            raise ValueError('sort_order must be one of {}'.format(
                enums.SORT_ORDER))

        params = {
            'reference_ids': ','.join(reference_ids),
            'page_size': page_size,
            'page_number': page_number,
            'sort_by': sort_by,
            'sort_order': sort_order
        }

        return _connection.get(
            '/videos/findByReferenceIds',
            params=params
        )

def add_field(self, field):
        """Add the received field to the model."""
        self.remove_field(field.name)
        self._fields[field.name] = field

        if field.default is not None:
            if six.callable(field.default):
                self._default_callables[field.key] = field.default
            else:
                self._defaults[field.key] = field.default

def add_field(self, field):
        """Add the received field to the model."""
        self.fields.append(field)

def longest_dir_prefix(path, prefixes):
  """Given a list of prefixes, return the one that is the longest prefix to the given path.

  Returns None if there are no matches.
  """
  longest_match, longest_prefix = 0, None
  for prefix in prefixes:
    if fast_relpath_optional(path, prefix) is not None and len(prefix) > longest_match:
      longest_match, longest_prefix = len(prefix), prefix

  return longest_prefix

def longest_dir_prefix(path, prefixes):
  """Given a list of prefixes, return the one that is the longest prefix to the given path.

  Returns None if there are no matches.
  """
  for prefix in prefixes:
    if path.startswith(prefix):
      return prefix
  return None

def _make_boundary(self):
        """ creates a boundary for multipart post (form post)"""
        if self.PY2:
            return '===============%s==' % uuid.uuid4().get_hex()
        elif self.PY3:
            return '===============%s==' % uuid.uuid4().hex
        else:
            from random import choice
            digits = "0123456789"
            letters = "abcdefghijklmnopqrstuvwxyz"
            return '===============%s==' % ''.join(choice(letters + digits) \
                                                   for i in range(15))

def add_file_or_directory_volume(self,
                                     runtime,         # type: List[Text]
                                     volume,          # type: MapperEnt
                                     host_outdir_tgt  # type: Optional[Text]
                                     ):  # type: (...) -> None
        """Append volume a file/dir mapping to the runtime option list."""
        if not volume.resolved.startswith("_:"):
            _check_docker_machine_path(docker_windows_path_adjust(
                volume.resolved))
            self.append_volume(runtime, volume.resolved, volume.target)

def add_file_or_directory_volume(self,
                                     runtime,         # type: List[Text]
                                     volume,          # type: MapperEnt
                                     host_outdir_tgt  # type: Optional[Text]
                                     ):  # type: (...) -> None
        """Append volume a file/dir mapping to the runtime option list."""
        if host_outdir_tgt is None:
            host_outdir_tgt = ""
        if volume.type == "file":
            runtime.append("--volume={}:{}:ro".format(volume.host_path,
                                                      os.path.join(host_outdir_tgt,
                                                                   volume.container_path)))
        elif volume.type == "directory":
            runtime.append("--volume={}:{}:rw".format(volume.host_path,
                                                      os.path.join(host_outdir_tgt,
                                                                   volume.container_path)))
        else:
            raise ValueError("Unknown volume type: {}".format(volume.type))

def to_selector(self):
        """ For some reason, the selector for <identity> is

            <identity id="1234" />

        rather than

            <identity by="id"></identity>
        """

        for i in self.SELECTORS:
            if hasattr(self, i):
                val = getattr(self, i)
                selector = i
                break

        return {selector: val}

def local_rfcformat(dt):
    """Return the RFC822-formatted representation of a timezone-aware datetime
    with the UTC offset.
    """
    if dt.tzinfo is None:
        raise ValueError("datetime must be timezone-aware")
    return dt.strftime("%a, %d %b %Y %H:%M:%S %z")

def load_quota(self, quota, TTL, interval):
        """
        Load new quota with a TTL. If the input is None,
        the reservoir will continue using old quota until it
        expires or has a non-None quota/TTL in a future load.
        """
        if quota is not None:
            self._quota = quota
        if TTL is not None:
            self._TTL = TTL
        if interval is not None:
            self._report_interval = interval / 10

def clean_email(self):
        """
        Ensure the email address is not already registered.
        """
        email = self.cleaned_data.get('email')
        if email:
            try:
                User.objects.get(email=email)
            except User.DoesNotExist:
                return email
            raise forms.ValidationError(
                'A user with that email address already exists.'
            )

def _get_index(self):
        """
        Get the guideline's index.
        This must return an ``int``.

        Subclasses may override this method.
        """
        glyph = self.glyph
        if glyph is not None:
            parent = glyph
        else:
            parent = self.font
        if parent is None:
            return None
        return parent.guidelines.index(self)

def iter_and_close(file_like, block_size):
    """Yield file contents by block then close the file."""
    while 1:
        try:
            block = file_like.read(block_size)
            if block:
                yield block
            else:
                raise StopIteration
        except StopIteration:
            file_like.close()
            return

def iter_and_close(file_like, block_size):
    """Yield file contents by block then close the file."""
    try:
        while True:
            data = file_like.read(block_size)
            if not data:
                break
            yield data
    finally:
        file_like.close()

def parse(self, parser):
        """Main method to render data into the template."""
        lineno = next(parser.stream).lineno

        if parser.stream.skip_if('name:short'):
            parser.stream.skip(1)
            short = parser.parse_expression()
        else:
            short = nodes.Const(False)

        result = self.call_method('_commit_hash', [short], [], lineno=lineno)
        return nodes.Output([result], lineno=lineno)

