def _fetch_meta_data(self):
        """Makes an API call to fetch meta data for the given probe and stores the raw data."""
        url = self.url + '/api/v1/probes/' + self.probe_id + '/meta'
        response = requests.get(url, headers=self.headers)
        if response.status_code == 200:
            self.meta_data = response.json()
        else:
            raise Exception('Error fetching meta data for probe ' + self.probe_id + ': ' + response.text)

def watchdog_handler(self):
        """Take care of threads if wachdog expires."""
        if self.watchdog_thread is not None:
            self.watchdog_thread.join()
        self.watchdog_thread = None
        if self.watchdog_timer is not None:
            self.watchdog_timer.cancel()
        self.watchdog_timer = None
        if self.watchdog_event is not None:
            self.watchdog_event.set()
        self.watchdog_event = None
        if self.watchdog_timeout is not None:
            self.watchdog_timeout = None
        if self.watchdog_timeout_handler is not None:
            self.watchdog_timeout_handler()
        self.watchdog_timeout_handler = None

def dedupe_by(things, key=None):
    """
    Given an iterator of things and an optional key generation function, return
    a new iterator of deduped things. Things are compared and de-duped by the
    key function, which is hash() by default.
    """
    if not key:
        key = hash
    index = {key(thing): thing for thing in things}
    return index.values()

def get_bond(iface):
    """
    Return the content of a bond script

    CLI Example:

    .. code-block:: bash

        salt '*' ip.get_bond bond0
    """
    iface = iface.strip()
    if iface.startswith("bond"):
        cmd = "cat /etc/sysconfig/network-scripts/ifcfg-{0}".format(iface)
        return __salt__["cmd.run"](cmd).splitlines()
    else:
        return []

