def prepare_filename_decorator(fn):
    """
    A decorator of `prepare_filename` method

    1. It automatically assign `settings.ROUGHPAGES_INDEX_FILENAME` if the
       `normalized_url` is ''.
    2. It automatically assign file extensions to the output list.
    """
    def wrapper(self, normalized_url, *args, **kwargs):
        if normalized_url == '':
            normalized_url = settings.ROUGHPAGES_INDEX_FILENAME
        return fn(self, normalized_url, *args, **kwargs)
    return wrapper

def file_current(self, fname, md5):
        """Checksum a file and compare the md5 with the known md5
        """
        if not os.path.exists(fname):
            return False
        if md5 is None:
            return True
        with open(fname, 'rb') as f:
            md5_file = hashlib.md5(f.read()).hexdigest()
        return md5_file == md5

def getaddrlist(self):
        """Parse all addresses.

        Returns a list containing all of the addresses.
        """
        result = []
        while self.pos < len(self.field):
            ad = self.getaddress()
            if ad:
                result += ad
            else:
                result.append(('', ''))
        return result

def iterchildren(self):
        """
        Iterates the subkeys for this Registry key.

        @rtype:  iter of L{RegistryKey}
        @return: Iterator of subkeys.
        """
        handle = self.handle
        index = 0
        while 1:
            subkey = win32.RegEnumKey(handle, index)
            if subkey is None:
                break
            yield self.child(subkey)
            index += 1

def iterchildren(self):
        """
        Iterates the subkeys for this Registry key.

        @rtype:  iter of L{RegistryKey}
        @return: Iterator of subkeys.
        """
        return iter(self.keys())

def make_query(self, *args, **kwargs):
        """ Returns a Q object from the submitted form """
        query = Q()  # initial is an empty query
        query_dict = self._build_query_dict(self.cleaned_data)
        if 'negate' in self.cleaned_data and self.cleaned_data['negate']:
            query = query & ~Q(**query_dict)
        else:
            query = query & Q(**query_dict)
        return query

def make_query(self, *args, **kwargs):
        """ Returns a Q object from the submitted form """
        query = Q()
        for field in self.fields:
            if field in kwargs:
                query &= Q(**{field: kwargs[field]})
        return query

