def RetrieveIP4Info(self, ip):
    """Retrieves information for an IP4 address."""
    if ip.is_private:
      return (IPInfo.INTERNAL, "Internal IP address.")
    try:
      # It's an external IP, let's try to do a reverse lookup.
      res = socket.getnameinfo((str(ip), 0), socket.NI_NAMEREQD)
      return (IPInfo.EXTERNAL, res[0])
    except (socket.error, socket.herror, socket.gaierror):
      return (IPInfo.EXTERNAL, "Unknown IP address.")

def RetrieveIP4Info(self, ip):
    """Retrieves information for an IP4 address."""
    try:
        ip_info = self.ip4_info[ip]
    except KeyError:
        ip_info = self.RetrieveIP4InfoFromAPI(ip)
        self.ip4_info[ip] = ip_info
    return ip_info

def check_url (aggregate):
    """Helper function waiting for URL queue."""
    while True:
        try:
            aggregate.urlqueue.join(timeout=30)
            break
        except urlqueue.Timeout:
            # Cleanup threads every 30 seconds
            aggregate.remove_stopped_threads()
            if not any(aggregate.get_check_threads()):
                break

def check_url (aggregate):
    """Helper function waiting for URL queue."""
    while True:
