            url = aggregate.get_nowait()
            return url
        except queue.Empty:
            pass

def _list_magic_methods(meta, class_):
        """Return names of magic methods defined by a class.
        :return: Iterable of magic methods, each w/o the ``__`` prefix/suffix
        """
        return [
            name[2:-2] for name, member in class_.__dict__.items()
            if len(name) > 4 and name.startswith('__') and name.endswith('__')
            and inspect.isfunction(member)
        ]

def _list_magic_methods(meta, class_):
        """Return names of magic methods defined by a class.
        :return: Iterable of magic methods, each w/o the ``__`` prefix/suffix
        """
        return (
            name
            for name in dir(class_)
            if name.startswith("__") and name.endswith("__")
        )

def write_to_file(self, destination_path):
        """
        Writes the metadata json or xml to a file.

        :param destination_path: the file path the file format is inferred
        from the destination_path extension.
        :type destination_path: str
        :return: the written metadata
        :rtype: str
        """
        if destination_path.endswith(".json"):
            return self.write_to_json(destination_path)
        elif destination_path.endswith(".xml"):
            return self.write_to_xml(destination_path)
        else:
            raise ValueError("Invalid file extension. Must be .json or .xml")

def detect(self):
        """
        Resolve the hostname to an IP address through the operating system.

        Depending on the 'family' option, either ipv4 or ipv6 resolution is
        carried out.

        If multiple IP addresses are found, the first one is returned.

        :return: ip address
        """
        if self.family == socket.AF_INET:
            return socket.gethostbyname(self.hostname)
        elif self.family == socket.AF_INET6:
            return socket.getaddrinfo(self.hostname, None)[0][4][0]
        else:
            raise ValueError("Invalid family: %s" % self.family)

