def percent_records_missing_location(user, method=None):
    """
    Return the percentage of records missing a location parameter.
    """

    if len(user.records) == 0:
        return 0.

    missing_locations = sum([1 for record in user.records if record.position._get_location(user) is None])
    return float(missing_locations) / len(user.records)

def percent_records_missing_location(user, method=None):
    """
    Return the percentage of records missing a location parameter.
    """
    if method is None:
        method = user.get_preferred_method()
    if method == 'api':
        return percent_records_missing_location_api(user)
    elif method == 'web':
        return percent_records_missing_location_web(user)
    else:
        raise ValueError('Invalid method: %s' % method)

def _num_vowel_to_acc(vowel, tone):
    """Convert a numbered vowel to an accented vowel."""
    try:
        return VOWEL_MAP[vowel + str(tone)]
    except IndexError:
        raise ValueError("Vowel must be one of '{}' and tone must be a tone.".format(VOWELS))

def _num_vowel_to_acc(vowel, tone):
    """Convert a numbered vowel to an accented vowel."""
    if vowel == 'a':
        return 'á'
    elif vowel == 'e':
        return 'é'
    elif vowel == 'i':
        return 'í'
    elif vowel == 'o':
        return 'ó'
    elif vowel == 'u':
        return 'ú'
    else:
        return vowel

def ensureVisible(self):
        """
        Ensures that this layer is visible by turning on all parent layers \
        that it needs to based on its inheritance value.
        """
        if self.inheritance == 'inherit':
            for parent in self.parents:
                parent.ensureVisible()
        elif self.inheritance == 'ignore':
            pass
        else:
            raise ValueError('Unknown inheritance value: %s' % self.inheritance)
        self.visible = True

def unix_line_discard(event):
    """
    Kill backward from the cursor to the beginning of the current line.
    """
    buff = event.current_buffer

    if buff.document.cursor_position_col == 0 and buff.document.cursor_position > 0:
        buff.delete_before_cursor(count=1)
    else:
        deleted = buff.delete_before_cursor(count=-buff.document.get_start_of_line_position())
        event.cli.clipboard.set_text(deleted)

def transformChildrenFromNative(self, clearBehavior=True):
        """
        Recursively transform native children to vanilla representations.
        """
        for childArray in self.contents.values():
            for child in childArray:
                child = child.transformFromNative()
                child.transformChildrenFromNative(clearBehavior)
                if clearBehavior:
                    child.behavior = None
                    child.parentBehavior = None

def transformChildrenFromNative(self, clearBehavior=True):
        """
        Recursively transform native children to vanilla representations.
        """
        for child in self.children:
            child.transformFromNative(clearBehavior)

def _connection(self):
        """
        If we have a pipeline, shared in thread, or in the good thread, return it
        else use the direct connection
        """
        if self.pipeline:
            return self.pipeline
        elif self.shared_connection:
            return self.shared_connection
        elif self.connection:
            return self.connection
        else:
            return self.direct_connection

def countfiles(path, recurse=False):
    """Returns the number of files under the given directory path."""
    if not op.isdir(path):
        return 0
    count = 0
    for r,ds,fs in os.walk(path):
        count += len(fs)
        if not recurse:
            break
    return count

def countfiles(path, recurse=False):
    """Returns the number of files under the given directory path."""
    if not os.path.isdir(path):
        raise ValueError("Not a directory: %s" % path)
    if recurse:
        return len(os.listdir(path))
    else:
        return len([f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])

def _get_folder(gi, folder_name, library, libitems):
    """Retrieve or create a folder inside the library with the specified name.
    """
    for item in libitems:
        if item["type"] == "folder" and item["name"] == "/%s" % folder_name:
            return item
    return gi.libraries.create_folder(library.id, folder_name)[0]

def _get_folder(gi, folder_name, library, libitems):
    """Retrieve or create a folder inside the library with the specified name.
    """
    folder = None
    for libitem in libitems:
        if libitem.name == folder_name:
            folder = libitem
            break
    if folder is None:
        folder = gi.library.create_folder(folder_name)
    return folder

