        return None

def exit(exit_code=0):
  r"""A function to support exiting from exit hooks.

  Could also be used to exit from the calling scripts in a thread safe manner.
  """
  if not isinstance(exit_code, int):
    raise TypeError('exit_code must be an integer.')
  if exit_code < 0:
    raise ValueError('exit_code must be non-negative.')
  if not _EXIT_HOOKS:
    sys.exit(exit_code)
  for hook in _EXIT_HOOKS:
    hook(exit_code)
  sys.exit(exit_code)

