def _extract_email(data):
    """
    {'elements': [{'handle': 'urn:li:emailAddress:319371470',
               'handle~': {'emailAddress': 'raymond.penners@intenct.nl'}}]}
    """
    if 'elements' in data:
        for element in data['elements']:
            if 'handle~' in element:
                return element['handle~']['emailAddress']
    return None

