def contains(self, em):
        """
            contains - Check if #em occurs within any of the elements within this list, as themselves or as a child, any
               number of levels down.

               To check if JUST an element is contained within this list directly, use the "in" operator.

            @param em <AdvancedTag> - Element of interest

            @return <bool> - True if contained, otherwise False
        """

        for node in self:
            if node.contains(em):
                return True

        return False

def contains(self, em):
        """
            contains - Check if #em occurs within any of the elements within this list, as themselves or as a child, any
               number of levels down.

               To check if JUST an element is contained within this list directly, use the "in" operator.

            @param em <AdvancedTag> - Element of interest

            @return <bool> - True if contained, otherwise False
        """
        if em in self:
            return True
        for e in self:
            if e.contains(em):
                return True
        return False

def has_legend(self, bool_value):
        """
        Add, remove, or leave alone the ``<c:legend>`` child element depending
        on current state and *bool_value*. If *bool_value* is |True| and no
        ``<c:legend>`` element is present, a new default element is added.
        When |False|, any existing legend element is removed.
        """
        if bool(bool_value) is False:
            self._remove_legend()
        else:
            if self.legend is None:
                self._add_legend()

def has_legend(self, bool_value):
        """
        Add, remove, or leave alone the ``<c:legend>`` child element depending
        on current state and *bool_value*. If *bool_value* is |True| and no
        ``<c:legend>`` element is present, a new default element is added.
        When |False|, any existing legend element is removed.
        """
        if bool_value:
            if not self._legend:
                self._legend = self._add_legend()
        elif self._legend is not None:
            self._legend._remove()
            self._legend = None

