def UnicodeFromCodePage(string):
  """Attempt to coerce string into a unicode object."""
  # get the current code page
  codepage = ctypes.windll.kernel32.GetOEMCP()
  try:
    return string.decode("cp%s" % codepage)
  except UnicodeError:
    try:
      return string.decode("utf16", "ignore")
    except UnicodeError:
      # Fall back on utf8 but ignore errors
      return string.decode("utf8", "ignore")

def UnicodeFromCodePage(string):
  """Attempt to coerce string into a unicode object."""
  try:
    return string.decode('utf-8')
  except UnicodeDecodeError:
    try:
      return string.decode('utf-16')
    except UnicodeDecodeError:
      try:
        return string.decode('utf-32')
      except UnicodeDecodeError:
        try:
          return string.decode('utf-7')
        except UnicodeDecodeError:
          try:
            return string.decode('utf-16-be')
          except UnicodeDecodeError:
            try:
              return string.decode('utf-16-le')
            except UnicodeDecodeError:
              try:
                return string.decode('utf-32-be')
              except UnicodeDecodeError:
                try:
                  return string.decode('utf-32-le')
                except UnicodeDecodeError:
                  try:
                    return string.decode('cp1252')
                  except UnicodeDecodeError:
                    try:
                      return string.decode('latin-1')
                    except UnicodeDecodeError:
                      try:
                        return string.decode('macroman')
                      except UnicodeDecodeError:
                        try:
                          return string.decode('ascii')
                        except UnicodeDecodeError:
                          return string

def same(d1, d2):
    """! @brief Test whether two sequences contain the same values.

    Unlike a simple equality comparison, this function works as expected when the two sequences
    are of different types, such as a list and bytearray. The sequences must return
    compatible types from indexing.
    """
    if len(d1) != len(d2):
        return False
    for i in range(len(d1)):
        if d1[i] != d2[i]:
            return False
    return True

def same(d1, d2):
    """! @brief Test whether two sequences contain the same values.

    Unlike a simple equality comparison, this function works as expected when the two sequences
    are of different types, such as a list and bytearray. The sequences must return
    compatible types from indexing.
    """
    if len(d1) != len(d2):
        return False
    for i in range(len(d1)):
        if d1[i] != d2[i]:
            return False
    return True

