def request(self, method, url, **kwargs):
        """
        Send a request.
        If timeout is not explicitly given, use the default timeouts.
        """
        if 'timeout' not in kwargs:
            if self.timeout is not None:
                kwargs['timeout'] = self.timeout
            else:
                kwargs['timeout'] = (DEFAULT_CONNECT_TIMEOUT,
                                     DEFAULT_READ_TIMEOUT)
        return super(Session, self).request(method=method, url=url, **kwargs)

def request(self, method, url, **kwargs):
        """
        Send a request.
        If timeout is not explicitly given, use the default timeouts.
        """
        timeout = kwargs.pop('timeout', None)
        if timeout is None:
            timeout = self.timeout
        kwargs.setdefault('allow_redirects', True)
        if self.proxies:
            kwargs.setdefault('proxies', self.proxies)
        if self.verify:
            kwargs.setdefault('verify', self.verify)
        if self.cert:
            kwargs.setdefault('cert', self.cert)
        if self.stream:
            kwargs.setdefault('stream', self.stream)
        if self.trust_env:
            kwargs.setdefault('trust_env', self.trust_env)
        if self.cookies:
            kwargs.setdefault('cookies', self.cookies)
        if self.hooks:
            kwargs.setdefault('hooks', self.hooks)
        if self.auth:
            kwargs.setdefault('auth', self.auth)
        if self.params:
            kwargs.setdefault('params', self.params)
        if self.data:
            kwargs.setdefault('data', self.data)
        if self.json:
            kwargs.setdefault('json', self.json)
        if self.headers:
            kwargs.setdefault('headers', self.headers)

        try:
            response = self.session.request(method, url, timeout=timeout, **kwargs)
        except requests.exceptions.Timeout:
            raise TimeoutError('Request timed out.')
        except requests.exceptions.ConnectionError:
            raise ConnectionError('Failed to establish a new connection.')
        except requests.exceptions.HTTPError:
            raise HTTPError('Bad response from server.')
        except requests.exceptions.RequestException:
            raise RequestError('Unexpected error.')

        if response.status_code == 401:
            raise UnauthorizedError('Unauthorized.')
        if response.status_code == 403:
            raise ForbiddenError('Forbidden.')
        if response.status_code == 404:
            raise NotFoundError

def modified_lines_from_diff(self, diff):
        """Returns the changed lines in a diff.

        - Potentially this is vc specific (if not using udiff).

        Note: this returns the line numbers in descending order.

        """
        modified_lines = []
        for line in diff.splitlines():
            if line.startswith('+'):
                modified_lines.append(int(line.split()[1]))
        return modified_lines

