def validate_context(self, context):
        """
        Checks to see if we're working with a valid lambda context object.

        :returns: True if valid, False if not
        :rtype: bool
        """
        if not isinstance(context, dict):
            return False

        if 'function_name' not in context:
            return False

        if 'function_version' not in context:
            return False

        if 'invoked_function_arn' not in context:
            return False

        if 'memory_limit_in_mb' not in context:
            return False

        if 'aws_request_id' not in context:
            return False

        if 'log_group_name' not in context:
            return False

        if 'log_stream_name' not in context:
            return False

        if 'identity' not in context:
            return False

        if 'client_context' not in context:
            return False

        return True

def _from_pointer(pointer, incref):
        """Wrap an existing :c:type:`cairo_scaled_font_t *` cdata pointer.

        :type incref: bool
        :param incref:
            Whether increase the :ref:`reference count <refcounting>` now.
        :return: A new :class:`ScaledFont` instance.

        """
        if pointer == ffi.NULL:
            raise ValueError("NULL pointer")
        if incref:
            libcairo.cairo_scaled_font_reference(pointer)
        return ScaledFont(pointer)

def find_clean_dirs(self):
        """Finds all (temporary) directories according to the glob and re patterns that should be cleaned."""

        for folder in glob.glob(self.glob_pattern):
            if re.match(self.re_pattern, folder):
                yield folder
        for folder in glob.glob(self.orig_glob_pattern):
            if re.match(self.orig_re_pattern, folder):
                yield folder

def find_clean_dirs(self):
        """Finds all (temporary) directories according to the glob and re patterns that should be cleaned."""
        clean_dirs = []
        for glob_pattern in self.clean_globs:
            clean_dirs.extend(glob.glob(glob_pattern))
        for re_pattern in self.clean_re_patterns:
            clean_dirs.extend(re.findall(re_pattern, self.output_dir))
        return clean_dirs

def setlocation(self, url, names=None):
        """
        Override the invocation location (url) for service method.
        @param url: A url location.
        @type url: A url.
        @param names:  A list of method names.  None=ALL
        @type names: [str,..]
        """
        for p in self.ports:
            for m in p.methods.values():
                if names is None or m.name in names:
                    m.location = url

def setlocation(self, url, names=None):
        """
        Override the invocation location (url) for service method.
        @param url: A url location.
        @type url: A url.
        @param names:  A list of method names.  None=ALL
        @type names: [str,..]
        """
        if names is None:
            names = self.get_method_names()
        for name in names:
            self.get_method(name).setlocation(url)

def container_running(self, container_name):
        """
        Finds out if a container with name ``container_name`` is running.

        :return: :class:`Container <docker.models.containers.Container>` if it's running, ``None`` otherwise.
        :rtype: Optional[docker.models.container.Container]
        """
        filters = {
            "name": container_name,
            "status": "running",
        }

        for container in self.client.containers.list(filters=filters):
            if container_name == container.name:
                return container
        return None

def container_running(self, container_name):
        """
        Finds out if a container with name ``container_name`` is running.

        :return: :class:`Container <docker.models.containers.Container>` if it's running, ``None`` otherwise.
        :rtype: Optional[docker.models.container.Container]
        """
        for container in self.containers:
            if container.name == container_name:
                return container
        return None

def get_email(self):
        """Gets email
        :return: Email of user
        """
        api_url = self.api_url + "/events/public"
        api_content = GithubRawApi(
            api_url,
            get_api_content_now=True
        ).api_content

        for event in api_content:
            if event["type"] == "PushEvent":
                return event["payload"]["commits"][0]["author"]["email"]

def configure(self):
        # type: () -> None
        """
            Configures object based on its initialization
        """
        for i in vars(self):
            if i.startswith("_"):
                continue
            val = self.__get(i, return_type=type(getattr(self, i)))
            if val is not None:
                setattr(self, i, val)

def get_package_version():
    """returns package version without importing it"""
    base = os.path.abspath(os.path.dirname(__file__))
    with open(os.path.join(base, "firepit/__init__.py")) as pkg:
        for line in pkg:
            m = version.match(line.strip())
            if not m:
                continue
            return ".".join(m.groups()[0].split(", "))

def get_package_version():
    """returns package version without importing it"""
    import os
    import re
    import sys

    def get_version_from_file(filename):
        with open(filename) as f:
            contents = f.read()
        return re.search(r"^__version__ = ['\"]([^'\"]+)['\"]", contents, re.M).group(1)

    def get_version_from_git():
        import subprocess

        try:
            p = subprocess.Popen(["git", "describe", "--tags"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out, err = p.communicate()
            if p.returncode != 0:
                raise RuntimeError("git describe failed: %s" % err)
            return out.strip().decode("utf-8")
        except OSError:
            return "0+unknown"

    def get_version_from_hg():
        import subprocess

        try:
            p = subprocess.Popen(["hg", "identify", "--id", "--num", "--branch"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out, err = p.communicate()
            if p.returncode != 0:
                raise RuntimeError("hg identify failed: %s" % err)
            return out.strip().decode("utf-8")
        except OSError:
            return "0+unknown"

    def get_version_from_svn():
        import subprocess

        try:
            p = subprocess.Popen(["svn", "info"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out, err = p.communicate()
            if p.returncode != 0:
                raise RuntimeError("svn info failed: %s" % err)
            return out.strip().decode("utf-8")
        except OSError:
            return "0+unknown"

    def get_version_from_vcs():
        vcs = os.environ.get("SCM_PROVIDER", "git")
        if vcs == "git":
            return get_version_from_

def _filter_queryset(self, perms, queryset):
        """Filter object objects by permissions of user in request."""
        user = self.request.user if self.request else AnonymousUser()
        return get_objects_for_user(user, perms, queryset)

def _filter_queryset(self, perms, queryset):
        """Filter object objects by permissions of user in request."""
        if perms.user.is_superuser:
            return queryset
        if perms.user.is_anonymous:
            return queryset.none()
        return queryset.filter(
            Q(user=perms.user) | Q(group__in=perms.user.groups.all())
        )

def master_main(painter, router, select, delay):
    """
    Loop until CTRL+C is pressed, waiting for the next result delivered by the
    Select. Use parse_output() to turn that result ('ps' command output) into
    rich data, and finally repaint the screen if the repaint delay has passed.
    """
    while True:
        try:
            result = select.select()
            if result:
                painter.parse_output(result)
                painter.repaint(delay)
        except KeyboardInterrupt:
            break

def get_stats_code_frequency(self):
        """
        :calls: `GET /repos/:owner/:repo/stats/code_frequency <http://developer.github.com/v3/repos/statistics/#get-the-number-of-additions-and-deletions-per-week>`_
        :rtype: None or list of :class:`github.StatsCodeFrequency.StatsCodeFrequency`
        """
        headers, data = self._requester.requestJsonAndCheck(
            "GET",
            self.url + "/stats/code_frequency"
        )
        if not data:
            return None
        else:
            return [
                github.StatsCodeFrequency.StatsCodeFrequency(self._requester, headers, attributes, completed=True)
                for attributes in data
            ]

def time_emd(emd_type, data):
    """Time an EMD command with the given data as arguments"""

    emd = {
        'cause': _CAUSE_EMD,
        'effect': pyphi.subsystem.effect_emd,
        'hamming': pyphi.utils.hamming_emd
    }[emd_type]

    def statement():
        for (d1, d2) in data:
            emd(d1, d2)

    results = timeit.repeat(statement, number=NUMBER, repeat=REPEAT)

    return min(results)

def time_emd(emd_type, data):
    """Time an EMD command with the given data as arguments"""
    start = time.time()
    emd_type(data)
    end = time.time()
    return end - start

def prepare_encoder(inputs, hparams, attention_type="local_1d"):
  """Prepare encoder for images."""
  with tf.variable_scope("encoder"):
    if attention_type == "local_1d":
      encoder_fn = local_1d_attention_encoder
    elif attention_type == "local_2d":
      encoder_fn = local_2d_attention_encoder
    elif attention_type == "global_1d":
      encoder_fn = global_1d_attention_encoder
    elif attention_type == "global_2d":
      encoder_fn = global_2d_attention_encoder
    else:
      raise ValueError("Unknown attention type: %s" % attention_type)

    encoder_outputs, encoder_state = encoder_fn(
        inputs, hparams, attention_type=attention_type)

    return encoder_outputs, encoder_state

def keywords(soup):
    """
    Find the keywords from the set of kwd-group tags
    which are typically labelled as the author keywords
    """
    if not raw_parser.author_keywords(soup):
        return []
    return list(map(node_text, raw_parser.author_keywords(soup)))

def keywords(soup):
    """
    Find the keywords from the set of kwd-group tags
    which are typically labelled as the author keywords
    """
    keywords = []
    for kwd_group in soup.find_all('kwd-group'):
        if kwd_group.get('kwd-group-type') == 'author':
            for kwd in kwd_group.find_all('kwd'):
                keywords.append(kwd.text)
    return keywords

def to_files(self, resource, directory):
        """
        Dumps the given resource and all resources linked to it into a set of
        representation files in the given directory.
        """
        if not os.path.exists(directory):
            os.makedirs(directory)
        for representation in self.representations:
            representation.to_file(resource, directory)

def to_time_field(formatter):
    """
    Returns a callable instance that will convert a string to a Time.

    :param formatter: String that represents data format for parsing.
    :return: instance of the TimeConverter.
    """
    class TimeConverter(object):

        def __init__(self, formatter):
            self.formatter = formatter

        def __call__(self, value):
            if isinstance(value, string_types):
                value = datetime.strptime(value, self.formatter).time()

            return value

    return TimeConverter(formatter)

def add_filter_by_client(self, query, out_params):
        """Applies the filter by client to the search query
        """
        if out_params.get('client'):
            query = query.filter(Client.name == out_params['client'])
        return query

def left_hash(msg, func="HS256"):
    """ Calculate left hash as described in
    https://openid.net/specs/openid-connect-core-1_0.html#CodeIDToken
    for at_hash and in
    for c_hash

    :param msg: The message over which the hash should be calculated
    :param func: Which hash function that was used for the ID token
    """
    if func == 'HS256':
        return as_unicode(b64e(sha256_digest(msg)[:16]))
    elif func == 'HS384':
        return as_unicode(b64e(sha384_digest(msg)[:24]))
    elif func == 'HS512':
        return as_unicode(b64e(sha512_digest(msg)[:32]))

def left_hash(msg, func="HS256"):
    """ Calculate left hash as described in
    https://openid.net/specs/openid-connect-core-1_0.html#CodeIDToken
    for at_hash and in
    for c_hash

    :param msg: The message over which the hash should be calculated
    :param func: Which hash function that was used for the ID token
    """
    if func == "HS256":
        return left_hash_hs256(msg)
    elif func == "RS256":
        return left_hash_rs256(msg)
    else:
        raise ValueError("Unknown hash function")

def encode_http_params(**kw):
    """
    url paremeter encode
    """
    try:
        _fo = lambda k, v: '{name}={value}'.format(
            name=k, value=to_basestring(quote(v)))
    except:
        _fo = lambda k, v: '%s=%s' % (k, to_basestring(quote(v)))

    _en = utf8

    return '&'.join([_fo(k, _en(v)) for k, v in kw.items() if not is_empty(v)])

def encode_http_params(**kw):
    """
    url paremeter encode
    """
    params = []
    for k, v in kw.items():
        params.append('{0}={1}'.format(k, v))
    return '&'.join(params)

def get_log(self, request, response):
        """
        Return a dict of data to log for a given request and response.

        Override this method if you need to log a different set of values.
        """
        return {
            'request': {
                'method': request.method,
                'path': request.path,
                'query_params': request.GET,
                'body': request.body,
                'headers': request.headers,
            },
            'response': {
                'status_code': response.status_code,
                'headers': response.headers,
                'body': response.content,
            },
        }

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    if isinstance(x, np.ndarray) and isinstance(y, np.ndarray):
        return np.in1d(x, y, invert=True)
    else:
        return [x not in y for x in x]

def select_each(conn, query: str, parameter_groups, name=None):
    """Run select query for each parameter set in single transaction."""
    if name is None:
        name = query
    with conn.cursor() as cur:
        cur.execute(query)
        columns = [col[0] for col in cur.description]
        for parameters in parameter_groups:
            cur.execute(query, parameters)
            yield {name: [dict(zip(columns, row)) for row in cur]}

def find_packages():
    """Walk source directory tree and convert each sub directory to a
    package name.

    """
    packages = ['pyctools']
    for root, dirs, files in os.walk(os.path.join('src', 'pyctools')):
        package = '.'.join(root.split(os.sep)[1:])
        for name in dirs:
            packages.append(package + '.' + name)
    return packages

def find_packages():
    """Walk source directory tree and convert each sub directory to a
    package name.

    """
    packages = []
    for root, dirs, files in os.walk('src'):
        if '__init__.py' in files:
            packages.append(root)
    return packages

def get_app_state(device_id, app_id):
    """ Get the state of the requested app """
    if not is_valid_app_id(app_id):
        abort(403)
    if not is_valid_device_id(device_id):
        abort(403)
    if device_id not in devices:
        abort(404)
    app_state = devices[device_id].app_state(app_id)
    return jsonify(state=app_state, status=app_state)

def get_app_state(device_id, app_id):
    """ Get the state of the requested app """
    return get_app_state_by_id(device_id, app_id)

def _get_study_txt(self, goid):
        """Get GO text from GOEA study."""
        if self.go2res is not None:
            res = self.go2res.get(goid, None)
            if res is not None:
                if self.study_items is not None:
                    return self._get_item_str(res)
                else:
                    return self.pltvars.fmtres.format(
                        study_count=res.study_count)

def _get_study_txt(self, goid):
        """Get GO text from GOEA study."""
        if goid in self.study.go2obj:
            return self.study.go2obj[goid].item.name
        else:
            return None

def deferral():
    """Defers a function call when it is being required like Go.

    ::

       with deferral() as defer:
           sys.setprofile(f)
           defer(sys.setprofile, None)
           # do something.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            def defer(*args, **kwargs):
                func(*args, **kwargs)
            return defer
        return wrapper
    return decorator

def save_slope(self, rootpath, raw=False, as_int=False):
        """ Saves the magnitude of the slope to a file
        """
        if raw:
            filename = os.path.join(rootpath, 'slope_raw.txt')
        else:
            filename = os.path.join(rootpath, 'slope.txt')
        if as_int:
            np.savetxt(filename, self.slope_raw, fmt='%d')
        else:
            np.savetxt(filename, self.slope_raw)

def qmed_all_methods(self):
        """
        Returns a dict of QMED methods using all available methods.

        Available methods are defined in :attr:`qmed_methods`. The returned dict keys contain the method name, e.g.
        `amax_record` with value representing the corresponding QMED estimate in m³/s.

        :return: dict of QMED estimates
        :rtype: dict
        """
        result = {}
        for method in self.methods:
            try:
                result[method] = getattr(self, '_qmed_from_' + method)()
            except:
                result[method] = None
        return result

