        )

def send_signal(self, request, response, forum):
        """ Sends the signal associated with the view. """
        if self.signal_kwargs:
            kwargs = self.signal_kwargs
        else:
            kwargs = {}
        if self.signal_kwargs_func:
            kwargs.update(self.signal_kwargs_func(request, response, forum))
        if self.signal_sender:
            sender = self.signal_sender
        else:
            sender = self.model
        if self.signal:
            signals.post_save.send(sender=sender, instance=forum,
                                   created=request.forum_created,
                                   update_fields=request.forum_updated_fields,
                                   **kwargs)

