        """
        try:
            # func_code does not exist in Python3
            code = func.__code__
        except AttributeError:
            import warnings
            warnings.warn("Could not extract a code object for the object %r"
                          % (func,))
            return
        if code not in self.code_map:
            self.code_map[code] = {}
            self.functions.append(func)

def aggregate(self, other=None):
        """collect the furthest failure from self and other."""
        if not self.status:
            return self
        if not other:
            return self
        if not other.status:
            return other
        return Value(True, other.index, self.value + other.value, None)

def aggregate(self, other=None):
        """collect the furthest failure from self and other."""
        if other is None:
            return self
        if self.furthest_failure is None:
            return other
        if other.furthest_failure is None:
            return self
        if self.furthest_failure.distance > other.furthest_failure.distance:
            return self
        return other

def from_value(value = None):
        """
        Converts specified value into ProjectionParams.

        :param value: value to be converted

        :return: a newly created ProjectionParams.
        """
        if isinstance(value, ProjectionParams):
            return value
        array = AnyValueArray.from_value(value) if value != None else AnyValueArray()
        return ProjectionParams(array)

def from_value(value = None):
        """
        Converts specified value into ProjectionParams.

        :param value: value to be converted

        :return: a newly created ProjectionParams.
        """
        if value is None:
            return None
        elif isinstance(value, ProjectionParams):
            return value
        elif isinstance(value, dict):
            return ProjectionParams(**value)
        elif isinstance(value, str):
            return ProjectionParams(value)
        else:
            raise ValueError('Invalid value type: %s' % type(value))

def go_aspect(self, go_term):
        """
        For GO terms, returns F, C, or P corresponding to its aspect
        """
        if not go_term.startswith("GO:"):
            return None
        else:
            # Check ancestors for root terms
            if self.is_molecular_function(go_term):
                return 'F'
            elif self.is_cellular_component(go_term):
                return 'C'
            elif self.is_biological_process(go_term):
                return 'P'

def go_aspect(self, go_term):
        """
        For GO terms, returns F, C, or P corresponding to its aspect
        """
        if go_term.startswith('GO:'):
            go_term = go_term[3:]
        if go_term in self.aspects:
            return self.aspects[go_term]
        else:
            return 'C'

def _regex_span(_regex, _str, case_insensitive=True):
    """Return all matches in an input string.
    :rtype : regex.match.span
    :param _regex: A regular expression pattern.
    :param _str: Text on which to run the pattern.
    """
    if case_insensitive:
        return _regex.search(_str).span()
    else:
        return _regex.search(_str).span(0)

