def _longer_than(segments, min_dur):
    """Remove segments longer than min_dur."""
    if min_dur <= 0.:
        return segments

    long_enough = []
    for seg in segments:

        if sum([t[1] - t[0] for t in seg['times']]) >= min_dur:
            long_enough.append(seg)

    return long_enough

def _longer_than(segments, min_dur):
    """Remove segments longer than min_dur."""
    return [s for s in segments if s.duration < min_dur]

def to_ufo_propagate_font_anchors(self, ufo):
    """Copy anchors from parent glyphs' components to the parent."""

    processed = set()
    for glyph in ufo:
        _propagate_glyph_anchors(self, ufo, glyph, processed)

def to_ufo_propagate_font_anchors(self, ufo):
    """Copy anchors from parent glyphs' components to the parent."""
    for glyph in ufo:
        for component in glyph.components:
            if component.baseGlyph in ufo:
                base_glyph = ufo[component.baseGlyph]
                for anchor in base_glyph.anchors:
                    if anchor.name not in glyph.anchors:
                        glyph.anchors.append(anchor)

