def add_cohp_dict(self, cohp_dict, key_sort_func=None):
        """
        Adds a dictionary of COHPs with an optional sorting function
        for the keys.

        Args:
            cohp_dict: dict of the form {label: Cohp}

            key_sort_func: function used to sort the cohp_dict keys.
        """
        if key_sort_func:
            keys = sorted(cohp_dict.keys(), key=key_sort_func)
        else:
            keys = cohp_dict.keys()
        for label in keys:
            self.add_cohp(label, cohp_dict[label])

def add_cohp_dict(self, cohp_dict, key_sort_func=None):
        """
        Adds a dictionary of COHPs with an optional sorting function
        for the keys.

        Args:
            cohp_dict: dict of the form {label: Cohp}

            key_sort_func: function used to sort the cohp_dict keys.
        """
        if key_sort_func is None:
            key_sort_func = lambda x: x
        for key in sorted(cohp_dict.keys(), key=key_sort_func):
            self.add_cohp(cohp_dict[key])

def get_class_field(cls, field_name):
        """
        Add management of dynamic fields: if a normal field cannot be retrieved,
        check if it can be a dynamic field and in this case, create a copy with
        the given name and associate it to the model.
        """
        try:
            return cls._meta.get_field(field_name)
        except FieldDoesNotExist:
            if field_name in cls.dynamic_fields:
                field = cls.dynamic_fields[field_name]
                field.name = field_name
                cls._meta.add_field(field)
                return field
            else:
                raise

def prepend_name_scope(name, import_scope):
  """Prepends name scope to a name."""
  # Based on tensorflow/python/framework/ops.py implementation.
  if import_scope:
    try:
      str_to_replace = r"([\^]|loc:@|^)(.*)"
      return re.sub(str_to_replace, r"\1" + import_scope + r"/\2",
                    tf.compat.as_str_any(name))
    except TypeError as e:
      # If the name is not of a type we can process, simply return it.
      logging.warning(e)
      return name
  else:
    return name

def prepend_name_scope(name, import_scope):
  """Prepends name scope to a name."""
  if import_scope:
    return "%s/%s" % (import_scope, name)
  else:
    return name

def coerce_value(cls, v):
        """Coerce a value to the right type for the collection, or return it if
        it is already of the right type."""
        if isinstance(v, cls.itemtype):
            return v
        else:
            try:
                return cls.coerceitem(v)
            except Exception as e:
                raise exc.CollectionItemCoerceError(
                    itemtype=cls.itemtype,
                    colltype=cls,
                    passed=v,
                    exc=e,
                )

def coerce_value(cls, v):
        """Coerce a value to the right type for the collection, or return it if
        it is already of the right type."""
        if isinstance(v, cls):
            return v
        return cls(v)

def validate_marked_location(location):
    """Validate that a Location object is safe for marking, and not at a field."""
    if not isinstance(location, (Location, FoldScopeLocation)):
        raise TypeError(u'Expected Location or FoldScopeLocation location, got: {} {}'.format(
            type(location).__name__, location))

    if location.field is not None:
        raise GraphQLCompilationError(u'Cannot mark location at a field: {}'.format(location))

def validate_marked_location(location):
    """Validate that a Location object is safe for marking, and not at a field."""
    if location.field:
        raise ValueError("Cannot mark a field.")
    if location.location_type.name == "Field":
        raise ValueError("Cannot mark a field.")
    if location.location_type.name == "Facility":
        raise ValueError("Cannot mark a facility.")

