def hist_calls_with_dims(**dims):
    """Decorator to check the distribution of return values of a
    function with dimensions.
    """
    def hist_wrapper(fn):
        @functools.wraps(fn)
        def fn_wrapper(*args, **kwargs):
            _histogram = histogram(
                "%s_calls" % pyformance.registry.get_qualname(fn), **dims)
            rtn = fn(*args, **kwargs)
            if type(rtn) in (int, float):
                _histogram.add(rtn)
            return rtn
        return fn_wrapper
    return hist_wrapper

def hist_calls_with_dims(**dims):
    """Decorator to check the distribution of return values of a
    function with dimensions.
    """
    def hist_calls_with_dims_decorator(func):
        @wraps(func)
        def hist_calls_with_dims_wrapper(*args, **kwargs):
            return_value = func(*args, **kwargs)
            if isinstance(return_value, tuple):
                return_value = return_value[0]
            if isinstance(return_value, np.ndarray):
                return_value = return_value.flatten()
            if isinstance(return_value, list):
                return_value = np.array(return_value)
            if isinstance(return_value, np.ma.MaskedArray):
                return_value = return_value.filled()
            if isinstance(return_value, np.ndarray):
                if len(return_value.shape) == 0:
                    return_value = return_value.item()
                else:
                    return_value = return_value.flatten()
            if isinstance(return_value, np.ndarray):
