def get_property(node_uri, property_name, ossos_base=True):
    """
    Retrieves the value associated with a property on a node in VOSpace.

    @param node_uri:
    @param property_name:
    @param ossos_base:
    @return:
    """
    # Must use force or we could have a cached copy of the node from before
    # properties of interest were set/updated.
    node = client.get_node(node_uri, force=True)
    property_uri = tag_uri(property_name) if ossos_base else property_name

    if property_uri not in node.props:
        return None

    return node.props[property_uri]

def get_property(node_uri, property_name, ossos_base=True):
    """
    Retrieves the value associated with a property on a node in VOSpace.

    @param node_uri:
    @param property_name:
    @param ossos_base:
    @return:
    """
    if ossos_base:
        node_uri = node_uri.replace('http://www.opensciences.org/', 'http://ossos.opensciences.org/')
    return requests.get(node_uri + '/' + property_name).text

def search_greater(values, target):
    """
    Return the first index for which target is greater or equal to the first
    item of the tuple found in values
    """
    for i, value in enumerate(values):
        if value[0] >= target:
            return i
    return None

def _raise_on_bad_jar_filename(jar_filename):
        """Ensure that jar_filename is a valid path to a jar file."""
        if jar_filename is None:
            return

        if not isinstance(jar_filename, string_type):
            raise TypeError("jar_filename is not a string: %r" % jar_filename)

        if not os.path.exists(jar_filename):
            raise ValueError("jar_filename does not exist: %r" % jar_filename)

def _raise_on_bad_jar_filename(jar_filename):
        """Ensure that jar_filename is a valid path to a jar file."""
        if not os.path.exists(jar_filename):
            raise ValueError("jar_filename does not exist: %s" % jar_filename)
        if not os.path.isfile(jar_filename):
            raise ValueError("jar_filename is not a file: %s" % jar_filename)
        if not jar_filename.endswith(".jar"):
            raise ValueError("jar_filename does not end with .jar: %s" % jar_filename)

def infer_x(self, y):
        """Infer probable x from input y

        @param y  the desired output for infered x.
        """
        assert len(y) == self.fmodel.dim_y, "Wrong dimension for y. Expected %i, got %i" % (self.fmodel.dim_y, len(y))
        if len(self.fmodel.dataset) == 0:
            return [[0.0]*self.dim_x]
        else:
            dists, index = self.fmodel.dataset.nn_y(y, k=self.k)
            w = self._weights(dists, index)
            idx = index[np.argmax(w)]
            return [self.fmodel.dataset.get_x(idx)]

