def lang_match_xml(row, accepted_languages):
    """Find if the XML row contains acceptable language data"""
    if not accepted_languages:
        return True
    column_languages = set()
    for elem in row:
        lang = elem[0].attrib.get(XML_LANG, None)
        if lang:
            column_languages.add(lang)
    return (not column_languages) or (column_languages & accepted_languages)

def lang_match_xml(row, accepted_languages):
    """Find if the XML row contains acceptable language data"""
    if row.find('language') is not None:
        for lang in row.find('language').findall('language'):
            if lang.text in accepted_languages:
                return True
    return False

def _get_available_versions(self):
        """
        Get available versions of the package.
        :return:
        """
        solvables = self.zypper.nolock.xml.call('se', '-xv', self.name).getElementsByTagName('solvable')
        if not solvables:
            raise CommandExecutionError('No packages found matching \'{0}\''.format(self.name))

        return sorted(set([slv.getAttribute(self._attr_solvable_version)
                           for slv in solvables if slv.getAttribute(self._attr_solvable_version)]))

def _get_available_versions(self):
        """
        Get available versions of the package.
        :return:
        """
        versions = []
        for version in self.versions:
            if version.available:
                versions.append(version)
        return versions

def select_edges(docgraph, conditions, data):
    """yields all edges that meet the conditions given as eval strings"""
    for (src_id, target_id, edge_attribs) in docgraph.edges(data=True):
        # if all conditions are fulfilled
        # we need to add edge_attribs to the namespace eval is working in
        if all((eval(cond, {'edge_attribs': edge_attribs})
                for cond in conditions)):
            if data:
                yield (src_id, target_id, edge_attribs)
            else:
                yield (src_id, target_id)

def select_edges(docgraph, conditions, data):
    """yields all edges that meet the conditions given as eval strings"""
    for edge in docgraph.edges:
        if all(eval(condition, {}, data) for condition in conditions):
            yield edge

