def _collect_attrs(self, name, obj):
        """Collect all the attributes for the provided file object.
        """
        for key in obj.ncattrs():
            value = getattr(obj, key)
            fc_key = "{}/attr/{}".format(name, key)
            try:
                self.file_content[fc_key] = np2str(value)
            except ValueError:
                self.file_content[fc_key] = value

def _collect_attrs(self, name, obj):
        """Collect all the attributes for the provided file object.
        """
        attrs = {}
        for attr in dir(obj):
            if attr.startswith('_'):
                continue
            attr_value = getattr(obj, attr)
            if callable(attr_value):
                continue
            attrs[attr] = attr_value
        return attrs

def cross(self, vec):
        """Cross product with another Vector3Array"""
        if not isinstance(vec, Vector3Array):
            raise TypeError('Cross product operand must be a Vector3Array')
        if self.nV != 1 and vec.nV != 1 and self.nV != vec.nV:
            raise ValueError('Cross product operands must have the same '
                             'number of elements.')
        return Vector3Array(np.cross(self, vec))

def cross(self, vec):
        """Cross product with another Vector3Array"""
        return Vector3Array(
            [
                self[1] * vec[2] - self[2] * vec[1],
                self[2] * vec[0] - self[0] * vec[2],
                self[0] * vec[1] - self[1] * vec[0],
            ]
        )

def aprint(*values, sep=None, end='\n', flush=False, streams=None, use_stderr=False, loop=None):
    """Asynchronous equivalent to *print*."""
    if streams is None:
        streams = [sys.stdout]
    if use_stderr:
        streams.append(sys.stderr)
    if loop is None:
        loop = asyncio.get_event_loop()
    for stream in streams:
        loop.create_task(aprint_stream(stream, *values, sep=sep, end=end, flush=flush))

def guess_mime_mimedb (filename):
    """Guess MIME type from given filename.
    @return: tuple (mime, encoding)
    """
    mime, encoding = None, None
    if mimedb is not None:
        mime, encoding = mimedb.guess_type(filename, strict=False)
    if mime not in ArchiveMimetypes and encoding in ArchiveCompressions:
        # Files like 't.txt.gz' are recognized with encoding as format, and
        # an unsupported mime-type like 'text/plain'. Fix this.
        mime = Encoding2Mime[encoding]
        encoding = None
    return mime, encoding

def guess_mime_mimedb (filename):
    """Guess MIME type from given filename.
    @return: tuple (mime, encoding)
    """
    import mimetypes
    mime, encoding = mimetypes.guess_type(filename)
    if mime is None:
        mime = 'application/octet-stream'
    return mime, encoding

