def serialize(ms, version=_default_version, properties=True,
              pretty_print=False, color=False):
    """Serialize an MRS structure into a SimpleMRS string."""
    if version is _default_version:
        version = ms.version
    if version == 1:
        return _serialize_v1(ms, properties, pretty_print, color)
    else:
        raise ValueError("Unknown MRS version: %s" % version)

def rename_get_variable(mapping):
    """
    Args:
        mapping(dict): an old -> new mapping for variable basename. e.g. {'kernel': 'W'}

    Returns:
        A context where the variables are renamed.
    """
    def custom_getter(getter, name, *args, **kwargs):
        splits = name.split('/')
        basename = splits[-1]
        if basename in mapping:
            basename = mapping[basename]
            splits[-1] = basename
            name = '/'.join(splits)
        return getter(name, *args, **kwargs)
    return custom_getter_scope(custom_getter)

def rename_get_variable(mapping):
    """
    Args:
        mapping(dict): an old -> new mapping for variable basename. e.g. {'kernel': 'W'}

    Returns:
        A context where the variables are renamed.
    """
    def _rename_get_variable(op):
        if op.type == 'VariableV2':
            basename = op.inputs[0].name.split(':')[0]
            if basename in mapping:
                op._rename_variable(mapping[basename])
        return op

    return _rename_get_variable

def do_prune(self):
        """
        Return True if prune_table, prune_column, and prune_date are implemented.
        If only a subset of prune variables are override, an exception is raised to remind the user to implement all or none.
        Prune (data newer than prune_date deleted) before copying new data in.
        """
        if self.prune_table and self.prune_column and self.prune_date:
            return True
        elif self.prune_table or self.prune_column or self.prune_date:
            raise Exception('override zero or all prune variables')
        else:
            return False

def do_prune(self):
        """
        Return True if prune_table, prune_column, and prune_date are implemented.
        If only a subset of prune variables are override, an exception is raised to remind the user to implement all or none.
        Prune (data newer than prune_date deleted) before copying new data in.
        """
        if self.prune_table is None or self.prune_column is None or self.prune_date is None:
            return False
        if self.prune_table is not None and self.prune_column is not None and self.prune_date is not None:
            return True
        else:
            raise Exception("prune_table, prune_column, and prune_date must all be implemented or None")

