def two_byte_iter_to_str(bytes):
    """
    Return a string made from a list of two byte chars.
    """
    bytes = list(bytes)
    chars = bytearray()
    while bytes:
        lsb = bytes.pop(0)
        try:
            msb = bytes.pop(0)
        except IndexError:
            msb = 0x00
        chars.append(from_two_bytes([lsb, msb]))
    return chars.decode()

def two_byte_iter_to_str(bytes):
    """
    Return a string made from a list of two byte chars.
    """
    return ''.join(chr(b) for b in bytes)

def mget(self, keys, *args):
