def _get(self, key, parser_result):
        """ Given a type and a dict of parser results, return
        the items as a list.
        """
        try:
            list_data = parser_result[key].asList()
            if any(isinstance(obj, str) for obj in list_data):
                txt_lines = [''.join(list_data)]
            else:
                txt_lines = [''.join(f) for f in list_data]
        except KeyError:
            txt_lines = []
        return txt_lines

def _get(self, key, parser_result):
        """ Given a type and a dict of parser results, return
        the items as a list.
        """
        if key not in parser_result:
            return []
        if isinstance(parser_result[key], list):
            return parser_result[key]
        return [parser_result[key]]

def glob(self, pattern):
        """Iterate over this subtree and yield all existing files (of any
        kind, including directories) matching the given pattern.
        """
        for root, dirs, files in self.walk():
            for name in files:
                if fnmatch.fnmatch(name, pattern):
                    yield os.path.join(root, name)

def transformToNative(obj):
        """
        Convert comma separated periods into tuples.
        """
        if isinstance(obj, str):
            if obj.startswith('(') and obj.endswith(')'):
                return tuple(obj[1:-1].split(','))
            else:
                return obj
        elif isinstance(obj, list):
            return tuple(obj)
        else:
            return obj

def next_string(min_size, max_size):
        """
        Generates a random string, consisting of upper and lower case letters (of the English alphabet),
        digits (0-9), and symbols ("_,.:-/.[].{},#-!,$=%.+^.&*-() ").

        :param min_size: (optional) minimum string length.

        :param max_size: maximum string length.

        :return: a random string.
        """
        import random
        import string
        import sys

        if min_size < 0:
            raise ValueError("min_size must be greater than or equal to 0")
        if max_size < min_size:
            raise ValueError("max_size must be greater than or equal to min_size")

        if sys.version_info[0] < 3:
            symbols = string.letters + string.digits + string.punctuation
        else:
            symbols = string.ascii_letters + string.digits + string.punctuation

        return ''.join(random.choice(symbols) for _ in range(random.randint(min_size, max_size)))

def full_id(self):
        """Return the full_id for this Async. Consists of the parent id, id and
        context id.
        """
        full_id = ""

        if self.parent_id:
            full_id = ":".join([self.parent_id, self.id])
        else:
            full_id = self.id

        if self.context_id:
            full_id = "|".join([full_id, self.context_id])

        return full_id

def _fill_role_cache(self, principal, overwrite=False):
        """Fill role cache for `principal` (User or Group), in order to avoid
        too many queries when checking role access with 'has_role'.

        Return role_cache of `principal`
        """
        if not self.app_state.use_cache:
            return None

        if not self._has_role_cache(principal) or overwrite:
            self._set_role_cache(principal, self._all_roles(principal))
        return self._role_cache(principal)

def _fill_role_cache(self, principal, overwrite=False):
        """Fill role cache for `principal` (User or Group), in order to avoid
        too many queries when checking role access with 'has_role'.

        Return role_cache of `principal`
        """
        if not overwrite and principal.role_cache is not None:
            return principal.role_cache

        role_cache = {}
        for role in principal.roles:
            role_cache[role.name] = role
        principal.role_cache = role_cache
        return role_cache

