def setDaemon(self, runnable, isdaemon, noregister = False):
        """
        If a runnable is a daemon, it will not keep the main loop running. The main loop will end when all alived runnables are daemons.
        """
        if not noregister and runnable not in self.registerIndex:
            self.register((), runnable)
        if isdaemon:
            self.daemons.add(runnable)
        else:
            self.daemons.discard(runnable)

def setDaemon(self, runnable, isdaemon, noregister = False):
        """
        If a runnable is a daemon, it will not keep the main loop running. The main loop will end when all alived runnables are daemons.
        """
        if not isinstance(runnable, Runnable):
            raise TypeError("runnable must be a Runnable")
        if not isinstance(isdaemon, bool):
            raise TypeError("isdaemon must be a bool")
        if not noregister:
            self.register(runnable)
        runnable.setDaemon(isdaemon)

def send(self, encoded_frame):
        """
        :param bytes encoded_frame:
        """
        if self.socket is not None:
            try:
                with self.__socket_semaphore:
                    self.socket.sendall(encoded_frame)
            except Exception:
                _, e, _ = sys.exc_info()
                log.error("Error sending frame", exc_info=1)
                raise e
        else:
            raise exception.NotConnectedException()

def removeFriend(self, friend_id=None):
        """
        Removes a specifed friend from your friend list

        :param friend_id: The ID of the friend that you want to remove
        :return: Returns error if the removing was unsuccessful, returns True when successful.
        """
        if friend_id is None:
            raise ValueError("You must specify a friend ID")
        if not isinstance(friend_id, int):
            raise ValueError("Friend ID must be an integer")
        if friend_id == self.user_id:
            raise ValueError("You cannot remove yourself from your friend list")
        if friend_id not in self.friends:
            raise ValueError("You are not friends with this user")
        self.friends.remove(friend_id)
        return True

def get_utc_timestamp(dt):
    """
    Returns the Timestamp/DatetimeIndex
    with either localized or converted to UTC.

    Parameters
    ----------
    dt : Timestamp/DatetimeIndex
        the date(s) to be converted

    Returns
    -------
    same type as input
        date(s) converted to UTC
    """
    if isinstance(dt, pd.Timestamp):
        return dt.tz_localize('UTC')
    elif isinstance(dt, pd.DatetimeIndex):
        return dt.tz_localize('UTC')
    else:
        raise TypeError('Input must be a Timestamp or DatetimeIndex')

def source_pipe(self, source, ps=None):
        """Create a source pipe for a source, giving it access to download files to the local cache"""

        if isinstance(source, string_types):
            source = self.source(source)

        source.dataset = self.dataset
        source._bundle = self

        iter_source, source_pipe = self._iterable_source(source, ps)

        if self.limited_run:
            source_pipe.limit = 500

        return iter_source, source_pipe

def source_pipe(self, source, ps=None):
        """Create a source pipe for a source, giving it access to download files to the local cache"""
        if ps is None:
            ps = self.pipeline_state
        if ps.source_pipe is None:
            ps.source_pipe = self.create_source_pipe(source)
        return ps.source_pipe

def call(self, obj, method, *args, **selectors):
        """
        This keyword can use object method from original python uiautomator

        See more details from https://github.com/xiaocong/uiautomator

        Example:

        | ${accessibility_text} | Get Object            | text=Accessibility | # Get the UI object                        |
        | Call                  | ${accessibility_text} | click              | # Call the method of the UI object 'click' |
        """
        func = getattr(obj, method)
        return func(**selectors)

