def get_files_to_remove(self):
        """
        Returns orphaned media files to be removed grouped by resource type.
        All files which paths start with any of exclude paths are ignored.
        """
        files_to_remove = {}
        needful_files = self.get_needful_files()
        for resources_type, resources in self.get_uploaded_resources():
            exclude_paths = self.get_exclude_paths()
            resources = {resource for resource in resources if not resource.startswith(exclude_paths)}
            files_to_remove[resources_type] = resources - needful_files
        return files_to_remove

def get_files_to_remove(self):
        """
        Returns orphaned media files to be removed grouped by resource type.
        All files which paths start with any of exclude paths are ignored.
        """
        files_to_remove = {}
        for resource_type in self.resource_types:
            files_to_remove[resource_type] = []
            for file_path in self.get_files_to_remove_for_resource_type(resource_type):
                if not self.is_excluded(file_path):
                    files_to_remove[resource_type].append(file_path)
        return files_to_remove

def number_of_interactions(records, direction=None):
    """
    The number of interactions.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing.
    """
    if direction is None:
        return len(records)
    else:
        return len([r for r in records if r.direction == direction])

def number_of_interactions(records, direction=None):
    """
    The number of interactions.

    Parameters
    ----------
    direction : str, optional
        Filters the records by their direction: ``None`` for all records,
        ``'in'`` for incoming, and ``'out'`` for outgoing.
    """
    if direction is None:
        return len(records)
    elif direction == 'in':
        return len([r for r in records if r.direction == 'in'])
    elif direction == 'out':
        return len([r for r in records if r.direction == 'out'])
    else:
        raise ValueError('Invalid direction: {}'.format(direction))

def serialize(obj, **options):
    """
    Serialize Python data to JSON.

    :param obj: the data structure to serialize
    :param options: options given to lower json/simplejson module.
    """

    try:
        if 'fp' in options:
            return salt.utils.json.dump(obj, _json_module=_json, **options)
        else:
            return salt.utils.json.dumps(obj, _json_module=_json, **options)
    except Exception as error:
        raise SerializationError(error)

def wait(self, pattern, timeout=10.0, safe=False, **match_kwargs):
        """Wait till pattern is found or time is out (default: 10s)."""
        t = time.time() + timeout
        while time.time() < t:
            ret = self.exists(pattern, **match_kwargs)
            if ret:
                return ret
            time.sleep(0.2)
        if not safe:
            raise errors.ImageNotFoundError('Not found image %s' %(pattern,))

def wait(self, pattern, timeout=10.0, safe=False, **match_kwargs):
        """Wait till pattern is found or time is out (default: 10s)."""
        if not isinstance(pattern, Pattern):
            pattern = self.convert_pattern_to_regex(pattern)
        if safe:
            return self.wait_for_safe(pattern, timeout, **match_kwargs)
        else:
            return self.wait_for(pattern, timeout, **match_kwargs)

def roles_required(*required_rolenames):
    """
    This decorator ensures that any uses accessing the decorated route have all
    the needed roles to access it. If an @auth_required decorator is not
    supplied already, this decorator will implicitly check @auth_required first
    """
    def decorator(method):
        @functools.wraps(method)
        def wrapper(*args, **kwargs):
            role_set = set([str(n) for n in required_rolenames])
            _verify_and_add_jwt()
            try:
                MissingRoleError.require_condition(
                    current_rolenames().issuperset(role_set),
                    "This endpoint requires all the following roles: {}",
                    [', '.join(role_set)],
                )
                return method(*args, **kwargs)
            finally:
                remove_jwt_data_from_app_context()
        return wrapper
    return decorator

def roles_required(*required_rolenames):
    """
    This decorator ensures that any uses accessing the decorated route have all
    the needed roles to access it. If an @auth_required decorator is not
    supplied already, this decorator will implicitly check @auth_required first
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if not current_user.is_authenticated:
                return redirect(url_for('auth.login'))
            if not current_user.has_roles(*required_rolenames):
                abort(403)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _createStatsDict(self, headers, rows):
        """Utility method that returns database stats as a nested dictionary.

        @param headers: List of columns in query result.
        @param rows:    List of rows in query result.
        @return:        Nested dictionary of values.
                        First key is the database name and the second key is the 
                        statistics counter name. 

        """
        dbstats = {}
        for row in rows:
            dbstats[row[0]] = dict(zip(headers[1:], row[1:]))
        return dbstats

def _createStatsDict(self, headers, rows):
        """Utility method that returns database stats as a nested dictionary.

        @param headers: List of columns in query result.
        @param rows:    List of rows in query result.
        @return:        Nested dictionary of values.
                        First key is the database name and the second key is the 
                        statistics counter name. 

        """
        statsDict = {}
        for row in rows:
            dbName = row[0]
            statsDict[dbName] = {}
            for i in range(1, len(headers)):
                statsDict[dbName][headers[i]] = row[i]
        return statsDict

