def convert_enum(func):
    """
    Decorator to use Enum value on type casts.
    """

    @wraps(func)
    def inner(self, value):
        try:
            if self.check_value(value.value):
                return value.value
            return func(self, value.value)
        except AttributeError:
            pass

        return func(self, value)

    return inner

def convert_enum(func):
    """
    Decorator to use Enum value on type casts.
    """
    def wrapper(self, value):
        if isinstance(value, Enum):
            value = value.value
        return func(self, value)
    return wrapper

def get(self, name=None):
        """Get initial yield value, or result of send(name) if name given."""
        if name is None:
            return self.init_value
        elif not self.support_name:
            msg = "generator does not support get-by-name: function {!r}"
            raise TypeError(msg.format(self.function))
        try:
            value = self.generator.send(name)
        except StopIteration:
            msg = "generator didn't yield: function {!r}"
            raise RuntimeError(msg.format(self.function))
        return value

def get(self, name=None):
        """Get initial yield value, or result of send(name) if name given."""
        if name is None:
            return self.yield_value
        else:
            return self.send(name)

def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        self._store_type = store_type
        if store_type == PUBLIC_KEY_STORE_TYPE_HEX:
            self._value = value.hex()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE64:
            self._value = b64encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE85:
            self._value = b85encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_JWK:
            # TODO: need to decide on which jwk library to import?
            raise NotImplementedError
        else:
            self._value = value
        return value

def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        if store_type == 'string':
            self.set_encode_key_value_string(value)
        elif store_type == 'integer':
            self.set_encode_key_value_integer(value)
        elif store_type == 'float':
            self.set_encode_key_value_float(value)
        elif store_type == 'boolean':
            self.set_encode_key_value_boolean(value)
        elif store_type == 'date':
            self.set_encode_key_value_date(value)
        elif store_type == 'datetime':
            self.set_encode_key_value_datetime(value)
        elif store_type == 'time':
            self.set_encode_key_value_time(value)
        elif store_type == 'json':
            self.set_encode_key_value_json(value)
        elif store_type == 'array':
            self.set_encode_key_value_array(value)
        elif store_type == 'object':
            self.set_encode_key_value_object(value)
        elif store_type == 'binary':
            self.set_encode_key_value_binary(value)
        else:
            raise ValueError('Unknown store type: %s' % store_type)

def get_config(ini_path=None, rootdir=None):
    """ Load configuration from INI.

    :return Namespace:

    """
    config = Namespace()
    config.default_section = 'pylama'

    if not ini_path:
        path = get_default_config_file(rootdir)
        if path:
            config.read(path)
    else:
        config.read(ini_path)

    return config

def get_config(ini_path=None, rootdir=None):
    """ Load configuration from INI.

    :return Namespace:

    """
    if ini_path is None:
        ini_path = os.path.join(rootdir, 'config.ini')

    if not os.path.exists(ini_path):
        raise IOError('Configuration file not found: {}'.format(ini_path))

    config = configparser.ConfigParser()
    config.read(ini_path)

    # Get the configuration
    config_dict = {}
    for section in config.sections():
        config_dict[section] = {}
        for key, value in config.items(section):
            config_dict[section][key] = value

    # Convert to a Namespace
    config_ns = Namespace()
    for section in config_dict:
        for key, value in config_dict[section].items():
            setattr(config_ns, key, value)

    return config_ns

def dict_merged(d, _filter=None, **kw):
    """Update dictionary d with the items passed as kw if the value passes _filter."""
    def f(s):
        if _filter:
            return _filter(s)
        return s is not None
    d = d or {}
    for k, v in iteritems(kw):
        if f(v):
            d[k] = v
    return d

def dict_merged(d, _filter=None, **kw):
    """Update dictionary d with the items passed as kw if the value passes _filter."""
    if _filter is None:
        _filter = lambda x: True
    for k, v in kw.items():
        if _filter(v):
            d[k] = v
    return d

