def location_on_land(self, coords_only=False):
        """Returns a random tuple specifying a coordinate set guaranteed to exist on land.
        Format is `(latitude, longitude, place name, two-letter country code, timezone)`
        Pass `coords_only` to return coordinates without metadata.
        """
        while True:
            lat, lon = self.latitude_longitude()
            if self.on_land(lat, lon):
                if coords_only:
                    return lat, lon
                else:
                    return lat, lon, self.place_name(lat, lon), self.country_code(lat, lon), self.timezone(lat, lon)

def next_on(context, rrevent=None):
    """
    Displays when the next occurence of a recurring event will be.  If the
    recurring event is not specified it is assumed to be the current page.
    """
    request = context['request']
    if rrevent is None:
        rrevent = context.get('page')
    eventNextOn = getattr(rrevent, '_nextOn', lambda _:None)
    return eventNextOn(request)

def next_on(context, rrevent=None):
    """
    Displays when the next occurence of a recurring event will be.  If the
    recurring event is not specified it is assumed to be the current page.
    """
    if rrevent is None:
        rrevent = context['this']
    if rrevent.recurring_event_id is None:
        return ''
    return rrevent.next_on

def _host_libc(self):
    """Use the --libc-dir option if provided, otherwise invoke a host compiler to find libc dev."""
    libc_dir_option = self.get_options().libc_dir
    if libc_dir_option:
      maybe_libc_crti = os.path.join(libc_dir_option, self._LIBC_INIT_OBJECT_FILE)
      if os.path.isfile(maybe_libc_crti):
        return HostLibcDev(crti_object=maybe_libc_crti,
                           fingerprint=hash_file(maybe_libc_crti))
      raise self.HostLibcDevResolutionError(
        "Could not locate {} in directory {} provided by the --libc-dir option."
        .format(self._LIBC_INIT_OBJECT_FILE, libc_dir_option))

    return self._get_host_libc_from_host_compiler()

def _host_libc(self):
    """Use the --libc-dir option if provided, otherwise invoke a host compiler to find libc dev."""
    if self.options.libc_dir:
        return self.options.libc_dir
    else:
        return self.default_libc_dir()

def rs_simple_encode_msg(msg_in, nsym, fcr=0, generator=2, gen=None):
    """Simple Reed-Solomon encoding (mainly an example for you to understand how it works, because it's slower than the inlined function below)"""
    if gen is None:
        gen = rs_gen_matrix(nsym, fcr, generator)
    msg_out = []
    for i in range(len(msg_in)):
        msg_out.append(msg_in[i] ^ gen[i])
    return msg_out

def filter(self, record):
        """Determines if the record should be logged and injects context info into the record. Always returns True"""
        fmt = LogManager.spec.context_format
        if fmt:
            data = self.context.to_dict()
            if data:
                record.context = fmt % ",".join("%s=%s" % (key, val) for key, val in sorted(data.items()) if key and val)
            else:
                record.context = ""
        return True

