            message.path.append(destination)
        return message

def trace_generator(trace, start=0, stop=None, step=1):
    """Return a generator returning values from the object's trace.

    Ex:
    T = trace_generator(theta.trace)
    T.next()
    for t in T:...
    """
    if stop is None:
        stop = len(trace)
    return itertools.islice(trace, start, stop, step)

def moving_average(data, periods, type='simple'):
    """
    compute a <periods> period moving average.
    type is 'simple' | 'exponential'
    """
    if type == 'simple':
        return data.rolling(periods).mean()
    elif type == 'exponential':
        return data.ewm(span=periods).mean()
    else:
        raise ValueError('type must be "simple" or "exponential"')

