        """
        For a given script, iterate over and pull out public pairs encoded as sec values.
        """
        for i, (pubkey, sig) in enumerate(generator):
            yield (pubkey, sig)

def _tupleCompare(tuple1, ineq, tuple2,
                 eq=lambda a,b: (a==b),
                 ander=AND,
                 orer=OR):
    """
    Compare two 'in-database tuples'.  Useful when sorting by a compound key
    and slicing into the middle of that query.
    """
    if tuple1 is None:
        return tuple2 is None
    if tuple2 is None:
        return False
    if len(tuple1) != len(tuple2):
        return False
    for i in range(len(tuple1)):
        if not eq(tuple1[i], tuple2[i]):
            return ineq(tuple1[i], tuple2[i])
    return True

def get_attribute(self, obj, attr):
        """Get attribute of given object instance.

        Reason for existence of this method is the fact that  'attribute' can
        be also object's key from if is a dict or any other kind of mapping.

        Note: it will return None if attribute key does not exist

        Args:
            obj (object): internal object to retrieve data from

        Returns:
            internal object's key value or attribute

        """
        if isinstance(obj, dict):
            return obj.get(attr)
        else:
            return getattr(obj, attr, None)

