def get_event(self):
        """return next event or None"""
        if self.event_queue.qsize() == 0:
            return None
        evt = self.event_queue.get()
        while isinstance(evt, win_layout.WinLayout):
            win_layout.set_layout(evt, self.set_layout)
            if self.event_queue.qsize() == 0:
                return None
            evt = self.event_queue.get()
        return evt

def get_event(self):
        """return next event or None"""
        if self.events:
            return self.events.pop(0)
        return None

