def get_roles(self):
        """Get the roles associated with the hosts.

        Returns
            dict of role -> [host]
        """
        roles = {}
        for host in self.hosts:
            for role in host.roles:
                if role not in roles:
                    roles[role] = []
                roles[role].append(host)
        return roles

def interpretBitEncoding(bitEncoding):
    """Returns a floattype string and a numpy array type.

    :param bitEncoding: Must be either '64' or '32'

    :returns: (floattype, numpyType)
    """
    if bitEncoding == '64':
        floattype = 'd' # 64-bit
        numpyType = numpy.float64
    elif bitEncoding == '32':
        floattype = 'f' # 32-bit
        numpyType = numpy.float32
    else:
        errorText = ''.join(['bitEncoding \'', bitEncoding, '\' not defined. ',
                             'Must be \'64\' or \'32\''
                             ])
        raise TypeError(errorText)
    return (floattype, numpyType)

def interpretBitEncoding(bitEncoding):
    """Returns a floattype string and a numpy array type.

    :param bitEncoding: Must be either '64' or '32'

    :returns: (floattype, numpyType)
    """
    if bitEncoding == '64':
        return 'float64', np.float64
    elif bitEncoding == '32':
        return 'float32', np.float32
    else:
        raise ValueError('bitEncoding must be either 64 or 32')

def do_server(self, arg):
        """
        Usage:
          server on
          server off
          server restart
          server log
          server help
        """
        if arg['on']:
            self.server_on()
        elif arg['off']:
            self.server_off()
        elif arg['restart']:
            self.server_restart()
        elif arg['log']:
            self.server_log()
        else:
            self.help_server()

def do_server(self, arg):
        """
        Usage:
          server on
          server off
          server restart
          server log
          server help
        """
        if arg == 'on':
            self.server.start()
        elif arg == 'off':
            self.server.stop()
        elif arg == 'restart':
            self.server.restart()
        elif arg == 'log':
            self.server.log()
        else:
            self.do_help('server')

def serialize_me(self, arn, event_time, tech, item=None):
        """Dumps the proper JSON for the schema. If the event is too big, then don't include the item.

        :param arn:
        :param event_time:
        :param tech:
        :param item:
        :return:
        """
        payload = {
            'arn': arn,
            'event_time': event_time,
            'tech': tech
        }

        if item:
            payload['item'] = item

        else:
            payload['event_too_big'] = True

        return self.dumps(payload).data.replace('<empty>', '')

def serialize_me(self, arn, event_time, tech, item=None):
        """Dumps the proper JSON for the schema. If the event is too big, then don't include the item.

        :param arn:
        :param event_time:
        :param tech:
        :param item:
        :return:
        """
        if item is None:
            return {
                'arn': arn,
                'event_time': event_time,
                'tech': tech
            }
        else:
            return {
                'arn': arn,
                'event_time': event_time,
                'tech': tech,
                'item': item
            }

