def add_part(self, part):
        """
        Function for adding partial pattern to the value
        :param part: string or compiled pattern
        """
        if isinstance(part, RE_TYPE):
            part = part.pattern

        # Allow U / spmething syntax
        if self == '^$':
            return URLPattern(part, self.separator)
        else:
            # Erase dup separator inbetween
            sep = self.separator
            return URLPattern(self.rstrip('$' + sep) + sep + part.lstrip(sep),
                              sep)

def add_part(self, part):
        """
        Function for adding partial pattern to the value
        :param part: string or compiled pattern
        """
        if isinstance(part, str):
            self.value += part
        else:
            self.value += part.pattern

def _op(self, _, obj, app):
        """ convert status code in Responses from int to string
        """
        if obj.responses == None: return 

        tmp = {}
        for k, v in six.iteritems(obj.responses):
            if isinstance(k, six.integer_types):
                tmp[str(k)] = v
            else:
                tmp[k] = v
        obj.update_field('responses', tmp)

def _op(self, _, obj, app):
        """ convert status code in Responses from int to string
        """
        if isinstance(obj, int):
            return str(obj)
        return obj

def _AddVariable(self, variable):
        """
        Add a variable to the model. Should not be used by end-user
        """
        if isinstance(variable, Signal):
            if not variable in self.signals:
                self.signals.append(variable)
        elif isinstance(variable, Variable):
            if not variable in self.variables:
                self.variables.append(variable)
        else:
            raise TypeError
        self._utd_graph = False

