            "/api/v2/groups/activity/{}/{}/".format(module, project),
            **kwargs
        )

def get(self, path, data=None):
        """Executes a GET.

        'path' may not be None. Should include the full path to the
        resource.
        'data' may be None or a dictionary. These values will be
        appended to the path as key/value pairs.

        Returns a named tuple that includes:

        status: the HTTP status code
        json: the returned JSON-HAL

        If the key was not set, throws an APIConfigurationException."""
        if data is None:
            data = {}
        if path is None:
            raise APIConfigurationException("path must be set")
        if not isinstance(data, dict):
            raise APIConfigurationException("data must be a dictionary")
        url = self.base_url + path
        for key, value in data.items():
            url += "&" + key + "=" + value
        response = requests.get(url, headers=self.headers)
        return self._handle_response(response)

def validate_token(self, token):
    """retrieve a subject based on a token. Valid means we return a participant
       invalid means we return None
    """
    try:
        payload = jwt.decode(token, self.secret_key, algorithms=['HS256'])
        return payload['sub']
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def parse_data(self, logfile):
        """Parse data from data stream and replace object lines.

        :param logfile: [required] Log file data stream.
        :type logfile: str
        """

        for line in logfile:
            stripped_line = line.strip()
            parsed_line = Line(stripped_line)

            if parsed_line.valid:
                self._valid_lines.append(parsed_line)
            else:
                self._invalid_lines.append(stripped_line)
        self.total_lines = len(self._valid_lines) + len(self._invalid_lines)

def concretize_write_addr(self, addr, strategies=None):
        """
        Concretizes an address meant for writing.

            :param addr:            An expression for the address.
            :param strategies:      A list of concretization strategies (to override the default).
            :returns:               A list of concrete addresses.
        """

        if isinstance(addr, int):
            return [ addr ]
        elif not self.state.solver.symbolic(addr):
            return [ self.state.solver.eval(addr) ]

        strategies = self.write_strategies if strategies is None else strategies
        return self._apply_concretization_strategies(addr, strategies, 'store')

def concretize_write_addr(self, addr, strategies=None):
        """
        Concretizes an address meant for writing.

            :param addr:            An expression for the address.
            :param strategies:      A list of concretization strategies (to override the default).
            :returns:               A list of concrete addresses.
        """
        if strategies is None:
            strategies = self.write_addr_strategies
        return self.concretize(addr, strategies)

def bind(self, **kwargs):
        """
        creates a copy of the object without the
        cached results and with the given keyword
        arguments as properties.
        """
        d = dict(self.__dict__)
        for k in d.keys():
            if k[0] == '_':
                del d[k]
            elif k.startswith('obj_'):
                d[k] = d[k].bind(**kwargs)
        d.update(kwargs)
        return self.__class__(**d)

