def remove_transition(self, transition_id, destroy=True):
        """Removes a transition from the container state

        :param transition_id: the id of the transition to remove
        :raises exceptions.AttributeError: if the transition_id is already used
        """
        if transition_id == -1 or transition_id == -2:
            raise AttributeError("The transition_id must not be -1 (Aborted) or -2 (Preempted)")
        if transition_id not in self._transitions:
            raise AttributeError("The transition_id %s does not exist" % str(transition_id))

        self.transitions[transition_id].parent = None
        return self.transitions.pop(transition_id)

def remove_transition(self, transition_id, destroy=True):
        """Removes a transition from the container state

        :param transition_id: the id of the transition to remove
        :raises exceptions.AttributeError: if the transition_id is already used
        """
        if transition_id in self.transitions:
            if destroy:
                self.transitions[transition_id].destroy()
            del self.transitions[transition_id]
        else:
            raise exceptions.AttributeError(
                "Transition with id {} does not exist".format(transition_id))

def install(name, link, path, priority):
    """
    Install symbolic links determining default commands

    CLI Example:

    .. code-block:: bash

        salt '*' alternatives.install editor /usr/bin/editor /usr/bin/emacs23 50
    """
    ret = {}
    if not __salt__["alternatives.exists"](name):
        if __salt__["alternatives.install"](name, link, path, priority):
            ret["result"] = True
            ret["comment"] = "Installed {0}".format(name)
        else:
            ret["result"] = False
            ret["comment"] = "Failed to install {0}".format(name)
    else:
        ret["result"] = True
        ret["comment"] = "Alternative {0} already installed".format(name)
    return ret

