def drop_message(self, message):
        """Drop the given message object from the appropriate message list.

        Returns True if the message was found, otherwise False."""

        for type_ in 'errors', 'warnings', 'notices':
            list_ = getattr(self, type_)
            if message in list_:
                list_.remove(message)
                if 'signing_severity' in message:
                    self.signing_summary[message['signing_severity']] -= 1
                return True

        return False

def drop_message(self, message):
        """Drop the given message object from the appropriate message list.

        Returns True if the message was found, otherwise False."""
        if message.type == 'request':
            return self.drop_request(message)
        elif message.type == 'response':
            return self.drop_response(message)
        elif message.type == 'event':
            return self.drop_event(message)
        else:
            raise ValueError('Unknown message type: %s' % message.type)

def do_map(input_dict, feature_format, positive_class=None):
    """
    Maps a new example to a set of features.
    """
    if feature_format == 'dict':
        return input_dict
    elif feature_format == 'list':
        return [input_dict[feature] for feature in feature_format]
    elif feature_format == 'list_of_dict':
        return [input_dict[feature][positive_class] for feature in feature_format]
    else:
        raise ValueError('feature_format must be one of "dict", "list", or "list_of_dict"')

def wait_for_job(self, job, poll=5):
        """Wait for an Amazon SageMaker training job to complete.

        Args:
            job (str): Name of the training job to wait for.
            poll (int): Polling interval in seconds (default: 5).

        Returns:
            (dict): Return value from the ``DescribeTrainingJob`` API.

        Raises:
            ValueError: If the training job fails.
        """
        waiter = self.sagemaker_client.get_waiter("training_job_completed_or_stopped")
        try:
            waiter.wait(TrainingJobName=job, WaiterConfig={"Delay": poll, "MaxAttempts": None})
        except botocore.exceptions.WaiterError as e:
            if e.last_response["TrainingJobStatus"] == "Stopped":
                raise ValueError(
                    "Training job {} stopped with failure reason: {}".format(
                        job, e.last_response["FailureReason"]
                    )
                )
            else:
                raise ValueError(
                    "Training job {} failed with failure reason: {}".format(
                        job, e.last_response["FailureReason"]
                    )
                )
        return self.sagemaker_client.describe_training_job(TrainingJobName=job)

