def _sample_as_dict(self, sample):
        """Convert list-like ``sample`` (list/dict/dimod.SampleView),
        ``list: var``, to ``map: idx -> var``.
        """
        if isinstance(sample, dict):
            return sample
        if isinstance(sample, (list, numpy.ndarray)):
            sample = enumerate(sample)
        return dict(sample)

def _sample_as_dict(self, sample):
        """Convert list-like ``sample`` (list/dict/dimod.SampleView),
        ``list: var``, to ``map: idx -> var``.
        """
        if isinstance(sample, dict):
            return sample
        elif isinstance(sample, list):
            return {idx: v for idx, v in enumerate(sample)}
        elif isinstance(sample, dimod.SampleView):
            return sample.to_dict()
        else:
            raise TypeError("sample must be a list, dict, or dimod.SampleView")

def getElementById(self, _id):
        """
            getElementById - Gets an element within this collection by id

            @param _id - string of "id" attribute

            @return - a single tag matching the id, or None if none found
        """
        for tag in self:
            if tag.id == _id:
                return tag
            for subtag in tag.children:
                tmp = subtag.getElementById(_id)
                if tmp is not None:
                    return tmp
        return None

def getElementById(self, _id):
        """
            getElementById - Gets an element within this collection by id

            @param _id - string of "id" attribute

            @return - a single tag matching the id, or None if none found
        """
        return self.find(lambda x: x.getAttribute("id") == _id)

def _recv_thread(self):
        """
        Internal thread to iterate over source messages and dispatch callbacks.
        """
        for msg, metadata in self._source:
            if msg.msg_type:
                self._call(msg, **metadata)
        # Break any upstream iterators
        for sink in self._sinks:
            i = sink()
            if i is not None:
                i.breakiter()
        self._dead = True

def _recv_thread(self):
        """
        Internal thread to iterate over source messages and dispatch callbacks.
        """
        while True:
            try:
                msg = self.source.recv()
                self.callback(msg)
            except Exception as e:
                self.logger.error(e)

def _get_binding_keys(self, port, host):
        """Get binding keys from the port binding"""
        binding_keys = list()
        switch_binding = port[portbindings.PROFILE].get(
            'local_link_information', None)
        if switch_binding:
            for binding in switch_binding:
                switch_id = binding.get('switch_id')
                port_id = binding.get('port_id')
                binding_keys.append((port['id'], (switch_id, port_id)))
        else:
            binding_keys.append((port['id'], host))
        return binding_keys

def _get_binding_keys(self, port, host):
        """Get binding keys from the port binding"""
        return [
            self._get_binding_key(port, host, key)
            for key in self.binding_keys
        ]

