def read_word_data(self, i2c_addr, register, force=None):
        """
        Read a single word (2 bytes) from a given register.

        :param i2c_addr: i2c address
        :type i2c_addr: int
        :param register: Register to read
        :type register: int
        :param force:
        :type force: Boolean
        :return: 2-byte word
        :rtype: int
        """
        if force is None:
            force = self.force_read
        if force:
            self.i2c.write_byte(i2c_addr, register)
            return self.i2c.read_word_data(i2c_addr, register)
        else:
            return self.i2c.read_word_data(i2c_addr, register)

