def when_file_changed(*filenames, **kwargs):
    """
    Register the decorated function to run when one or more files have changed.

    :param list filenames: The names of one or more files to check for changes
        (a callable returning the name is also accepted).
    :param str hash_type: The type of hash to use for determining if a file has
        changed.  Defaults to 'md5'.  Must be given as a kwarg.
    """
    hash_type = kwargs.pop('hash_type', 'md5')
    if kwargs:
        raise TypeError('when_file_changed() got unexpected keyword argument(s): ' + ', '.join(kwargs))

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if any(file_changed(filename, hash_type) for filename in filenames):
                func(*args, **kwargs)
        return wrapper
    return decorator

def getElementsByTagName(self, tagName):
        """
            getElementsByTagName - Gets elements within this collection having a specific tag name

            @param tagName - String of tag name

            @return - TagCollection of unique elements within this collection with given tag name
        """
        ret = TagCollection()
        if len(self) == 0:
            return ret

        tagName = tagName.lower()
        _cmpFunc = lambda tag : bool(tag.tagName == tagName)

        for tag in self:
            TagCollection._subset(ret, _cmpFunc, tag)

        return ret

def getElementsByTagName(self, tagName):
        """
            getElementsByTagName - Gets elements within this collection having a specific tag name

            @param tagName - String of tag name

            @return - TagCollection of unique elements within this collection with given tag name
        """
        return TagCollection(self.driver, self.driver.execute_script("return arguments[0].getElementsByTagName(arguments[1]);", self.element, tagName))

def find_first_regex_match(key, regex_candidates):
    """
    find the first regex that match with the key
    :param key: a key to try to match against multiple regex
    :param match_candidates: a list of regexes to check if they match the key
    :return: the first candidate found
    """
    for cand in regex_candidates:
        try:
            pattern = re.compile(cap_match_string(cand))
            if pattern.match(key):
                return cand
        except:
            logging.warn('[ros_interface] Ignoring invalid regex string "{0!s}"!'.format(cand))

    return None

def resolve(self, working_set=None):
    """Resolves any configured plugins and adds them to the global working set.

    :param working_set: The working set to add the resolved plugins to instead of the global
                        working set (for testing).
    :type: :class:`pkg_resources.WorkingSet`
    """
    working_set = working_set or global_working_set
    if self._plugin_requirements:
      for plugin_location in self._resolve_plugin_locations():
        if self._is_wheel(plugin_location):
          plugin_location = self._activate_wheel(plugin_location)
        working_set.add_entry(plugin_location)
    return working_set

def resolve(self, working_set=None):
    """Resolves any configured plugins and adds them to the global working set.

    :param working_set: The working set to add the resolved plugins to instead of the global
                        working set (for testing).
    :type: :class:`pkg_resources.WorkingSet`
    """
    if working_set is None:
        working_set = pkg_resources.working_set

    for plugin in self.plugins:
        if plugin.name in working_set.by_key:
            continue

        if plugin.name in self.resolved_plugins:
            continue

        self.resolved_plugins.add(plugin.name)

        if plugin.path is None:
            plugin.path = os.path.join(self.plugin_dir, plugin.name)

        if not os.path.exists(plugin.path):
            raise PluginNotFoundError(plugin.name)

        if not os.path.isdir(plugin.path):
            raise PluginNotFoundError(plugin.name)

        if plugin.version is None:
            plugin.version = self.get_plugin_version(plugin.path)

        if plugin.version is None:
            raise PluginNotFoundError(plugin.name)

        if plugin.name in self.plugin_versions:
            if plugin.version != self.plugin_versions[plugin.name]:
                raise PluginVersionMismatchError(plugin.name, plugin.version, self.plugin_versions[plugin.name])
        else:
            self.plugin_versions[plugin.name] = plugin.version

        working_set.add_entry(plugin.path)

