        """
        return self.as_reference_point()

def find(self, name):
        """
        Return a list of subset of VM that match the pattern name
        @param name (str): the vm name of the virtual machine
        @param name (Obj): the vm object that represent the virtual
                           machine (can be Pro or Smart)
        @return (list): the subset containing the serach result.
        """
        if name.__class__ is 'base.Server.Pro' or name.__class__ is 'base.Server.Smart':
            # print('DEBUG: matched VM object %s' % name.__class__)
            pattern = name.vm_name
        else:
            # print('DEBUG: matched Str Object %s' % name.__class__)
            pattern = name
        # 14/06/2013: since this method is called within a thread and I wont to pass the return objects with queue or
        # call back, I will allocate a list inside the Interface class object itself, which contain all of the vm found
        # 02/11/2015: this must be changed ASAP! it's a mess this way... what was I thinking??
        self.last_search_result = [vm for vm in self if pattern in vm.vm_name]
        return self.last_search_result

def find(self, name):
        """
        Return a list of subset of VM that match the pattern name
        @param name (str): the vm name of the virtual machine
        @param name (Obj): the vm object that represent the virtual
                           machine (can be Pro or Smart)
        @return (list): the subset containing the serach result.
        """
        if isinstance(name, str):
            return [vm for vm in self.vms if vm.name == name]
        elif isinstance(name, Pro):
            return [vm for vm in self.vms if vm.name == name.name]
        elif isinstance(name, Smart):
            return [vm for vm in self.vms if vm.name == name.name]
        else:
            raise TypeError("name must be a string or a Pro or a Smart object")

def get_hdrgos_g_usrgos(self, usrgos):
        """Return hdrgos which contain the usrgos."""
        hdrgos_for_usrgos = set()
        hdrgos_all = self.get_hdrgos()
        usrgo2hdrgo = self.get_usrgo2hdrgo()
        for usrgo in usrgos:
            if usrgo in hdrgos_all:
                hdrgos_for_usrgos.add(usrgo)
                continue
            hdrgo_cur = usrgo2hdrgo.get(usrgo, None)
            if hdrgo_cur is not None:
                hdrgos_for_usrgos.add(hdrgo_cur)
        return hdrgos_for_usrgos

def get_hdrgos_g_usrgos(self, usrgos):
        """Return hdrgos which contain the usrgos."""
        hdrgos = []
        for hdrgo in self.hdrgos:
            if usrgos.issubset(hdrgo.usrgos):
                hdrgos.append(hdrgo)
        return hdrgos

def read(self, filename):
        """Reads config file
        """

        try:
            conf_file = open(filename, 'r')
            config = conf_file.read()
            config_keys = re.findall(r'\[.*\]', config)
            self.section_keys = [key[1:-1] for key in config_keys]
        except IOError as e:
            # Pass if file not found
            if e.errno != 2:
                raise

        return self.config_parser.read(filename)

def setRect( self, rect ):
        """
        Sets the rect for this node, ensuring that the width and height \
        meet the minimum requirements.

        :param      rect        <QRectF>
        """
        mwidth  = self.minimumWidth()
        mheight = self.minimumHeight()

        if ( rect.width() < mwidth ):
            rect.setWidth(mwidth)
        if ( rect.height() < mheight ):
            rect.setHeight(mheight)

        return super(XNode, self).setRect(rect)

def pretty(self, indent=1, debug=False):
        """
        Return a pretty formatted representation of self.
        Include additional debug details if `debug` is True.
        """
        debug_details = ''
        if debug:
            debug_details += '<isliteral=%r, iscanonical=%r>' % (self.isliteral, self.iscanonical)
        if self.isliteral:
            pretty_literal = self.args[0].pretty(indent=0, debug=debug)
            return (' ' * indent) + '%s(%s%s)' % (self.__class__.__name__, debug_details, pretty_literal)
        else:
            return super(NOT, self).pretty(indent=indent, debug=debug)

def pretty(self, indent=1, debug=False):
        """
        Return a pretty formatted representation of self.
        Include additional debug details if `debug` is True.
        """
        if debug:
            return self._pretty(indent, debug)
        else:
            return self._pretty(indent)

