def match(elem, seq_expr):
        """
        Return True if elem (an element of elem_list) matches seq_expr, an element in self.sequence
        """
        if type(seq_expr) is str:  # wild-card
            if seq_expr == '.':  # match any element
                return True
            elif seq_expr == '\d':
                return elem.is_numerical()
            elif seq_expr == '\D':
                return not elem.is_numerical()
            else:  # invalid wild-card specified
                raise LookupError('{0} is not a valid wild-card'.format(seq_expr))
        else:  # date element
            return elem == seq_expr

def match(elem, seq_expr):
        """
        Return True if elem (an element of elem_list) matches seq_expr, an element in self.sequence
        """
        if isinstance(seq_expr, str):
            return elem == seq_expr
        elif isinstance(seq_expr, list):
            return elem in seq_expr
        elif isinstance(seq_expr, tuple):
            return elem in seq_expr
        elif isinstance(seq_expr, dict):
            return elem in seq_expr.keys()
        else:
            raise ValueError("Invalid sequence expression: %s" % seq_expr)

def cast(source, target):
    """Currently Literal to *Scalar implicit casts are allowed"""
    import ibis.expr.operations as ops  # TODO: don't use ops here

    if not castable(source, target):
        raise com.IbisTypeError('Source is not castable to target type!')

    # currently it prevents column -> scalar implicit castings
    # however the datatypes are matching
    op = source.op()
    if not isinstance(op, ops.Literal):
        raise com.IbisTypeError('Only able to implicitly cast literals!')

    out_type = target.type().scalar_type()
    return out_type(op)

def cast(source, target):
    """Currently Literal to *Scalar implicit casts are allowed"""
    if isinstance(source, Literal) and isinstance(target, Scalar):
        return True
    return False

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, str):
        return instance
    elif hasattr(instance, 'decode'):
        return instance.decode(encoding)
    elif isinstance(instance, list):
        return list([to_str(item, encoding) for item in instance])
    elif isinstance(instance, tuple):
        return tuple([to_str(item, encoding) for item in instance])
    elif isinstance(instance, dict):
        return dict(
            [(to_str(key, encoding), to_str(value, encoding))
                for key, value in instance.items()])
    else:
        return instance

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, dict):
        return {to_str(k, encoding): to_str(v, encoding) for k, v in instance.items()}
    elif isinstance(instance, list):
        return [to_str(v, encoding) for v in instance]
    elif isinstance(instance, tuple):
        return tuple(to_str(v, encoding) for v in instance)
    elif isinstance(instance, set):
        return {to_str(v, encoding) for v in instance}
    elif isinstance(instance, bytes):
        return instance.decode(encoding)
    else:
        return str(instance)

def _initialize_if_needed():
    """Initialize ``TENSOR_SPACE_IMPLS`` if not already done."""
    global IS_INITIALIZED, TENSOR_SPACE_IMPLS
    if not IS_INITIALIZED:
        # pkg_resources has long import time
        from pkg_resources import iter_entry_points
        for entry_point in iter_entry_points(group='odl.space', name=None):
            try:
                module = entry_point.load()
            except ImportError:
                pass
            else:
                TENSOR_SPACE_IMPLS.update(module.tensor_space_impls())
        IS_INITIALIZED = True

