def _make_like(self, column, format, value):
        """
        make like condition
        :param column: column object
        :param format: '%_' '_%' '%_%'
        :param value: column value
        :return: condition object
        """
        if format == '%_':
            return column.like(value + '%')
        elif format == '_%':
            return column.like('%' + value)
        elif format == '%_%':
            return column.like('%' + value + '%')
        else:
            return column == value

