def _check_endings(self):
        """Check begin/end of slug, raises Error if malformed."""
        if self.slug.startswith("/") and self.slug.endswith("/"):
            raise InvalidSlugError(
                _("Invalid slug. Did you mean {}, without the leading and trailing slashes?".format(self.slug.strip("/"))))
        elif self.slug.startswith("/"):
            raise InvalidSlugError(
                _("Invalid slug. Did you mean {}, without the leading slash?".format(self.slug.strip("/"))))
        elif self.slug.endswith("/"):
            raise InvalidSlugError(
                _("Invalid slug. Did you mean {}, without the trailing slash?".format(self.slug.strip("/"))))

def _check_endings(self):
        """Check begin/end of slug, raises Error if malformed."""
        if self.slug.startswith('-'):
            raise Error('Slug cannot start with a hyphen.')
        if self.slug.endswith('-'):
            raise Error('Slug cannot end with a hyphen.')

def mouseReleaseEvent(self, event):
        """
        Reimplements the :meth:`QLabel.mouseReleaseEvent` method.

        :param event: QEvent.
        :type event: QEvent
        """

        if self.underMouse():
            if self.__checkable:
                self.set_checked(not self.__checked)
            else:
                self.setPixmap(self.__active_pixmap)
        else:
            self.setPixmap(self.__default_pixmap)
        self.released.emit()
        self.clicked.emit()

def mouseReleaseEvent(self, event):
        """
        Reimplements the :meth:`QLabel.mouseReleaseEvent` method.

        :param event: QEvent.
        :type event: QEvent
        """
        if self.isEnabled():
            if self.isVisible():
                if self.isMouseInside(event):
                    self.mouseReleased.emit(event)
                    self.mouseReleased.emit(event.pos())
                    self.mouseReleased.emit(event.globalPos())

def fill_auth_list_from_groups(self, auth_provider, user_groups, auth_list):
        """
        Returns a list of authorisation matchers that a user is eligible for.
        This list is a combination of the provided personal matchers plus the
        matchers of any group the user is in.
        """
        group_names = [item for item in auth_provider if item.endswith('%')]
        if group_names:
            for group_name in group_names:
                if group_name.rstrip("%") in user_groups:
                    for matcher in auth_provider[group_name]:
                        auth_list.append(matcher)
        return auth_list

