def find_val_for_first_bf_l_meta(d, prop_name):
    """Returns the $ value of the first meta element with
    the @property that matches @prop_name (or None).
    """
    m_list = d.get('meta')
    if not m_list:
        return None
    if not isinstance(m_list, list):
        m_list = [m_list]
    for m_el in m_list:
        if m_el.get('@property') == prop_name:
            return extract_meta(m_el)
    return None

def find_val_for_first_bf_l_meta(d, prop_name):
    """Returns the $ value of the first meta element with
    the @property that matches @prop_name (or None).
    """
    for meta in d.findall('meta'):
        if meta.get('property') == prop_name:
            return meta.get('content')
    return None

def star_resource_statements(self):
        """
        Find statements with a resources that is a * or has a * in it.
        """

        star_resources = []
        for statement in self.statements:
            if not statement.resource:
                continue
            if statement.resource == "*" or (isinstance(statement.resource, list) and "*" in statement.resource):
                star_resources.append(statement)
        return star_resources

def star_resource_statements(self):
        """
        Find statements with a resources that is a * or has a * in it.
        """
        return self.find_statements(lambda s: s.get_resource().is_blank_node() or s.get_resource().is_wildcard())

def materialize_directories(self, directories_paths_and_digests):
    """Creates the specified directories on the file system.

    :param directories_paths_and_digests tuple<DirectoryToMaterialize>: Tuple of the path and
           digest of the directories to materialize.
    :returns: Nothing or an error.
    """
    for directory_to_materialize in directories_paths_and_digests:
        directory_path = directory_to_materialize.path
        directory_digest = directory_to_materialize.digest
        try:
            self._materialize_directory(directory_path, directory_digest)
        except Exception as e:
            raise MaterializeDirectoryError(
                "Failed to materialize directory {directory_path} with digest {directory_digest}".format(
                    directory_path=directory_path, directory_digest=directory_digest
                ),
                e,
            )

def f2lookup(f, lookup):
    """
    find and replace elements in lookup within file
    """
    lookup = {i: r for i, r in [l.strip().split('\t')[0:2] for l in lookup]}
    for line in f:
        line = line.strip().split()
        for i, w in enumerate(line):
            if w in lookup:
                line[i] = lookup[w]
        yield ' '.join(line)

