def serve(self, port=None, address=None):
        """Serves the SMTP server on the given port and address."""
        port = port or self.port
        address = address or self.address

        log.info('Starting SMTP server at {0}:{1}'.format(address, port))

        server = InboxServer(self.collator, (address, port), None)

        try:
            asyncore.loop()
        except KeyboardInterrupt:
            log.info('Cleaning up')

def serve(self, port=None, address=None):
        """Serves the SMTP server on the given port and address."""
        if port is None:
            port = self.port
        if address is None:
            address = self.address
        self.server = smtpd.DebuggingServer((address, port), self)
        self.server.timeout = 1
        self.server.serve_forever()

def preprocess(self, source, name=None, filename=None):
        """Preprocesses the source with all extensions.  This is automatically
        called for all parsing and compiling methods but *not* for :meth:`lex`
        because there you usually only want the actual source tokenized.
        """
        if name is None:
            name = self.name
        if filename is None:
            filename = self.filename
        if self.extensions:
            for ext in self.extensions:
                source = ext.preprocess(source, name, filename)
        return source

