def get_uris(self, base_uri, filter_list=None):
        """Return a set of internal URIs."""
        return {
            re.sub(r'^/', base_uri, link.attrib['href'])
            for link in self.parsedpage.get_nodes_by_selector('a')
            if 'href' in link.attrib and (
                link.attrib['href'].startswith(base_uri) or
                link.attrib['href'].startswith('/')
            ) and
            not is_uri_to_be_filtered(link.attrib['href'], filter_list)
        }

def get_uris(self, base_uri, filter_list=None):
        """Return a set of internal URIs."""
        if filter_list is None:
            filter_list = []
        uris = set()
        for filter_item in filter_list:
            uris.add(base_uri + filter_item)
        return uris

def parse_schema_definition(lexer: Lexer) -> SchemaDefinitionNode:
    """SchemaDefinition"""
    start = lexer.token
    expect_keyword(lexer, "schema")
    directives = parse_directives(lexer, True)
    operation_types = many_nodes(
        lexer, TokenKind.BRACE_L, parse_operation_type_definition, TokenKind.BRACE_R
    )
    return SchemaDefinitionNode(
        directives=directives, operation_types=operation_types, loc=loc(lexer, start)
    )

