def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values
    """
    def _time_meter(fn):
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            mark = timeit.default_timer()
            result = fn(*args, **kwargs)
            cost = timeit.default_timer() - mark
            if msg:
                logger.info(msg, cost)
            else:
                logger.info('Execute <%s.%s> method cost %s seconds.', fn.__module__, fn.__name__, cost)
            return result
        return _wrapper
    return _time_meter

def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values
    """

    def decorator(fn):
        def wrapper(*args, **kwargs):
            start = time.time()
            result = fn(*args, **kwargs)
            end = time.time()
            if msg is None:
                print(f"{fn.__name__} execute time: {end - start}s")
            else:
                print(f"{msg} execute time: {end - start}s")
            return result

        return wrapper

    return decorator

def read_http_header(sock):
    """Read HTTP header from socket, return header and rest of data."""
    header = ''
    while True:
        data = sock.recv(1024)
        if not data:
            break
        header += data
        if header.endswith('\r\n\r\n'):
            break
    return header

def _system_config_file():
    """
    Returns the path to the settings.cfg file. On Windows the file is
    located in the AppData/Local/envipyengine directory. On Unix, the file
    will be located in the ~/.envipyengine directory.

    :return: String specifying the full path to the settings.cfg file
    """
    if os.name == 'nt':
        return os.path.join(os.getenv('APPDATA'), 'envipyengine', 'settings.cfg')
    else:
        return os.path.join(os.path.expanduser('~'), '.envipyengine', 'settings.cfg')

def collate_fonts_data(fonts_data):
    """Collate individual fonts data into a single glyph data list."""
    glyphs = {}

    for family in fonts_data:
        for glyph in family:
            if glyph['unicode'] not in glyphs:
                glyphs[glyph['unicode']] = glyph
            else:
                c = glyphs[glyph['unicode']]['contours']
                glyphs[glyph['unicode']]['contours'] = c | glyph['contours']
    return glyphs.values()

def collate_fonts_data(fonts_data):
    """Collate individual fonts data into a single glyph data list."""
    glyph_data = []
    for font_data in fonts_data:
        glyph_data.extend(font_data)
    return glyph_data

