      os.makedirs(subdir_path)

def create_files(filedef, cleanup=True):
    """Contextmanager that creates a directory structure from a yaml
       descripttion.
    """
    import os
    import shutil
    import tempfile
    import yaml

    def _create_files(filedef):
        """Create the files and directories described in the filedef.
        """
        for name, contents in filedef.items():
            if isinstance(contents, dict):
                os.mkdir(name)
                _create_files(contents)
            else:
                with open(name, 'w') as f:
                    f.write(contents)

    def _cleanup(filedef):
        """Remove the files and directories described in the filedef.
        """
        for name, contents in filedef.items():
            if isinstance(contents, dict):
                _cleanup(contents)
                os.rmdir(name)
            else:
                os.remove(name)

    tmpdir = tempfile.mkdtemp()
    try:
        _create_files(filedef)
        yield tmpdir
    finally:
        if cleanup:
            _cleanup(filedef)
        shutil.rmtree(tmpdir)

def train(self, record):
        """
        Updates the trees with the given training record.
        """
        self._fell_trees()
        self._grow_trees()
        for tree in self.trees:
            if random.random() < self.sample_ratio:
                tree.train(record)
            else:
                tree.out_of_bag_samples.append(record)
                while len(tree.out_of_bag_samples) > self.max_out_of_bag_samples:
                    tree.out_of_bag_samples.pop(0)

