def preorder_iter_with_position(expression):
    """Iterate over the expression in preorder.

    Also yields the position of each subexpression.
    """
    yield expression, ()
    if isinstance(expression, Operation):
        for i, operand in enumerate(op_iter(expression)):
            for child, pos in preorder_iter_with_position(operand):
                yield child, (i, ) + pos

def preorder_iter_with_position(expression):
    """Iterate over the expression in preorder.

    Also yields the position of each subexpression.
    """
    stack = [(0, expression)]
    while stack:
        position, node = stack.pop()
        if isinstance(node, tuple):
            stack.append((position, node[1]))
            stack.append((position, node[0]))
        else:
            yield node, position

def from_int(cls, retries, redirect=True, default=None):
        """ Backwards-compatibility for the old retries format."""
        if retries is None:
            retries = default if default is not None else cls.DEFAULT

        if isinstance(retries, Retry):
            return retries

        redirect = bool(redirect) and None
        new_retries = cls(retries, redirect=redirect)
        log.debug("Converted retries value: %r -> %r" % (retries, new_retries))
        return new_retries

def from_int(cls, retries, redirect=True, default=None):
        """ Backwards-compatibility for the old retries format."""
        if retries is None:
            return cls(0, redirect=redirect, default=default)
        return cls(retries, redirect=redirect, default=default)

def __parse_imap_search_result(self, result):
        """
        This takes the result of imap_search and returns SANE results
        @Params
        result - result from an imap_search call
        @Returns
        List of IMAP search results
        """
        if isinstance(result, types.ListType):
            # Above is same as "type(result) == types.ListType"
            if len(result) == 1:
                return self.__parse_imap_search_result(result[0])
            else:
                return result
        elif isinstance(result, types.StringType):
            # Above is same as "type(result) == types.StringType"
            return result.split()
        else:
            # Fail silently assuming tests will fail if emails are not found
            return []

def __parse_imap_search_result(self, result):
        """
        This takes the result of imap_search and returns SANE results
        @Params
        result - result from an imap_search call
        @Returns
        List of IMAP search results
        """
        if result is None:
            return []
        return [self.__parse_imap_search_result_item(item) for item in result]

def _http_call(self, url, method, data=None, **kwargs):
        """url -> full target url
           method -> method from requests
           data -> request body
           kwargs -> url formatting args
        """
        response = self._http_response(url, method, data=data, **kwargs)
        if not response.content:
            return {}

        return response.json()

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        signature = (
            'schema',
            'ignore_none_values',
            'allow_unknown',
            'require_all',
            'purge_unknown',
            'purge_readonly',
        )
        for i, p in enumerate(signature[: len(args)]):
            if p in kwargs:
                raise TypeError("__init__ got multiple values for argument " "'%s'" % p)
            else:
                kwargs[p] = args[i]
        self._config = kwargs

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        for arg in args:
            kwargs[arg] = getattr(self, arg)
        self.config = kwargs

async def _request(self, method: str, url: str, headers: Mapping[str, str],
                       body: bytes = b'') -> Tuple[int, Mapping[str, str], bytes]:
        """Make an HTTP request."""
        if self.proxy:
            proxy = self.proxy
        else:
            proxy = urllib.request.ProxyHandler({})
        opener = urllib.request.build_opener(proxy)
        if self.ca_certs:
            opener.add_handler(urllib.request.HTTPSHandler(cafile=self.ca_certs))
        if self.timeout:
            opener.add_handler(urllib.request.HTTPHandler(timeout=self.timeout))
        opener.add_handler(urllib.request.HTTPSHandler(context=self.ssl_context))
        request = urllib.request.Request(url, body, headers)
        request.get_method = lambda: method
        try:
            response = opener.open(request)
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()
        except urllib.error.URLError as e:
            raise HTTPError(e.reason)
        return response.code, response.headers, response.read()

