def create_asset_delivery_policy(access_token, ams_account, key_delivery_url):
    """Create Media Service Asset Delivery Policy.

    Args:
        access_token (str): A valid Azure authentication token.
        ams_account (str): Media Service Account.

    Returns:
        HTTP response. JSON body.
    """
    url = 'https://' + ams_account + '.restv2.westcentralus.media.azure.net/api/AssetDeliveryPolicies'
    headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + access_token,
        'x-ms-version': '2.19'
    }
    body = {
        'Name': 'AssetDeliveryPolicy',
        'AssetDeliveryProtocol': 'SmoothStreaming',
        'AssetDeliveryPolicyType': 'DynamicEnvelopeEncryption',
        'AssetDeliveryConfiguration': {
            'EnvelopeEncryptionConfiguration': {
                'EnvelopeEncryptionType': 'AesDynamicEncryption',
                'KeyDeliveryConfiguration': {
                    'KeyDeliveryType': 'UrlSigningKeyDelivery',
                    'UrlSigningKeyDeliveryConfiguration': {
                        'UrlSigningKeyUrl': key_delivery_url
                    }
                }
            }
        }
    }
    response = requests.post(url, headers=headers, json=body)
    return response

def draw(self,N=1.5):
        """compute every node coordinates after converging to optimal ordering by N
           rounds, and finally perform the edge routing.
        """
        while N>0.5:
            for (l,mvmt) in self.ordering_step():
                pass
            N = N-1
        if N>0:
            for (l,mvmt) in self.ordering_step(oneway=True):
                pass
        self.setxy()
        self.draw_edges()

def get_drive_rotational_speed_rpm(system_obj):
    """Gets the set of rotational speed rpms of the disks.

    :param system_obj: The HPESystem object.
    :returns the set of rotational speed rpms of the HDD devices.
    """
    drive_rotational_speed_rpm = set()
    for drive in system_obj.drives:
        if drive.rotational_speed_rpm is not None:
            drive_rotational_speed_rpm.add(drive.rotational_speed_rpm)
    return drive_rotational_speed_rpm

def configure(root_url, **kwargs):
    """"
    Notice that `configure` can either apply to the default configuration or
    `Client.config`, which is the  configuration used by the current thread
    since `Client` inherits form `threading.local`.
    """
    default = kwargs.pop('default', True)
    kwargs['client_agent'] = 'example-client/' + __version__
    if 'headers' not in kwargs:
        kwargs['headers'] = {}
    kwargs['headers']['Accept-Type'] = 'application/json'
    if default:
        default_config.reset(root_url, **kwargs)
    else:
        Client.config = wac.Config(root_url, **kwargs)

def build(self, field: Field) -> Mapping[str, Any]:
        """
        Build a swagger parameter from a marshmallow field.

        """
        builder_types = self.builder_types() + [
            # put default last
            self.default_builder_type()
        ]

        builders: List[ParameterBuilder] = [
            builder_type(
                build_parameter=self.build,
            )
            for builder_type in builder_types
        ]

        builder = next(
            builder
            for builder in builders
            if builder.supports_field(field)
        )

        return builder.build(field)

def build(self, field: Field) -> Mapping[str, Any]:
        """
        Build a swagger parameter from a marshmallow field.

        """
        if isinstance(field, fields.Nested):
            return self.build_nested(field)
        elif isinstance(field, fields.List):
            return self.build_list(field)
        elif isinstance(field, fields.Dict):
            return self.build_dict(field)
        elif isinstance(field, fields.String):
            return self.build_string(field)
        elif isinstance(field, fields.Integer):
            return self.build_integer(field)
        elif isinstance(field, fields.Number):
            return self.build_number(field)
        elif isinstance(field, fields.Boolean):
            return self.build_boolean(field)
        elif isinstance(field, fields.Date):
            return self.build_date(field)
        elif isinstance(field, fields.DateTime):
            return self.build_datetime(field)
        elif isinstance(field, fields.Time):
            return self.build_time(field)
        elif isinstance(field, fields.UUID):
            return self.build_uuid(field)
        elif isinstance(field, fields.URL):
            return self.build_url(field)
        elif isinstance(field, fields.Email):
            return self.build_email(field)
        elif isinstance(field, fields.Method):
            return self.build_method(field)
        elif isinstance(field, fields.Function):
            return self.build_function(field)
        elif isinstance(field, fields.Raw):
            return self.build_raw(field)
        elif isinstance(field, fields.Constant):
            return self.build_constant(field)
        elif isinstance(field, fields.Decimal):
            return self.build_decimal(field)
        elif isinstance(field, fields.UUID):
            return self.build_uuid(field)
        elif isinstance(field, fields.Int):
            return self.build_int(field)
        elif isinstance(field, fields.Float):
            return self.build_float(field)
        elif isinstance(field, fields.Dict):
            return self.build_dict(field)

def residual_dilated_conv(x, repeat, padding, name, hparams):
  """A stack of convolution blocks with residual connections."""
  with tf.variable_scope(name):
    for i in range(repeat):
      x = residual_conv(x, padding, name='conv_%d' % i, hparams=hparams)
    return x

def _get_uniparc_sequences_through_uniprot_ACs(self, mapping_pdb_id, uniprot_ACs, cache_dir):
        """Get the UniParc sequences associated with the UniProt accession number."""

        # Map the UniProt ACs to the UniParc IDs
        m = uniprot_map('ACC', 'UPARC', uniprot_ACs, cache_dir = cache_dir)
        UniParcIDs = []
        for _, v in m.iteritems():
            UniParcIDs.extend(v)

        # Create a mapping from the mapping_pdb_id to the UniParcEntry objects. This must match the return type from pdb_to_uniparc.
        mapping = {mapping_pdb_id : []}
        for UniParcID in UniParcIDs:
            entry = UniParcEntry(UniParcID, cache_dir = cache_dir)
            mapping[mapping_pdb_id].append(entry)

        return mapping

def _get_uniparc_sequences_through_uniprot_ACs(self, mapping_pdb_id, uniprot_ACs, cache_dir):
        """Get the UniParc sequences associated with the UniProt accession number."""
        uniparc_sequences = {}
        for uniprot_AC in uniprot_ACs:
            uniparc_sequences[uniprot_AC] = self._get_uniparc_sequences_through_uniprot_AC(mapping_pdb_id, uniprot_AC, cache_dir)
        return uniparc_sequences

