def handle_trunks(self, trunks, event_type):
        """Trunk data model change from the server."""

        LOG.debug("Trunks event received: %(event_type)s. Trunks: %(trunks)s",
                  {'event_type': event_type, 'trunks': trunks})

        if event_type == events.DELETED:
            # The port trunks have been deleted. Remove them from cache.
            for trunk in trunks:
                self._trunks.pop(trunk.id, None)
        else:
            for trunk in trunks:
                self._trunks[trunk.id] = trunk
                self._setup_trunk(trunk)

def handle_trunks(self, trunks, event_type):
        """Trunk data model change from the server."""
        for trunk in trunks:
            if trunk['id'] in self.trunks:
                self.trunks[trunk['id']].update(trunk)
            else:
                self.trunks[trunk['id']] = Trunk(trunk)

        for trunk_id in self.trunks:
            if trunk_id not in trunks:
                del self.trunks[trunk_id]

        if event_type == 'trunk.create':
            for trunk in trunks:
                self.trunk_created(trunk)
        elif event_type == 'trunk.update':
            for trunk in trunks:
                self.trunk_updated(trunk)
        elif event_type == 'trunk.delete':
            for trunk in trunks:
                self.trunk_deleted(trunk)

def _normalize_file_paths(self, *args):
        """Returns all given configuration file paths as one list."""
        paths = []
        for arg in args:
            if arg is None:
                continue
            elif self._is_valid_file(arg):
                paths.append(arg)
            elif isinstance(arg, list) and all(self._is_valid_file(_) for _ in arg):
                paths = paths + arg
            elif not self.ignore_errors:
                raise TypeError('Config file paths must be string path or list of paths!')
        return paths

def _normalize_file_paths(self, *args):
        """Returns all given configuration file paths as one list."""
        return [os.path.abspath(os.path.expanduser(path)) for path in args]

