def href(*args, **kw):
    """
    Simple function for URL generation.  Position arguments are used for the
    URL path and keyword arguments are used for the url parameters.
    """
    result = [(request.script_root if request else "") + "/"]
    for idx, arg in enumerate(args):
        result.append(("/" if idx else "") + url_quote(arg))
    if kw:
        result.append("?" + url_encode(kw))
    return "".join(result)

def href(*args, **kw):
    """
    Simple function for URL generation.  Position arguments are used for the
    URL path and keyword arguments are used for the url parameters.
    """
    return url(*args, **kw)

def _adjust_inserted_indices(inserted_indices_list, prune_indices_list):
        """Adjust inserted indices, if there are pruned elements."""
        if not prune_indices_list:
            return inserted_indices_list

        prune_indices_list.sort()
        prune_indices_list.reverse()
        for prune_index in prune_indices_list:
            for i, inserted_index in enumerate(inserted_indices_list):
                if inserted_index > prune_index:
                    inserted_indices_list[i] -= 1

        return inserted_indices_list

def _read_nowait(self, n: int) -> bytes:
        """ Read not more than n bytes, or whole buffer is n == -1 """
        chunks = []

        while self._buffer:
            chunk = self._read_nowait_chunk(n)
            chunks.append(chunk)
            if n != -1:
                n -= len(chunk)
                if n == 0:
                    break

        return b''.join(chunks) if chunks else b''

def _read_nowait(self, n: int) -> bytes:
        """ Read not more than n bytes, or whole buffer is n == -1 """
        if n == -1:
            return self._buffer
        if n > len(self._buffer):
            n = len(self._buffer)
        data = self._buffer[:n]
        self._buffer = self._buffer[n:]
        return data

def get_leaves(self):
        """Get the deepest entries as a flat set."""
        ret_set = set()
        for val in self.values():
            if isinstance(val, self.__class__):
                ret_set |= val.get_leaves()
            elif isinstance(val, dict):
                ret_set |= set(val.values())
            elif isinstance(val, list):
                ret_set |= set(val)
            elif isinstance(val, set):
                ret_set |= val
            else:
                ret_set.add(val)
        return ret_set

def get_leaves(self):
        """Get the deepest entries as a flat set."""
        return set(self.leaves())

def _tomask(self, indices, element):
        r"""
        This is a generalized version of tomask that accepts a string of
        'pore' or 'throat' for programmatic access.
        """
        if element == 'pore':
            return self.tomask(indices)
        elif element == 'throat':
            return self.tomask(indices, mode='xnor')
        else:
            raise Exception('Invalid element type')

def app(config, src, dst, features, reload, force):
    """Takes several files or directories as src and generates the code
    in the given dst directory."""
    config = Path(config)
    if reload:
        argv = sys.argv.copy()
        argv.remove('--reload')
        monitor(config.dirname(), src, dst, argv)
    else:
        run(config, src, dst, force)

