def get_parent(self, update=False):
        """
        :returns: the parent node of the current node object.
            Caches the result in the object itself to help in loops.
        """
        if self.is_root():
            return
        try:
            if update:
                del self._cached_parent_obj
            else:
                return self._cached_parent_obj
        except AttributeError:
            pass
        # parent = our most direct ancestor
        self._cached_parent_obj = self.get_ancestors().reverse()[0]
        return self._cached_parent_obj

def _safe_minmax(values):
    """Calculate min and max of array with guards for nan and inf."""
    if len(values) == 0:
        return np.nan, np.nan
    return np.nanmin(values), np.nanmax(values)

def _set_container(self, container):
        """
        Sets the container (and, if needed, the configured TTL on it), making
        the container publicly available.
        """
        if self.use_pyrax:
            if container.cdn_ttl != self.ttl or not container.cdn_enabled:
                container.make_public(ttl=self.ttl)
            if hasattr(self, "_container_public_uri"):
                delattr(self, "_container_public_uri")
        self._container = container

def _set_container(self, container):
        """
        Sets the container (and, if needed, the configured TTL on it), making
        the container publicly available.
        """
        if container is None:
            return

        if self.container_ttl is not None:
            container.set_container_ttl(self.container_ttl)

        container.set_public()

def validate_query_params(self, request):
        """
        Validate that query params are in the list of valid query keywords in
        :py:attr:`query_regex`

        :raises ValidationError: if not.
        """
        query_params = request.GET.get('query', '')
        if query_params:
            query_params = query_params.split('&')
            for query_param in query_params:
                if not re.match(self.query_regex, query_param):
                    raise ValidationError(
                        'Invalid query parameter: %s' % query_param)

