        return self._queue.get()

def __get_host(node, vm_):
    """
    Return public IP, private IP, or hostname for the libcloud 'node' object
    """
    if __get_ssh_interface(vm_) == 'private_ips' or vm_['external_ip'] is None:
        ip_address = node.private_ips[0]
        log.info('Salt node data. Private_ip: %s', ip_address)
    else:
        ip_address = node.public_ips[0]
        log.info('Salt node data. Public_ip: %s', ip_address)

    if ip_address:
        return ip_address

    return node.name

def __get_host(node, vm_):
    """
    Return public IP, private IP, or hostname for the libcloud 'node' object
    """
    if vm_.get('public_ip'):
        return node.public_ips[0]
    elif vm_.get('private_ip'):
        return node.private_ips[0]
    else:
        return node.extra['hostname']

def _convert_option(self):
        """
        Determines how to convert CDF byte ordering to the system
        byte ordering.
        """
        if self.byte_order == 'little':
            return '>'
        else:
            return '<'

def pillar(tgt=None, tgt_type='glob', **kwargs):
    """
    .. versionchanged:: 2017.7.0
        The ``expr_form`` argument has been renamed to ``tgt_type``, earlier
        releases must use ``expr_form``.

    Return cached pillars of the targeted minions

    CLI Example:

    .. code-block:: bash

        salt-run cache.pillar
    """
    if "expr_form" in kwargs:
        salt.utils.warn_until(
            "Nitrogen",
            "The \'expr_form\' argument to cache.pillar has been renamed to \'tgt_type\'.",
        )
        tgt_type = kwargs.pop("expr_form")

    if tgt_type not in salt.utils.minions.CACHE_TARGET_TYPES:
        raise salt.exceptions.SaltInvocationError(
            "Invalid tgt_type: {0}".format(tgt_type)
        )

    if tgt:
        minions = salt.utils.minions.CACHE_TARGET_TYPES[tgt_type](tgt, **kwargs)
    else:
        minions = list(salt.utils.minions.CACHE_TARGET_TYPES[tgt_type](**kwargs))

    ret = {}
    for minion in minions:
        ret[minion] = __salt__["pillar.items"](minion)
    return ret

def ssh_known_hosts_lines(application_name, user=None):
    """Return contents of known_hosts file for given application.

    :param application_name: Name of application eg nova-compute-something
    :type application_name: str
    :param user: The user that the ssh asserts are for.
    :type user: str
    """
    known_hosts_list = []
    with open(known_hosts(application_name, user)) as hosts:
        for hosts_line in hosts:
            if hosts_line.rstrip():
                known_hosts_list.append(hosts_line.rstrip())
    return(known_hosts_list)

