    :param application_name: Name of application eg nova-compute-something
    :type application_name: str
    :param user: The user that the ssh asserts are for.
    :type user: str
    """
    if user is None:
        user = getpass.getuser()
    return _ssh_known_hosts_lines(application_name, user)

def cast(s):
    """
    Cast a basestring to a more appropriate type.
    Example::
        >>> from yaxil import cast
        >>> type(cast("999"))
        <type 'int'>

    :param s: String
    :type s: basestring
    :returns: Casted string
    :rtype: int|float|str
    """
    if not isinstance(s, basestring):
        raise TypeError("argument must be a string")
    for test in [int, float, str]:
        try:
            return test(s)
        except ValueError:
            continue
    return str(s)

def cast(s):
    """
    Cast a basestring to a more appropriate type.
    Example::
        >>> from yaxil import cast
        >>> type(cast("999"))
        <type 'int'>

    :param s: String
    :type s: basestring
    :returns: Casted string
    :rtype: int|float|str
    """
    try:
        return int(s)
    except ValueError:
        try:
            return float(s)
        except ValueError:
            return s

def get_by_name(self, name, namespace=None):
        """
        name: can be either <namespace>/<dataset_name> or just <dataset_name>
        namespace: if specified, will skip name parsing, defaults to current user's username
        """
        if not namespace:
            namespace, name = get_namespace_from_name(name)
        if not namespace:
            namespace = AuthConfigManager.get_access_token().username
        try:
            response = self.request('GET', '%s/%s/%s' % (self.url, namespace, name))
            return Dataset.from_dict(response.json())
        except NotFoundException:
            return None

