        return self.get(namespace, name)

def sleep():
    """Sleeps for a dynamic duration of time as determined by set_rate() and true().

    :raises: BeatError: if this function is called before calling set_rate() or \
            before calling true()
    """
    if not _rate:
        raise BeatError("set_rate() must be called before sleep()")
    if not _true:
        raise BeatError("true() must be called before sleep()")
    time.sleep(_rate)

def filter_whitespace(mode: str, text: str) -> str:
    """Transform whitespace in ``text`` according to ``mode``.

    Available modes are:

    * ``all``: Return all whitespace unmodified.
    * ``single``: Collapse consecutive whitespace with a single whitespace
      character, preserving newlines.
    * ``oneline``: Collapse all runs of whitespace into a single space
      character, removing all newlines in the process.

    .. versionadded:: 4.3
    """
    if mode == "all":
        return text
    elif mode == "single":
        text = re.sub(r"([\t ]+)", " ", text)
        text = re.sub(r"(\s*\n\s*)", "\n", text)
        return text
    elif mode == "oneline":
        return re.sub(r"(\s+)", " ", text)
    else:
        raise Exception("invalid whitespace mode %s" % mode)

def filter_whitespace(mode: str, text: str) -> str:
    """Transform whitespace in ``text`` according to ``mode``.

    Available modes are:

    * ``all``: Return all whitespace unmodified.
    * ``single``: Collapse consecutive whitespace with a single whitespace
      character, preserving newlines.
    * ``oneline``: Collapse all runs of whitespace into a single space
      character, removing all newlines in the process.

    .. versionadded:: 4.3
    """
    if mode == "all":
        return text
    elif mode == "single":
        return " ".join(text.split())
    elif mode == "oneline":
        return " ".join(text.splitlines())
    else:
        raise ValueError(f"Unknown whitespace mode: {mode!r}")

def clean_text(self, country, guess=False, **kwargs):
        """Determine a two-letter country code based on an input.

        The input may be a country code, a country name, etc.
        """
        code = country.lower().strip()
        if code in self.names:
            return code
        country = countrynames.to_code(country, fuzzy=guess)
        if country is not None:
            return country.lower()

def clean_text(self, country, guess=False, **kwargs):
        """Determine a two-letter country code based on an input.

        The input may be a country code, a country name, etc.
        """
        if country is None:
            return None
        if isinstance(country, str):
            country = country.lower()
        if country in self.country_codes:
            return country
        if guess:
            return self.guess_country(country)
        raise ValueError(f"Unknown country: {country}")

def _has_example(self, label):
        """Whether this data type has an example with the given ``label``."""
        if label in self._raw_examples:
            return True
        else:
            for field in self.all_fields:
                dt, _ = unwrap_nullable(field.data_type)
                if not is_user_defined_type(dt) and not is_void_type(dt):
                    continue
                if label == field.name:
                    return True
            else:
                return False

def _has_example(self, label):
        """Whether this data type has an example with the given ``label``."""
        return label in self._examples

def find_java_home(cratedb_version: tuple) -> str:
    """ Return a path to a JAVA_HOME suites for the given CrateDB version """
    if MIN_VERSION_FOR_JVM11 <= cratedb_version < (4, 0):
        # Supports 8 to 11+, use whatever is set
        return os.environ.get('JAVA_HOME', '')
    if cratedb_version < MIN_VERSION_FOR_JVM11:
        return _find_matching_java_home(lambda ver: ver[0] == 8)
    else:
        return _find_matching_java_home(lambda ver: ver[0] >= 11)

def find_java_home(cratedb_version: tuple) -> str:
    """ Return a path to a JAVA_HOME suites for the given CrateDB version """
    java_home = os.environ.get("JAVA_HOME")
    if java_home:
        return java_home

    if cratedb_version[0] == 4:
        return "/usr/lib/jvm/java-11-openjdk-amd64"
    else:
        return "/usr/lib/jvm/java-8-openjdk-amd64"

def resolve(track_url):
    """
    Resolves the URL to an actual track from the SoundCloud API.

    If the track resolves to more than one possible track, it takes the first search result.

    :returns: The track dictionary from the SoundCloud API
    """
    try:
        path = urlparse.urlparse(track_url).path
        tracks = client.get('/tracks', q=path)

        if tracks:
            return tracks[0]
        else:
            raise ValueError('Track not found for URL {}'.format(track_url))
    except Exception as e:
        raise ValueError('Error obtaining track by url: {}'.format(str(e)))

def point_on_line(ab, c):
    """
    point_on_line((a,b), c) yields True if point x is on line (a,b) and False otherwise.
    """
    return (c[0] - ab[0]) * (ab[1] - ab[0]) == (c[1] - ab[0]) * (ab[1] - ab[0])

def unpack_struct(self, struct):
        """
        unpacks the given struct from the underlying buffer and returns
        the results. Will raise an UnpackException if there is not
        enough data to satisfy the format of the structure
        """

        size = struct.size

        offset = self.offset
        if self.data:
            avail = len(self.data) - offset
        else:
            avail = 0

        if avail < size:
            raise UnpackException(struct.format, size, avail)

        self.offset = offset + size
        return struct.unpack_from(self.data, offset)

def unpack_struct(self, struct):
        """
        unpacks the given struct from the underlying buffer and returns
        the results. Will raise an UnpackException if there is not
        enough data to satisfy the format of the structure
        """
        try:
            return struct.unpack_from(self.buffer, self.offset)
        except struct.error as e:
            raise UnpackException(e)

def recursive_delete(self, path, **kwargs):
        """Recursively delete path."""

        while True:
            try:
                yield self.delete(path, **kwargs)
            except NoNodeException:
                break
            except NotEmptyException:
                children = yield self.get_children(path)
                for name in children:
                    yield self.recursive_delete(path + "/" + name)
            else:
                break

def recursive_delete(self, path, **kwargs):
        """Recursively delete path."""
        if not self.exists(path):
            return
        if self.isfile(path):
            self.delete(path, **kwargs)
        else:
            for p in self.listdir(path):
                self.recursive_delete(self.join(path, p), **kwargs)
            self.rmdir(path, **kwargs)

def unicode_wrapper(self, property, default=ugettext('Untitled')):
        """
        Wrapper to allow for easy unicode representation of an object by
        the specified property. If this wrapper is not able to find the
        right translation of the specified property, it will return the
        default value instead.

        Example::
            def __unicode__(self):
                return unicode_wrapper('name', default='Unnamed')

        """
        # TODO: Test coverage!
        try:
            value = getattr(self, property)
        except ValueError:
            logger.warn(
                u'ValueError rendering unicode for %s object.',
                self._meta.object_name
            )

            value = None

        if not value:
            value = default

        return value

def unicode_wrapper(self, property, default=ugettext('Untitled')):
        """
        Wrapper to allow for easy unicode representation of an object by
        the specified property. If this wrapper is not able to find the
        right translation of the specified property, it will return the
        default value instead.

        Example::
            def __unicode__(self):
                return unicode_wrapper('name', default='Unnamed')

        """
        try:
            return getattr(self, property)
        except AttributeError:
            return default

def delete_node(self, node_id):
        """Removes the node identified by node_id from the graph."""
        if node_id not in self.nodes:
            raise KeyError("Node %s not in graph" % node_id)
        self.nodes.pop(node_id)
        for node_id in self.nodes:
            self.nodes[node_id].remove_neighbor(node_id)

