def readf(nb_file, fmt=None):
    """Read a notebook from the file with given name"""
    if nb_file == '-':
        text = sys.stdin.read()
        fmt = fmt or divine_format(text)
        return reads(text, fmt)

    _, ext = os.path.splitext(nb_file)
    fmt = copy(fmt or {})
    fmt.update({'extension': ext})
    with io.open(nb_file, encoding='utf-8') as stream:
        return read(stream, fmt, as_version=4)

def readf(nb_file, fmt=None):
    """Read a notebook from the file with given name"""
    if fmt is None:
        fmt = nb_file.split('.')[-1]
    if fmt == 'ipynb':
        with open(nb_file, 'r') as f:
            nb = nbformat.read(f, as_version=4)
    elif fmt == 'py':
        nb = nbformat.from_filename(nb_file)
    else:
        raise ValueError('Unknown file format: {}'.format(fmt))
    return nb

def _case_format(self, occur):
        """Return the serialization format for a case node.""" 
        if self.occur == 1:
            self.attr["nma:implicit"] = "true"
        ccnt = len(self.rng_children())
        if ccnt == 0: return "<empty/>%s"
        if ccnt == 1 or not self.interleave:
            return self.start_tag("group") + "%s" + self.end_tag("group")
        return (self.start_tag("interleave") + "%s" +
                self.end_tag("interleave"))

def _case_format(self, occur):
        """Return the serialization format for a case node."""
        if occur == 'optional':
            return '?'
        elif occur == 'multiple':
            return '*'
        else:
            return ''

def visit_import(self, node):
        """triggered when an import statement is seen"""
        if self.process_module:
            # Store salt imported modules
            for module, import_as in node.names:
                if not module.startswith('salt'):
                    continue
                if import_as and import_as not in self.imported_salt_modules:
                    self.imported_salt_modules[import_as] = module
                    continue
                if module not in self.imported_salt_modules:
                    self.imported_salt_modules[module] = module

def visit_import(self, node):
        """triggered when an import statement is seen"""
        self.visit(node.module)

