def symmetric_difference_update(self, that):
        """
        Update the set, keeping only elements found in either *self* or *that*,
        but not in both.
        """
        if not isinstance(that, Set):
            raise TypeError("'in' requires set or frozenset")
        if self is that:
            return
        if len(self) < len(that):
            self._symmetric_difference_update(that)
        else:
            that._symmetric_difference_update(self)

def __remove_append_items(self, whole=False):
        """
        internal method, delete all append items (ends with +)
        :param whole: pass thru 'whole' param to climb
        :return: None
        """
        for node in self.climb(whole=whole):
            for key in sorted(node.data.keys()):
                if key.endswith('+'):
                    del node.data[key]

def __remove_append_items(self, whole=False):
        """
        internal method, delete all append items (ends with +)
        :param whole: pass thru 'whole' param to climb
        :return: None
        """
        if whole:
            for item in self.items:
                item.__remove_append_items(whole=True)
        else:
            for item in self.items:
                if item.name.endswith('+'):
                    self.items.remove(item)

def get_root(directory):
    """Get root directory of the local git repo from any subdirectory within it.

    :raise GitError: If git command fails (dir not a git repo?).

    :param str directory: Subdirectory in the local repo.

    :return: Root directory of repository.
    :rtype: str
    """
    command = ['git', 'rev-parse', '--show-toplevel']
    try:
        output = run_command(directory, command, env_var=False)
    except CalledProcessError as exc:
        raise GitError('Failed to find local git repository root in {}.'.format(repr(directory)), exc.output)
    if IS_WINDOWS:
        output = output.replace('/', '\\')
    return output.strip()

def get_root(directory):
    """Get root directory of the local git repo from any subdirectory within it.

    :raise GitError: If git command fails (dir not a git repo?).

    :param str directory: Subdirectory in the local repo.

    :return: Root directory of repository.
    :rtype: str
    """
    try:
        return subprocess.check_output(
            ['git', 'rev-parse', '--show-toplevel'],
            cwd=directory,
            stderr=subprocess.STDOUT,
        ).decode('utf-8').strip()
    except subprocess.CalledProcessError as e:
        raise GitError(e.output.decode('utf-8'))

def __interpret_slices(self, slices):
    """
    Convert python slice objects into a more useful and computable form:

    - requested_bbox: A bounding box representing the volume requested
    - steps: the requested stride over x,y,z
    - channel_slice: A python slice object over the channel dimension

    Returned as a tuple: (requested_bbox, steps, channel_slice)
    """
    if slices is None:
        return None, None, None

    if not isinstance(slices, tuple):
        slices = (slices,)

    requested_bbox = None
    steps = None
    channel_slice = None

    for slice_ in slices:
        if isinstance(slice_, BoundingBox):
            if requested_bbox is None:
                requested_bbox = slice_
            else:
                requested_bbox = requested_bbox.intersection(slice_)
        elif isinstance(slice_, slice):
            if steps is None:
                steps = slice_
            else:
                steps = steps.intersection(slice_)
        elif isinstance(slice_, int):
            if channel_slice is None:
                channel_slice = slice_
            else:
                channel_slice = channel_slice.intersection(slice_)
        else:
            raise ValueError("Unknown slice type: %s" % type(slice_))

    return requested_bbox, steps, channel_slice

def _tempDirectories(self):
        """
        :rtype : an iterator to the temporary directories containing jobs/stats files
        in the hierarchy of directories in self.tempFilesDir
        """
        def _dirs(path, levels):
            if levels > 0:
                for subPath in os.listdir(path):
                    for i in _dirs(os.path.join(path, subPath), levels-1):
                        yield i
            else:
                yield path
        for tempDir in _dirs(self.tempFilesDir, self.levels):
            yield tempDir

def _tempDirectories(self):
        """
        :rtype : an iterator to the temporary directories containing jobs/stats files
        in the hierarchy of directories in self.tempFilesDir
        """
        return self._tempDirectoriesHelper(self.tempFilesDir)

def _merge_fix(d):
    """Fixes keys that start with "&" and "-"
        d = {
          "&steve": 10,
          "-gary": 4
        }
        result = {
          "steve": 10,
          "gary": 4
        }
    """
    if type(d) is dict:
        for key in d.keys():
            if key[0] in ('&', '-'):
                d[key[1:]] = _merge_fix(d.pop(key))
    return d

def _merge_fix(d):
    """Fixes keys that start with "&" and "-"
        d = {
          "&steve": 10,
          "-gary": 4
        }
        result = {
          "steve": 10,
          "gary": 4
        }
    """
    for k, v in d.items():
        if k.startswith("&"):
            d[k[1:]] = v
            del d[k]
        elif k.startswith("-"):
            d[k[1:]] = -v
            del d[k]
    return d

def filter_params(params):
    """
    convert dict value if value is bool type,
    False -> "false"
    True -> "true"
    """
    if params is not None:
        new_params = copy.deepcopy(params)
        new_params = dict((k, v) for k, v in new_params.items() if v is not None)
        for key, value in new_params.items():
            if isinstance(value, bool):
                new_params[key] = "true" if value else "false"
        return new_params

def filter_params(params):
    """
    convert dict value if value is bool type,
    False -> "false"
    True -> "true"
    """
    for key, value in params.items():
        if isinstance(value, bool):
            params[key] = str(value).lower()
    return params

def parse_compound_count(s):
    """Parse a compound count (number of compounds)."""
    m = re.match(r'^\((.*)\)$', s)
    if m:
        s = m.group(1)

    for count_type in (int, Decimal, affine.Expression):
        try:
            return count_type(s)
        except:
            pass

    raise ValueError('Unable to parse compound count: {}'.format(s))

def parse_compound_count(s):
    """Parse a compound count (number of compounds)."""
    if s.isdigit():
        return int(s)
    elif s.startswith('~'):
        return int(s[1:])
    else:
        return None

def get_user_of_group(config, fas, groupname):
    """ Return the list of users in the specified group.

    :arg config: a dict containing the fedmsg config
    :arg fas: a fedora.client.fas2.AccountSystem object instanciated and loged
        into FAS.
    :arg groupname: the name of the group for which we want to retrieve the
        members.
    :return: a list of FAS user members of the specified group.
    """

    if not _cache.is_configured:
        _cache.configure(**config['fmn.rules.cache'])

    key = cache_key_generator(get_user_of_group, groupname)
    def creator():
        if not fas:
            return set()
        return set([u.username for u in fas.group_members(groupname)])
    return _cache.get_or_create(key, creator)

