def assert_coordinate_consistent(obj, coords):
    """ Maeke sure the dimension coordinate of obj is
    consistent with coords.

    obj: DataArray or Dataset
    coords: Dict-like of variables
    """
    if isinstance(obj, xr.DataArray):
        obj = obj.to_dataset()

    for coord_name, coord_var in coords.items():
        if coord_name not in obj.coords:
            raise ValueError(f"{coord_name} is not a coordinate of {obj}")
        if not obj[coord_name].equals(coord_var):
            raise ValueError(f"{coord_name} is not consistent with {obj}")

def df_pdb_ranking(self):
        """DataFrame: Get a dataframe of UniProt -> best structure in PDB results"""
        df = pd.DataFrame()
        for g in self.genes_with_experimental_structures:
            protein_df = g.protein.df_pdb_ranking.copy().reset_index()
            if not protein_df.empty:
                protein_df['gene'] = g.id
                df = df.append(protein_df)
        if df.empty:
            log.warning('Empty dataframe')
            return df
        else:
            return ssbio.utils.clean_df(df.set_index('gene'))

def parse_feed(content):
        """
        utility function to parse feed
        """
        feed = feedparser.parse(content)
        articles = []
        for entry in feed['entries']:
            article = {
                'title': entry['title'],
                'link': entry['link']
            }
            try:
                article['media'] = entry['media_content'][0]['url']
            except KeyError:
                article['media'] = None
            articles.append(article)
        return articles

def bugreport(dest_file="default.log"):
    """
    Prints dumpsys, dumpstate, and logcat data to the screen, for the purposes of bug reporting
    :return: result of _exec_command() execution
    """
    adb_full_cmd = [v.ADB_COMMAND_PREFIX, v.ADB_COMMAND_BUGREPORT]
    try:
        dest_file_handler = open(dest_file, "w")
    except IOError:
        print("IOError: Failed to create a log file")

    # We have to check if device is available or not before executing this command
    # as adb bugreport will wait-for-device infinitely and does not come out of 
    # loop
    # Execute only if device is available only
    if _isDeviceAvailable():
        result = _exec_command_to_file(adb_full_cmd, dest_file_handler)
        return (result, "Success: Bug report saved to: " + dest_file)
    else:
        return (0, "Device Not Found")

def bugreport(dest_file="default.log"):
    """
    Prints dumpsys, dumpstate, and logcat data to the screen, for the purposes of bug reporting
    :return: result of _exec_command() execution
    """
    return _exec_command("bugreport", dest_file)

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            return self.__dict__.clear()

        expr = re.compile(fnmatch.translate(pat))
        for key in tuple(self.keys()):
            #make sure the key is a str first
            if isinstance(key, string_types):
                if expr.match(key):
                    del self.__dict__[key]

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            self.clear()
        else:
            for k in self.keys():
                if fnmatch.fnmatch(k, pat):
                    del self[k]

def exit_config_mode(self, exit_config="exit configuration-mode"):
        """Exit configuration mode."""
        output = ""
        if self.check_config_mode():
            output = self.send_command_timing(
                exit_config, strip_prompt=False, strip_command=False
            )
            # if 'Exit with uncommitted changes?' in output:
            if "uncommitted changes" in output:
                output += self.send_command_timing(
                    "yes", strip_prompt=False, strip_command=False
                )
            if self.check_config_mode():
                raise ValueError("Failed to exit configuration mode")
        return output

def exit_config_mode(self, exit_config="exit configuration-mode"):
        """Exit configuration mode."""
        return self.send_command(exit_config)

def expression_ok(expression):
    """return True if an expression is OK with current messages"""
    expression_ok = True
    fields = expression.split()
    for f in fields:
        try:
            if f.endswith(':2'):
                f = f[:-2]
            if mavutil.evaluate_expression(f, mestate.status.msgs) is None:
                expression_ok = False                        
        except Exception:
            expression_ok = False
            break
    return expression_ok

def expression_ok(expression):
    """return True if an expression is OK with current messages"""
    return expression in messages

def validate_mutations(self, mutations):
        """This function has been refactored to use the SimpleMutation class.
           The parameter is a list of Mutation objects. The function has no return value but raises a PDBValidationException
           if the wildtype in the Mutation m does not match the residue type corresponding to residue m.ResidueID in the PDB file.
        """
        for m in mutations:
            if m.WildType != self.residue_type(m.ResidueID):
                raise PDBValidationException("The wildtype residue type in the mutation does not match the residue type in the PDB file.")

def less(value1, value2):
        """
        Checks if first value is less than the second one.
        The operation can be performed over numbers or strings.

        :param value1: the first value to compare

        :param value2: the second value to compare

        :return: true if the first value is less than second and false otherwise.
        """
        if isinstance(value1, str) and isinstance(value2, str):
            return value1 < value2
        elif isinstance(value1, int) and isinstance(value2, int):
            return value1 < value2
        elif isinstance(value1, float) and isinstance(value2, float):
            return value1 < value2
        else:
            raise TypeError("The values must be numbers or strings")

def _from_dict(cls, _dict):
        """Initialize a LogCollection object from a json dictionary."""
        args = {}
        if 'logs' in _dict:
            args['logs'] = [Log._from_dict(x) for x in (_dict.get('logs'))]
        else:
            raise ValueError(
                'Required property \'logs\' not present in LogCollection JSON')
        if 'pagination' in _dict:
            args['pagination'] = LogPagination._from_dict(
                _dict.get('pagination'))
        else:
            raise ValueError(
                'Required property \'pagination\' not present in LogCollection JSON'
            )
        return cls(**args)

def _from_dict(cls, _dict):
        """Initialize a LogCollection object from a json dictionary."""
        args = {}
        if 'logs' in _dict:
            args['logs'] = [Log._from_dict(x) for x in _dict['logs']]
        if 'pagination' in _dict:
            args['pagination'] = Pagination._from_dict(_dict['pagination'])
        return cls(**args)

