    return json.dumps(content, cls=DjangoJSONEncoder, indent=indent)

def google_v3(address):
    """
    Given an address, return ``(computed_address, (latitude, longitude))``
    tuple using Google Geocoding API v3.

    """
    try:
        g = geocoders.GoogleV3(api_key=settings.EASY_MAPS_GOOGLE_KEY or settings.EASY_MAPS_GOOGLE_MAPS_API_KEY)

        results = g.geocode(smart_str(address), exactly_one=False)
        if results is not None:
            return results[0]

        raise Error("No results found for '%s'" % address)
    except (UnboundLocalError, ValueError, GeocoderServiceError) as e:
        raise Error(e)

def google_v3(address):
    """
    Given an address, return ``(computed_address, (latitude, longitude))``
    tuple using Google Geocoding API v3.

    """
    url = 'https://maps.googleapis.com/maps/api/geocode/json?address={address}&key={key}'.format(
        address=address,
        key=settings.GOOGLE_GEOCODING_API_KEY
    )
    response = requests.get(url)
    response.raise_for_status()
    data = response.json()
    if data['status'] == 'OK':
        return data['results'][0]['formatted_address'], (
            data['results'][0]['geometry']['location']['lat'],
            data['results'][0]['geometry']['location']['lng']
        )
    else:
        raise ValueError(data['status'])

def distance(self,other):
        """
        A generic distance method, which requires the existence of an attribute
        called distance_criteria, giving a list of strings naming the attributes
        to be considered by the distance metric.

        Parameters
        ----------
        other : object
            Another object to compare this instance to.

        Returns
        -------
        (unnamed) : float
            The distance between this object and another, using the "universal
            distance" metric.
        """
        if not hasattr(other,'distance_criteria'):
            raise AttributeError("The other object does not have a distance_criteria attribute.")
        if not hasattr(self,'distance_criteria'):
            raise AttributeError("This object does not have a distance_criteria attribute.")
        if not isinstance(other.distance_criteria,list):
            raise TypeError("The other object's distance_criteria attribute is not a list.")
        if not isinstance(self.distance_criteria,list):
            raise TypeError("This object's distance_criteria attribute is not a list.")
        if len(other.distance_criteria) != len(self.distance_criteria):
            raise ValueError("The other object's distance_criteria attribute is not the same length as this object's.")
        if not all([isinstance(x,str) for x in other.distance_criteria]):
            raise TypeError("The other object's distance_criteria attribute is not a list of strings.")
        if not all([isinstance(x,str) for x in self.distance_criteria]):
            raise TypeError("This object's distance_criteria attribute is not a list of strings.")
        if not all([hasattr(other,x) for x in other.distance_criteria]):
            raise AttributeError("The other object does not have all the attributes named in its distance_criteria attribute.")
        if not all([hasattr(self,x) for x in self.distance_criteria]):
            raise AttributeError("This object does not have all the attributes named in its distance_criteria attribute.")
        if not all([isinstance(getattr(other,x),float) for x in other.distance_criteria]):
            raise TypeError("The other object's distance_criteria attribute is not a list of floats.")
        if not all([isinstance(getattr(self,x),float) for x in self.distance_criteria]):
            raise TypeError("This object's distance_criteria attribute is not a list of floats.")
        return sum([getattr(other,x) - getattr(self,x) for x in other.distance_criteria])

def stream_decode_gzip(iterator):
    """Stream decodes a gzip-encoded iterator"""
    try:
        dec = zlib.decompressobj(16 + zlib.MAX_WBITS)
        for chunk in iterator:
            rv = dec.decompress(chunk)
            if rv:
                yield rv
        buf = dec.decompress('')
        rv = buf + dec.flush()
        if rv:
            yield rv
    except zlib.error:
        pass

def stream_decode_gzip(iterator):
    """Stream decodes a gzip-encoded iterator"""
    import gzip
    import io
    import itertools

    def decode_gzip(data):
        """Decodes a gzip-encoded string"""
        return gzip.decompress(data)

    return itertools.chain.from_iterable(
        io.BytesIO(chunk).read()
        for chunk in iterator
        if chunk
    )

