def serialize(self, value, **kwargs):
        """Serialize instance to JSON

        If the value is a HasProperties instance, it is serialized with
        the include_class argument passed along. Otherwise, to_json is
        called.
        """
        kwargs.update({'include_class': kwargs.get('include_class', True)})
        if self.serializer is not None:
            return self.serializer(value, **kwargs)
        if value is None:
            return None
        if isinstance(value, HasProperties):
            return value.serialize(**kwargs)
        return self.to_json(value, **kwargs)

def serialize(self, value, **kwargs):
        """Serialize instance to JSON

        If the value is a HasProperties instance, it is serialized with
        the include_class argument passed along. Otherwise, to_json is
        called.
        """
        if isinstance(value, HasProperties):
            return value.to_json(include_class=True, **kwargs)
        else:
            return value.to_json(**kwargs)

def _get_domain(self):
        """
        Return the object representation of this provider VM.

        Returns:
            libvirt.virDomain: Libvirt domain object

        Raises:
            :exc:`~lago.plugins.vm.LagoFailedToGetVMStateError:
                If the VM exist, but the query returned an error.
        """
        try:
            return self.libvirt_con.lookupByName(self._libvirt_name())
        except libvirt.libvirtError as e:
            raise vm_plugin.LagoVMDoesNotExistError(str(e))

def _get_domain(self):
        """
        Return the object representation of this provider VM.

        Returns:
            libvirt.virDomain: Libvirt domain object

        Raises:
            :exc:`~lago.plugins.vm.LagoFailedToGetVMStateError:
                If the VM exist, but the query returned an error.
        """
        try:
            return self.conn.lookupByName(self.name)
        except libvirt.libvirtError as e:
            if e.get_error_code() == libvirt.VIR_ERR_NO_DOMAIN:
                raise LagoVMNotFoundError(self.name)
            else:
                raise LagoFailedToGetVMStateError(self.name)

