def iter_documents(self, fileids=None, categories=None, _destroy=False):
        """ Return an iterator over corpus documents. """
        doc_ids = self._filter_ids(fileids, categories)
        for doc in imap(self.get_document, doc_ids):
            yield doc
            if _destroy:
                doc.destroy()

def iter_documents(self, fileids=None, categories=None, _destroy=False):
        """ Return an iterator over corpus documents. """
        if fileids is None:
            fileids = self.fileids()
        if categories is None:
            categories = self.categories()
        for fileid in fileids:
            for category in categories:
                if _destroy:
                    yield self.make_document(fileids=[fileid], categories=[category],
                                            _destroy=True)
                else:
                    yield self.make_document(fileids=[fileid], categories=[category])

def keys_values(self):
        """Key values might be a list or not, always return a list."""
        keys_values = []
        for value in self.keys.values():
            if isinstance(value, list):
                keys_values += value
            elif isinstance(value, basestring) and not value.startswith('-'):
                # Avoid -99. Should be fixed in geozones
                keys_values.append(value)
            elif isinstance(value, int) and value >= 0:
                # Avoid -99. Should be fixed in geozones
                keys_values.append(str(value))
        return keys_values

def keys_values(self):
        """Key values might be a list or not, always return a list."""
        if isinstance(self.keys, list):
            return self.keys, self.values
        else:
            return [self.keys], [self.values]

