def mod_4hz(self, rate_wavsample):
    """Computes and returns the 4Hz modulation energy features for the given input wave file"""
    # Compute the 4Hz modulation energy features
    mod_4hz = np.zeros(rate_wavsample)
    for i in range(0, rate_wavsample):
        if i < 1000:
            mod_4hz[i] = 0
        else:
            mod_4hz[i] = np.sum(self.wav_data[i-1000:i])
    return mod_4hz

def getParam(self, name=None):
        """ Function getParam
        Return a dict of parameters or a parameter value

        @param key: The parameter name
        @return RETURN: dict of parameters or a parameter value
        """
        if 'parameters' in self.keys():
            l = {x['name']: x['value'] for x in self['parameters'].values()}
            if name:
                if name in l.keys():
                    return l[name]
                else:
                    return False
            else:
                return l

def getParam(self, name=None):
        """ Function getParam
        Return a dict of parameters or a parameter value

        @param key: The parameter name
        @return RETURN: dict of parameters or a parameter value
        """
        if name is None:
            return self.params
        else:
            return self.params[name]

