def configure_mock(self, **kwargs):
        """Set attributes on the mock through keyword arguments.

        Attributes plus return values and side effects can be set on child
        mocks using standard dot notation and unpacking a dictionary in the
        method call:

        >>> attrs = {'method.return_value': 3, 'other.side_effect': KeyError}
        >>> mock.configure_mock(**attrs)"""
        for name, value in kwargs.items():
            setattr(self, name, value)

def _clear_minimum_terms(self, match_key):
        """clears minimum match_key term values"""
        try:  # clear match = True case
            del self._query_terms[match_key]['$gte']
        except KeyError:
            pass
        try:  # clear match = False case
            del self._query_terms[match_key]['$lt']
        except KeyError:
            pass
        try:
            if self._query_terms[match_key] == {}:
                del self._query_terms[match_key]
        except KeyError:
            pass

def _clear_minimum_terms(self, match_key):
        """clears minimum match_key term values"""
        for term in self.terms:
            if term.match_key == match_key:
                term.minimum = None

def _pipe(self):
        """On Windows we use a pipe to emulate a Linux style character
        buffer."""
        if sys.platform == 'win32':
            return os.pipe()
        else:
            return os.pipe2(os.O_NONBLOCK)

def _parse_java_version(line: str) -> tuple:
    """ Return the version number found in the first line of `java -version`

    >>> _parse_java_version('openjdk version "11.0.2" 2018-10-16')
    (11, 0, 2)
    """
    m = VERSION_RE.search(line)
    version_str = m and m.group(0).replace('"', '') or '0.0.0'
    if '_' in version_str:
        fst, snd = version_str.split('_', maxsplit=2)
        version = parse_version(fst)
        return (version[1], version[2], int(snd))
    else:
        return parse_version(version_str)

def recursive_symlink_dirs(source_d, destination_d):
    """
    Create dirs and symlink all files recursively from source_d, ignoring
    errors (e.g. existing files)
    """
    for root, dirs, files in os.walk(source_d):
        for d in dirs:
            os.mkdir(os.path.join(destination_d, root, d))
        for f in files:
            os.symlink(os.path.join(root, f), os.path.join(destination_d, root, f))

def _show_final_overflow_message(self, row_overflow, col_overflow):
        """Displays overflow message after import in statusbar"""

        if row_overflow and col_overflow:
            overflow_cause = _("rows and columns")
        elif row_overflow:
            overflow_cause = _("rows")
        elif col_overflow:
            overflow_cause = _("columns")
        else:
            raise AssertionError(_("Import cell overflow missing"))

        statustext = \
            _("The imported data did not fit into the grid {cause}. "
              "It has been truncated. Use a larger grid for full import.").\
            format(cause=overflow_cause)
        post_command_event(self.main_window, self.StatusBarMsg,
                           text=statustext)

def _show_final_overflow_message(self, row_overflow, col_overflow):
        """Displays overflow message after import in statusbar"""
        if row_overflow:
            self.statusbar.showMessage(
                "Imported {0} rows, {1} rows overflowed".format(
                    self.row_count, row_overflow
                )
            )
        elif col_overflow:
            self.statusbar.showMessage(
                "Imported {0} rows, {1} columns overflowed".format(
                    self.row_count, col_overflow
                )
            )
        else:
            self.statusbar.showMessage(
                "Imported {0} rows".format(self.row_count)
            )

def compile_emoticons(emoticons_list):
    """
    Compile a new list of emoticon tuples.
    Each tuple contains a compiled regular expression
    of the emoticon, and the html version of the emoticon.
    """
    emoticons_compiled = []
    for emoticons, image in emoticons_list:
        for emoticon in emoticons:
            context = {
                'name': emoticon,
                'image': os.path.join(EMOTICONS_DIRECTORY, image),
                'code': binascii.hexlify(emoticon.encode('utf-8'))}
            emoticons_compiled.append(
                (re.compile(re.escape(emoticon)),
                 EMOTICON_TEMPLATE.render(context).strip())
            )
    return emoticons_compiled

def _reorder(string, salt):
    """Reorders `string` according to `salt`."""
    return ''.join(sorted(string, key=lambda x: salt.index(x)))

def get_fields_with_visibility(self, visibility, mode="add"):
        """Return the AR fields with the current visibility
        """
        fields = []
        for field in self.fields.keys():
            if field in self.fields_layout:
                if self.fields_layout[field].get("visibility", "always") == visibility:
                    if mode == "add":
                        fields.append(field)
                    elif mode == "edit":
                        if self.fields_layout[field].get("editable", True):
                            fields.append(field)
        return fields

def _get_zeropoint(expnum, ccd, prefix=None, version='p'):
    """
    Retrieve the zeropoint stored in the tags associated with this image.
    @param expnum: Exposure number
    @param ccd: ccd of the exposure
    @param prefix: possible prefix (such as 'fk')
    @param version: which version: p, s, or o ?
    @return: zeropoint
    """
    if prefix is not None:
        DeprecationWarning("Prefix is no longer used here as the 'fk' and 's' have the same zeropoint.")

    key = "zeropoint_{:1s}{:02d}".format(version, int(ccd))
    return get_tag(expnum, key)

def _get_zeropoint(expnum, ccd, prefix=None, version='p'):
    """
    Retrieve the zeropoint stored in the tags associated with this image.
    @param expnum: Exposure number
    @param ccd: ccd of the exposure
    @param prefix: possible prefix (such as 'fk')
    @param version: which version: p, s, or o ?
    @return: zeropoint
    """
    if prefix is None:
        prefix = ''
    else:
        prefix = prefix + '_'
    if version == 'p':
        tag = 'zeropoint_' + prefix + str(expnum) + '_' + str(ccd)
    elif version == 's':
        tag = 'zeropoint_' + prefix + str(expnum) + '_' + str(ccd) + '_s'
    elif version == 'o':
        tag = 'zeropoint_' + prefix + str(expnum) + '_' + str(ccd) + '_o'
    else:
        raise ValueError('Unknown version: ' + version)
    return get_tag(expnum, tag)

