def read_to_end(self, record=None):
        """ Read remainder of the stream
        If a digester is included, update it
        with the data read
        """

        # no current record to read
        if not self.record:
            return None

        # already at end of this record, don't read until it is consumed
        if self.member_info:
            return None

        curr_offset = self.offset

        while True:
            b = self.record.raw_stream.read(BUFF_SIZE)
            if not b:
                break

def as_document(data, schema=None, label=u"<unicode string>"):
    """
    Translate dicts/lists and scalar (string/bool/float/int/etc.) values into a
    YAML object which can be dumped out.
    """
    if schema is None:
        schema = Any()

    return schema(YAMLChunk(schema.to_yaml(data), label=label))

def as_document(data, schema=None, label=u"<unicode string>"):
    """
    Translate dicts/lists and scalar (string/bool/float/int/etc.) values into a
    YAML object which can be dumped out.
    """
    if isinstance(data, dict):
        return _as_document_dict(data, schema, label)
    elif isinstance(data, list):
        return _as_document_list(data, schema, label)
    elif isinstance(data, basestring):
        return _as_document_string(data, schema, label)
    elif isinstance(data, bool):
        return _as_document_bool(data, schema, label)
    elif isinstance(data, int):
        return _as_document_int(data, schema, label)
    elif isinstance(data, float):
        return _as_document_float(data, schema, label)
    elif data is None:
        return _as_document_none(schema, label)
    else:
        raise ValueError("Unknown type: %s" % type(data))

