def format_value(self, val):
        """Helper function to format a value."""
        if isinstance(val, six.text_type):
            return self.format_string(val)
        else:
            return six.text_type(val)

def format_value(self, val):
        """Helper function to format a value."""
        if isinstance(val, str):
            return val
        elif isinstance(val, int):
            return str(val)
        elif isinstance(val, float):
            return str(val)
        elif isinstance(val, bool):
            return str(val).lower()
        elif isinstance(val, list):
            return ",".join(val)
        elif isinstance(val, dict):
            return ",".join(val.keys())
        else:
            raise ValueError("Unknown value type: {}".format(type(val)))

def wrap_response(self, data, many):
        """Wrap data and links according to the JSON API """
        ret = {'data': data}
        # self_url_many is still valid when there isn't any data, but self_url
        # may only be included if there is data in the ret
        if many or data:
            top_level_links = self.get_top_level_links(data, many)
            if top_level_links['self']:
                ret['links'] = top_level_links
        return ret

def wrap_response(self, data, many):
        """Wrap data and links according to the JSON API """
        if many:
            return {
                'data': data,
                'links': {
                    'self': self.get_url(self.request, self.view),
                    'next': self.get_next_link(),
                    'previous': self.get_previous_link()
                }
            }
        else:
            return {
                'data': data,
                'links': {
                    'self': self.get_url(self.request, self.view),
                }
            }

def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    if isinstance(d, str):
        return from_json(d)

    if not isinstance(d, dict):
        raise TypeError("argument must be of type dict")
    if 'nparray' not in d.keys():
        raise ValueError("input dictionary missing 'nparray' entry")

    classname = d.pop('nparray').title()
    return getattr(_wrappers, classname)(**d)

def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    return np.array(d['data'], dtype=d['dtype'])

def str_to_dt(val):
    """ Return a datetime object if the string value represents one

    Epoch integer or an ISO 8601 compatible string is
    supported.

    :param val: str
    :return: datetime
    :raise: ValueError
    """

    if isinstance(val, dt):
        return val

    try:
        if val.isdigit():
            return dt.utcfromtimestamp(float(val))
        else:
            return dt.strptime(val, '%Y-%m-%dT%H:%M:%S.%f')
    except (AttributeError, TypeError):
        raise ValueError

def str_to_dt(val):
    """ Return a datetime object if the string value represents one

    Epoch integer or an ISO 8601 compatible string is
    supported.

    :param val: str
    :return: datetime
    :raise: ValueError
    """
    if val is None:
        return None
    if isinstance(val, int):
        return datetime.fromtimestamp(val)
    if isinstance(val, str):
        return datetime.strptime(val, '%Y-%m-%dT%H:%M:%S.%f')
    raise ValueError('Invalid value for datetime: {}'.format(val))

def load_data(path, dense=False):
    """Load data from a CSV, LibSVM or HDF5 file based on the file extension.

    Args:
        path (str): A path to the CSV, LibSVM or HDF5 format file containing data.
        dense (boolean): An optional variable indicating if the return matrix
                         should be dense.  By default, it is false.

    Returns:
        Data matrix X and target vector y
    """
    if path.endswith('.csv'):
        return load_csv(path, dense=dense)
    elif path.endswith('.libsvm'):
        return load_libsvm(path, dense=dense)
    elif path.endswith('.h5'):
        return load_hdf5(path, dense=dense)
    else:
        raise ValueError('Unsupported file format.')

def iter_tags(self, number=-1, etag=None):
        """Iterates over tags on this repository.

        :param int number: (optional), return up to at most number tags.
            Default: -1 returns all available tags.
        :param str etag: (optional), ETag from a previous request to the same
            endpoint
        :returns: generator of :class:`RepoTag <github3.repos.tag.RepoTag>`\ s
        """
        params = {}
        if number != -1:
            params['per_page'] = number
        if etag:
            params['If-None-Match'] = etag
        url = self._url + '/tags'
        return self._get_page_iterator(url, params, RepoTag)

def convert_general(value):
    """Take a python object and convert it to the format Imgur expects."""
    if isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, list):
        value = [convert_general(item) for item in value]
        value = convert_to_imgur_list(value)
    elif isinstance(value, Integral):
        return str(value)
    elif 'pyimgur' in str(type(value)):
        return str(getattr(value, 'id', value))
    return value

def convert_general(value):
    """Take a python object and convert it to the format Imgur expects."""
    if isinstance(value, bool):
        return str(value).lower()
    elif isinstance(value, int):
        return str(value)
    elif isinstance(value, str):
        return value
    elif isinstance(value, list):
        return ','.join(value)
    elif isinstance(value, dict):
        return ','.join('%s=%s' % (k, v) for k, v in value.items())
    else:
        raise TypeError('Unknown type: %s' % type(value))

