def validate(self, value, redis):
        """
        Validates data obtained from a request in ISO 8061 and returns it in Datetime data type
        """

        value = self.value_or_default(value)

        self.validate_required(value)

        if value is None:
            return None

        if type(value) == str:
            try:
                value = datetime.datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
            except ValueError:
                raise InvalidFieldError(self.name)

        return value

def validate(self, value, redis):
        """
        Validates data obtained from a request in ISO 8061 and returns it in Datetime data type
        """
        try:
            return datetime.strptime(value, '%Y-%m-%dT%H:%M:%S.%fZ')
        except ValueError:
            raise ValidationError(self.error_messages['invalid'], code='invalid')

def wipe_cfg_vals_from_git_cfg(*cfg_opts):
    """Remove a set of options from Git config."""
    for cfg_key_suffix in cfg_opts:
        cfg_key = f'cherry-picker.{cfg_key_suffix.replace("_", "-")}'
        cmd = "git", "config", "--local", "--unset-all", cfg_key
        subprocess.check_call(cmd, stderr=subprocess.STDOUT)

def wipe_cfg_vals_from_git_cfg(*cfg_opts):
    """Remove a set of options from Git config."""
    git_cfg_path = os.path.expanduser('~/.gitconfig')
    git_cfg_file = open(git_cfg_path, 'r')
    git_cfg_lines = git_cfg_file.readlines()
    git_cfg_file.close()

    git_cfg_file = open(git_cfg_path, 'w')
    for line in git_cfg_lines:
        for cfg_opt in cfg_opts:
            if line.startswith(cfg_opt):
                break
        else:
            git_cfg_file.write(line)
    git_cfg_file.close()

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  if config_list is None:
    return {}
  else:
    mapping = {}
    for pair in config_list:
      if (constants.CONFIG_SEPARATOR not in pair) or (pair.count(constants.CONFIG_SEPARATOR) != 1):
        raise ValueError("configs must be passed as two strings separted by a %s", constants.CONFIG_SEPARATOR)
      (config, value) = pair.split(constants.CONFIG_SEPARATOR)
      mapping[config] = value
    return mapping

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  config_dict = {}
  for config_item in config_list:
    config_key, config_value = config_item.split('=')
    config_dict[config_key] = config_value
  return config_dict

def mark_as_read(self, request, pk):
        """ Marks the considered forums as read. """
        if self.top_level_forum is not None:
            forums = request.forum_permission_handler.get_readable_forums(
                self.top_level_forum.get_descendants(include_self=True), request.user,
            )
        else:
            forums = request.forum_permission_handler.get_readable_forums(
                Forum.objects.all(), request.user,
            )

        # Marks forums as read
        track_handler.mark_forums_read(forums, request.user)

        if len(forums):
            messages.success(request, self.success_message)

        return HttpResponseRedirect(self.get_top_level_forum_url())

