def add_hashed_value(self, hash_value, store_key):
        """Add hashed value to the index.

        :param hash_value: The hashed value to be added to the index
        :type hash_value: str
        :param store_key: The key for the document in the store
        :type store_key: object

        """
        if self._unique and hash_value in self._index:
            raise NonUnique('Hash value {} already in index'.format(hash_value))
        if store_key not in self._index[hash_value]:
            self._index[hash_value].append(store_key)
        if hash_value not in self._reverse_index[store_key]:
            self._reverse_index[store_key].append(hash_value)

def child_added(self, child):
        """ Handle the child added event from the declaration.

        This handler will unparent the child toolkit widget. Subclasses
        which need more control should reimplement this method.

        """
        super(AndroidViewGroup, self).child_added(child)

        widget = self.widget
        #: TODO: Should index be cached?
        for i, child_widget in enumerate(self.child_widgets()):
            if child_widget == child.widget:
                if child.layout_params:
                    widget.addView_(child_widget, i,
                                             child.layout_params)
                else:
                    widget.addView(child_widget, i)

def output(self, stream, disabletransferencoding = None):
        """
        Set output stream and send response immediately
        """
        if self._sendHeaders:
            raise HttpProtocolException('Cannot modify response, headers already sent')
        self.outputstream = stream
        try:
            content_length = len(stream)
        except Exception:
            pass
        else:
            self.header(b'Content-Length', str(content_length).encode('ascii'))
        if disabletransferencoding is not None:
            self.disabledeflate = disabletransferencoding
        self._startResponse()

def output(self, stream, disabletransferencoding = None):
        """
        Set output stream and send response immediately
        """
        if disabletransferencoding is None:
            disabletransferencoding = self.disabletransferencoding
        if disabletransferencoding:
            self.disabletransferencoding = disabletransferencoding
        self.stream = stream
        self.send()

def _parse_and_store_headers(self):
        """
        Coroutine used retrieve header data and parse each header until
        the body is found.
        """
        while True:
            line = yield from self._read_line()
            if line == b'':
                raise InvalidResponse('Connection closed')
            if line == b'\r\n':
                break
            if line.startswith(b'HTTP/'):
                self._parse_status_line(line)
            else:
                self._parse_header(line)

