    """
    if id is None and name is None:
        raise ValueError("You must provide either an ID or a name")
    if id is not None and name is not None:
        raise ValueError("You must provide either an ID or a name, not both")
    if id is not None:
        return Project.query.get(id)
    if name is not None:
        return Project.query.filter_by(name=name).first()

def _convert_priority(p_priority):
    """
    Converts todo.txt priority to an iCalendar priority (RFC 2445).

    Priority A gets priority 1, priority B gets priority 5 and priority C-F get
    priorities 6-9. This scheme makes sure that clients that use "high",
    "medium" and "low" show the correct priority.
    """
    if p_priority == "A":
        return 1
    elif p_priority == "B":
        return 5
    elif p_priority == "C":
        return 6
    elif p_priority == "D":
        return 7
    elif p_priority == "E":
        return 8
    elif p_priority == "F":
        return 9
    else:
        return 0

def df(self, list_of_points, force_read=True):
        """
        When connected, calling DF should force a reading on the network.
        """

        his = []
        for point in list_of_points:
            try:
                his.append(self._findPoint(point, force_read=force_read).history)
            except ValueError as ve:
                self._log.error("{}".format(ve))
                continue
        if not _PANDAS:
            return dict(zip(list_of_points, his))
        return pd.DataFrame(dict(zip(list_of_points, his)))

