def validate_session(self, session, latest_only=False):
        """ Check that a session is present in the metadata dictionary.

        raises :exc:`~billy.scrape.NoDataForPeriod` if session is invalid

        :param session:  string representing session to check
        """
        if latest_only:
            if session != self.metadata['terms'][-1]['sessions'][-1]:
                raise NoDataForPeriod(session)

        for t in self.metadata['terms']:
            if session in t['sessions']:
                return True
        raise NoDataForPeriod(session)

def validate_session(self, session, latest_only=False):
        """ Check that a session is present in the metadata dictionary.

        raises :exc:`~billy.scrape.NoDataForPeriod` if session is invalid

        :param session:  string representing session to check
        """
        if session not in self.metadata['sessions']:
            raise NoDataForPeriod('No data for session %s' % session)

        if latest_only:
            return

        session_data = self.metadata['sessions'][session]
        if session_data['start_date'] > session_data['end_date']:
            raise NoDataForPeriod('Session %s has no data' % session)

def load_from_file(self, path):
        """
        Load cookies from the file.

        Content of file should be a JSON-serialized list of dicts.
        """

        with open(path) as inf:
            data = inf.read()
            if data:
                items = json.loads(data)
            else:
                items = {}
        for item in items:
            extra = dict((x, y) for x, y in item.items()
                         if x not in ['name', 'value', 'domain'])
            self.set(item['name'], item['value'], item['domain'], **extra)

def _gather_group_members(group, groups, users):
    """
    Gather group members
    """
    _group = __salt__['group.info'](group)

    if not _group:
        log.warning('Group %s does not exist, ignoring.', group)
        return

    for member in _group['members']:
        if member not in users:
            users[member] = groups[group]

def _gather_group_members(group, groups, users):
    """
    Gather group members
    """
    group_members = []
    for member in group.get('members', []):
        if member['type'] == 'group':
            group_members.extend(_gather_group_members(groups[member['id']], groups, users))
        else:
            group_members.append(users[member['id']])
    return group_members

def describe_key_pairs():
    """
    Returns all key pairs for region
    """
    region_keys = {}
    for r in boto3.client('ec2', 'us-west-2').describe_regions()['Regions']:
        region = r['RegionName']
        client = boto3.client('ec2', region_name=region)
        try:
            pairs = client.describe_key_pairs()
            if pairs:
                region_keys[region] = pairs
        except Exception as e:
            app.logger.info(e)
    return region_keys

