def tensor_product_basis(*bases):
    """
    Returns a TomographyBasis formed by the tensor
    product of two or more factor bases. Each basis element
    is the tensor product of basis elements from the underlying
    factors.
    """
    if len(bases) == 1:
        return bases[0]
    else:
        return TensorProductBasis(bases[0], tensor_product_basis(*bases[1:]))

def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    kv = _parse_linux_cmdline(cmdline)
    if state == 'absent':
        try:
            del kv[name]
        except KeyError:
            pass
    elif state == 'present':
        kv[name] = value
    return _assemble_linux_cmdline(kv)

def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    if value is None:
        # Remove the parameter
        return ' '.join([x for x in cmdline.split() if x != name])
    else:
        # Replace the parameter
        return ' '.join([x if x != name else value for x in cmdline.split()])

def make_version(ref=None):
    """Build git version string for current directory"""
    if ref is None:
        ref = "HEAD"
    try:
        import subprocess
        p = subprocess.Popen(["git", "describe", "--tags", "--always", "--dirty", ref],
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out, err = p.communicate()
        if p.returncode != 0:
            raise RuntimeError("git describe failed: %s" % err)
        return out.strip()
    except:
        return "unknown"

def responsify(error):
    """Take an Error model and return it as a Flask response"""
    assert str(type(error).__name__) == 'Error'
    if error.error in code_to_class:
        e = code_to_class[error.error](error.error_description)
        if error.error_id:
            e.error_id = error.error_id
        if error.user_message:
            e.user_message = error.user_message
        return e.http_reply()
    elif isinstance(error, PyMacaronException):
        return error.http_reply()
    else:
        return PyMacaronException("Caught un-mapped error: %s" % error).http_reply()

def responsify(error):
    """Take an Error model and return it as a Flask response"""
    return jsonify({
        'error': error.name,
        'description': error.description
    }), error.status_code

