def inherit_kwargs(inherit_func):
    """
    TODO move to util_decor
    inherit_func = inspect_pdfs
    func = encoder.visualize.im_func
    """
    def wrapper(*args, **kwargs):
        func_kwargs = inspect.getcallargs(func, *args, **kwargs)
        inherit_kwargs = inspect.getcallargs(inherit_func, *args, **kwargs)
        for k, v in inherit_kwargs.items():
            if k not in func_kwargs:
                func_kwargs[k] = v
        return func(**func_kwargs)
    return wrapper

def read_config(
        config_filepath,
        logger=logging.getLogger('ProsperCommon'),
):
    """fetch and parse config file

    Args:
        config_filepath (str): path to config file.  abspath > relpath
        logger (:obj:`logging.Logger`): logger to catch error msgs

    """
    config = {}
    try:
        with open(config_filepath, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logger.error(f'config file not found: {config_filepath}')
    except json.decoder.JSONDecodeError:
        logger.error(f'config file not valid json: {config_filepath}')
    return config

def cov_from_scales(self, scales):
        """Return a covariance matrix built from a dictionary of scales.

        `scales` is a dictionary keyed by stochastic instances, and the
        values refer are the variance of the jump distribution for each
        stochastic. If a stochastic is a sequence, the variance must
        have the same length.
        """
        cov = np.zeros((self.dimension, self.dimension))
        for i, stoch in enumerate(self.stochastics):
            if isinstance(stoch, Stochastic):
                cov[i, i] = scales[stoch]
            else:
                for j, stoch2 in enumerate(stoch):
                    cov[i, j] = scales[stoch2]
                    cov[j, i] = scales[stoch2]
        return cov

def run_script(self, description):
        """
        Run an existing script using its description to look it up

        Usage: C{engine.run_script(description)}

        @param description: description of the script to run
        @raise Exception: if the specified script does not exist
        """
        targetScript = None
        for item in self.configManager.allItems:
            if item.description == description and isinstance(item, model.Script):
                targetScript = item

        if targetScript is not None:
            self.runner.run_subscript(targetScript)
        else:
            raise Exception("No script with description '%s' found" % description)

def run_script(self, description):
        """
        Run an existing script using its description to look it up

        Usage: C{engine.run_script(description)}

        @param description: description of the script to run
        @raise Exception: if the specified script does not exist
        """
        script = self.get_script(description)
        if script is None:
            raise Exception("Script %s does not exist" % description)
        script.run()

def reset(self, index=None):
        """
        Reset the points for the specified index position.  If no index is
        specified, reset points for all point handlers.
        """
        points_handler_count = len(self.registration_view.points)
        if index is None:
            indexes = range(points_handler_count)
        else:
            indexes = [index]

        indexes = [i for i in indexes if i < points_handler_count]

        for i in indexes:
            self.registration_view.points[i].reset()
        if indexes:
            self.registration_view.update_transform()

def reset(self, index=None):
        """
        Reset the points for the specified index position.  If no index is
        specified, reset points for all point handlers.
        """
        if index is None:
            for i in range(self.GetNumberOfPointHandlers()):
                self.Reset(i)
        else:
            self.Reset(index)

