def get_processor(self, entity_id, sp_config):
        """ Instantiate user-specified processor or default to an all-access base processor.
            Raises an exception if the configured processor class can not be found or initialized.
        """
        processor_string = sp_config.get('processor', None)
        if processor_string:
            try:
                return import_string(processor_string)(entity_id)
            except Exception as e:
                logger.error("Failed to instantiate processor: {} - {}".format(processor_string, e), exc_info=True)
                raise
        return BaseProcessor(entity_id)

def get_processor(self, entity_id, sp_config):
        """ Instantiate user-specified processor or default to an all-access base processor.
            Raises an exception if the configured processor class can not be found or initialized.
        """
        processor_class = sp_config.get('processor_class')
        if processor_class is None:
            processor_class = 'all_access_processor'
        try:
            processor_class = getattr(self, processor_class)
        except AttributeError:
            raise Exception('Processor class %s not found' % processor_class)
        try:
            processor = processor_class(entity_id, sp_config)
        except Exception as e:
            raise Exception('Processor class %s could not be initialized: %s' % (processor_class, e))
        return processor

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        if not check_namespace(namespace_id):
            return self._reply_json({'error': 'Invalid namespace'}, status_code=400)

        blockstackd_url = get_blockstackd_url()
        name_count = blockstackd_client.get_num_names_in_namespace(namespace_id, hostport=blockstackd_url)
        if json_is_error(name_count):
            log.error("Failed to load namespace count for {}: {}".format(namespace_id, name_count['error']))
            return self._reply_json({'error': 'Failed to load namespace count: {}'.format(name_count['error'])}, status_code=404)

        self._reply_json({'names_count': name_count})

def from_dict(data, ctx):
        """
        Instantiate a new DynamicOrderState from a dict (generally from loading
        a JSON response). The data used to instantiate the DynamicOrderState is
        a shallow copy of the dict passed in, with any complex child types
        instantiated appropriately.
        """

        data = data.copy()

        if data.get('trailingStopValue') is not None:
            data['trailingStopValue'] = ctx.convert_decimal_number(
                data.get('trailingStopValue')
            )

        if data.get('triggerDistance') is not None:
            data['triggerDistance'] = ctx.convert_decimal_number(
                data.get('triggerDistance')
            )

        return DynamicOrderState(**data)

