def _get_rnn_layer(mode, num_layers, input_size, hidden_size, dropout, weight_dropout):
    """create rnn layer given specs"""
    if mode == 'rnn_relu':
        rnn_block = functools.partial(rnn.RNN, activation='relu')
    elif mode == 'rnn_tanh':
        rnn_block = functools.partial(rnn.RNN, activation='tanh')
    elif mode == 'lstm':
        rnn_block = rnn.LSTM
    elif mode == 'gru':
        rnn_block = rnn.GRU

    block = rnn_block(hidden_size, num_layers, dropout=dropout,
                      input_size=input_size)

    if weight_dropout:
        apply_weight_drop(block, '.*h2h_weight', rate=weight_dropout)

    return block

def _get_rnn_layer(mode, num_layers, input_size, hidden_size, dropout, weight_dropout):
    """create rnn layer given specs"""
    if mode == 'LSTM':
        return nn.LSTM(input_size, hidden_size, num_layers, dropout=dropout,
                       bidirectional=True, batch_first=True)
    elif mode == 'GRU':
        return nn.GRU(input_size, hidden_size, num_layers, dropout=dropout,
                      bidirectional=True, batch_first=True)
    elif mode == 'RNN':
        return nn.RNN(input_size, hidden_size, num_layers, dropout=dropout,
                      bidirectional=True, batch_first=True)
    else:
        raise ValueError('Unknown mode: {}'.format(mode))

def create_token_response(self, uri, http_method='GET', body=None,
                              headers=None, credentials=None):
        """Extract grant_type and route to the designated handler."""
        if not headers:
            headers = {}
        if not credentials:
            credentials = {}
        grant_type = self.get_grant_type(headers)
        if grant_type == 'authorization_code':
            return self.create_authorization_code_response(uri, http_method,
                                                           body, headers,
                                                           credentials)
        elif grant_type == 'client_credentials':
            return self.create_client_credentials_response(uri, http_method,
                                                           body, headers,
                                                           credentials)
        elif grant_type == 'password':
            return self.create_password_response(uri, http_method, body,
                                                 headers, credentials)
        elif grant_type == 'refresh_token':
            return self.create_refresh_token_response(uri, http_method, body,
                                                      headers, credentials)
        else:
            raise UnsupportedGrantType()

def to_auto_download_state(arg):
    """
    to_auto_download_state(arg) attempts to coerce the given argument into a valid auto-downloading
      instruction. Essentially, if arg is "on", "yes", "true", "1", True, or 1, then True is
      returned; if arg is "structure" then "structure" is returned; otherwise False is returned.
    """
    if isinstance(arg, bool):
        return arg
    if isinstance(arg, int):
        return arg != 0
    if isinstance(arg, str):
        arg = arg.lower()
        if arg in ("on", "yes", "true", "1"):
            return True
        if arg == "structure":
            return "structure"
        return False
    return False

