def get_pks_for_filter(self, key, filter_type, value):
        """Extract the pks from the zset key for the given type and value

        For the parameters, see BaseRangeIndex.get_pks_for_filter
        """
        if filter_type == 'gt':
            return self.zrangebyscore(key, value, '+inf')
        elif filter_type == 'gte':
            return self.zrangebyscore(key, value, '+inf', withscores=True)
        elif filter_type == 'lt':
            return self.zrangebyscore(key, '-inf', value)
        elif filter_type == 'lte':
            return self.zrangebyscore(key, '-inf', value, withscores=True)
        elif filter_type == 'eq':
            return self.zrangebyscore(key, value, value)
        elif filter_type == 'ne':
            return self.zrangebyscore(key, '-inf', '+inf')
        elif filter_type == 'in':
            return self.zrangebyscore(key, *value)
        elif filter_type == 'nin':
            return self.zrangebyscore(key, '-inf', '+inf')
        else:
            raise ValueError('Invalid filter type: %s' % filter_type)

def serializeFields(obj, order=None):
    """
    Turn an object's fields into a ';' and ',' seperated string.

    If order is None, obj should be a list, backslash escape each field and
    return a ';' separated string.
    """
    fields = []
    if order is None:
        fields = [backslashEscape(val) for val in obj]
    else:
        for field in order:
            escapedValueList = [backslashEscape(val) for val in
                                toList(getattr(obj, field))]
            fields.append(','.join(escapedValueList))
    return ';'.join(fields)

def serializeFields(obj, order=None):
    """
    Turn an object's fields into a ';' and ',' seperated string.

    If order is None, obj should be a list, backslash escape each field and
    return a ';' separated string.
    """
    if order is None:
        return ';'.join(
            [
                field.replace('\\', '\\\\').replace(';', '\\;')
                for field in obj
            ]
        )
    else:
        return ','.join(
            [
                field.replace('\\', '\\\\').replace(',', '\\,')
                for field in order
            ]
        )

