def _updateImage(self):
        """Internal method to render text as an image."""
        # Fill the background of the image
        if self.backgroundColor is not None:
            self.textImage.fill(self.backgroundColor)

        # Render the text as a single line, and blit it onto the textImage surface
        if self.mask is None:
            lineSurface = self.font.render(self.text, True, self.textColor)
        else:
            nChars = len(self.text)
            maskedText = self.mask * nChars
            lineSurface = self.font.render(maskedText, True, self.textColor)
        self.textImage.blit(lineSurface, (0, 0))

def _cast_dict(self, data_dict):
        """Internal method that makes sure any dictionary elements
        are properly cast into the correct types, instead of
        just treating everything like a string from the csv file.

        Args:
            data_dict: dictionary containing bro log data.

        Returns:
            Cleaned Data dict.
        """
        for key, value in data_dict.items():
            if isinstance(value, str):
                try:
                    data_dict[key] = int(value)
                except ValueError:
                    try:
                        data_dict[key] = float(value)
                    except ValueError:
                        pass
        return data_dict

def getRenderModelErrorNameFromEnum(self, error):
        """Returns a string for a render model error"""
        if error == vr.TrackedDevicePose_t.TrackingResult_Uninitialized:
            return "Uninitialized"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Calibrating_InProgress:
            return "Calibrating_InProgress"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Calibrating_OutOfRange:
            return "Calibrating_OutOfRange"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Running_OK:
            return "Running_OK"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Running_OutOfRange:
            return "Running_OutOfRange"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Fallback_RotationOnly:
            return "Fallback_RotationOnly"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Fallback_PositionOnly:
            return "Fallback_PositionOnly"
        elif error == vr.TrackedDevicePose_t.TrackingResult_Error:
            return "Error"
        else:
            return "Unknown"

def extend_children(children):
    """
    extend_children(children)

    Returns a set containing
    nearest conditionally stochastic (Stochastic, not Deterministic) descendants.
    """
    extended_children = set()
    for child in children:
        if isinstance(child, Stochastic):
            extended_children.add(child)
        else:
            extended_children.update(extend_children(child.children))
    return extended_children

def to_native_types(self, slicer=None, na_rep='nan', quoting=None,
                        **kwargs):
        """ convert to our native types format, slicing if desired """

        values = self.get_values()

        if slicer is not None:
            values = values[:, slicer]
        mask = isna(values)

        if not self.is_object and not quoting:
            values = values.astype(str)
        else:
            values = np.array(values, dtype='object')

        values[mask] = na_rep
        return values

def to_native_types(self, slicer=None, na_rep='nan', quoting=None,
                        **kwargs):
        """ convert to our native types format, slicing if desired """
        if slicer is not None:
            slicer = self._slice(slicer)
        return self._engine.to_native_types(slicer=slicer,
                                           na_rep=na_rep,
                                           quoting=quoting,
                                           **kwargs)

def check_input_data_type(self):
        """Check the input data types of the state

        Checks all input data ports if the handed data is not of the specified type and generate an error logger message
        with details of the found type conflict.
        """
        for data_port in self.input_data_ports.values():
            if data_port.name in self.input_data and self.input_data[data_port.name] is not None:
                #check for class
                if not isinstance(self.input_data[data_port.name], data_port.data_type):
                    logger.error("{0} had an data port error: Input of execute function must be of type '{1}' not '{2}'"
                                 " as current value '{3}'".format(self, data_port.data_type.__name__,
                                                               type(self.input_data[data_port.name]).__name__,
                                                               self.input_data[data_port.name]))

def check_input_data_type(self):
        """Check the input data types of the state

        Checks all input data ports if the handed data is not of the specified type and generate an error logger message
        with details of the found type conflict.
        """
        for port in self.input_ports:
            if port.data_type is not None:
                if not isinstance(self.input_ports[port.name].data, port.data_type):
                    self.logger.error(
                        f"Input data type mismatch for port {port.name} of state {self.name}. "
                        f"Expected type {port.data_type} but got {type(self.input_ports[port.name].data)}"
                    )

def _pop_async_request(self, msg_id, msg_name):
        """Pop the set of callbacks for a request.

        Return tuple of Nones if callbacks already popped (or don't exist).

        """
        if msg_id in self._async_callbacks:
            callbacks = self._async_callbacks[msg_id]
            self._async_callbacks.pop(msg_id)
            return callbacks
        else:
            return None, None

def get_namespace_preorder_burn_info( outputs ):
    """
    Given the set of outputs, find the fee sent 
    to our burn address.

    Return the fee and burn address on success as {'op_fee': ..., 'burn_address': ...}
    Return None if not found
    """
    if len(outputs) < 3:
        # not a well-formed preorder 
        return None 

    op_fee = outputs[2]['value']
    burn_address = None

    try:
        burn_address = virtualchain.script_hex_to_address(outputs[2]['script'])
        assert burn_address
    except:
        log.warning("Invalid burn script: {}".format(outputs[2]['script']))
        return None

    return {'op_fee': op_fee, 'burn_address': burn_address}

def get_namespace_preorder_burn_info( outputs ):
    """
    Given the set of outputs, find the fee sent 
    to our burn address.

    Return the fee and burn address on success as {'op_fee': ..., 'burn_address': ...}
    Return None if not found
    """
    for output in outputs:
        if output['address'] == BURN_ADDRESS:
            return {'op_fee': output['amount'], 'burn_address': output['address']}
    return None

def drum_status(self, filter_supported: bool = True) -> Dict[str, Any]:
        """Return the state of all drums."""
        drum_status = {}
        for color in self.COLOR_NAMES:
            try:
                drum_stat = self.data.get('{}_{}'.format(SyncThru.DRUM, color),
                                          {})
                if filter_supported and drum_stat.get('opt', 0) == 0:
                    continue
                else:
                    drum_status[color] = drum_stat
            except (KeyError, AttributeError):
                drum_status[color] = {}
        return drum_status

def drum_status(self, filter_supported: bool = True) -> Dict[str, Any]:
        """Return the state of all drums."""
