def get_wbfmt(self, data_nt=None):
        """Return format for text cell."""
        if data_nt is None or self.b_plain:
            return self.fmtname2wbfmtobj.get('plain')
        # User namedtuple field/value for color
        if self.ntfld_wbfmt is not None:
            return self.__get_wbfmt_usrfld(data_nt)
        # namedtuple format_txt for color/bold/border
        if self.b_format_txt:
            wbfmt = self.__get_wbfmt_format_txt(data_nt)
            if wbfmt is not None:
                return wbfmt
        # 'ntfld_wbfmt': namedtuple field which contains a value used as a key for a xlsx format
        # 'ntval2wbfmtdict': namedtuple value and corresponding xlsx format dict.
        return self.fmtname2wbfmtobj.get('plain')

def get_wbfmt(self, data_nt=None):
        """Return format for text cell."""
        if data_nt is None:
            data_nt = self.data_nt
        if data_nt is None:
            return None
        if self.wb_format is None:
            self.wb_format = self.wb.add_format({'num_format': data_nt})
        return self.wb_format

def is_existing_up_to_date(destination, latest_version):
    """Returns False if there is no existing install or if the existing install
    is out of date. Otherwise, returns True."""
    if not os.path.exists(destination):
        return False
    else:
        existing_version = get_version_from_file(destination)
        return existing_version == latest_version

def read_table(self, table_type):
        """Read either the hash or block table of a MPQ archive."""

        if table_type == 'hash':
            entry_class = MPQHashTableEntry
        elif table_type == 'block':
            entry_class = MPQBlockTableEntry
        else:
            raise ValueError("Invalid table type.")

        table_offset = self.header['%s_table_offset' % table_type]
        table_entries = self.header['%s_table_entries' % table_type]
        key = self._hash('(%s table)' % table_type, 'TABLE')

        self.file.seek(table_offset + self.header['offset'])
        data = self.file.read(table_entries * 16)
        data = self._decrypt(data, key)

        def unpack_entry(position):
            entry_data = data[position*16:position*16+16]
            return entry_class._make(
                struct.unpack(entry_class.struct_format, entry_data))

        return [unpack_entry(i) for i in range(table_entries)]

def get_management_commands(settings):
    """
    Find registered managemend commands and return their classes
    as a :class:`dict`. Keys are names of the management command
    and values are classes of the management command.
    """
    from django.core.management.base import BaseCommand

    commands = {}
    for app in settings.INSTALLED_APPS:
        try:
            app_module = import_module(app)
        except ImportError:
            continue
        try:
            commands_module = import_module('%s.management' % app)
        except ImportError:
            continue
        for name, obj in inspect.getmembers(commands_module):
            if inspect.isclass(obj) and issubclass(obj, BaseCommand):
                commands[name] = obj
    return commands

def readTypedObject(self):
        """
        Reads an aliased ActionScript object from the stream and attempts to
        'cast' it into a python class.

        @see: L{pyamf.register_class}
        """
        class_alias = self.readString()

        try:
            alias = self.context.getClassAlias(class_alias)
        except pyamf.UnknownClassAlias:
            if self.strict:
                raise

            alias = pyamf.TypedObjectClassAlias(class_alias)

        obj = alias.createInstance(codec=self)
        self.context.addObject(obj)

        attrs = self.readObjectAttributes(obj)
        alias.applyAttributes(obj, attrs, codec=self)

        return obj

def get(self, uri, disable_proxy=False, stream=False):
        """Return Requests response to GET request."""
        response = requests.get(
            uri,
            headers=self.headers,
            allow_redirects=True,
            cookies={},
            stream=stream,
            proxies=self.proxy if not disable_proxy else False
        )

        if response.status_code in _PERMITTED_STATUS_CODES:
            self.response_headers = response.headers
            return response.content if not stream else response.iter_content()
        else:
            raise requests.exceptions.HTTPError(
                "HTTP response did not have a permitted status code."
            )

def get(self, uri, disable_proxy=False, stream=False):
        """Return Requests response to GET request."""
        return self._request('GET', uri, disable_proxy=disable_proxy, stream=stream)

def clean_text(self, domain, **kwargs):
        """Try to extract only the domain bit from the """
        if domain is None:
            return None
        if domain.startswith('http://'):
            domain = domain[7:]
        if domain.startswith('https://'):
            domain = domain[8:]
        if domain.startswith('www.'):
            domain = domain[4:]
        if domain.endswith('/'):
            domain = domain[:-1]
        return domain

def __skip_updates(self):
        """
        Get and discard all pending updates before first poll of the bot
        :return: total updates skipped
        """
        total_skipped = 0
        while True:
            try:
                self.get_updates(offset=total_skipped + 1)
                total_skipped += 1
            except telegram.error.TimedOut:
                break
        return total_skipped

