def _verify(function):
    """decorator to ensure pin is properly set up"""
    def _verify_wrapper(self, *args, **kwargs):
        if not self.is_setup:
            raise PinError("Pin %s is not setup" % self)
        return function(self, *args, **kwargs)
    return _verify_wrapper

def _get_context(keyspaces, connections):
    """Return all the execution contexts"""

    if keyspaces:
        if not isinstance(keyspaces, (list, tuple)):
            raise ValueError('keyspaces must be a list or a tuple.')

    if connections:
        if not isinstance(connections, (list, tuple)):
            raise ValueError('connections must be a list or a tuple.')

    keyspaces = keyspaces if keyspaces else [None]
    connections = connections if connections else [None]

    return product(connections, keyspaces)

def _get_context(keyspaces, connections):
    """Return all the execution contexts"""
    context = {}
    for keyspace in keyspaces:
        context[keyspace] = {}
        for connection in connections:
            context[keyspace][connection] = {}
    return context

def _get_qtyprc(self, n_points=6):
        """ Returns a list of tuples of the form (qty, prc) created from the
        cost function.  If the cost function is polynomial it will be converted
        to piece-wise linear using poly_to_pwl(n_points).
        """
        if self.cost_function.is_polynomial():
            return self.poly_to_pwl(n_points)
        else:
            return self.cost_function.get_qtyprc()

