def get_files(self, commit, paths, recursive=False):
        """
        Returns the contents of a list of files at a specific Commit as a
        dictionary of file paths to data.

        Params:
        * commit: A tuple, string, or Commit object representing the commit.
        * paths: A list of paths to retrieve.
        * recursive: If True, will go into each directory in the list
        recursively.
        """
        if isinstance(commit, tuple):
            commit = self.get_commit(commit)
        elif isinstance(commit, str):
            commit = self.get_commit(commit)
        elif not isinstance(commit, Commit):
            raise TypeError("commit must be a tuple, string, or Commit object")

        if not isinstance(paths, list):
            raise TypeError("paths must be a list")

        if not isinstance(recursive, bool):
            raise TypeError("recursive must be a boolean")

        files = {}
        for path in paths:
            if recursive:
                files.update(self._get_files_recursive(commit, path))
            else:
                files.update(self._get_files(commit, path))

        return files

def whofaved_deviation(self, deviationid, offset=0, limit=10):

        """Fetch a list of users who faved the deviation

        :param deviationid: The deviationid you want to fetch
        :param offset: the pagination offset
        :param limit: the pagination limit
        """

        response = self._req('/deviation/whofaved', get_data={
            'deviationid' : deviationid,
            'offset' : offset,
            'limit' : limit
        })

        users = []

        for item in response['results']:
            u = {}
            u['user'] = User()
            u['user'].from_dict(item['user'])
            u['time'] = item['time']

            users.append(u)

        return {
            "results" : users,
            "has_more" : response['has_more'],
            "next_offset" : response['next_offset']
        }

def handle(self, data, **kwargs):
        """Run marshalling for the specified mapper_class.

        Supports both .marshal and .many().marshal Kim interfaces.  Handles errors raised
        during marshalling and automatically returns a HTTP error response.

        :param data: Data to be marshaled.
        :returns: Marshaled object according to mapper configuration
        :raises: :class:`werkzeug.exceptions.UnprocessableEntity`
        """
        try:
            if self.many:
                return self.mapper.many(raw=self.raw, **self.mapper_kwargs).marshal(
                    data, role=self.role
                )
            else:
                return self.mapper(
                    data=data,
                    obj=self.obj,
                    partial=self.partial,
                    **self.mapper_kwargs
                ).marshal(role=self.role)
        except MappingInvalid as e:
            self.handle_error(e)

def handle(self, data, **kwargs):
        """Run marshalling for the specified mapper_class.

        Supports both .marshal and .many().marshal Kim interfaces.  Handles errors raised
        during marshalling and automatically returns a HTTP error response.

        :param data: Data to be marshaled.
        :returns: Marshaled object according to mapper configuration
        :raises: :class:`werkzeug.exceptions.UnprocessableEntity`
        """
        try:
            if isinstance(data, list):
                return self.many().marshal(data, **kwargs)
            else:
                return self.marshal(data, **kwargs)
        except (ValidationError, TypeError) as e:
            raise UnprocessableEntity(str(e))

def is_taps_aff(self):
        """Returns True if taps aff for this location"""

        request = requests.get('https://www.taps-aff.co.uk/api/%s' % self.location)
        if request.status_code == 200:
            try:
                taps = request.json()['taps']['status']
                if taps == 'aff':
                    return True
                elif taps == 'oan':
                    return False
                else:
                    raise RuntimeError("Unexpected taps value: %s" % taps)
            except ValueError:
                raise RuntimeError("Unexpected response from service")
        else:
            raise IOError("Failure downloading from Api")

def is_taps_aff(self):
        """Returns True if taps aff for this location"""
        return self.taps_aff

def get_options(option_type, from_options):
    """Extract options for specified option type from all options

    :param option_type: the object of specified type of options
    :param from_options: all options dictionary
    :return: the dictionary of options for specified type, each option can be filled by value from all options
             dictionary or blank in case the option for specified type is not exist in all options dictionary
    """
    options = {}
    for option_name, option_value in from_options.items():
        if isinstance(option_value, option_type):
            options[option_name] = option_value
    return options

def _assemble_regulate_amount(stmt):
    """Assemble RegulateAmount statements into text."""
    obj_str = _assemble_agent_str(stmt.obj)
    if stmt.subj is not None:
        subj_str = _assemble_agent_str(stmt.subj)
        if isinstance(stmt, ist.IncreaseAmount):
            rel_str = ' increases the amount of '
        elif isinstance(stmt, ist.DecreaseAmount):
            rel_str = ' decreases the amount of '
        stmt_str = subj_str + rel_str + obj_str
    else:
        if isinstance(stmt, ist.IncreaseAmount):
            stmt_str = obj_str + ' is produced'
        elif isinstance(stmt, ist.DecreaseAmount):
            stmt_str = obj_str + ' is degraded'
    return _make_sentence(stmt_str)

def _assemble_regulate_amount(stmt):
    """Assemble RegulateAmount statements into text."""
    regulator = stmt.regulator.name
    target = stmt.target.name
    if stmt.regulator.db_refs.get('FPLX'):
        regulator = stmt.regulator.db_refs['FPLX']
    if stmt.target.db_refs.get('FPLX'):
        target = stmt.target.db_refs['FPLX']
    if stmt.evidence[0].epistemics.get('direct'):
        return '{} regulates the amount of {}'.format(regulator, target)
    else:
        return '{} regulates the amount of {} in {}'.format(regulator,
                                                           target,
                                                           stmt.evidence[0].
                                                           annotations['cell_type'])

def log_fault (exc, message = "", level = logging.CRITICAL,
               traceback = False):
  """Print the usual traceback information, followed by a listing of all
  the local variables in each frame.
  """
  if traceback:
    logging.log (level, message, exc)
  else:
    logging.log (level, message)
  for frame in inspect.getinnerframes (inspect.currentframe ()):
    logging.log (level, "  %s: %s" % (frame.filename, frame.lineno))
    for name, value in frame.f_locals.items ():
      logging.log (level, "    %s = %s" % (name, value))

def stats(self, symbol):
        """
        curl https://api.bitfinex.com/v1/stats/btcusd
        [
            {"period":1,"volume":"7410.27250155"},
            {"period":7,"volume":"52251.37118006"},
            {"period":30,"volume":"464505.07753251"}
        ]
        """
        data = self._get(self.url_for(PATH_STATS, (symbol)))

        for period in data:

            for key, value in period.items():
                if key == 'period':
                    new_value = int(value)
                elif key == 'volume':
                    new_value = float(value)

                period[key] = new_value

        return data

