def _pre_process_cfg(self):
        """
        Pre-process the acyclic CFG.
        - Change all FakeRet edges to normal edges when necessary (e.g. the normal/expected return edge does not exist)
        """
        for _, dst, data in self._acyclic_cfg.graph.edges(data=True):
            if 'jumpkind' in data and data['jumpkind'] == 'Ijk_FakeRet':
                all_edges_to_dst = self._acyclic_cfg.graph.in_edges([ dst ], data=True)
                if not any((s, d) for s, d, da in all_edges_to_dst if da['jumpkind'] != 'Ijk_FakeRet' ):
                    # All in edges are FakeRets
                    # Change them to a normal edge
                    for _, _, data_ in all_edges_to_dst:
                        data_['jumpkind'] = 'Ijk_Boring'

def get_mirrors(hostname=None):
    """Return the list of mirrors from the last record found on the DNS
    entry::

    >>> from pip.index import get_mirrors
    >>> get_mirrors()
    ['a.pypi.python.org', 'b.pypi.python.org', 'c.pypi.python.org',
    'd.pypi.python.org']

    Originally written for the distutils2 project by Alexis Metaireau.
    """
    if hostname is None:
        hostname = socket.gethostname()
    try:
        hostname = socket.gethostbyname(hostname)
    except socket.error:
        return []
    try:
        answer = socket.getaddrinfo(hostname, 80, socket.AF_INET,
                                    socket.SOCK_STREAM)
    except socket.gaierror:
        return []
    if not answer:
        return []
    ip, port = answer[0][4]
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect((ip, port))
        s.send('GET /simple/ HTTP/1.0\r\nHost: %s\r\n\r\n' % hostname)
        data = s.recv(1024)
        s.close()
    except socket.error:
        return []
    if not data:
        return []
    mirrors = []
    for line in data.split('\n'):
        if line.startswith('<a href="/simple/'):
            mirrors.append(line[17:-1])
    return mirrors

def _check_requirements(self):
        """
        Check if VPCS is available with the correct version.
        """
        try:
            import vpcs
        except ImportError:
            raise ImportError("VPCS is not installed. Please install VPCS with "
                              "pip install vpcs")
        else:
            if not hasattr(vpcs, '__version__'):
                raise ImportError("VPCS is not installed. Please install VPCS "
                                  "with pip install vpcs")
            else:
                if vpcs.__version__ < '0.1.0':
                    raise ImportError("VPCS is not installed. Please install "
                                      "VPCS with pip install vpcs")

def str_to_hostentry(entry):
        """
        Transform a line from a hosts file into an instance of HostsEntry
        :param entry: A line from the hosts file
        :return: An instance of HostsEntry
        """
        line_parts = entry.strip().split()
        if is_ipv4(line_parts[0]) and valid_hostnames(line_parts[1:]):
            return HostsEntry(entry_type='ipv4',
                              address=line_parts[0],
                              names=line_parts[1:])
        elif is_ipv6(line_parts[0]) and valid_hostnames(line_parts[1:]):
            return HostsEntry(entry_type='ipv6',
                              address=line_parts[0],
                              names=line_parts[1:])
        else:
            return False

def _get(self, key, section=None, default=_onion_dict_guard):
        """Try to get the key from each dict in turn.
        If you specify the optional section it looks there first.
        """
        if section is not None:
            section_dict = self.__sections.get(section, {})
            if key in section_dict:
                return section_dict[key]
        for d in self.__dictionaries:
            if key in d:
                return d[key]
        if default is _onion_dict_guard:
            raise KeyError(key)
        else:
            return default

def _get(self, key, section=None, default=_onion_dict_guard):
        """Try to get the key from each dict in turn.
        If you specify the optional section it looks there first.
        """
        if section is not None:
            try:
                return self[section][key]
            except KeyError:
                pass
        for d in self._dicts:
            try:
                return d[key]
            except KeyError:
                pass
        if default is _onion_dict_guard:
            raise KeyError(key)
        return default

def handle(self):
        """Process queued work until interrupt() is called
        """
        while True:
            # TODO: Queue.get() (and anything using thread.allocate_lock
            #       ignores signals :(  so timeout periodically to allow delivery
            try:
                callable = None # ensure no lingering references to past work while blocking
                callable = self._Q.get(True, 1.0)
            except Empty:
                continue  # retry on timeout
            try:
                if callable is self._stopit:
                    break
                callable()
            except:
                _log.exception("Error from WorkQueue")
            finally:
                self._Q.task_done()

def handle(self):
        """Process queued work until interrupt() is called
        """
        self.logger.info("Starting worker thread")
        while not self.interrupted:
            try:
                work = self.queue.get(timeout=1)
                self.logger.debug("Got work: %s", work)
                self.process_work(work)
            except Queue.Empty:
                pass
        self.logger.info("Worker thread exiting")

def measure_one(self, data):
        """Do measuring of read and write operations.
        @param  data:   3-tuple from get_test_data
        @return:        (time readhex, time writehex)
        """
        _unused, hexstr, ih = data
        tread, twrite = 0.0, 0.0
        if self.read:
            tread = run_readtest_N_times(intelhex.IntelHex, hexstr, self.n)[0]
        if self.write:
            twrite = run_writetest_N_times(ih.write_hex_file, self.n)[0]
        return tread, twrite

def measure_one(self, data):
        """Do measuring of read and write operations.
        @param  data:   3-tuple from get_test_data
        @return:        (time readhex, time writehex)
        """
        self.logger.info("Measuring read and write operations")
        self.logger.info("Reading %s bytes from %s" % (data[0], data[1]))
        start = time.time()
        self.readhex(data[0], data[1])
        end = time.time()
        self.logger.info("Reading %s bytes from %s took %s seconds" % (data[0], data[1], end - start))
        self.logger.info("Writing %s bytes to %s" % (data[0], data[1]))
        start = time.time()
        self.writehex(data[0], data[1])
        end = time.time()
        self.logger.info("Writing %s bytes to %s took %s seconds" % (data[0], data[1], end - start))
        return (end - start, end - start)

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema == os.path.abspath(schema):
                schema_file = schema
            else:
                schema_file = os.path.join(self.paths.schemas, schema)

            if os.path.isfile(schema_file):
                # Absolute path: use it.
                yield schema_file
            elif skip_missing_schemas:
                logger.warning("Unable to locate schema %s at %s", schema, schema_file)
            else:
                raise PathError("Unable to locate schema %s at %s" % (schema, schema_file))

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema not in self.schemas:
                if skip_missing_schemas:
                    continue
                raise ldaperrors.NoSuchObject(
                    "No such schema: %s" % schema)

def _repr(self, *args, **kwargs):
        """Return a __repr__ string from the arguments provided to __init__.

        @param args: list of arguments to __init__
        @param kwargs: dictionary of keyword arguments to __init__
        @return: __repr__ string

        """
        # Remove unnecessary empty keywords arguments and sort the arguments
        kwargs = {k: v for k, v in kwargs.items() if v is not None}
        kwargs = OrderedDict(sorted(kwargs.items()))

        # Build the __repr__ string pieces
        args_repr = ', '.join(repr(arg) for arg in args)
        kwargs_repr = ', '.join(k + '=' + repr(v) for k, v in kwargs.items())
        if args_repr and kwargs_repr:
            kwargs_repr = ', ' + kwargs_repr
        name = self.__class__.__name__

        return "{}({}{})".format(name, args_repr, kwargs_repr)

def _repr(self, *args, **kwargs):
        """Return a __repr__ string from the arguments provided to __init__.

        @param args: list of arguments to __init__
        @param kwargs: dictionary of keyword arguments to __init__
        @return: __repr__ string

        """
        return self.__class__.__name__ + '(' + ', '.join(
            [repr(arg) for arg in args] +
            ['%s=%s' % (k, repr(v)) for k, v in kwargs.items()]
        ) + ')'

