def _serialize_input_list(input_value):
        """Recursively serialize task input list"""
        input_list = []
        for item in input_value:
            if isinstance(item, list):
                input_list.append(Task._serialize_input_list(item))
            else:
                if isinstance(item, File):
                    item = Task._to_api_file_format(item)
                input_list.append(item)
        return input_list

def _serialize_input_list(input_value):
        """Recursively serialize task input list"""
        if isinstance(input_value, list):
            return [_serialize_input_list(v) for v in input_value]
        elif isinstance(input_value, dict):
            return {k: _serialize_input_list(v) for k, v in input_value.items()}
        else:
            return input_value

def get_flag(var, fallback, expected=True, warn=True):
    """Use a fallback method for determining SOABI flags if the needed config
    var is unset or unavailable."""
    val = get_config_var(var)
    if val is None:
        if warn:
            warnings.warn("Config variable '{0}' is unset, Python ABI tag may "
                          "be incorrect".format(var), RuntimeWarning, 2)
        return fallback()
    return val == expected

def get_flag(var, fallback, expected=True, warn=True):
    """Use a fallback method for determining SOABI flags if the needed config
    var is unset or unavailable."""
    if var in os.environ:
        return os.environ[var] == str(expected)
    if warn:
        print(f"WARNING: {var} not set, using fallback method")
    return fallback() == expected

def from_inline(cls: Type[MembershipType], version: int, currency: str, membership_type: str,
                    inline: str) -> MembershipType:
        """
        Return Membership instance from inline format

        :param version: Version of the document
        :param currency: Name of the currency
        :param membership_type: "IN" or "OUT" to enter or exit membership
        :param inline: Inline string format
        :return:
        """
        if version == 1:
            return cls.from_inline_v1(currency, membership_type, inline)
        elif version == 2:
            return cls.from_inline_v2(currency, membership_type, inline)
        else:
            raise ValueError(f"Unknown version {version}")

def to_python(self, value):
        """
        Handles the following cases:
        1. If the value is already the proper type (a regex), return it.
        2. If the value is a string, compile and return the regex.

        Raises: A ValidationError if the regex cannot be compiled.
        """
        if isinstance(value, type(re.compile(''))):
            return value
        else:
            if value is None and self.null:
                return None
            else:
                try:
                    return self.get_compiled_regex(value)
                except:
                    raise ValidationError('Invalid regex {0}'.format(value))

def to_python(self, value):
        """
        Handles the following cases:
        1. If the value is already the proper type (a regex), return it.
        2. If the value is a string, compile and return the regex.

        Raises: A ValidationError if the regex cannot be compiled.
        """
        if isinstance(value, RegexType):
            return value
        elif isinstance(value, six.string_types):
            try:
                return re.compile(value)
            except re.error:
                raise ValidationError(self.error_messages['invalid'], code='invalid')
        else:
            raise ValidationError(self.error_messages['invalid'], code='invalid')

