def restore(self, fade=False):
        """Restore the state of a device to that which was previously saved.

        For coordinator devices restore everything. For slave devices
        only restore volume etc., not transport info (transport info
        comes from the slave's coordinator).

        Args:
            fade (bool): Whether volume should be faded up on restore.
        """

        try:
            if self.is_coordinator:
                self._restore_coordinator()
        finally:
            self._restore_volume(fade)

        # Now everything is set, see if we need to be playing, stopped
        # or paused ( only for coordinators)
        if self.is_coordinator:
            if self.transport_state == 'PLAYING':
                self.device.play()
            elif self.transport_state == 'STOPPED':
                self.device.stop()

def parse_variable(self, variable):
        """Method to parse an input or output variable.

        **Example Variable**::

        #App:1234:output!String

        Args:
            variable (string): The variable name to parse.

        Returns:
            (dictionary): Result of parsed string.
        """
        # Split the variable into its parts
        parts = variable.split('!')
        # Check if the variable is an input or output
        if parts[0].startswith('input'):
            # Check if the variable is a list
            if parts[1].startswith('List'):
                # Return the variable as a list
                return {
                    'type': 'input',
                    'name': parts[0].split(':')[2],
                    'list': True,
                    'list_type': parts[1].split(':')[1]
                }
            # Return the variable as a string
            return {
                'type': 'input',
                'name': parts[0].split(':')[2],
                'list': False
            }
        # Check if the variable is an output
        elif parts[0].startswith('output'):
            # Check if the variable is a list
            if parts[1].startswith('List'):
                # Return the variable as a list
                return {
                    'type': 'output',
                    'name': parts[0].split(':')[2],
                    'list': True,
                    'list_type': parts[1].split(':')[1]
                }
            # Return the variable as a string
            return {
                'type': 'output',
                'name': parts[0].split(':')[2],
                'list': False
            }
        # Return an error
        return {
            'error': 'Invalid variable name'
        }

def resolve_module(module, definitions):
  """Resolve (through indirections) the program contents of a module definition.
  The result is a list of program chunks."""

  assert module in definitions, "No definition for module '%s'" % module

  d = definitions[module]
  if type(d) == dict:
    if 'filename' in d:
      with open(d['filename']) as f:
        return [f.read().strip()]
    elif 'reference' in d:
      return resolve_module(d['reference'], definitions)
    elif 'group' in d:
      return sum([resolve_module(m,definitions) for m in d['group']],[])
    else:
      assert False
  else:
    assert type(d) == str
    return [d]

def resolve_module(module, definitions):
  """Resolve (through indirections) the program contents of a module definition.
  The result is a list of program chunks."""
  if module.is_resolved:
    return module.program
  else:
    module.is_resolved = True
    module.program = []
    for chunk in module.chunks:
      if chunk.is_resolved:
        module.program.append(chunk)
      else:
        chunk.is_resolved = True
        if chunk.is_import:
          module.program.append(resolve_module(definitions[chunk.name], definitions))
        else:
          module.program.append(chunk)
    return module.program

def apply_array_ufunc(func, *args, dask='forbidden'):
    """Apply a ndarray level function over ndarray objects."""
    if any(isinstance(arg, dask_array_type) for arg in args):
        if dask == 'forbidden':
            raise ValueError('apply_ufunc encountered a dask array on an '
                             'argument, but handling for dask arrays has not '
                             'been enabled. Either set the ``dask`` argument '
                             'or load your data into memory first with '
                             '``.load()`` or ``.compute()``')
        elif dask == 'parallelized':
            raise ValueError("cannot use dask='parallelized' for apply_ufunc "
                             'unless at least one input is an xarray object')
        elif dask == 'allowed':
            pass
        else:
            raise ValueError('unknown setting for dask array handling: {}'
                             .format(dask))
    return func(*args)

def apply_array_ufunc(func, *args, dask='forbidden'):
    """Apply a ndarray level function over ndarray objects."""
    if dask == 'forbidden':
        return func(*args)
    else:
        return da.apply_array_ufunc(func, *args)

def trigger_streamer(*inputs, **kwargs):
    """Trigger a streamer based on the index read from input b.

    Returns:
        list(IOTileReading)
    """

    streamer_marker = kwargs['mark_streamer']

    try:
        reading = inputs[1].pop()
    except StreamEmptyError:
        return []
    finally:
        for input_x in inputs:
            input_x.skip_all()

    try:
        streamer_marker(reading.value)
    except ArgumentError:
        return []

    return [IOTileReading(0, 0, 0)]

def report_idle_after(seconds):
    """Report_idle_after after certain number of seconds."""

    def decorator(func):
        def wrapper(*args, **kwargs):
            def _handle_timeout(signum, frame):
                config = get_config()
                if not config.ready:
                    config.load()
                message = {
                    "subject": "Idle Experiment.",
                    "body": idle_template.format(
                        app_id=config.get("id"), minutes_so_far=round(seconds / 60)
                    ),
                }
                log("Reporting problem with idle experiment...")
                get_messenger(config).send(message)

            signal.signal(signal.SIGALRM, _handle_timeout)
            signal.alarm(seconds)
            try:
                result = func(*args, **kwargs)
            finally:
                signal.alarm(0)
            return result

        return wraps(func)(wrapper)

    return decorator

def report_idle_after(seconds):
    """Report_idle_after after certain number of seconds."""
    def decorator(func):
        """Decorator."""
        @wraps(func)
        def wrapper(*args, **kwargs):
            """Wrapper."""
            time.sleep(seconds)
            return func(*args, **kwargs)
        return wrapper
    return decorator

