def starts_with(self, other: 'Key') -> bool:
        """
        Checks if this key starts with the other key provided. Returns False if key_type, identity
        or group are different.
        For `KeyType.TIMESTAMP` returns True.
        For `KeyType.DIMENSION` does prefix match between the two dimensions property.
        """
        if (self.key_type, self.identity, self.group) != (other.key_type, other.identity,
                                                          other.group):
            return False
        if self.key_type == KeyType.TIMESTAMP:
            return True
        if self.key_type == KeyType.DIMENSION:
            if len(self.dimensions) < len(other.dimensions):
                return False
            return self.dimensions[0:len(other.dimensions)] == other.dimensions

def starts_with(self, other: 'Key') -> bool:
        """
        Checks if this key starts with the other key provided. Returns False if key_type, identity
        or group are different.
        For `KeyType.TIMESTAMP` returns True.
        For `KeyType.DIMENSION` does prefix match between the two dimensions property.
        """
        if self.key_type != other.key_type:
            return False
        if self.key_type == KeyType.TIMESTAMP:
            return True
        if self.key_type == KeyType.DIMENSION:
            return self.dimension.starts_with(other.dimension)
        return False

def _build_operator_name(name, function, symbol):
        """implementation details"""
        def add_operator(sym):
            if 'new' in sym or 'delete' in sym:
                return 'operator ' + sym
            return 'operator' + sym
        if isinstance(name, Callable) and None is function:
            name = None
        if name:
            if 'operator' not in name:
                name = add_operator(name)
            return name
        elif symbol:
            return add_operator(symbol)
        return name

def _build_operator_name(name, function, symbol):
        """implementation details"""
        return name + function.__name__ + symbol

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if self.cmdprefix:
            raise CmdError("prefix not allowed")
        targets = self.input_process_list( self.split_tokens(arg, 1) )
        if not targets:
            print("Error: missing parameters")
        else:
            debug = self.debug
            for pid in targets:
                try:
                    debug.attach(pid)
                    print("Attached to process (%d)" % pid)
                except Exception:
                    print("Error: can't attach to process (%d)" % pid)

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if not arg:
            print("attach requires a target")
            return
        for target in arg.split():
            self.attach(target)

def get_slack_users(self, token):
        """
        Get all users from Slack
        """

        ret = salt.utils.slack.query(function='users',
                                     api_key=token,
                                     opts=__opts__)
        users = {}
        if 'message' in ret:
            for item in ret['message']:
                if 'is_bot' in item:
                    if not item['is_bot']:
                        users[item['name']] = item['id']
