def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with closing(self._tqdm(desc="MD5 checksumming", total=getsize(file_path), unit="B",
                                unit_scale=True)) as progress:
            md5 = hashlib.md5()
            with open(file_path, "rb") as f:
                while True:
                    block_data = f.read(block_size)
                    if not block_data:
                        break
                    md5.update(block_data)
                    progress.update(len(block_data))
            return md5.hexdigest().lower() == checksum.lower()

def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with open(file_path, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                data = f.read(block_size)
                if not data:
                    break
                md5.update(data)
            return md5.hexdigest() == checksum

def profile_validation(self, status):
        """Return run total value."""
        self.selected_profile.data.setdefault('validation_pass_count', 0)
        self.selected_profile.data.setdefault('validation_fail_count', 0)
        if status:
            self.selected_profile.data['validation_pass_count'] += 1
        else:
            self.selected_profile.data['validation_fail_count'] += 1

def profile_validation(self, status):
        """Return run total value."""
        if status == 'pass':
            return self.pass_count
        elif status == 'fail':
            return self.fail_count
        elif status == 'skip':
            return self.skip_count
        elif status == 'xfail':
            return self.xfail_count
        elif status == 'xpass':
            return self.xpass_count
        elif status == 'error':
            return self.error_count
        elif status == 'blocked':
            return self.blocked_count
        elif status == 'rerun':
            return self.rerun_count
        elif status == 'total':
            return self.total_count
        else:
            return 0

def rewrite_file_imports(item, vendored_libs):
    """Rewrite 'import xxx' and 'from xxx import' for vendored_libs"""
    if item.startswith('import '):
        for lib in vendored_libs:
            if item.startswith('import ' + lib):
                item = 'import ' + vendored_libs[lib]
                break
    elif item.startswith('from '):
        for lib in vendored_libs:
            if item.startswith('from ' + lib + ' import'):
                item = 'from ' + vendored_libs[lib] + ' import'
                break
    return item

def prepare_ec(oo, sizes, M):
    """
    This prepares EC and converts from contig_id to an index.
    """
    ec = {}
    for i in range(len(oo)):
        ec[oo[i]] = i
    ec_sizes = {}
    for i in range(len(sizes)):
        ec_sizes[ec[i]] = sizes[i]
    ec_M = {}
    for i in range(len(M)):
        ec_M[ec[i]] = M[i]
    return ec, ec_sizes, ec_M

def base_add_isoquant_data(features, quantfeatures, acc_col, quantacc_col,
                           quantfields):
    """Generic function that takes a peptide or protein table and adds
    quant data from ANOTHER such table."""
    quant_map = get_quantmap(quantfeatures, quantacc_col, quantfields)
    for feature in features:
        feat_acc = feature[acc_col]
        outfeat = {k: v for k, v in feature.items()}
        try:
            outfeat.update(quant_map[feat_acc])
        except KeyError:
            outfeat.update({field: 'NA' for field in quantfields})
        yield outfeat

def _read_message(self):
        """Reads the contents of a message.

        Returns:
            body of message if parsable else None
        """
        line = self._rfile.readline()

        if not line:
            return None

        content_length = self._content_length(line)

        # Blindly consume all header lines
        while line and line.strip():
            line = self._rfile.readline()

        if not line:
            return None

        # Grab the body
        return self._rfile.read(content_length)

def _read_message(self):
        """Reads the contents of a message.

        Returns:
            body of message if parsable else None
        """
        try:
