def _parse(self):
        """
        Loop through all child elements and execute any available parse methods for them
        """
        # Is this a shorthand template?
        if self._element.tag == 'template':
            return self._parse_template(self._element)

        # Is this a shorthand redirect?
        if self._element.tag == 'redirect':
            return self._parse_redirect(self._element)

        for child in self._element:
            method_name = '_parse_' + child.tag

            if hasattr(self, method_name):
                parse = getattr(self, method_name)
                parse(child)

def _parse(self):
        """
        Loop through all child elements and execute any available parse methods for them
        """
        for child in self.children:
            if hasattr(child, 'parse'):
                child.parse()

def list_datastore_clusters(kwargs=None, call=None):
    """
    List all the datastore clusters for this VMware environment

    CLI Example:

    .. code-block:: bash

        salt-cloud -f list_datastore_clusters my-vmware-config
    """
    if call != 'function':
        raise SaltCloudSystemExit(
            'The list_datastore_clusters function must be called with '
            '-f or --function.'
        )

    return {'Datastore Clusters': salt.utils.vmware.list_datastore_clusters(_get_si())}

def list_datastore_clusters(kwargs=None, call=None):
    """
    List all the datastore clusters for this VMware environment

    CLI Example:

    .. code-block:: bash

        salt-cloud -f list_datastore_clusters my-vmware-config
    """
    if call != "function":
        raise SaltCloudSystemExit(
            "The list_datastore_clusters function must be called with -f or --function."
        )

    if not kwargs or "vmc_name" not in kwargs:
        raise SaltCloudSystemExit(
            "The list_datastore_clusters function requires a vmc_name to be provided."
        )

    try:
        conn = get_conn(kwargs)
        datastore_clusters = conn.list_datastore_clusters()
    except Exception as exc:
        log.error(
            "Could not list datastore clusters for %s: %s",
            kwargs["vmc_name"],
            exc,
            exc_info_on_loglevel=logging.DEBUG,
        )
        return {}

    ret = {}
    for datastore_cluster in datastore_clusters:
        ret[datastore_cluster.name] = {
            "name": datastore_cluster.name,
            "hosts": [host.name for host in datastore_cluster.hosts],
            "datastores": [datastore.name for datastore in datastore_cluster.datastores],
        }

    return ret

def _get_host_disks(host_reference):
    """
    Helper function that returns a dictionary containing a list of SSD and Non-SSD disks.
    """
    storage_system = host_reference.configManager.storageSystem
    disks = storage_system.storageDeviceInfo.scsiLun
    ssds = []
    non_ssds = []

    for disk in disks:
        try:
            has_ssd_attr = disk.ssd
        except AttributeError:
            has_ssd_attr = False
        if has_ssd_attr:
            ssds.append(disk)
        else:
            non_ssds.append(disk)

    return {'SSDs': ssds, 'Non-SSDs': non_ssds}

def _get_host_disks(host_reference):
    """
    Helper function that returns a dictionary containing a list of SSD and Non-SSD disks.
    """
    host_disks = {}
    host_disks['ssd'] = []
    host_disks['non_ssd'] = []
    for disk in host_reference.config.storageDevice.scsiLun:
        if disk.deviceType == 'disk':
            if disk.ssd:
                host_disks['ssd'].append(disk)
            else:
                host_disks['non_ssd'].append(disk)
    return host_disks

def _to_dict(self):
        """Return keyrange's state as a dict.

        :rtype: dict
        :returns: state of this instance.
        """
        mapping = {}

        if self.start_open:
            mapping["start_open"] = self.start_open

        if self.start_closed:
            mapping["start_closed"] = self.start_closed

        if self.end_open:
            mapping["end_open"] = self.end_open

        if self.end_closed:
            mapping["end_closed"] = self.end_closed

        return mapping

def add(self, func, position):
        """
        Adds all 8 cardinal directions as moves for the King if legal.

        :type: function: function
        :type: position: Board
        :rtype: gen
        """
        try:
            if self.loc_adjacent_to_opponent_king(func(self.location), position):
                return
        except IndexError:
            return

        if position.is_square_empty(func(self.location)):
            yield self.create_move(func(self.location), notation_const.MOVEMENT)

        elif position.piece_at_square(func(self.location)).color != self.color:
            yield self.create_move(func(self.location), notation_const.CAPTURE)

def add(self, func, position):
        """
        Adds all 8 cardinal directions as moves for the King if legal.

        :type: function: function
        :type: position: Board
        :rtype: gen
        """
        for i in range(8):
            if self.is_legal(func(position, i)):
                yield func(position, i)

def d_from_format(self, attr):
        """ Find out the local name of an attribute

        :param attr: An Attribute dictionary
        :return: The local attribute name or "" if no mapping could be made
        """
        if attr["name_format"]:
            if self.name_format == attr["name_format"]:
                try:
                    return self._fro[attr["name"].lower()]
                except KeyError:
                    pass
        else:  # don't know the name format so try all I have
            try:
                return self._fro[attr["name"].lower()]
            except KeyError:
                pass

        return ""

def d_from_format(self, attr):
        """ Find out the local name of an attribute

        :param attr: An Attribute dictionary
        :return: The local attribute name or "" if no mapping could be made
        """
        if attr.get('name') is not None:
            return attr['name']
        if attr.get('local_name') is not None:
            return attr['local_name']
        if attr.get('local_names') is not None:
            return attr['local_names'][0]
        return ""

