def _is_match(self, response, answer):
        """For MC, can call through to MultiChoice Item Record?"""
        # TODO: this varies depending on question type
        if self._only_generic_right_feedback():
            return str(answer.genus_type) == str(RIGHT_ANSWER_GENUS)
        elif self._is_multiple_choice():
            return MultiChoiceItemRecord._is_match(self, response, answer)
        elif self._is_image_sequence() or self._is_mw_sentence():
            return OrderedChoiceItemRecord._is_match(self, response, answer)
        elif self._is_numeric_response():
            return CalculationInteractionItemRecord._is_match(self, response, answer)
        elif self._is_fitb():
            return MagicRandomizedInlineChoiceItemRecord._is_match(self, response, answer)
        return False

def _is_match(self, response, answer):
        """For MC, can call through to MultiChoice Item Record?"""
        return self.is_match(response, answer)

def search(self, field_name, search_terms, operator=QueryOperator.OR):
        """
        For more complex text searching

        @param str field_name: The field name in the index you want to query.
        :type str
        @param str search_terms: The terms you want to query
        @param QueryOperator operator: OR or AND
        """

        if field_name is None:
            raise ValueError("None field_name is invalid")

        field_name = Query.escape_if_needed(field_name)
        self._add_operator_if_needed()
        self.negate_if_needed(field_name)

        self.last_equality = {field_name: "(" + search_terms + ")" if ' ' in search_terms else search_terms}
        token = _Token(field_name=field_name, token="search", value=self.add_query_parameter(search_terms),
                       search_operator=operator)
        token.write = self.rql_where_write(token)
        self._where_tokens.append(token)
        return self

def search(self, field_name, search_terms, operator=QueryOperator.OR):
        """
        For more complex text searching

        @param str field_name: The field name in the index you want to query.
        :type str
        @param str search_terms: The terms you want to query
        @param QueryOperator operator: OR or AND
        """
        if not isinstance(search_terms, list):
            search_terms = [search_terms]
        if operator == QueryOperator.OR:
            query = " OR ".join(["{}:{}".format(field_name, term) for term in search_terms])
        elif operator == QueryOperator.AND:
            query = " AND ".join(["{}:{}".format(field_name, term) for term in search_terms])
        else:
            raise ValueError("Invalid operator")
        return self.query(query)

def __substitute_replace_pairs(self):
        """
        Substitutes all replace pairs in the source of the stored routine.
        """
        for replace_pair in self.replace_pairs:
            self.source = self.source.replace(replace_pair[0], replace_pair[1])

def add_path(self, path, method=None):
        """
        Adds the path/method combination to the Swagger, if not already present

        :param string path: Path name
        :param string method: HTTP method
        :raises ValueError: If the value of `path` in Swagger is not a dictionary
        """
        if method is None:
            method = 'get'

        if path not in self.paths:
            self.paths[path] = {}

        if method not in self.paths[path]:
            self.paths[path][method] = {}

def fill_in_table(self, table, worksheet, flags):
        """
        Fills in any rows with missing right hand side data with empty cells.
        """
        max_row = 0
        min_row = sys.maxint
        for row in table:
            if len(row) > max_row:
                max_row = len(row)
            if len(row) < min_row:
                min_row = len(row)
        if max_row != min_row:
            for row in table:
                if len(row) < max_row:
                    row.extend([None]*(max_row-len(row)))

def unindex(self, data, field):
        """Remove index of a given set of data"""
        indices = extractIndices(self.index_fields[field])

        for doc in data:
            if doc:
                for _, index, preprocess in indices:
                    index.unindex(preprocess(doc))

        for index_type, index, _ in indices:

            index._index.initSearch()

            for predicate in self.index_fields[field][index_type]:
                logger.debug("Canopy: %s", str(predicate))
                predicate.index = index

def unindex(self, data, field):
        """Remove index of a given set of data"""
        if not self.indexed(field):
            raise ValueError("Field %s is not indexed" % field)
        self.indexes[field].unindex(data)

def addClass(self, cn):
        """Add the specific class names to the class set and return ``self``.
        """
        if cn:
            if isinstance(cn, (tuple, list, set, frozenset)):
                add = self.addClass
                for c in cn:
                    add(c)
            else:
                classes = self._classes
                if classes is None:
                    self._extra['classes'] = classes = set()
                add = classes.add
                for cn in cn.split():
                    add(slugify(cn))
        return self

def connect(self):
        """Connect to the unix domain socket, which is passed to us as self.host

        This is in host because the format we use for the unix domain socket is:

        http+unix://%2Fpath%2Fto%2Fsocket.sock

        """
        try:
            self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)

            if has_timeout(self.timeout):
                self.sock.settimeout(self.timeout)

            self.sock.connect(unquote(self.host))
        except socket.error as msg:
            if self.sock:
                self.sock.close()
            self.sock = None

            raise socket.error(msg)

def get_body(self):
        """ Return a HTTPStatus compliant body attribute

        Be sure to purge any unallowed properties from the object.

        TIP: At the risk of being a bit slow we copy the errors
             instead of mutating them since they may have key/vals
             like headers that are useful elsewhere.
        """

        body = copy.deepcopy(self.errors)

        for error in body:
            for key in error.keys():
                if key not in self.ERROR_OBJECT_FIELDS:
                    del error[key]
        return json.dumps({'errors': body})

def get_body(self):
        """ Return a HTTPStatus compliant body attribute

        Be sure to purge any unallowed properties from the object.

        TIP: At the risk of being a bit slow we copy the errors
             instead of mutating them since they may have key/vals
             like headers that are useful elsewhere.
        """
        body = {}
        if self.status_code is not None:
            body['status_code'] = self.status_code
        if self.message is not None:
            body['message'] = self.message
        if self.errors is not None:
            body['errors'] = self.errors
        if self.headers is not None:
            body['headers'] = self.headers
        if self.body is not None:
            body['body'] = self.body
        return body

def add_argument(self, *args, **kwargs):
        """ Add an argument incorporating the default value into the help string

        :param args:
        :param kwargs:
        :return:
        """
        defhelp = kwargs.pop("help", None)
        defaults = kwargs.pop("default", None)
        default = defaults if self.use_defaults else None
        if not defhelp or default is None or kwargs.get('action') == 'help':
            return super().add_argument(*args, help=defhelp, default=default, **kwargs)
        else:
            return super().add_argument(*args, help=defhelp + " (default: {})".format(default),
                                        default=default, **kwargs)

def get_hangs(self):
        """
        Determine the type of overlap given query, ref alignment coordinates
        Consider the following alignment between sequence a and b:

        aLhang \              / aRhang
                \------------/
                /------------\
        bLhang /              \ bRhang

        Terminal overlap: a before b, b before a
        Contain overlap: a in b, b in a
        """
        if self.query_start < self.ref_start:
            if self.query_end < self.ref_end:
                return "terminal"
            else:
                return "contain"
        else:
            if self.query_end < self.ref_end:
                return "contain"
            else:
                return "terminal"

def get_size(vm_):
    """
    Return the VM's size object
    """
    vm_size = config.get_cloud_config_value('size', vm_, __opts__)
    sizes = avail_sizes()

    if not vm_size:
        return sizes['Small Instance']

    for size in sizes:
        combinations = (six.text_type(sizes[size]['id']), six.text_type(size))
        if vm_size and six.text_type(vm_size) in combinations:
            return sizes[size]
    raise SaltCloudNotFound(
        'The specified size, \'{0}\', could not be found.'.format(vm_size)
    )

def get_size(vm_):
    """
    Return the VM's size object
    """
    return vm_.get_size()

def assess_content(member,file_filter):
    """Determine if the filter wants the file to be read for content.
    In the case of yes, we would then want to add the content to the
    hash and not the file object.
    """
    member_path = member.name.replace('.','',1)

    if len(member_path) == 0:
        return False

    # Does the filter skip it explicitly?
    if "skip_files" in file_filter:
        if member_path in file_filter['skip_files']:
            return False

    if "assess_content" in file_filter:
        if member_path in file_filter['assess_content']:
            return True
    return False

def assess_content(member,file_filter):
    """Determine if the filter wants the file to be read for content.
    In the case of yes, we would then want to add the content to the
    hash and not the file object.
    """
    if file_filter.content_filter:
        if file_filter.content_filter.match(member.name):
            return True
    return False

def check_for_errors(self):
        """Check connection and channel for errors.

        :raises AMQPChannelError: Raises if the channel encountered an error.
        :raises AMQPConnectionError: Raises if the connection
                                     encountered an error.
        :return:
        """
        try:
            self._connection.check_for_errors()
        except AMQPConnectionError:
            self.set_state(self.CLOSED)
            raise

        if self.exceptions:
            exception = self.exceptions[0]
            if self.is_open:
                self.exceptions.pop(0)
            raise exception

        if self.is_closed:
            raise AMQPChannelError('channel was closed')

def check_for_errors(self):
        """Check connection and channel for errors.

        :raises AMQPChannelError: Raises if the channel encountered an error.
        :raises AMQPConnectionError: Raises if the connection
                                     encountered an error.
        :return:
        """
        if self.connection.is_closed:
            raise AMQPConnectionError(
                "Connection to %s:%s closed unexpectedly" % (
                    self.connection.params.host,
                    self.connection.params.port
                )
            )
        if self.channel.is_closed:
            raise AMQPChannelError(
                "Channel closed unexpectedly"
            )

def get_object(self, point, buffer_size=0, multiple=False):
        """ lookup object based on point as [longitude, latitude] """
        # first search bounding boxes
        # idx.intersection method modifies input if it is a list
        try:
            tmp = tuple(point)
        except TypeError:
            return None
        # point must be in the form (minx, miny, maxx, maxy) or (x, y)
        if len(tmp) not in [2, 4]:
            return None

        # buffer point if size is specified
        geom = tmp = Point(tmp)
        if buffer_size:
            geom = tmp.buffer(buffer_size)
        if multiple:
            return self._get_all_near(geom)
        return self._get_nearest(tmp, geom)

def get_object(self, point, buffer_size=0, multiple=False):
        """ lookup object based on point as [longitude, latitude] """
        if multiple:
            return self.get_objects(point, buffer_size)
        else:
            return self.get_object_by_id(self.get_object_id(point, buffer_size))

def regex_group(ctx, text, pattern, group_num):
    """
    Tries to match the text with the given pattern and returns the value of matching group
    """
    match = re.search(pattern, text)
    if match:
        return match.group(group_num)
    else:
        return None

def emit_containers(self, containers, verbose=True):
        """
        Emits the applications and sorts containers by name

        :param containers: List of the container definitions
        :type containers: list of dict

        :param verbose: Print out newlines and indented JSON
        :type verbose: bool

        :returns: The text output
        :rtype: str
        """
        containers = sorted(containers, key=lambda c: c.get('id'))

        if len(containers) == 1 and isinstance(containers, list):
            containers = containers[0]

        if verbose:
            return json.dumps(containers, indent=4, sort_keys=True)
        else:
            return json.dumps(containers)

def process_experiences(self, current_info: AllBrainInfo, next_info: AllBrainInfo):
        """
        Checks agent histories for processing condition, and processes them as necessary.
        Processing involves calculating value and advantage targets for model updating step.
        :param current_info: Current AllBrainInfo
        :param next_info: Next AllBrainInfo
        """
        for agent_id in current_info.agents:
            if agent_id not in next_info.agents:
                continue
            if self.use_hindsight:
                self.process_experiences_hindsight(current_info, next_info, agent_id)
            else:
                self.process_experiences_no_hindsight(current_info, next_info, agent_id)

def cached(key, timeout=3600):
    """Cache the return value of the decorated function with the given key.

    Key can be a String or a function.
    If key is a function, it must have the same arguments as the decorated function,
    otherwise it cannot be called successfully.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if isinstance(key, str):
                key = key.format(*args, **kwargs)
            else:
                key = key(*args, **kwargs)
            value = cache.get(key)
            if value is None:
                value = func(*args, **kwargs)
                cache.set(key, value, timeout)
            return value
        return wrapper
    return decorator

def get_trips(self, authentication_info, start, end):
        """Get trips for this device between start and end."""
        return self._get_trips(authentication_info, start, end)

def __identify_user(self, username, csrf):
        """
        Returns reusable CSRF code and the auth level as a 2-tuple
        """
        if not username:
            return None, None

        if not csrf:
            csrf = self.get_csrf()

        user = self.get_user(username)
        if not user:
            return None, None

        return csrf, user.auth_level

def close(self):
        """ Close the connection.
        """
        if not self._closed:
            if self.protocol_version >= 3:
                log_debug("[#%04X]  C: GOODBYE", self.local_port)
                self._append(b"\x02", ())
                try:
                    self.send()
                except ServiceUnavailable:
                    pass
            log_debug("[#%04X]  C: <CLOSE>", self.local_port)
            try:
                self.socket.close()
            except IOError:
                pass
            finally:
                self._closed = True

