        Delete a template type and its typeattrs.
    """
    if template_i is None:
        template_i = get_template_i(type_id)
    if template_i is None:
        return
    template_i.delete()
    typeattrs = get_typeattrs(type_id)
    for typeattr in typeattrs:
        delete_typeattr(typeattr.id)

def save(self):
        """ Saves prefs to disk in dict format """
        fpath = self.get_fpath()
        if fpath in ['', None]:
            if self._tree.parent is not None:
                if VERBOSE_PREF:
                    print('[pref.save] Can my parent save me?')  # ...to disk
                return self._tree.parent.save()
            if VERBOSE_PREF:
                print('[pref.save] I cannot be saved. I have no parents.')
            return False
        with open(fpath, 'wb') as f:
            print('[pref] Saving to ' + fpath)
            pref_dict = self.to_dict()
            pickle.dump(pref_dict, f, protocol=2)  # Use protocol 2 to support python2 and 3
        return True

def _parse_ports(port_values: dict) -> dict:
        """Parse ports key.

        Args:
            port_values (dict): ports configuration values

        Returns:
            dict, Ports specification which contains exposed ports

        """
        ports = {}
        for port_key, port_value in port_values.items():
            if port_key == "exposed":
                ports["exposed"] = port_value
            elif port_key == "internal":
                ports["internal"] = port_value
            elif port_key == "external":
                ports["external"] = port_value
            else:
                raise ValueError(f"Invalid port key: {port_key}")
        return ports

def save_data(fpath, data, **kwargs):
    """ More generic interface to write data """
    ext = splitext(fpath)[1]
    if ext in ['.pickle', '.cPkl', '.pkl']:
        return save_cPkl(fpath, data, **kwargs)
    elif ext in ['.json']:
        return save_json(fpath, data, **kwargs)
    elif ext in ['.hdf5']:
        return save_hdf5(fpath, data, **kwargs)
    elif ext in ['.txt']:
        return save_text(fpath, **kwargs)
    elif HAS_NUMPY and ext in ['.npz', '.npy']:
        return save_numpy(fpath, data, **kwargs)
    else:
        assert False, 'unknown ext=%r for fpath=%r' % (ext, fpath)

def save_data(fpath, data, **kwargs):
    """ More generic interface to write data """
    if fpath.endswith('.h5'):
        save_h5(fpath, data, **kwargs)
    elif fpath.endswith('.npz'):
        save_npz(fpath, data, **kwargs)
    elif fpath.endswith('.json'):
        save_json(fpath, data, **kwargs)
    elif fpath.endswith('.pkl'):
        save_pkl(fpath, data, **kwargs)
    else:
        raise ValueError('Unknown file extension')

def login(self, password):
        """Attempts to log in as the current user with given password"""

        if self.logged_in:
            raise RuntimeError("User already logged in!")

        params = {"name": self.nick, "password": password}
        resp = self.conn.make_api_call("login", params)
        if "error" in resp:
            raise RuntimeError(
                f"Login failed: {resp['error'].get('message') or resp['error']}"
            )
        self.session = resp["session"]
        self.conn.make_call("useSession", self.session)
        self.conn.cookies.update({"session": self.session})
        self.logged_in = True
        return True

