def is_null(*symbols):
    """ True if no nodes or all the given nodes are either
    None, NOP or empty blocks. For blocks this applies recursively
    """
    from symbols.symbol_ import Symbol

    for sym in symbols:
        if sym is None:
            continue
        if not isinstance(sym, Symbol):
            return False
        if sym.token == 'NOP':
            continue
        if sym.token == 'BLOCK':
            if not is_null(*sym.children):
                return False
            continue
        return False
    return True

def is_null(*symbols):
    """ True if no nodes or all the given nodes are either
    None, NOP or empty blocks. For blocks this applies recursively
    """
    return all(is_null_node(symbol) for symbol in symbols)

def fetch(self, remote, branch, local_branch = None, force=False):
        """Pull a repository
        :param remote: git-remote instance
        :param branch: name of the branch to pull
        """
        if local_branch is None:
            local_branch = branch
        if force:
            self.git.checkout(local_branch)
            self.git.pull(remote, branch)
        else:
            self.git.pull(remote, branch, local_branch)

def revoke_session(self, sid='', token=''):
        """
        Mark session as revoked but also explicitly revoke all issued tokens

        :param token: any token connected to the session
        :param sid: Session identifier
        """
        if not sid:
            if token:
                sid = self.handler.sid(token)
            else:
                raise ValueError('Need one of "sid" or "token"')

        for typ in ['access_token', 'refresh_token', 'code']:
            try:
                self.revoke_token(self[sid][typ], typ)
            except KeyError:  # If no such token has been issued
                pass

        self.update(sid, revoked=True)

def is_monotonic(a, increasing=True):
    """
    Tests whether a vector a has monotonicity.

    Parameters
    ----------
    a : array-like
        Array that should be tested for monotonicity

    increasing : bool, default: True
        Test if the array is montonically increasing, otherwise test if the
        array is montonically decreasing.
    """
    a = np.asarray(a) # ensure a is array-like

    if a.ndim > 1:
        raise ValueError("not supported for multi-dimensonal arrays")

    if len(a) <= 1:
        return True

    if increasing:
        return np.all(a[1:] >= a[:-1], axis=0)
    return np.all(a[1:] <= a[:-1], axis=0)

def is_monotonic(a, increasing=True):
    """
    Tests whether a vector a has monotonicity.

    Parameters
    ----------
    a : array-like
        Array that should be tested for monotonicity

    increasing : bool, default: True
        Test if the array is montonically increasing, otherwise test if the
        array is montonically decreasing.
    """
    if increasing:
        return np.all(a[1:] >= a[:-1])
    else:
        return np.all(a[1:] <= a[:-1])

def parse_argspec(callable_):
        """
        Takes a callable and returns a tuple with the list of Argument objects,
        the name of *args, and the name of **kwargs.
        If *args or **kwargs is not present, it will be None.
        This returns a namedtuple called Argspec that has three fields named:
        args, starargs, and kwargs.
        """
        argspec = inspect.getargspec(callable_)
        args = argspec.args
        if argspec.defaults:
            args = args[:-len(argspec.defaults)]
        if argspec.varargs:
            starargs = argspec.varargs
        else:
            starargs = None
        if argspec.keywords:
            kwargs = argspec.keywords
        else:
            kwargs = None
        return Argspec(args, starargs, kwargs)

def harvest(self):
        """Start the harvesting process"""
        if self.perform_initialization() is not None:
            self.process_items()
            self.finalize()
        return self.job

def _session_for(self, model_or_session):
        """Return session instance for object parameter.

        If parameter is a session instance, it is return as is.
        If parameter is a registered model instance, its session will be used.

        If parameter is a detached model instance, or None, application scoped
        session will be used (db.session())

        If parameter is a scoped_session instance, a new session will be
        instanciated.
        """
        if isinstance(model_or_session, Session):
            return model_or_session
        elif isinstance(model_or_session, Model):
            return model_or_session.session
        elif model_or_session is None:
            return self.session
        elif isinstance(model_or_session, scoped_session):
            return model_or_session()
        else:
            raise TypeError(
                "Expected a session, model or None, got %s" % type(model_or_session)
            )

def marshal(self, o, use_value_list=False):
        """
        Packages the return from a parser for easy use in a rule.
        """

        if o is None:
            return
        elif isinstance(o, dict):
            if use_value_list:
                for k, v in o.items():
                    o[k] = [v]
            return o
        elif isinstance(o, six.string_types):
            if use_value_list:
                return {o: [True]}
            else:
                return {o: True}
        else:
            raise TypeError("Marshaller doesn't support given type %s" % type(o))

def marshal(self, o, use_value_list=False):
        """
        Packages the return from a parser for easy use in a rule.
        """
        if use_value_list:
            return self.value_list(o)
        else:
            return self.value(o)

