def wait_for_completion(self, job_id, timeout=None):
        """
        Wait for the job given by job_id to change to COMPLETED or CANCELED. Raises a
        iceqube.exceptions.TimeoutError if timeout is exceeded before each job change.

        :param job_id: the id of the job to wait for.
        :param timeout: how long to wait for a job state change before timing out.
        """
        while 1:
            job = self.wait(job_id, timeout=timeout)
            if job.state in [State.COMPLETED, State.FAILED, State.CANCELED]:
                return job
            else:
                continue

def wait_for_completion(self, job_id, timeout=None):
        """
        Wait for the job given by job_id to change to COMPLETED or CANCELED. Raises a
        iceqube.exceptions.TimeoutError if timeout is exceeded before each job change.

        :param job_id: the id of the job to wait for.
        :param timeout: how long to wait for a job state change before timing out.
        """
        if timeout is None:
            timeout = self.timeout

        start_time = time.time()
        while True:
            job = self.get_job(job_id)
            if job.state == 'COMPLETED' or job.state == 'CANCELED':
                return job
            elif time.time() - start_time > timeout:
                raise TimeoutError('Timeout exceeded while waiting for job to complete.')
            else:
                time.sleep(1)

def _inject_language(self, src, strings):
    """Injects languages into (potentially) template strings."""
    if src not in self.sources:
      raise ValueError("Invalid source for '{0}': {1}".format(self.name, src))
    def _format_string(s):
      if "{0}" in s and "{1}" and "{src}" in s:
        return s.format(*sorted([src, self.target]), src=src)
      elif "{0}" in s and "{1}" in s:
        return s.format(*sorted([src, self.target]))
      elif "{src}" in s:
        return s.format(src=src)
      else:
        return s
    return [_format_string(s) for s in strings]

def _inject_language(self, src, strings):
    """Injects languages into (potentially) template strings."""
    if not strings:
        return src

    # Inject language into strings.
    for string in strings:
        src = src.replace(string, string + '|' + self.language)

    # Inject language into comments.
    for comment in self.comments:
        src = src.replace(comment, comment + '|' + self.language)

    return src

def get_files():
    """
    Read all the template's files
    """

    files_root = path.join(path.dirname(__file__), 'files')

    for root, dirs, files in walk(files_root):
        rel_root = path.relpath(root, files_root)

        for file_name in files:
            try:
                f = open(path.join(root, file_name), 'r', encoding='utf-8')
                with f:
                    yield rel_root, file_name, f.read(), True
            except UnicodeError:
                f = open(path.join(root, file_name), 'rb')
                with f:
                    yield rel_root, file_name, f.read(), False

def get_files():
    """
    Read all the template's files
    """
    files = []
    for root, dirs, files in os.walk(TEMPLATE_DIR):
        for file in files:
            if file.endswith(".html"):
                files.append(os.path.join(root, file))
    return files

def build_pos_grid(start, end, nstep, mesh=False):
    """
    Return a grid of positions starting at X,Y given by 'start', and ending
    at X,Y given by 'end'. The grid will be completely filled in X and Y by
    every 'step' interval.
    """
    if mesh:
        return np.meshgrid(np.linspace(start[0], end[0], nstep),
                           np.linspace(start[1], end[1], nstep))
    else:
        return np.linspace(start[0], end[0], nstep), np.linspace(start[1], end[1], nstep)

def recv_msg(self):
        """message receive routine"""
        while True:
            try:
                msg = self.sock.recv(1024)
                if msg:
                    self.msg_queue.put(msg)
            except socket.error:
                break

def get_fun(fun):
    """
    Return a dict of the last function called for all minions
    """
    serv = _get_serv(ret=None)
    ret = {}
    for minion in serv.smembers('minions'):
        ind_str = '{0}:{1}'.format(minion, fun)
        try:
            jid = serv.get(ind_str)
        except Exception:
            continue
        if not jid:
            continue
        data = serv.get('{0}:{1}'.format(minion, jid))
        if data:
            ret[minion] = salt.utils.json.loads(data)
    return ret

def get_fun(fun):
    """
    Return a dict of the last function called for all minions
    """
    ret = {}
    for minion in __salt__["mine.get"](tgt="*", fun=fun, expr_form="list"):
        ret[minion] = __salt__["mine.get"](tgt=minion, fun=fun)
    return ret

def encode(self, obj):
        """Fired for every object."""
        if isinstance(obj, datetime.datetime):
            return obj.isoformat()
        elif isinstance(obj, datetime.date):
            return obj.isoformat()
        elif isinstance(obj, datetime.time):
            return obj.isoformat()
        elif isinstance(obj, decimal.Decimal):
            return float(obj)
        elif isinstance(obj, uuid.UUID):
            return str(obj)
        elif isinstance(obj, bytes):
            return obj.decode('utf-8')
        elif isinstance(obj, set):
            return list(obj)
        elif isinstance(obj, enum.Enum):
            return obj.value
        elif isinstance(obj, collections.abc.Mapping):
            return dict(obj)
        elif isinstance(obj, collections.abc.Iterable):
            return list(obj)
        else:
            return obj

