def from_dict(cls, val):
        """Creates dict2 object from dict object

        Args:
            val (:obj:`dict`): Value to create from

        Returns:
            Equivalent dict2 object.
        """
        if isinstance(val, dict2):
            return val

        elif isinstance(val, dict):
            res = cls()
            for k, v in val.items():
                res[k] = cls.from_dict(v)
            return res

        elif isinstance(val, list):
            res = []
            for item in val:
                res.append(cls.from_dict(item))
            return res
        else:
            return val

def _get_file_name(self, contentDisposition,
                       url, ext=".unknown"):
        """ gets the file name from the header or url if possible """
        if self.PY2:
            if contentDisposition is not None:
                return re.findall(r'filename[^;=\n]*=(([\'"]).*?\2|[^;\n]*)',
                                  contentDisposition.strip().replace('"', ''))[0][0]
            elif os.path.basename(url).find('.') > -1:
                return os.path.basename(url)
        elif self.PY3:
            if contentDisposition is not None:
                p = re.compile(r'filename[^;=\n]*=(([\'"]).*?\2|[^;\n]*)')
                return p.findall(contentDisposition.strip().replace('"', ''))[0][0]
            elif os.path.basename(url).find('.') > -1:
                return os.path.basename(url)
        return "%s.%s" % (uuid.uuid4().get_hex(), ext)

def _get_file_name(self, contentDisposition,
                       url, ext=".unknown"):
        """ gets the file name from the header or url if possible """
        if contentDisposition:
            _, params = cgi.parse_header(contentDisposition)
            if "filename" in params:
                return params["filename"]
        return url.split("/")[-1].split(".")[0] + ext

async def ping(self, reconnect=True):
        """Check if the server is alive"""
        if self._writer is None and self._reader is None:
            if reconnect:
                await self._connect()
                reconnect = False
            else:
                raise Error("Already closed")
        try:
            await self._execute_command(COMMAND.COM_PING, "")
            await self._read_ok_packet()
        except Exception:
            if reconnect:
                await self._connect()
                await self.ping(False)
            else:
                raise

async def ping(self, reconnect=True):
        """Check if the server is alive"""
        if self.is_connected():
            self.send_command(b'PING')
            return True
        else:
            if reconnect:
                self.connect()
                return self.ping()
            else:
                return False

def _get_key_index(self, row):
        """Get the key that should be used as the first interpolation value"""
        return row[self.key_column]

def from_object(cls, obj):
        # type: (Any) -> UrlPath
        """
        Attempt to convert any object into a UrlPath.

        Raise a value error if this is not possible.
        """
        if isinstance(obj, UrlPath):
            return obj
        if isinstance(obj, _compat.string_types):
            return UrlPath.parse(obj)
        if isinstance(obj, PathParam):
            return UrlPath(obj)
        if isinstance(obj, (tuple, list)):
            return UrlPath(*obj)
        raise ValueError("Unable to convert object to UrlPath `%r`" % obj)

def from_object(cls, obj):
        # type: (Any) -> UrlPath
        """
        Attempt to convert any object into a UrlPath.

        Raise a value error if this is not possible.
        """
        if isinstance(obj, cls):
            return obj
        if isinstance(obj, str):
            return cls.from_string(obj)
        if isinstance(obj, list):
            return cls.from_list(obj)
        if isinstance(obj, tuple):
            return cls.from_tuple(obj)
        if isinstance(obj, dict):
            return cls.from_dict(obj)
        raise ValueError("Cannot convert object of type {} to UrlPath".format(type(obj)))

def fetch_previous(self, next_page):
        """
        Fetches the previous page of results of a paginated request. Pass in the
        previous page in its entirety, or the pagination information dict
        returned as a part of that pages first status ('_pagination_prev').

        Returns the previous page or None if no further data is available.
        """
        if isinstance(next_page, list) and len(next_page) != 0:
            if hasattr(next_page[0], '_pagination_prev'):
                params = copy.deepcopy(next_page[0]._pagination_prev)
            else:
                return None
        else:
            params = copy.deepcopy(next_page)

        method = params['_pagination_method']
        del params['_pagination_method']

        endpoint = params['_pagination_endpoint']
        del params['_pagination_endpoint']

        return self.__api_request(method, endpoint, params)

def fetch_previous(self, next_page):
        """
        Fetches the previous page of results of a paginated request. Pass in the
        previous page in its entirety, or the pagination information dict
        returned as a part of that pages first status ('_pagination_prev').

        Returns the previous page or None if no further data is available.
        """
        if next_page is None:
            return None

        if isinstance(next_page, dict):
            next_page = next_page['_pagination_prev']

        if next_page is None:
            return None

        return self.fetch(next_page)

def inverse(self, encoded, duration=None):
        """Inverse transformation"""
        if duration is None:
            duration = self.duration
        return self.inverse_transform(encoded, duration)

def error_handler(f):
    """Return a json payload and appropriate status code on expection."""
    @wraps(f)
    def inner(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except ReceiverDoesNotExist:
            return jsonify(
                status=404,
                description='Receiver does not exists.'
            ), 404
        except InvalidPayload as e:
            return jsonify(
                status=415,
                description='Receiver does not support the'
                            ' content-type "%s".' % e.args[0]
            ), 415
        except WebhooksError:
            return jsonify(
                status=500,
                description='Internal server error'
            ), 500
    return inner

def error_handler(f):
    """Return a json payload and appropriate status code on expection."""
    def wrapper(*args, **kwargs):
        try:
            return f(*args, **kwargs)
        except Exception as e:
            return jsonify({'error': str(e)}), 400
    return wrapper

def parse_changelog(args: Any) -> Tuple[str, str]:
    """Return an updated changelog and and the list of changes."""
    changelog = ""
    changes = []
    with open(args.changelog, "r") as f:
        for line in f:
            if line.startswith("##"):
                break
            changelog += line
    with open(args.changelog, "r") as f:
        for line in f:
            if line.startswith("##"):
                changes.append(line.strip())
    return changelog, "\n".join(changes)

def _auto_compile(self, template, use_format=False):
        """Compile replacements."""

        is_replace = _is_replace(template)
        is_string = isinstance(template, (str, bytes))
        if is_replace and use_format != template.use_format:
            raise ValueError("Compiled replace cannot be a format object!")
        if is_replace or (is_string and self.auto_compile):
            return self.compile(template, (FORMAT if use_format and not is_replace else 0))
        elif is_string and use_format:
            # Reject an attempt to run format replace when auto-compiling
            # of template strings has been disabled and we are using a
            # template string.
            raise AttributeError('Format replaces cannot be called without compiling replace template!')
        else:
            return template

def _auto_compile(self, template, use_format=False):
        """Compile replacements."""
        if use_format:
            return template.format(**self.replacements)
        else:
            return template.replace(**self.replacements)

def emit(self, record):
        """
        Emit a record.

        The record is formatted, and then sent to the syslog server. If
        exception information is present, it is NOT sent to the server.
        """
        try:
            msg = self.format(record)
            priority = self.mapPriority(record.levelname)
            if self.use_udp:
                self.sock.sendto(msg, (self.host, self.port))
            else:
                self.sock.send(msg)
        except (KeyboardInterrupt, SystemExit):
            raise
        except:
            self.handleError(record)

def _hash_to_sh_address(script_hash, witness=False, cashaddr=True):
    """
    bytes, bool, bool -> str
    cashaddrs are preferred where possible
    but cashaddr is ignored in most cases
    is there a better way to structure this?
    """
    addr_bytes = bytearray()
    if riemann.network.CASHADDR_P2SH is not None and cashaddr:
        addr_bytes.extend(riemann.network.CASHADDR_P2SH)
        addr_bytes.extend(script_hash)
        return riemann.network.CASHADDR_ENCODER.encode(addr_bytes)
    if witness:
        addr_bytes.extend(riemann.network.P2WSH_PREFIX)
        addr_bytes.extend(script_hash)
        return riemann.network.SEGWIT_ENCODER.encode(addr_bytes)
    else:
        addr_bytes.extend(riemann.network.P2SH_PREFIX)
        addr_bytes.extend(script_hash)
        return riemann.network.LEGACY_ENCODER.encode(addr_bytes)

def _hash_to_sh_address(script_hash, witness=False, cashaddr=True):
    """
    bytes, bool, bool -> str
    cashaddrs are preferred where possible
    but cashaddr is ignored in most cases
    is there a better way to structure this?
    """
    if cashaddr:
        try:
            return _hash_to_cash_address(script_hash, witness)
        except ValueError:
            pass
    return _hash_to_base58_address(script_hash, witness)

def iter_parts(self):
        """
        Generate exactly one reference to each of the parts in the package by
        performing a depth-first traversal of the rels graph.
        """
        def walk_parts(source, visited=list()):
            for rel in source.rels.values():
                if rel.is_external:
                    continue
                part = rel.target_part
                if part in visited:
                    continue
                visited.append(part)
                yield part
                new_source = part
                for part in walk_parts(new_source, visited):
                    yield part

        for part in walk_parts(self):
            yield part

def iter_parts(self):
        """
        Generate exactly one reference to each of the parts in the package by
        performing a depth-first traversal of the rels graph.
        """
        for rel in self.rels.values():
            if isinstance(rel, PackagePart):
                yield rel
            elif isinstance(rel, PackagePartCollection):
                for part in rel.iter_parts():
                    yield part

def release(self):
        """ Release file and thread locks. If in 'degraded' mode, close the
        stream to reduce contention until the log files can be rotated. """
        try:
            if self._rotateFailed:
                self._close()
        except Exception:
            self.handleError(NullLogRecord())
        finally:
            try:
                if self.stream_lock and not self.stream_lock.closed:
                    unlock(self.stream_lock)
            except Exception:
                self.handleError(NullLogRecord())
            finally:
                # release thread lock
                if Handler:
                    Handler.release(self)

def parse_command_lines(self, acd_def):
        """
        parse the command line to generate an abstract job order dictionary,
        based on the parameters defined in the ACD
        structure of job order is that for each defined parameter, there is
        a dictionary entry containing its value and the value of its various
        qualifiers
        """
        job_order = {}
        for param in acd_def.parameters:
            if param.name in self.command_line:
                job_order[param.name] = self.command_line[param.name]
                if param.qualifiers:
                    for qualifier in param.qualifiers:
                        if qualifier.name in self.command_line:
                            job_order[param.name][qualifier.name] = self.command_line[qualifier.name]
        return job_order

def removereadergroup(self, group):
        """Remove a reader group"""
        if group in self.readergroups:
            self.readergroups.remove(group)

def as_matrix_transform(transform):
    """
    Simplify a transform to a single matrix transform, which makes it a lot
    faster to compute transformations.

    Raises a TypeError if the transform cannot be simplified.
    """
    if isinstance(transform, ChainTransform):
        matrix = np.identity(4)
        for tr in transform.transforms:
            # We need to do the matrix multiplication manually because VisPy
            # somehow doesn't mutliply matrices if there is a perspective
            # component. The equation below looks like it's the wrong way
            # around, but the VisPy matrices are transposed.
            matrix = np.matmul(as_matrix_transform(tr).matrix, matrix)
        return MatrixTransform(matrix)
    elif isinstance(transform, InverseTransform):
        matrix = as_matrix_transform(transform._inverse)
        return MatrixTransform(matrix.inv_matrix)
    elif isinstance(transform, NullTransform):
        return MatrixTransform()
    elif isinstance(transform, STTransform):
        return transform.as_matrix()
    elif isinstance(transform, MatrixTransform):
        return transform
    else:
        raise TypeError("Could not simplify transform of type {0}".format(type(transform)))

def as_matrix_transform(transform):
    """
    Simplify a transform to a single matrix transform, which makes it a lot
    faster to compute transformations.

    Raises a TypeError if the transform cannot be simplified.
    """
    if isinstance(transform, MatrixTransform):
        return transform
    elif isinstance(transform, ChainTransform):
        return ChainTransform(
            *[as_matrix_transform(t) for t in transform.transforms]
        )
    elif isinstance(transform, Transform):
        return MatrixTransform(transform.matrix)
    else:
        raise TypeError(
            "Cannot simplify transform of type %s" % type(transform)
        )

def isPythonFile(filename):
    """Return True if filename points to a Python file."""
    if filename.endswith('.py'):
        return True

    # Avoid obvious Emacs backup files
    if filename.endswith("~"):
        return False

    max_bytes = 128

    try:
        with open(filename, 'rb') as f:
            text = f.read(max_bytes)
            if not text:
                return False
    except IOError:
        return False

    first_line = text.splitlines()[0]
    return PYTHON_SHEBANG_REGEX.match(first_line)

def isPythonFile(filename):
    """Return True if filename points to a Python file."""
    return filename.endswith('.py')

def iter_distribution_names(self):
        """Yield all packages, modules, and extension names in distribution"""

        for pkg in self.packages or ():
            yield pkg

        for module in self.py_modules or ():
            yield module

        for ext in self.ext_modules or ():
            if isinstance(ext, tuple):
                name, buildinfo = ext
            else:
                name = ext.name
            if name.endswith('module'):
                name = name[:-6]
            yield name

def iter_distribution_names(self):
        """Yield all packages, modules, and extension names in distribution"""
        for name in self.iter_distribution_names_recursive():
            yield name

