def module_sys_modules_key(key):
    """
    Check if a module is in the sys.modules dictionary in some manner.  If so,
    return the key used in that dictionary.

    :param key: our key to the module.
    :returns: the key in sys.modules or None.
    """
    if key in sys.modules:
        return key
    if key.replace('.', '/') in sys.modules:
        return key.replace('.', '/')
    if key.replace('.', '/') + '.py' in sys.modules:
        return key.replace('.', '/') + '.py'
    if key.replace('.', '/') + '.pyc' in sys.modules:
        return key.replace('.', '/') + '.pyc'
    if key.replace('.', '/') + '.pyo' in sys.modules:
        return key.replace('.', '/') + '.pyo'
    return None

