def _fill_schemas_from_definitions(self, obj):
        """At first create schemas without 'AllOf'
        :param obj:
        :return: None
        """
        if obj.get('definitions'):
            self.schemas.clear()
            all_of_stack = []
            for name, definition in obj['definitions'].items():
                if 'allOf' in definition:
                    all_of_stack.append((name, definition))
                else:
                    self.schemas.create_schema(
                        definition, name, SchemaTypes.DEFINITION, root=self)
            while all_of_stack:
                name, definition = all_of_stack.pop(0)
                self.schemas.create_schema(
                    definition, name, SchemaTypes.DEFINITION, root=self)

def _fill_schemas_from_definitions(self, obj):
        """At first create schemas without 'AllOf'
        :param obj:
        :return: None
        """
        if isinstance(obj, dict):
            if 'definitions' in obj:
                for key, value in obj['definitions'].items():
                    if 'AllOf' in value:
                        obj['definitions'][key] = value['AllOf'][0]

def set_hyperparameters(self, hyperparameters):
        """Set new hyperparameters.

        Only the specified hyperparameters are modified, so any other
        hyperparameter keeps the value that had been previously given.

        If necessary, a new instance of the primitive is created.

        Args:
            hyperparameters (dict): Dictionary containing as keys the name
                                    of the hyperparameters and as values
                                    the values to be used.
        """
        if not isinstance(hyperparameters, dict):
            raise TypeError("Hyperparameters must be a dictionary.")

        # Check that all hyperparameters are valid
        for key in hyperparameters:
            if key not in self.hyperparameters:
                raise ValueError("Invalid hyperparameter: %s" % key)

        # Check that all hyperparameters have a valid value
        for key, value in hyperparameters.items():
            if not isinstance(value, self.hyperparameters[key]):
                raise TypeError("Invalid value for hyperparameter %s: %s" %
                                (key, value))

        # Check that the new hyperparameters are valid
        for key, value in hyperparameters.items():
            if key in self.hyperparameters:
                if value != self.hyperparameters[key]:
                    raise ValueError("Invalid value for hyperparameter %s: %s"
                                     % (key, value))

        # Check that the new hyperparameters are compatible with the
        # current instance
        for key, value in hyperparameters.items():
            if key in self.hyperparameters:
                if value != self.hyperparameters[key]:
                    raise ValueError("Invalid value for hyperparameter %s: %s"
                                     % (key, value))

        # Update the hyperparameters
        self.hyperparameters.update(hyperparameters)

        # Create a new instance if necessary
        if self.hyperparameters != self._hyperparameters:
            self._hyperparameters = self.hyperparameters
            self._instance = None

def samReferencesToStr(filenameOrSamfile, indent=0):
    """
    List SAM/BAM file reference names and lengths.

    @param filenameOrSamfile: Either a C{str} SAM/BAM file name or an
        instance of C{pysam.AlignmentFile}.
    @param indent: An C{int} number of spaces to indent each line.
    @return: A C{str} describing known reference names and their lengths.
    """
    indent = ' ' * indent

    def _references(sam):
        result = []
        for i in range(sam.nreferences):
            result.append('%s%s (length %d)' % (
                indent, sam.get_reference_name(i), sam.lengths[i]))
        return '\n'.join(result)

    if isinstance(filenameOrSamfile, six.string_types):
        with samfile(filenameOrSamfile) as sam:
            return _references(sam)
    else:
        return _references(sam)

def samReferencesToStr(filenameOrSamfile, indent=0):
    """
    List SAM/BAM file reference names and lengths.

    @param filenameOrSamfile: Either a C{str} SAM/BAM file name or an
        instance of C{pysam.AlignmentFile}.
    @param indent: An C{int} number of spaces to indent each line.
    @return: A C{str} describing known reference names and their lengths.
    """
    if isinstance(filenameOrSamfile, str):
        samfile = pysam.AlignmentFile(filenameOrSamfile, "rb")
    else:
        samfile = filenameOrSamfile
    refs = samfile.references
    refs.sort()
    refs = [str(x) for x in refs]
    refs = "\n".join([" " * indent + x for x in refs])
    return "References:\n" + refs

def puts(s='', newline=True, stream=STDOUT):
    """Prints given string to stdout."""
