        """Remove a document(s) from this collection.

        **DEPRECATED** - Use :meth:`delete_one` or :meth:`delete_many` instead.

        .. versionchanged:: 3.0
           Removed the `safe` parameter. Pass ``w=0`` for unacknowledged write
           operations.
        """
        warnings.warn("remove is deprecated. Use delete_one or delete_many "
                      "instead.", DeprecationWarning, stacklevel=2)
        if spec_or_id is None:
            spec_or_id = {}
        if not isinstance(spec_or_id, abc.Mapping):
            spec_or_id = {"_id": spec_or_id}
        write_concern = None
        collation = validate_collation_or_none(kwargs.pop('collation', None))
        if kwargs:
            write_concern = WriteConcern(**kwargs)
        return self._delete_retryable(
            spec_or_id, multi, write_concern, collation=collation)

def remove(self, spec_or_id=None, multi=True, **kwargs):
        """Remove a document(s) from this collection.

        **DEPRECATED** - Use :meth:`delete_one` or :meth:`delete_many` instead.

        .. versionchanged:: 3.0
           Removed the `safe` parameter. Pass ``w=0`` for unacknowledged write
           operations.
        """
        warnings.warn(
            "Collection.remove is deprecated. Use delete_one or delete_many instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        if spec_or_id is None:
            raise ValueError("spec_or_id must be provided")
        if not multi:
            return self.delete_one(spec_or_id, **kwargs)
        return self.delete_many(spec_or_id, **kwargs)

def validate(self, instance, value):
        """Check if input is valid URL"""
        if not value:
            raise ValidationError(self.error_messages['required'])
        try:
            result = urlparse(value)
            if not all([result.scheme, result.netloc]):
                raise ValidationError(self.error_messages['invalid'])
        except:
            raise ValidationError(self.error_messages['invalid'])

def _get_coordinatenames(self):
        """Create ordered list of coordinate names
        """
        validnames = ("direction", "spectral", "linear", "stokes", "tabular")
        self._names = [""] * len(validnames)
        n = 0
        for key in self._csys.keys():
            for name in validnames:
                if key.startswith(name):
                    idx = int(key[len(name):])
                    self._names[idx] = name
                    n += 1
        # reverse as we are c order in python
        self._names = self._names[:n][::-1]

        if len(self._names) == 0:
            raise LookupError("Coordinate record doesn't contain valid coordinates")

def _w_within_shard(args: Dict[str, Any]):
    """Applies a W gate when the gate acts only within a shard."""
    if args['shard_idx'] is None:
        return args['gate']
    else:
        return cirq.WGate(exponent=args['exponent'],
                          global_shift=args['global_shift'],
                          shard_idx=args['shard_idx'])

def _insert_url(request, redirect_field_name=REDIRECT_FIELD_NAME,
                inserted_url=None):
    """Redirects to the *inserted_url* before going to the orginal
    request path."""
    if inserted_url is None:
        inserted_url = request.GET.get(redirect_field_name)
    if inserted_url is None:
        inserted_url = request.POST.get(redirect_field_name)
    if inserted_url is None:
        return HttpResponseRedirect(request.path)
    return HttpResponseRedirect(inserted_url)

def dynamic_shape(self, max_elements):
        """Determine the dynamic shape, given incoming data that is big enough
        to hold `max_elements` elements.
        """
        known = 1
        unknown_pos = -1
        for i, x in enumerate(self.shape):
            if x is not None:
                known *= x
            else:
                assert unknown_pos == -1, 'Shape has multiple unknown dimensions'
                unknown_pos = i
        if unknown_pos == -1:
            return self.shape
        else:
            shape = list(self.shape)
            if known == 0:
                shape[unknown_pos] = 0
            else:
                shape[unknown_pos] = max_elements // known
            return shape

