def pressure_tendency(code: str, unit: str = 'mb') -> str:
    """
    Translates a 5-digit pressure outlook code

    Ex: 50123 -> 12.3 mb: Increasing, then decreasing
    """
    if code == '00000':
        return 'No change'
    elif code == '00001':
        return 'Increasing'
    elif code == '00010':
        return 'Decreasing'
    elif code == '00011':
        return 'Increasing, then decreasing'
    elif code == '00100':
        return 'Decreasing, then increasing'
    elif code == '00101':
        return 'Increasing, then decreasing, then increasing'
    elif code == '00110':
        return 'Decreasing, then increasing, then decreasing'
    elif code == '00111':
        return 'Increasing, then decreasing, then increasing, then decreasing'
    elif code == '01000':
        return 'Decreasing, then increasing, then decreasing'
    elif code == '01001':
        return 'Increasing, then decreasing, then increasing, then decreasing'
    elif code == '01010':
        return 'Decreasing, then increasing, then decreasing, then increasing'
    elif code == '01011':
        return 'Increasing, then decreasing, then increasing, then decreasing, then increasing'
    elif code == '01100':
        return 'Decreasing, then increasing, then decreasing, then increasing, then decreasing'
    elif code == '01101':
        return 'Increasing, then decreasing, then increasing, then decreasing, then increasing, then decreasing'
    elif code == '01110':
        return 'Decreasing, then increasing, then decreasing, then increasing, then decreasing, then increasing'
    elif code == '01111':
        return 'Increasing, then decreasing, then increasing, then decreasing, then increasing, then decreasing, then increasing'
    elif code == '10000':
        return 'Decreasing, then increasing, then decreasing, then increasing, then decreasing'
    elif code == '10001':
        return

def is_valid(self):
        """
        Checks the feature list product spec against.
        Checks if all mandartory features are contained;
        Checks that all "never" features are not contained
        :return: boolean
        """
        for spec in self.product_specs:

            for feature in spec.get('mandatory', []):
                if feature.replace('__', '.') not in self.feature_list:
                    self.errors_mandatory.append(feature)

            for feature in spec.get('never', []):
                if feature.replace('__', '.') in self.feature_list:
                    self.errors_never.append(feature)

        return not self.has_errors()

def is_valid(self):
        """
        Checks the feature list product spec against.
        Checks if all mandartory features are contained;
        Checks that all "never" features are not contained
        :return: boolean
        """
        if not self.product_spec:
            return False
        if not self.product_spec.get('features'):
            return False
        if not self.product_spec.get('features').get('mandatory'):
            return False
        if not self.product_spec.get('features').get('never'):
            return False
        if not self.product_spec.get('features').get('optional'):
            return False
        if not self.product_spec.get('features').get('mandatory'):
            return False
        if not self.product_spec.get('features').get('mandatory').get('features'):
            return False
        if not self.product_spec.get('features').get('never').get('features'):
            return False
        if not self.product_spec.get('features').get('optional').get('features'):
            return False
        if not self.product_spec.get('features').get('mandatory').get('features').get('feature'):
            return False
        if not self.product_spec.get('features').get('never').get('features').get('feature'):
            return False
        if not self.product_spec.get('features').get('optional').get('features').get('feature'):
            return False
        return True

def get_class_from_settings_from_apps(settings_key):
    """Try and get a class from a settings path by lookin in installed apps.
    """
    cls_path = getattr(settings, settings_key, None)

    if not cls_path:
        raise NotImplementedError()

    try:
        app_label = cls_path.split('.')[-2]
        model_name = cls_path.split('.')[-1]
    except ValueError:
        raise ImproperlyConfigured("{0} must be of the form "
                                   "'app_label.model_name'".format(
                                                                settings_key))

    app = apps.get_app_config(app_label).models_module

    if not app:
        raise ImproperlyConfigured("{0} setting refers to an app that has not "
                                   "been installed".format(settings_key))

    return getattr(app, model_name)

def get_class_from_settings_from_apps(settings_key):
    """Try and get a class from a settings path by lookin in installed apps.
    """
    from django.apps import apps
    from django.conf import settings

    try:
        app_label, class_name = settings_key.split('.')
    except ValueError:
        raise ValueError("settings_key must be in the format app_label.class_name")

    try:
        app_config = apps.get_app_config(app_label)
    except LookupError:
        raise LookupError("Could not find app with label {}".format(app_label))

    try:
        return getattr(app_config.models_module, class_name)
    except AttributeError:
        raise AttributeError("Could not find class {} in app {}".format(class_name, app_label))

