def git_version():
    """Constructs a version string of the form:

           <tag>[.<distance-from-tag>[+<branch-name-if-not-master>]]

       Master is understood to be always buildable and thus untagged
       versions are treated as patch levels. Branches not master are treated
       as PEP-440 "local version identifiers".
    """
    def _git_version():
        """Runs git commands to determine the version."""
        # This is a no-op if the directory is not a git repo.
        git_dir = os.path.join(os.path.dirname(__file__), '.git')
        if not os.path.exists(git_dir):
            return '0.0.0'

        # Determine the current commit.
        try:
            commit = subprocess.check_output(['git', 'rev-parse', 'HEAD'],
                                             cwd=git_dir).strip()
        except subprocess.CalledProcessError:
            return '0.0.0'

        # Determine the distance from the tag.
        try:
            distance = subprocess.check_output(['git', 'rev-list', 'HEAD',
                                                '--count'],
                                               cwd=git_dir).strip()
        except subprocess.CalledProcessError:
            return '0.0.0'

        # Determine the tag.
        try:
            tag = subprocess.check_output(['git', 'describe', '--tags',
                                           '--exact-match'],
                                          cwd=git_dir).strip()
        except subprocess.CalledProcessError:
            tag = None

        # Determine the branch.
        try:
            branch = subprocess.check_output(['git', 'rev-parse', '--abbrev-ref',
                                              'HEAD'],
                                             cwd=git_dir).strip()
        except subprocess.CalledProcessError:
            branch = None

        # Determine the version.
        if tag is not None:
            version = tag
        else:
            version = '0.0.0'
            if distance != '0':
                version += '.%s' % distance
            if branch is not None and branch != 'master':
                version += '+%s' % branch

        return version

    # Cache the result.
    try:
        return _git_version_cache
    except NameError:
        _git_version_cache = _git_

def subgraph_from(self, targets: sos_targets):
        """Trim DAG to keep only nodes that produce targets"""
        if 'DAG' in env.config['SOS_DEBUG'] or 'ALL' in env.config['SOS_DEBUG']:
            env.log_to_file('DAG', 'create subgraph')
        # first, find all nodes with targets
        subnodes = []
        for node in self.nodes():
            if node._output_targets.valid() and any(
                    x in node._output_targets for x in targets):
                subnodes.append(node)
        #
        ancestors = set()
        for node in subnodes:
            ancestors |= nx.ancestors(self, node)
        return SoS_DAG(nx.subgraph(self, subnodes + list(ancestors)))

def subgraph_from(self, targets: sos_targets):
        """Trim DAG to keep only nodes that produce targets"""
        targets = self._targets_to_nodes(targets)
        return self.subgraph(targets)

def _print_MatMul(self, expr):
        """
        Matrix multiplication printer. The sympy one turns everything into a
        dot product without type-checking.
        """
        from sympy import MatrixExpr
        links = []
        for i, j in zip(expr.args[1:], expr.args[:-1]):
            if isinstance(i, MatrixExpr) and isinstance(j, MatrixExpr):
                links.append(').dot(')
            else:
                links.append('*')
        printouts = [self._print(i) for i in expr.args]
        result = [printouts[0]]
        for link, printout in zip(links, printouts[1:]):
            result.extend([link, printout])
        return '({0})'.format(''.join(result))

def _print_MatMul(self, expr):
        """
        Matrix multiplication printer. The sympy one turns everything into a
        dot product without type-checking.
        """
        if expr.args[0].shape[1] != expr.args[1].shape[0]:
            raise ValueError("Incompatible shapes for matrix multiplication")
        return "{} {} {}".format(
            self._print(expr.args[0]),
            self._print(expr.args[1]),
            self._print(expr.args[2]),
        )

def assign_variable_names(self):
        """
        Assign default names to all variables.

        :return: None
        """

        for var in self._variables:
            if isinstance(var, SimStackVariable):
                if var.name is not None:
                    continue
                if var.ident.startswith('iarg'):
                    var.name = 'arg_%x' % var.offset
                else:
                    var.name = 's_%x' % (-var.offset)
                    # var.name = var.ident
            elif isinstance(var, SimRegisterVariable):
                if var.name is not None:
                    continue
                var.name = var.ident

def parse_single_value(value):
    """
    Tries to convert to int, float and then gives up and assumes the value
    is of type string. Useful when excepting values that may be string
    representations of numerical values
    """
    if isinstance(value, basestring):
        try:
            if value.startswith('"') and value.endswith('"'):
                value = str(value[1:-1])
            elif '.' in value:
                value = float(value)
            else:
                value = int(value)
        except ValueError:
            value = str(value)
    elif not isinstance(value, (int, float)):
        raise ArcanaUsageError(
            "Unrecognised type for single value {}".format(value))
    return value

def parse_single_value(value):
    """
    Tries to convert to int, float and then gives up and assumes the value
    is of type string. Useful when excepting values that may be string
    representations of numerical values
    """
    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return value

