def catch_raise_api_exception():
    """Context manager that translates upstream API exceptions."""
    try:
        yield
    except _ApiException as exc:
        detail = None
        fields = None

        if exc.body:
            try:
                # pylint: disable=no-member
                data = json.loads(exc.body)
                detail = data.get("detail", None)
                fields = data.get("fields", None)
            except ValueError:
                pass

        detail = detail or exc.reason

        raise ApiException(
            exc.status, detail=detail, headers=exc.headers, body=exc.body, fields=fields
        )

def catch_raise_api_exception():
    """Context manager that translates upstream API exceptions."""
    try:
        yield
    except Exception as e:
        raise APIException(e)

def alwaysCalledWithMatch(self, *args, **kwargs): #pylint: disable=invalid-name
        """
        Determining whether args/kwargs are the ONLY matched args/kwargs called previously
        Handle each arg/kwarg as a SinonMatcher
        Return: Boolean
        """
        self.__remove_args_first_item()
        alist, klist, gfunc = self.args, self.kwargs, self.__get_func
        if args and kwargs:
            return (uch.tuple_partial_cmp_always(args, alist, gfunc) and
                    uch.dict_partial_cmp_always(kwargs, klist, gfunc))
        elif args:
            return uch.tuple_partial_cmp_always(args, alist, gfunc)
        elif kwargs:
            return uch.dict_partial_cmp_always(kwargs, klist, gfunc)
        else:
            ErrorHandler.called_with_empty_error()
        self.__get_func = SinonSpy.__get_by_matcher

def del_metadata_keys(self, bucket, label, keys):
        """Delete the metadata corresponding to the specified keys.
        """
        if self.mode !="r":
            try:
                payload = self._get_bucket_md(bucket)
            except OFSFileNotFound:
                # No MD found...
                raise OFSFileNotFound("Couldn't find a md file for %s bucket" % bucket)
            except OFSException as e:
                raise OFSException(e)
            if payload.has_key(label):
                for key in [x for x in keys if payload[label].has_key(x)]:
                    del payload[label][key]
            self.put_stream(bucket, MD_FILE, json.dumps(payload), params={}, replace=True, add_md=False)
        else:
            raise OFSException("Cannot update MD in archive in 'r' mode")

def del_metadata_keys(self, bucket, label, keys):
        """Delete the metadata corresponding to the specified keys.
        """
        if not keys:
            return
        if not isinstance(keys, list):
            keys = [keys]
        for key in keys:
            self.del_metadata(bucket, label, key)

def _load_filter(self, config):
        """ Load the filter file and populates self._devices accordingly """
        path = pathlib.Path(config)
        if not path.is_file():
            return

        with open(config, 'r') as conf:
            devices = yaml.load(conf)['devices']
            for ha_id, dev in devices.items():
                self._devices[dev['scs_id']] = {
                    ha_id: dev,
                    'name': dev['name']}

def _load_filter(self, config):
        """ Load the filter file and populates self._devices accordingly """
        if not config:
            return

        if not os.path.exists(config):
            raise Exception("Filter file %s does not exist" % config)

        with open(config, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue

                if line.startswith('+'):
                    self._devices.append(line[1:])
                elif line.startswith('-'):
                    self._devices.remove(line[1:])
                else:
                    raise Exception("Invalid filter file %s" % config)

def send_command(self, *args, **kwargs):
        """
        If the ASA is in multi-context mode, then the base_prompt needs to be
        updated after each context change.
        """
        if len(args) >= 1:
            command_string = args[0]
        else:
            command_string = kwargs["command_string"]

        # If changeto in command, look for '#' to determine command is done
        if "changeto" in command_string:
            if len(args) <= 1:
                expect_string = kwargs.get("expect_string", "#")
                kwargs["expect_string"] = expect_string
        output = super(CiscoAsaSSH, self).send_command(*args, **kwargs)

        if "changeto" in command_string:
            self.set_base_prompt()

        return output

def send_command(self, *args, **kwargs):
        """
        If the ASA is in multi-context mode, then the base_prompt needs to be
        updated after each context change.
        """
        if self.multi_context:
            self.base_prompt = self.find_prompt(
                self.base_prompt,
                strip_context=True
            )
        return super(CiscoASA, self).send_command(*args, **kwargs)

def _ensure_sequence(self, mutable=False):
        """This method can be called by methods that need a sequence.  If
        `mutable` is true, it will also ensure that the response sequence
        is a standard Python list.

        .. versionadded:: 0.6
        """
        if not isinstance(self.response, list):
            self.response = list(self.response)
        if mutable:
            self.response = list(self.response)

def prune(force):
    """Remove all configuration for environments."""
    if not force:
        echo_warning(
            'Removing configuration of environments that may be in use will leave '
            'them in a potentially unusable state. If you wish to proceed (e.g. you '
            'have just restarted your machine), you may use the -f / --force flag.'
        )
        abort(code=2)

    checks = get_configured_checks()
    for check in checks:
        envs = get_configured_envs(check)

        if envs:
            echo_info('{}:'.format(check))
            for env in envs:
                echo_waiting('Removing `{}`... '.format(env), nl=False, indent=True)
                remove_env_data(check, env)
                echo_success('success!')

        remove_env_root(check)

