            "Are you sure you want to continue?",
            abort=True,
        )

    for env in get_environments():
        click.echo(f"Removing configuration for {env}")
        remove_environment(env)

def execute(self, logical_form: str):
        """Executes a logical form, using whatever predicates you have defined."""
        if not hasattr(self, '_functions'):
            raise RuntimeError("You must call super().__init__() in your Language constructor")
        logical_form = logical_form.replace(",", " ")
        expression = util.lisp_to_nested_expression(logical_form)
        return self._execute_expression(expression)

def broadcast(self, clients, msg):
        """ Optimized C{broadcast} implementation. Depending on type of the
        session, will json-encode message once and will call either
        C{send_message} or C{send_jsonifed}.

        @param clients: Clients iterable

        @param msg: Message to send
        """
        json_msg = None

        count = 0

        for c in clients:
            sess = c.session
            if not sess.is_closed:
                if sess.send_expects_json:
                    if json_msg is None:
                        json_msg = proto.json_encode(msg)
                    sess.send_jsonified(json_msg, stats=False)
                else:
                    sess.send_message(msg, stats=False)

                count += 1

        self.stats.packSent(count)

def broadcast(self, clients, msg):
        """ Optimized C{broadcast} implementation. Depending on type of the
        session, will json-encode message once and will call either
        C{send_message} or C{send_jsonifed}.

        @param clients: Clients iterable

        @param msg: Message to send
        """
        if isinstance(msg, dict):
            msg = json.dumps(msg)
        for client in clients:
            self.send_message(client, msg)

def login(self, user, password, token=None, callback=None):
        """Login with a username and password

        Arguments:
        user - username or email address
        password - the password for the account

        Keyword Arguments:
        token - meteor resume token
        callback - callback function containing error as first argument and login data"""
        # TODO: keep the tokenExpires around so we know the next time
        #       we need to authenticate

        # hash the password
        hashed = hashlib.sha256(password).hexdigest()
        # handle username or email address
        if '@' in user:
            user_object = {
                'email': user
            }
        else:
            user_object = {
                'username': user
            }
        password_object = {
            'algorithm': 'sha-256',
            'digest': hashed
        }

        self._login_token = token
        self._login_data = {'user': user_object, 'password': password_object}

        if token:
            self._resume(token, callback=callback)
        else:
            self._login(self._login_data, callback=callback)

def set_properties(self, eid, value, idx='*'):
        """
        Set the value and/or attributes of an xml element, marked with the matching eid attribute, using the
        properties of the specified object.
        """
        if value.__class__ not in Template.class_cache:
            props = []
            for name in dir(value.__class__):
                prop = getattr(value.__class__, name)
                if type(prop) == property and hasattr(prop, 'fget'):
                    props.append((name, prop))
            Template.class_cache[value.__class__] = props
        for (name, prop) in Template.class_cache[value.__class__]:
            new_eid = ''.join([eid, ':', name])
            self.set_value(new_eid, prop.fget(value), idx)
            self.set_attribute(eid, name, prop.fget(value), idx)

def set_properties(self, eid, value, idx='*'):
        """
        Set the value and/or attributes of an xml element, marked with the matching eid attribute, using the
        properties of the specified object.
        """
        if isinstance(value, str):
            self.set_text(eid, value, idx)
        elif isinstance(value, dict):
            self.set_attributes(eid, value, idx)
        elif isinstance(value, list):
            self.set_children(eid, value, idx)
        else:
            raise ValueError('Invalid value type: %s' % type(value))

def get_waiting_list(self, force=False):
        """ Add lines for any waiting fields that can be completed now. """
        if not force and self.waiting_list:
            return
        self.waiting_list = []
        for field in self.fields:
            if field.waiting:
                self.waiting_list.append(field)

def rename_with_prefix(self, prefix="", new_path=None, in_place=True, remove_desc=True):
        """Rename every sequence based on a prefix."""
        # Temporary path #
        if new_path is None: prefixed = self.__class__(new_temp_path())
        else:                prefixed = self.__class__(new_path)
        # Generator #
        def prefixed_iterator():
            for i,read in enumerate(self):
                read.id = prefix + read.id
                if remove_desc: read.description = ""
                yield read
        # Do it #
        prefixed.write(prefixed_iterator())
        prefixed.close()
        # Replace it #
        if in_place:
            os.remove(self.path)
            shutil.move(prefixed, self.path)
        return prefixed

def rename_with_prefix(self, prefix="", new_path=None, in_place=True, remove_desc=True):
        """Rename every sequence based on a prefix."""
        if new_path is None:
            new_path = self.path
        if not in_place:
            new_path = os.path.join(new_path, self.name)
        if remove_desc:
            new_path = os.path.join(new_path, self.name.split("_")[0])
        for seq in self.sequences:
            seq.rename(prefix, new_path, in_place, remove_desc)

def node_is_subclass(cls, *subclass_names):
    """Checks if cls node has parent with subclass_name."""
    for subclass_name in subclass_names:
        if cls.parent_name == subclass_name:
            return True
    return False

def fits_recarray_to_dict(table):
    """Convert a FITS recarray to a python dictionary."""

    cols = {}
    for icol, col in enumerate(table.columns.names):

        col_data = table.data[col]
        if type(col_data[0]) == np.float32:
            cols[col] = np.array(col_data, dtype=float)
        elif type(col_data[0]) == np.float64:
            cols[col] = np.array(col_data, dtype=float)
        elif type(col_data[0]) == str:
            cols[col] = np.array(col_data, dtype=str)
        elif type(col_data[0]) == np.string_:
            cols[col] = np.array(col_data, dtype=str)
        elif type(col_data[0]) == np.int16:
            cols[col] = np.array(col_data, dtype=int)
        elif type(col_data[0]) == np.ndarray:
            cols[col] = np.array(col_data)
        else:
            raise Exception(
                'Unrecognized column type: %s %s' % (col, str(type(col_data))))

    return cols

def fits_recarray_to_dict(table):
    """Convert a FITS recarray to a python dictionary."""
    return {colname: table[colname] for colname in table.dtype.names}

def prepare(value, should_escape):
    """
    Prepares a value to be added to the result

    :param value:
        The value to add to the result

    :param should_escape:
        If the string should be HTML-escaped

    :return:
        A unicode string or strlist
    """

    if value is None:
        return u''
    type_ = type(value)
    if type_ is not strlist:
        if type_ is not str_class:
            if type_ is bool:
                value = u'true' if value else u'false'
            else:
                value = str_class(value)
        if should_escape:
            value = escape(value)
    return value

def prepare(value, should_escape):
    """
    Prepares a value to be added to the result

    :param value:
        The value to add to the result

    :param should_escape:
        If the string should be HTML-escaped

    :return:
        A unicode string or strlist
    """

    if should_escape:
        if isinstance(value, str):
            return escape(value)
        elif isinstance(value, strlist):
            return strlist(escape(v) for v in value)
        else:
            return value
    else:
        return value

def _remove_qualifiers(obj):
        """
        Remove all qualifiers from the input objectwhere the object may
        be an CIMInstance or CIMClass. Removes qualifiers from the object and
        from properties, methods, and parameters

        This is used to process the IncludeQualifier parameter for classes
        and instances
        """
        if isinstance(obj, CIMInstance):
            for prop in obj.properties:
                prop.qualifiers = []
        elif isinstance(obj, CIMClass):
            for prop in obj.properties:
                prop.qualifiers = []
            for method in obj.methods:
                method.qualifiers = []
            for param in obj.parameters:
                param.qualifiers = []
        return obj

def prep_jid(nocache=False, passed_jid=None):
    """
    Return a job id and prepare the job id directory
    This is the function responsible for making sure jids don't collide (unless
    its passed a jid)
    So do what you have to do to make sure that stays the case
    """
    if passed_jid is None:
        jid = salt.utils.jid.gen_jid(__opts__)
    else:
        jid = passed_jid

    cb_ = _get_connection()

    try:
        cb_.add(six.text_type(jid),
               {'nocache': nocache},
               ttl=_get_ttl(),
               )
    except couchbase.exceptions.KeyExistsError:
        # TODO: some sort of sleep or something? Spinning is generally bad practice
        if passed_jid is None:
            return prep_jid(nocache=nocache)

    return jid

def _remove_unexpected_query_parameters(schema, req):
    """Remove unexpected properties from the req.GET."""
    additional_properties = schema.get('addtionalProperties', True)

    if additional_properties:
        pattern_regexes = []

        patterns = schema.get('patternProperties', None)
        if patterns:
            for regex in patterns:
                pattern_regexes.append(re.compile(regex))

        for param in set(req.GET.keys()):
            if param not in schema['properties'].keys():
                if not (list(regex for regex in pattern_regexes if
                             regex.match(param))):
                    del req.GET[param]

def _remove_unexpected_query_parameters(schema, req):
    """Remove unexpected properties from the req.GET."""
    for key in list(req.GET.keys()):
        if key not in schema:
            del req.GET[key]

def get_parameter(name, withdecryption=False, resp_json=False, region=None, key=None, keyid=None, profile=None):
    """
    Retrives a parameter from SSM Parameter Store

    .. versionadded:: Neon

    .. code-block:: text

        salt-call boto_ssm.get_parameter test-param withdescription=True
    """
    conn = __utils__['boto3.get_connection']('ssm', region=region, key=key, keyid=keyid, profile=profile)
    try:
        resp = conn.get_parameter(Name=name, WithDecryption=withdecryption)
    except conn.exceptions.ParameterNotFound:
        log.warning("get_parameter: Unable to locate name: %s", name)
        return False

    if resp_json:
        return json.loads(resp['Parameter']['Value'])
    else:
        return resp['Parameter']['Value']

def get_parameter(name, withdecryption=False, resp_json=False, region=None, key=None, keyid=None, profile=None):
    """
    Retrives a parameter from SSM Parameter Store

    .. versionadded:: Neon

    .. code-block:: text

        salt-call boto_ssm.get_parameter test-param withdescription=True
    """
    if not region:
        region = __salt__["boto_ssm.get_region"](key, keyid, profile)

    conn = _get_conn(region, key, keyid, profile)

    try:
        response = conn.get_parameter(Name=name, WithDecryption=withdecryption)
    except ClientError as e:
        log.error(e)
        return False

    if resp_json:
        return response
    else:
        return response["Parameter"]

def branch_lengths(self, terminal=True, internal=True):
        """Generator over the lengths of the selected branches of this ``Tree``. Edges with length ``None`` will be output as 0-length

        Args:
            ``terminal`` (``bool``): ``True`` to include terminal branches, otherwise ``False``

            ``internal`` (``bool``): ``True`` to include internal branches, otherwise ``False``
        """
        if not isinstance(terminal, bool):
            raise TypeError("terminal must be a bool")
        if not isinstance(internal, bool):
            raise TypeError("internal must be a bool")
        for node in self.traverse_preorder():
            if (internal and not node.is_leaf()) or (terminal and node.is_leaf()):
                if node.edge_length is None:
                    yield 0
                else:
                    yield node.edge_length

def _read_gtf(gtf):
    """
    Load GTF file with precursor positions on genome
    """
    gtf_dict = {}
    with open(gtf, 'r') as f:
        for line in f:
            if line[0] == '#':
                continue
            line = line.strip().split('\t')
            if line[2] == 'exon':
                chrom = line[0]
                start = int(line[3])
                end = int(line[4])
                gene_id = line[8].split(';')[0].split(' ')[1]
                transcript_id = line[8].split(';')[1].split(' ')[1]
                if transcript_id not in gtf_dict:
                    gtf_dict[transcript_id] = {}
                if gene_id not in gtf_dict[transcript_id]:
                    gtf_dict[transcript_id][gene_id] = {}
                if chrom not in gtf_dict[transcript_id][gene_id]:
                    gtf_dict[transcript_id][gene_id][chrom] = {}
                gtf_dict[transcript_id][gene_id][chrom][start] = end
    return gtf_dict

def get_node_text(self, goid, goobj):
        """Return a string to be printed in a GO term box."""
        txt = []
        # Header line: "GO:0036464 L04 D06"
        txt.append(self.get_hdr(goid, goobj))
        # GO name line: "cytoplamic ribonucleoprotein"
        if 'no_name' not in self.present:
            txt.append(self._get_go_name(goobj))
        # study info line: "24 genes"
        if 'objgoea' in self.kws:
            study_txt = self.kws['objgoea'].get_study_txt(goid)
            if study_txt is not None:
                txt.append(study_txt)
        # Add user-specified text, if needed
        if 'go2txt' in self.kws and goid in self.kws['go2txt']:
            txt.append(self.kws['go2txt'][goid])
        return "\n".join(txt)

def get_node_text(self, goid, goobj):
        """Return a string to be printed in a GO term box."""
        if goobj.namespace == 'biological_process':
            return '{} ({} {})'.format(goobj.name, goobj.namespace, goobj.id)
        else:
            return '{} ({})'.format(goobj.name, goobj.namespace)

def _load_bundle_map(self):
        """
        Return a map of all bundles in the Clarify app that have an external_id set for them.
        The bundles with external_ids set are assumed to be the ones we have inserted from Brightcove.
        The external_id contains the Brightcove video id.
        """
        bundle_map = {}
        next_href = None
        has_next = True

        while has_next:
            bundles = self.clarify_client.get_bundle_list(href=next_href, embed_items=True)
            items = get_embedded_items(bundles)
            for item in items:
                bc_video_id = item.get('external_id')
                if bc_video_id is not None and len(bc_video_id) > 0:
                    bundle_map[bc_video_id] = item
            next_href = get_link_href(bundles, 'next')
            if next_href is None:
                has_next = False
        return bundle_map

def _load_bundle_map(self):
        """
        Return a map of all bundles in the Clarify app that have an external_id set for them.
        The bundles with external_ids set are assumed to be the ones we have inserted from Brightcove.
        The external_id contains the Brightcove video id.
        """
        bundle_map = {}
        for bundle in self.clarify.bundles.list():
            if bundle.external_id:
                bundle_map[bundle.external_id] = bundle
        return bundle_map

def teardown(self):
        """
        Tears down the instance, removing any remaining sessions that this instance has created.

        The instance must not be used after this method has been called.
        """
        with self._teardown_lock:
            if not self._teardown_called:
                self._teardown_called = True
                if len(self._acquiring_session_ids) > 0:
                    logger.info(
                        f"Destroying all sessions that have not acquired keys: {self._acquiring_session_ids}...")
                for session_id in self._acquiring_session_ids:
                    try:
                        self.consul_client.session.destroy(session_id=session_id)
                        logger.debug(f"Destroyed: {session_id}")
                    except requests.exceptions.ConnectionError as e:
                        logger.debug(f"Exception: {e}")
                        logger.warning(f"Could not connect to Consul to clean up session {session_id}")
                atexit.unregister(self.teardown)

def get_current_orga(request, hproject, availableOrga):
    """Return the current orga to use"""
    if request.user.is_authenticated:
        if request.user.is_superuser:
            return availableOrga
        else:
            return request.user.orga
    else:
        return availableOrga

