def in_check(self, position, location=None):
        """
        Finds if the king is in check or if both kings are touching.

        :type: position: Board
        :return: bool
        """
        location = location or self.location
        for piece in position:

            if piece is not None and piece.color != self.color:
                if not isinstance(piece, King):
                    for move in piece.possible_moves(position):

                        if move.end_loc == location:
                            return True
                else:
                    if self.loc_adjacent_to_opponent_king(piece.location, position):
                        return True

        return False

def in_check(self, position, location=None):
        """
        Finds if the king is in check or if both kings are touching.

        :type: position: Board
        :return: bool
        """
        if location is None:
            location = self.location
        if self.check_king(position, location):
            return True
        if self.check_king(position, location.flip()):
            return True
        return False

def flush(self):
        """Flush all streams."""
        if self.__logFileStream is not None:
            try:
                self.__logFileStream.flush()
            except:
                pass
            try:
                os.fsync(self.__logFileStream.fileno())
            except:
                pass
        if self.__stdout is not None:
            try:
                self.__stdout.flush()
            except:
                pass
            try:
                os.fsync(self.__stdout.fileno())
            except:
                pass

def flush(self):
        """Flush all streams."""
        for stream in self.streams:
            stream.flush()

def visible_width(string):
    """Get the visible width of a unicode string.

    Some CJK unicode characters are more than one byte unlike ASCII and latin unicode characters.

    From: https://github.com/Robpol86/terminaltables/pull/9

    :param str string: String to measure.

    :return: String's width.
    :rtype: int
    """
    if '\033' in string:
        string = RE_COLOR_ANSI.sub('', string)

    # Convert to unicode.
    try:
        string = string.decode('u8')
    except (AttributeError, UnicodeEncodeError):
        pass

    width = 0
    for char in string:
        if unicodedata.east_asian_width(char) in ('F', 'W'):
            width += 2
        else:
            width += 1

    return width

def _sanity_check_all_marked_locations_are_registered(ir_blocks, query_metadata_table):
    """Assert that all locations in MarkLocation blocks have registered and valid metadata."""
    # Grab all the registered locations, then make sure that:
    # - Any location that appears in a MarkLocation block is also registered.
    # - There are no registered locations that do not appear in a MarkLocation block.
    registered_locations = {
        location
        for location, _ in query_metadata_table.registered_locations
    }

    ir_encountered_locations = {
        block.location
        for block in ir_blocks
        if isinstance(block, MarkLocation)
    }

    unregistered_locations = ir_encountered_locations - registered_locations
    unencountered_locations = registered_locations - ir_encountered_locations
    if unregistered_locations:
        raise AssertionError(u'IR blocks unexpectedly contain locations not registered in the '
                             u'QueryMetadataTable: {}'.format(unregistered_locations))
    if unencountered_locations:
        raise AssertionError(u'QueryMetadataTable unexpectedly contains registered locations that '
                             u'never appear in the IR blocks: {}'.format(unencountered_locations))

def _sanity_check_all_marked_locations_are_registered(ir_blocks, query_metadata_table):
    """Assert that all locations in MarkLocation blocks have registered and valid metadata."""
    for block in ir_blocks:
        if isinstance(block, MarkLocation):
            location = block.location
            if location not in query_metadata_table:
                raise ValueError(
                    f"Location {location} is not registered in the query metadata table."
                )
            if not query_metadata_table[location].is_valid:
                raise ValueError(
                    f"Location {location} is registered in the query metadata table but is not valid."
                )

def notify_items(**kwargs):
    """
    Signal endpoint that actually sends knocks whenever an instance is created / saved
    """
    instance = kwargs.get('instance')
    created = kwargs.get('created', False)
    if hasattr(instance, 'send_knock') and active_knocks(instance):
        try:
            # This is a stupid generic interface for multilanguage models (hvad / parler)
            if hasattr(instance, 'get_available_languages'):
                langs = instance.get_available_languages()
            else:
                langs = [get_language()]
            for lang in langs:
                with override(lang):
                    instance.send_knock(created)
            return True
        except AttributeError:  # pragma: no cover
            pass
    return False

def notify_items(**kwargs):
    """
    Signal endpoint that actually sends knocks whenever an instance is created / saved
    """
    if kwargs.get('created'):
        notify_knocks(kwargs['instance'])

def get_health(self):
        """Summarize health of managed system

        This provides a summary of the health of the managed system.
        It additionally provides an iterable list of reasons for
        warning, critical, or failed assessments.
        """
        summary = {'badreadings': [], 'health': const.Health.Ok}
        fallbackreadings = []
        try:
            self.oem_init()
            fallbackreadings = self._oem.get_health(summary)
            for reading in self.get_sensor_data():
                if reading.health != const.Health.Ok:
                    summary['health'] |= reading.health
                    summary['badreadings'].append(reading)
        except exc.BypassGenericBehavior:
            pass
        if not summary['badreadings']:
            summary['badreadings'] = fallbackreadings
        return summary

def get_health(self):
        """Summarize health of managed system

        This provides a summary of the health of the managed system.
        It additionally provides an iterable list of reasons for
        warning, critical, or failed assessments.
        """
        health = self.get_health_status()
        if health == 'OK':
            return health
        else:
            return health, self.get_health_reasons()

def _is_child_wikicode(self, obj, recursive=True):
        """Return whether the given :class:`.Wikicode` is a descendant."""
        def deref(nodes):
            if isinstance(nodes, _ListProxy):
                return nodes._parent  # pylint: disable=protected-access
            return nodes

        target = deref(obj.nodes)
        if target is deref(self.nodes):
            return True
        if recursive:
            todo = [self]
            while todo:
                code = todo.pop()
                if target is deref(code.nodes):
                    return True
                for node in code.nodes:
                    todo += list(node.__children__())
        return False

def _is_child_wikicode(self, obj, recursive=True):
        """Return whether the given :class:`.Wikicode` is a descendant."""
        if recursive:
            return any(
                _is_child_wikicode(child, recursive=recursive)
                for child in obj.children
            )
        else:
            return obj in self.children

def stringReceived(self, response):
        """
        Handle a response from the broker.
        """
        correlation_id = response[0:4]
        try:
            d = self._pending.pop(correlation_id)
        except KeyError:
            self._log.warn((
                "Response has unknown correlation ID {correlation_id!r}."
                " Dropping connection to {peer}."
            ), correlation_id=correlation_id, peer=self.transport.getPeer())
            self.transport.loseConnection()
        else:
            d.callback(response)

def stringReceived(self, response):
        """
        Handle a response from the broker.
        """
        if response.isError():
            self.log.error("Error response: %s" % response.getError())
        else:
            self.log.info("Received: %s" % response.getBody())

def create_alias(target_path, alias_path):
    """Creates an alias at 'alias_path' pointing to the file 'target_path'.

    On Unix, this is implemented via symlink. On Windows, this is done by
    creating a Windows shortcut file.

    Args:
        target_path: Destination path that the alias should point to.
        alias_path: Path at which to create the new alias.
    """
    if not os.path.exists(target_path):
        raise IOError('Target path does not exist: %s' % target_path)

    if os.path.exists(alias_path):
        raise IOError('Alias path already exists: %s' % alias_path)

    if sys.platform == 'win32':
        _create_shortcut(target_path, alias_path)
    else:
        os.symlink(target_path, alias_path)

def match_rules_context(tree, rules, parent_context={}):
    """Recursively matches a Tree structure with rules and returns context

    Args:
        tree (Tree): Parsed tree structure
        rules (dict): See match_rules
        parent_context (dict): Context of parent call
    Returns:
        dict: Context matched dictionary of matched rules or
        None if no match
    """
    for template, match_rules in rules.items():
        context = parent_context.copy()
        if match_template(tree, template, context):
            for key, child_rules in match_rules.items():
                child_context = match_rules_context(context[key], child_rules, context)
                if child_context:
                    for k, v in child_context.items():
                        context[k] = v
                else:
                    return None
            return context
    return None

def match_rules_context(tree, rules, parent_context={}):
    """Recursively matches a Tree structure with rules and returns context

    Args:
        tree (Tree): Parsed tree structure
        rules (dict): See match_rules
        parent_context (dict): Context of parent call
    Returns:
        dict: Context matched dictionary of matched rules or
        None if no match
    """
    if not tree:
        return None

    if not rules:
        return None

    if not isinstance(tree, Tree):
        return None

    if not isinstance(rules, dict):
        return None

    if not isinstance(parent_context, dict):
        return None

    # Check if the tree matches the first rule
    if tree.label() in rules:
        # If the rule is a string, it is a leaf
        if isinstance(rules[tree.label()], str):
            # Check if the leaf matches the rule
            if tree.leaves()[0] == rules[tree.label()]:
                # Return the context
                return {tree.label(): tree.leaves()[0]}
            else:
                return None
        # If the rule is a list, it is a branch
        elif isinstance(rules[tree.label()], list):
            # Check if the branch matches the rule
            if tree.label() in rules[tree.label()]:
                # Recursively match the children
                context = match_rules_context(tree[0], rules[tree.label()], parent_context)
                if context:
                    # Return the context
                    return {tree.label(): context}
                else:
                    return None
            else:
                return None
        # If the rule is a dict, it is a branch
        elif isinstance(rules[tree.label()], dict):
            # Check if the branch matches the rule
            if tree.label() in rules[tree.label()]:
                # Recursively match the children
                context = match_rules_context(tree[0], rules[tree.label()], parent_context)
                if context:
                    # Return the context
                    return {tree.label(): context}
                else:
                    return None
            else:
                return None
        else:
            return None
    else:
        return None

def setup_logger(log_level, log_file=None, logger_name=None):
        """setup logger
            @param log_level: debug/info/warning/error/critical
            @param log_file: log file path
            @param logger_name: the name of logger, default is 'root' if not specify
        """
        applogger = AppLog(logger_name)
        level = getattr(logging, log_level.upper(), None)
        if not level:
            color_print("Invalid log level: %s" % log_level, "RED")
            sys.exit(1)

        # hide traceback when log level is INFO/WARNING/ERROR/CRITICAL
        if level >= logging.INFO:
            sys.tracebacklimit = 0

        if log_file:
            applogger._handle2file(log_file)
        else:
            applogger._handle2screen(color = True)

        applogger.logger.setLevel(level)

def setup_logger(log_level, log_file=None, logger_name=None):
        """setup logger
            @param log_level: debug/info/warning/error/critical
            @param log_file: log file path
            @param logger_name: the name of logger, default is 'root' if not specify
        """
        if logger_name is None:
            logger_name = 'root'
        logger = logging.getLogger(logger_name)
        logger.setLevel(log_level)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        if log_file is None:
            ch = logging.StreamHandler()
        else:
            ch = logging.FileHandler(log_file)
        ch.setFormatter(formatter)
        logger.addHandler(ch)
        return logger

def parse_json(target, json, create_sections = False, create_options = False):
 """Given a confmanager object and a dictionary object, import the values from the dictionary into the object, optionally adding sections and options as it goes."""
 is_dict = isinstance(json, dict)
 for o in json:
  if is_dict:
   section = o
  else:
   section = o[0]
  if not target.has_section(section):
   if create_sections:
    target.add_section(section)
   else:
    continue
  for k, v in (json[o].items() if is_dict else o[1]):
   if target.has_option(section, k) or create_options:
    target.set(section, k, v) # Don't add if it shouldn't be there.
 return target

def parse_json(target, json, create_sections = False, create_options = False):
 """Given a confmanager object and a dictionary object, import the values from the dictionary into the object, optionally adding sections and options as it goes."""

 if create_sections:
  for section in json:
   target.add_section(section)

 if create_options:
  for section in json:
   for option in json[section]:
    target.add_option(section, option, json[section][option])

 for section in json:
  for option in json[section]:
   target.set(section, option, json[section][option])

def maxpool(self, k=2, s=None, globe=False):
        """
        Takes max value over a k x k area in each input map, or over the entire map (global = True)
        :param k: int
        :param globe:  int, whether to pool over each feature map in its entirety
        """
        if s is None:
            s = k
        if globe:
            return self.apply(lambda x: F.max_pool2d(x, (x.size(2), x.size(3)), stride=s))
        else:
            return self.apply(lambda x: F.max_pool2d(x, (k, k), stride=s))

def wr_xlsx_sections(self, fout_xlsx, sections, sortby=None, **kws_usr):
        """Write goids into a table."""
        nts = self.get_nts_sections(sections, sortby)
        kws_wr = kws_usr.copy()
        if 'fld2col_widths' not in kws_wr:
            kws_wr['fld2col_widths'] = self.fld2col_widths
        else:
            fld2col_widths = self.fld2col_widths.copy()
            for fld, wid in kws_usr['fld2col_widths'].items():
                fld2col_widths[fld] = wid
            kws_wr['fld2col_widths'] = fld2col_widths
        wr_xlsx_sections_tbl(fout_xlsx, nts, **kws_wr)

def bip32(self, s):
        """
        Parse a bip32 public key from a text string, either a seed, a prv or a pub.
        Return a :class:`BIP32 <pycoin.key.BIP32Node.BIP32Node>` or None.
        """
        if s.startswith("xpub"):
            return BIP32Node.from_xpub(s)
        elif s.startswith("xprv"):
            return BIP32Node.from_xprv(s)
        elif s.startswith("ypub"):
            return BIP32Node.from_ypub(s)
        elif s.startswith("yprv"):
            return BIP32Node.from_yprv(s)
        elif s.startswith("zpub"):
            return BIP32Node.from_zpub(s)
        elif s.startswith("zprv"):
            return BIP32Node.from_zprv(s)
        elif s.startswith("tpub"):
            return BIP32Node.from_tpub(s)
        elif s.startswith("tprv"):
            return BIP32Node.from_tprv(s)
        elif s.startswith("npub"):
            return BIP32Node.from_npub(s)
        elif s.startswith("nprv"):
            return BIP32Node.from_nprv(s)
        elif s.startswith("upub"):
            return BIP32Node.from_upub(s)
        elif s.startswith("uprv"):
            return BIP32Node.from_uprv(s)
        elif s.startswith("vpub"):
            return BIP32Node.from_vpub(s)
        elif s.startswith("vprv"):
            return BIP32Node.from_vprv(s)
        elif s.startswith("Ypub"):
            return BIP32Node.from_Ypub(s)
        elif s.startswith("Yprv"):
            return BIP32Node.from_Yprv(s)
        elif s.startswith("Zpub"):
            return BIP32Node.from_Zpub(s)
        elif s.startswith("Zprv"):
            return BIP32

def set_proxy(self, proxy_server, proxy_port, proxy_username,
                  proxy_password):
        """ Sets a proxy on the Session

        :param str proxy_server: the proxy server
        :param int proxy_port: the proxy port, defaults to 8080
        :param str proxy_username: the proxy username
        :param str proxy_password: the proxy password
        """
        if proxy_server and proxy_port:
            if proxy_username and proxy_password:
                self.proxy = {
                    "http": "http://{}:{}@{}:{}".format(proxy_username,
                                                        proxy_password,
                                                        proxy_server,
                                                        proxy_port),
                    "https": "https://{}:{}@{}:{}".format(proxy_username,
                                                          proxy_password,
                                                          proxy_server,
                                                          proxy_port),
                }
            else:
                self.proxy = {
                    "http": "http://{}:{}".format(proxy_server, proxy_port),
                    "https": "https://{}:{}".format(proxy_server, proxy_port),
                }

def get_time_string(contest, contest_type):
  """Return a string with time for the contest to begin/end"""

  if contest_type == challenge().ACTIVE:
    time_diff = time_difference(contest["end"])
  elif contest_type == challenge().UPCOMING:
    time_diff = time_difference(contest["start"])
  elif contest_type in [challenge().HIRING, challenge().SHORT, challenge().ALL]:
    try:
      time_diff = time_difference(contest["start"])
    except:
      time_diff = time_difference(contest["end"])
  time_diff_string = ""

  if time_diff.days > 0: 
    time_diff_string = "{0} days {1} hours".format(time_diff.days, time_diff.hours)
  elif time_diff.hours > 0:
    time_diff_string = "{0} hours {1} minutes".format(time_diff.hours, time_diff.minutes)
  else:
    time_diff_string = "{0} minutes".format(time_diff.minutes)
  return time_diff_string

def get_time_string(contest, contest_type):
  """Return a string with time for the contest to begin/end"""
  if contest_type == 'begin':
    return contest['begin_time']
  elif contest_type == 'end':
    return contest['end_time']
  else:
    return ''

def __update_density(self, compound='', element=''):
        """Re-calculate the density of the element given due to stoichiometric changes as
        well as the compound density (if density is not locked)

        Parameters:
        ===========
        compound: string (default is '') name of compound
        element: string (default is '') name of element
        """
        if compound == '':
            compound = self.compound
        if element == '':
            element = self.element
        if self.density_locked:
            return
        if compound == '':
            return
        if element == '':
            return
        if compound not in self.compounds:
            return
        if element not in self.compounds[compound]:
            return
        if element not in self.compounds[compound]['density']:
            return
        if element not in self.compounds[compound]['stoichiometry']:
            return
        if self.compounds[compound]['density'][element] == 0:
            return
        if self.compounds[compound]['stoichiometry'][element] == 0:
            return
        self.compounds[compound]['density'][element] = \
            self.compounds[compound]['density'][element] * \
            self.compounds[compound]['stoichiometry'][element]
        if self.compound == '':
            return
        if self.element == '':
            return
        if self.compound not in self.compounds:
            return
        if self.element not in self.compounds[self.compound]:
            return
        if self.element not in self.compounds[self.compound]['density']:
            return
        if self.element not in self.compounds[self.compound]['stoichiometry']:
            return
        if self.compounds[self.compound]['density'][self.element] == 0:
            return
        if self.compounds[self.compound]['stoichiometry'][self.element] == 0:
            return
        self.compounds[self.compound]['density'][self.element] = \
            self.compounds[self.compound]['density'][self.element] * \
            self.compounds[self.compound]['stoichiometry'][self.element]

def _wait_ready(self, timeout_sec=1):
        """Wait until the PN532 is ready to receive commands.  At most wait
        timeout_sec seconds for the PN532 to be ready.  If the PN532 is ready
        before the timeout is exceeded then True will be returned, otherwise
        False is returned when the timeout is exceeded.
        """
        start_time = time.time()
        while True:
            if self._ready():
                return True
            if time.time() - start_time > timeout_sec:
                return False
            time.sleep(0.01)

def on_shutdown(self, callback: callable, polling=True, webhook=True):
        """
        Register a callback for the shutdown process

        :param callback:
        :param polling: use with polling
        :param webhook: use with webhook
        """
        self._check_frozen()
        if not webhook and not polling:
            warn('This action has no effect!', UserWarning)
            return

        if isinstance(callback, (list, tuple, set)):
            for cb in callback:
                self.on_shutdown(cb, polling, webhook)
            return

        if polling:
            self._on_shutdown_polling.append(callback)
        if webhook:
            self._on_shutdown_webhook.append(callback)

def remote_complete(self, failure=None):
        """
        Called by the worker's
        L{buildbot_worker.base.WorkerForBuilderBase.commandComplete} to
        notify me the remote command has finished.

        @type  failure: L{twisted.python.failure.Failure} or None

        @rtype: None
        """
        if failure is not None:
            self.log.error("remote command failed: %s", failure)
            self.remote_failure = failure
        self.remote_complete_deferred.callback(None)

def _merge_update_item(self, model_item, data):
        """
            Merge a model with a python data structure
            This is useful to turn PUT method into a PATCH also
        :param model_item: SQLA Model
        :param data: python data structure
        :return: python data structure
        """
        for key, value in data.items():
            if key in model_item:
                if isinstance(model_item[key], list):
                    model_item[key] = value
                elif isinstance(model_item[key], dict):
                    model_item[key] = self._merge_update_item(model_item[key], value)
                else:
                    model_item[key] = value
            else:
                model_item[key] = value
        return model_item

def restore_directory_state(self, fname):
        """Restore directory expanded state"""
        root = osp.normpath(to_text_string(fname))
        if not osp.exists(root):
            # Directory has been (re)moved outside Spyder
            return
        for basename in os.listdir(root):
            path = osp.normpath(osp.join(root, basename))
            if osp.isdir(path) and path in self.__expanded_state:
                self.__expanded_state.pop(self.__expanded_state.index(path))
                if self._to_be_loaded is None:
                    self._to_be_loaded = []
                self._to_be_loaded.append(path)
                self.setExpanded(self.get_index(path), True)
        if not self.__expanded_state:
            self.fsmodel.directoryLoaded.disconnect(self.restore_directory_state)

def restore_directory_state(self, fname):
        """Restore directory expanded state"""
        if os.path.exists(fname):
            with open(fname, 'r') as f:
                self.expanded_state = json.load(f)

def remove_from_list(self, key: str, value, count: int = 0,
                         pipeline: bool = False):
        """Remove specified value(s) from the list stored at key.

        Args:
            key (str): Key where the list is stored.
            value: value to remove
            count (int): Number of entries to remove, default 0 == all
            pipeline(bool): If True, start a transaction block. Default False.

        """
        if pipeline:
            if redis.__version__ == '2.10.6':
                self._pipeline.lrem(name=key, value=value, num=count)
            else:
                self._pipeline.lrem(key, count, value)
        else:
            if self._db.exists(key):
                if redis.__version__ == '2.10.6':
                    self._db.lrem(name=key, value=value, num=count)
                else:
                    self._db.lrem(key, count, value)

def remove_from_list(self, key: str, value, count: int = 0,
                         pipeline: bool = False):
        """Remove specified value(s) from the list stored at key.

        Args:
            key (str): Key where the list is stored.
            value: value to remove
            count (int): Number of entries to remove, default 0 == all
            pipeline(bool): If True, start a transaction block. Default False.

        """
        if not pipeline:
            return self.execute_command('LREM', key, count, value)
        else:
            return self.execute_command('LREM', key, count, value,
                                        transaction=True)

def verify(self, string_version=None):
        """
        Check that the version information is consistent with the VCS
        before doing a release. If supplied with a string version,
        this is also checked against the current version. Should be
        called from setup.py with the declared package version before
        releasing to PyPI.
        """
        if string_version and string_version != str(self):
            raise Exception("Supplied string version does not match current version.")

        if self.dirty:
            raise Exception("Current working directory is dirty.")

        if self.release != self.expected_release:
            raise Exception("Declared release does not match current release tag.")

        if self.commit_count !=0:
            raise Exception("Please update the VCS version tag before release.")

        if self._expected_commit not in [None, "$Format:%h$"]:
            raise Exception("Declared release does not match the VCS version tag")

def verify(self, string_version=None):
        """
        Check that the version information is consistent with the VCS
        before doing a release. If supplied with a string version,
        this is also checked against the current version. Should be
        called from setup.py with the declared package version before
        releasing to PyPI.
        """
        if string_version is not None:
            if string_version != self.version:
                raise ValueError(
                    "Version mismatch: %s != %s" % (string_version, self.version)
                )
        if self.vcs is None:
            raise RuntimeError("No VCS found")
        if self.vcs.get_version() != self.version:
            raise RuntimeError(
                "Version mismatch: %s != %s" % (self.vcs.get_version(), self.version)
            )

def skos_hierarchical_mappings(rdf, narrower=True):
    """Infer skos:broadMatch/skos:narrowMatch (S43) and add the super-properties
    skos:broader/skos:narrower (S41).

    :param bool narrower: If set to False, skos:narrowMatch will not be added,
        but rather removed.
    """
    for s, o in rdf.subject_objects(SKOS.broadMatch):
        rdf.add((s, SKOS.broader, o))
        if narrower:
            rdf.add((o, SKOS.narrowMatch, s))
            rdf.add((o, SKOS.narrower, s))

    for s, o in rdf.subject_objects(SKOS.narrowMatch):
        rdf.add((o, SKOS.broadMatch, s))
        rdf.add((o, SKOS.broader, s))
        if narrower:
            rdf.add((s, SKOS.narrower, o))
        else:
            rdf.remove((s, SKOS.narrowMatch, o))

def skos_hierarchical_mappings(rdf, narrower=True):
    """Infer skos:broadMatch/skos:narrowMatch (S43) and add the super-properties
    skos:broader/skos:narrower (S41).

    :param bool narrower: If set to False, skos:narrowMatch will not be added,
        but rather removed.
    """
    for s, p, o in rdf.triples((None, SKOS.broadMatch, None)):
        rdf.add((s, SKOS.broader, o))
        if narrower:
            rdf.add((o, SKOS.narrower, s))
    for s, p, o in rdf.triples((None, SKOS.narrowMatch, None)):
        rdf.add((s, SKOS.narrower, o))
        if narrower:
            rdf.add((o, SKOS.broader, s))

def _compose(self, name, args, mkdir=True):
        """Get a named filesystem entry, and extend it into a path with additional
        path arguments"""
        if mkdir:
            self.mkdir(name)
        return self.path(name) + self.path(*args)

def envcontext(patch, _env=None):
    """In this context, `os.environ` is modified according to `patch`.

    `patch` is an iterable of 2-tuples (key, value):
        `key`: string
        `value`:
            - string: `environ[key] == value` inside the context.
            - UNSET: `key not in environ` inside the context.
            - template: A template is a tuple of strings and Var which will be
              replaced with the previous environment
    """
    if _env is None:
        _env = os.environ
    env = _env.copy()
    for key, value in patch:
        if value is UNSET:
            if key in env:
                del env[key]
        else:
            env[key] = value
    return env

def segments_overlapping(ab, cd):
    """
    segments_overlapping((a, b), (c, d)) yields True if the line segments (a,b) and (c,d) are both
    colinear and have a non-finite overlap. If (a,b) and (c,d) touch at a single point, they are not
    considered overlapping.
    """
    if ab[0] == ab[1]:
        return False
    if cd[0] == cd[1]:
        return False
    if ab[0] == cd[0]:
        return False
    if ab[1] == cd[1]:
        return False
    if ab[0] > ab[1]:
        ab = (ab[1], ab[0])
    if cd[0] > cd[1]:
        cd = (cd[1], cd[0])
    if ab[0] > cd[1]:
        return False
    if ab[1] < cd[0]:
        return False
    if ab[0] < cd[0]:
        return False
    if ab[1] > cd[1]:
        return False
    return True

