def set_advanced_configs(vm_name, datacenter, advanced_configs,
                         service_instance=None):
    """
    Appends extra config parameters to a virtual machine advanced config list

    vm_name
        Virtual machine name

    datacenter
        Datacenter name where the virtual machine is available

    advanced_configs
        Dictionary with advanced parameter key value pairs

    service_instance
        vCenter service instance for connection and configuration
    """
    if not service_instance:
        service_instance = get_service_instance(opts=__opts__,
                                                opts_id=__opts__['id'])
    vm_obj = get_vm_ref(vm_name, datacenter, service_instance)
    if not vm_obj:
        raise VMwareObjectRetrievalError(
            'Unable to locate virtual machine \'{0}\''.format(vm_name)
        )
    if not advanced_configs:
        return
    for key, value in advanced_configs.items():
        if key not in __opts__['vmware_advanced_configs']:
            raise VMwareConfigError(
                'Invalid advanced config parameter \'{0}\''.format(key)
            )
        if value is None:
            continue
        if isinstance(value, bool):
            value = str(value).lower()
        elif isinstance(value, int):
            value = str(value)
        elif isinstance(value, str):
            pass
        else:
            raise VMwareConfigError(
                'Invalid advanced config parameter value \'{0}\''.format(value)
            )
        vm_obj.set(key, value)

def audio_stream_capture(self, httptype=None,
                             channel=None, path_file=None):
        """
        Params:

            path_file - path to output file
            channel: - integer
            httptype - type string (singlepart or multipart)

                singlepart: HTTP content is a continuos flow of audio packets
                multipart: HTTP content type is multipart/x-mixed-replace, and
                           each audio packet ends with a boundary string

        """
        if httptype is None:
            httptype = 'singlepart'

        if channel is None:
            channel = 0

        if path_file is None:
            path_file = 'audio_stream_capture.wav'

        if httptype == 'singlepart':
            self.audio_stream_capture_singlepart(path_file)
        elif httptype == 'multipart':
            self.audio_stream_capture_multipart(path_file)
        else:
            raise ValueError('httptype must be singlepart or multipart')

