def _get_callers(items, stage, special_cases=False):
    """Retrieve available callers for the provided stage.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis.
    """
    callers = utils.deepish_copy(_CALLERS[stage])
    if special_cases and "cnvkit" in callers:
        has_lumpy = any("lumpy" in get_svcallers(d) or "lumpy" in d["config"]["algorithm"].get("svcaller_orig", [])
                        for d in items)
        if has_lumpy and any("lumpy_usecnv" in dd.get_tools_on(d) for d in items):
            if stage != "initial":
                del callers["cnvkit"]
        else:
            if stage != "standard":
                del callers["cnvkit"]
    return callers

def _get_callers(items, stage, special_cases=False):
    """Retrieve available callers for the provided stage.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis.
    """
    callers = []
    for item in items:
        if special_cases:
            if item.startswith("CNVkit"):
                if stage == "initial":
                    callers.append("CNVkit")
                elif stage == "standard":
                    callers.append("CNVkit_standard")
            else:
                callers.append(item)
        else:
            callers.append(item)
    return callers

def _map_block_index_to_location(ir_blocks):
    """Associate each IR block with its corresponding location, by index."""
    block_index_to_location = {}
    # MarkLocation blocks occur after the blocks related to that location.
    # The core approach here is to buffer blocks until their MarkLocation is encountered
    # after which all buffered blocks can be associated with the encountered MarkLocation.location.
    current_block_ixs = []
    for num, ir_block in enumerate(ir_blocks):
        if isinstance(ir_block, blocks.GlobalOperationsStart):
            if len(current_block_ixs) > 0:
                unassociated_blocks = [ir_blocks[ix] for ix in current_block_ixs]
                raise AssertionError(
                    u'Unexpectedly encountered global operations before mapping blocks '
                    u'{} to their respective locations.'.format(unassociated_blocks))
            break
        current_block_ixs.append(num)
        if isinstance(ir_block, blocks.MarkLocation):
            for ix in current_block_ixs:
                block_index_to_location[ix] = ir_block.location
            current_block_ixs = []
    return block_index_to_location

def _map_block_index_to_location(ir_blocks):
    """Associate each IR block with its corresponding location, by index."""
    block_index_to_location = {}
    for block_index, block in enumerate(ir_blocks):
        block_index_to_location[block_index] = block.location
    return block_index_to_location

def query(self, url, method="GET", params=dict(), headers=dict()):
        """
        Request a API endpoint at ``url`` with ``params`` being either the
        POST or GET data.
        """
        if method == "GET":
            url = url + "?" + urlencode(params)
        else:
            headers["Content-Type"] = "application/x-www-form-urlencoded"

        try:
            response = self.session.request(method, url, params=params,
                                            headers=headers)
        except requests.exceptions.RequestException as e:
            raise APIError(e)

        if response.status_code == 401:
            raise APIError("Unauthorized")
        elif response.status_code == 403:
            raise APIError("Forbidden")
        elif response.status_code == 404:
            raise APIError("Not Found")
        elif response.status_code == 405:
            raise APIError("Method Not Allowed")
        elif response.status_code == 406:
            raise APIError("Not Acceptable")
        elif response.status_code == 409:
            raise APIError("Conflict")
        elif response.status_code == 410:
            raise APIError("Gone")
        elif response.status_code == 412:
            raise APIError("Precondition Failed")
        elif response.status_code == 415:
            raise APIError("Unsupported Media Type")
        elif response.status_code == 422:
            raise APIError("Unprocessable Entity")
        elif response.status_code == 429:
            raise APIError("Too Many Requests")
        elif response.status_code == 500:
            raise APIError("Internal Server Error")
        elif response.status_code == 501:
            raise APIError("Not Implemented")
        elif response.status_code == 502:
            raise APIError("Bad Gateway")
        elif response.status_code == 503:
            raise APIError("Service Unavailable")
        elif response.status_code == 504:
            raise APIError("Gateway Timeout")
        elif response.status_code == 505:
            raise APIError

def select(self, *fields, **kw):
        """
        Projection columns. Remember to avoid column names' conflict.

        :param fields: columns to project
        :param kw: columns and their names to project
        :return: new collection
        :rtype: :class:`odps.df.expr.expression.CollectionExpr`
        """
        if len(fields) == 1 and isinstance(fields[0], list):
            fields = fields[0]
        else:
            fields = list(fields)
        if kw:
            def handle(it):
                it = self._defunc(it)
                if not isinstance(it, Expr):
                    it = Scalar(it)
                return it
            fields.extend([handle(f).rename(new_name)
                           for new_name, f in six.iteritems(kw)])

        return self._project(fields)

def select(self, *fields, **kw):
        """
        Projection columns. Remember to avoid column names' conflict.

        :param fields: columns to project
        :param kw: columns and their names to project
        :return: new collection
        :rtype: :class:`odps.df.expr.expression.CollectionExpr`
        """
        if fields:
            return CollectionExpr(_expr=self._expr.select(*fields))
        else:
            return CollectionExpr(_expr=self._expr.select(**kw))

def GaussSeidelStep(self, S, X, ATYU, rho, lcw, W2):
        """Gauss-Seidel step for linear system in TV problem."""

        Xss = np.zeros_like(S, dtype=self.dtype)
        for ax in self.axes:
            Xss += sl.zpad(X[(slice(None),)*ax + (slice(0, -1),)],
                           (1, 0), ax)
            Xss += sl.zpad(X[(slice(None),)*ax + (slice(1, None),)],
                           (0, 1), ax)
        return (rho*(Xss + ATYU) + W2*S) / (W2 + rho*lcw)

def clear(**kwargs):
    """Clear the specified names from the specified databases.

    This can be highly destructive as it destroys tables and when all names
    are removed from a database, the database itself.
    """
    for dbname, names in kwargs.items():
        db = get_db(dbname)
        for name in names:
            db.clear(name)

