def _get_step_inout(step):
    """Retrieve set of inputs and outputs connecting steps.
    """
    inout = {}
    for inp in step.inputs:
        inout[inp.name] = inp
    for outp in step.outputs:
        inout[outp.name] = outp
    return inout

