def cli(env, identifier, name, all, note):
    """Capture one or all disks from a virtual server to a SoftLayer image."""
    client = env.client
    if all:
        disks = client['SoftLayer_Virtual_Guest'].getDisks(id=identifier)
        for disk in disks:
