def gethost(self, ip_addr):
        """
        Do reverse lookup on an ip address
        """
        # Handle silly fake ipv6 addresses
        try:
            if ip_addr[:7] == '::ffff:':
                ip_addr = ip_addr[7:]
        except TypeError:
            pass

        if ip_addr[0] in string.letters:
            return ip_addr

        try:
            return self.hostsmap[ip_addr]
        except KeyError:
            pass

        try:
            name = socket.gethostbyaddr(ip_addr)[0]
        except socket.error:
            name = ip_addr

        self.hostsmap[ip_addr] = name
        return name

def gethost(self, ip_addr):
        """
        Do reverse lookup on an ip address
        """
        try:
            host = socket.gethostbyaddr(ip_addr)[0]
        except socket.herror:
            host = None
        return host

def keys(self, latest=False):
        """
        Return a list of the keys in this directory.

        Parameters
        ----------

        latest : bool, optional (default=False)
            If True then return a list of keys with unique names where only the
            key with the highest cycle number is included where multiple keys
            exist with the same name.

        Returns
        -------

        keys : list
            List of keys

        """
        if latest:
            keys = {}
            for key in self.keys():
                name = key.GetName()
                if name in keys:
                    if key.GetCycle() > keys[name].GetCycle():
                        keys[name] = key
                else:
                    keys[name] = key
            return keys.values()
        return [asrootpy(key) for key in self.GetListOfKeys()]

def literal(compiler, cont, arg):
