def save(self, **kwargs):
        """
        Method that creates the translations tasks for every selected instance

        :param kwargs:
        :return:
        """
        if not self.instance.pk:
            raise ValueError('Cannot create translations for a new instance')

        if not self.instance.translations.exists():
            self.instance.translations.create(language_code=self.language_code)

        for field in self.fields:
            if field.name in self.instance.translations.first().fields_to_translate:
                self.fields[field.name].save(**kwargs)

def update(self, payload):
        """Updates the queried record with `payload` and returns the updated record after validating the response

        :param payload: Payload to update the record with
        :raise:
            :NoResults: if query returned no results
            :MultipleResults: if query returned more than one result (currently not supported)
        :return:
            - The updated record
        """
        try:
            result = self.get_one()
            if 'sys_id' not in result:
                raise NoResults()
        except MultipleResults:
            raise MultipleResults("Update of multiple records is not supported")
        except NoResults as e:
            e.args = ('Cannot update a non-existing record',)
            raise

        if not isinstance(payload, dict):
            raise InvalidUsage("Update payload must be of type dict")

        response = self.session.put(self._get_table_url(sys_id=result['sys_id']), data=json.dumps(payload))
        return self._get_content(response)

def _apply_uncertainty_to_geometry(self, source, value):
        """
        Modify ``source`` geometry with the uncertainty value ``value``
        """
        if self.uncertainty_type == 'simpleFaultDipRelative':
            source.modify('adjust_dip', dict(increment=value))
        elif self.uncertainty_type == 'simpleFaultDipAbsolute':
            source.modify('set_dip', dict(dip=value))
        elif self.uncertainty_type == 'simpleFaultGeometryAbsolute':
            trace, usd, lsd, dip, spacing = value
            source.modify(
                'set_geometry',
                dict(fault_trace=trace, upper_seismogenic_depth=usd,
                     lower_seismogenic_depth=lsd, dip=dip, spacing=spacing))
        elif self.uncertainty_type == 'complexFaultGeometryAbsolute':
            edges, spacing = value
            source.modify('set_geometry', dict(edges=edges, spacing=spacing))
        elif self.uncertainty_type == 'characteristicFaultGeometryAbsolute':
            source.modify('set_geometry', dict(surface=value))

def _apply_uncertainty_to_geometry(self, source, value):
        """
        Modify ``source`` geometry with the uncertainty value ``value``
        """
        if value is None:
            return
        if isinstance(source, (list, tuple)):
            for s in source:
                self._apply_uncertainty_to_geometry(s, value)
        elif isinstance(source, dict):
            for k, v in source.items():
                self._apply_uncertainty_to_geometry(v, value)
        elif isinstance(source, (int, float)):
            source = value * source
        elif isinstance(source, str):
            if source.startswith("{") and source.endswith("}"):
                source = value * float(source[1:-1])
        elif isinstance(source, (list, tuple)):
            for i, v in enumerate(source):
                self._apply_uncertainty_to_geometry(v, value)
        elif isinstance(source, dict):
            for k, v in source.items():
                self._apply_uncertainty_to_geometry(v, value)
        else:
            raise ValueError(f"Unrecognized geometry type: {type(source)}")

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        try:
            if value is None and self._default is not None:
                return self._export(self.default)
            self._check_required(value)
            value = self._export(value)
            return value
        except ValueError as ex:
            raise ValueError(ex, self._errors['to_data'])

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        if value is None:
            if self.required:
                raise ValueError("Required field %s is None" % self.name)
            else:
                return self.default
        elif isinstance(value, (list, tuple)):
            return [self.to_data(v) for v in value]
        elif isinstance(value, dict):
            return {self.to_data(k): self.to_data(v) for k, v in value.items()}
        else:
            return value

def get_dict(*keys, **extras):
    """Returns request dict of given keys."""
    return {key: request.args.get(key) for key in keys}

def heldout_log_likelihood(self, test_mask=None):
        """
        Compute the log likelihood of the masked data given the latent
        discrete and continuous states.
        """
        if test_mask is None:
            # If a test mask is not supplied, use the negation of this object's mask
            if self.mask is None:
                return 0
            else:
                test_mask = ~self.mask

        xs = np.hstack((self.gaussian_states, self.inputs))
        if self.single_emission:
            return self.emission_distns[0].\
                log_likelihood((xs, self.data), mask=test_mask).sum()
        else:
            hll = 0
            z = self.stateseq
            for idx, ed in enumerate(self.emission_distns):
                hll += ed.log_likelihood((xs[z == idx], self.data[z == idx]),
                                         mask=test_mask[z == idx]).sum()

def heldout_log_likelihood(self, test_mask=None):
        """
        Compute the log likelihood of the masked data given the latent
        discrete and continuous states.
        """
        if test_mask is None:
            test_mask = self.test_mask
        return self.log_likelihood(self.test_data, test_mask)

def _write_data_csv(csv_data):
    """
    CSV data has been parsed by this point, so take it and write it file by file.
    :return:
    """
    logger_excel.info("enter write_data_csv")
    # Loop for each file and data that is stored
    for file in csv_data:
        for filename, data in file.items():
            # Make sure we're working with the right data types before trying to open and write a file
            if isinstance(filename, str) and isinstance(data, list):
                try:
                    with open(filename, 'w+') as f:
                        w = csv.writer(f)
                        for line in data:
                            w.writerow(line)
                except Exception:
                    logger_excel.debug("write_data_csv: Unable to open/write file: {}".format(filename))

    logger_excel.info("exit write_data_csv")
    return

def execute_setup(self):  # type: () -> Dict[str,str]
        """
        for really surprising things like a dict foo in setup(**foo)
        consider python3 setup.py --version
        :return:
        """

        ver = execute_get_text("python setup.py --version")
        if not ver:
            return None

        if "UserWarning" in ver:
            logger.warning(
                "python setup.py --version won't parse, got :" + unicode(ver)
            )
            # UserWarning- Ther version specified ... is an invalid...
            return {}

        if ver:
            string = unicode(ver).strip(" \n")
            if "\n" in string:
                string = string.split("\n")[0]

            return {"setup.py --version": string.strip(" \n")}
        else:
            return {}

def route(self, path=None, method='GET', **kargs):
        """ Decorator: Bind a function to a GET request path.

            If the path parameter is None, the signature of the decorated
            function is used to generate the path. See yieldroutes()
            for details.

            The method parameter (default: GET) specifies the HTTP request
            method to listen to. You can specify a list of methods. 
        """
        if path is None:
            path = self.path(kargs)
        if isinstance(method, basestring):
            method = [method]
        def decorator(func):
            self.add_route(path, func, method)
            return func
        return decorator

def shellsafe(s, quote='', doescape=True):
    """Returns the value string, wrapped in the specified quotes (if not empty), but checks and raises an Exception if the string is at risk of causing code injection"""
    if sys.version[0] == '2' and not isinstance(s,unicode): #pylint: disable=undefined-variable
        s = unicode(s,'utf-8') #pylint: disable=undefined-variable
    if len(s) > 1024:
        raise ValueError("Variable value rejected for security reasons: too long")
    if quote:
        if quote in s:
            if doescape:
                s = escape(s,quote)
            else:
                raise ValueError("Variable value rejected for security reasons: " + s)
        return quote + s + quote
    else:
        for c in s:
            if c in DISALLOWINSHELLSAFE:
                raise ValueError("Variable value rejected for security reasons: " + s)
        return s

def shellsafe(s, quote='', doescape=True):
    """Returns the value string, wrapped in the specified quotes (if not empty), but checks and raises an Exception if the string is at risk of causing code injection"""
    if quote:
        if quote not in ('"', "'"):
            raise Exception("Invalid quote character: %s" % quote)
        if quote == "'" and "'" in s:
            raise Exception("Single quotes are not allowed in the string: %s" % s)
        if quote == '"' and '"' in s:
            raise Exception("Double quotes are not allowed in the string: %s" % s)
    if doescape:
        s = s.replace('\\', '\\\\')
        s = s.replace('"', '\\"')
        s = s.replace("'", "\\'")
    return quote + s + quote

def _build_item_closure(itemset, productionset):
    """Build input itemset closure """
    #For every item inside current itemset, if we have the following rule:
    #  xxx <cursor><nonterminalSymbol> xxx  append every rule from self._productionruleset that begins with that NonTerminalSymbol
    if not isinstance(itemset, LR0ItemSet):
        raise TypeError
    import copy
    resultset = copy.copy(itemset)
    changed = True
    while changed:
        changed = False
        for currentitem in resultset.itemlist:
            nextsymbol = currentitem.next_symbol()
            if nextsymbol is None:
                break
            for rule in productionset.productions:
                newitem = LR0Item(rule)
                if rule.leftside[0] == nextsymbol and newitem not in resultset.itemlist:
                    resultset.append_item(newitem)
                    changed = True
    return resultset

def _build_item_closure(itemset, productionset):
    """Build input itemset closure """
    closure = set()
    for item in itemset:
        closure.update(productionset[item])
    return closure

def hazard_extra_keyword(keyword, feature, parent):
    """Given a keyword, it will return the value of the keyword
    from the hazard layer's extra keywords.

    For instance:
    *   hazard_extra_keyword( 'depth' ) -> will return the value of 'depth'
        in current hazard layer's extra keywords.
    """
    if not feature.extra_keywords:
        return None
    for key, value in feature.extra_keywords.items():
        if key == keyword:
            return value
    return None

def get_device_tree(self):
        """Get a tree of all devices."""
        root = DevNode(None, None, [], None)
        device_nodes = {
            dev.object_path: DevNode(dev, dev.parent_object_path, [],
                                     self._ignore_device(dev))
            for dev in self.udisks
        }
        for node in device_nodes.values():
            device_nodes.get(node.root, root).children.append(node)
        device_nodes['/'] = root
        for node in device_nodes.values():
            node.children.sort(key=DevNode._sort_key)

        # use parent as fallback, update top->down:
        def propagate_ignored(node):
            for child in node.children:
                if child.ignored is None:
                    child.ignored = node.ignored
                propagate_ignored(child)
        propagate_ignored(root)
        return device_nodes

def get_device_tree(self):
        """Get a tree of all devices."""
        return self._device_tree

def _prepare_abi(self, jsonabi):
        """
        Prepare the contract json abi for sighash lookups and fast access

        :param jsonabi: contracts abi in json format
        :return:
        """
        self.signatures = {}
        for element_description in jsonabi:
            abi_e = AbiMethod(element_description)
            if abi_e["type"] == "constructor":
                self.signatures[b"__constructor__"] = abi_e
            elif abi_e["type"] == "fallback":
                abi_e.setdefault("inputs", [])
                self.signatures[b"__fallback__"] = abi_e
            elif abi_e["type"] == "function":
                # function and signature present
                # todo: we could generate the sighash ourselves? requires keccak256
                if abi_e.get("signature"):
                    self.signatures[Utils.str_to_bytes(abi_e["signature"])] = abi_e
            elif abi_e["type"] == "event":
                self.signatures[b"__event__"] = abi_e
            else:
                raise Exception("Invalid abi type: %s - %s - %s" % (abi_e.get("type"),
                                                                    element_description, abi_e))

