def _send_merge_commands(self, config, file_config):
        """
        Netmiko is being used to push set commands.
        """
        if self.loaded is False:
            if self._save_backup() is False:
                raise MergeConfigException('Error while storing backup '
                                           'config.')
        if self.ssh_connection is False:
            self._open_ssh()

        if file_config:
            if isinstance(config, str):
                config = config.splitlines()
        else:
            if isinstance(config, str):
                config = str(config).split()

        self.ssh_device.send_config_set(config)
        self.loaded = True
        self.merge_config = True

def _send_merge_commands(self, config, file_config):
        """
        Netmiko is being used to push set commands.
        """
        # Create a list of commands to send to the device
        commands = []
        for key, value in file_config.items():
            if key in config:
                if config[key] != value:
                    commands.append(f"{key} {value}")

        # Send the commands to the device
        if commands:
            self.device.send_config_set(commands)

def tararchive_opener(path, pattern='', verbose=False):
    """Opener that opens files from tar archive.

    :param str path: Path.
    :param str pattern: Regular expression pattern.
    :return: Filehandle(s).
    """
    import tarfile
    import re
    import os

    if not os.path.exists(path):
        raise IOError('File not found: %s' % path)

    if not os.path.isfile(path):
        raise IOError('Not a file: %s' % path)

    if not pattern:
        pattern = '.*'

    pattern = re.compile(pattern)

    with tarfile.open(path, 'r') as tar:
        for member in tar.getmembers():
            if pattern.match(member.name):
                if verbose:
                    print('Opening %s' % member.name)
                yield tar.extractfile(member)

def is_cache(cache):
    """Returns `True` if ``cache`` is a readable cache file or object

    Parameters
    ----------
    cache : `str`, `file`, `list`
        Object to detect as cache

    Returns
    -------
    iscache : `bool`
        `True` if the input object is a cache, or a file in LAL cache format,
        otherwise `False`
    """
    if isinstance(cache, str):
        return os.path.isfile(cache) and cache.endswith('.cache')
    elif isinstance(cache, list):
        return all(isinstance(c, str) and os.path.isfile(c) and c.endswith('.cache') for c in cache)
    elif isinstance(cache, file):
        return cache.name.endswith('.cache')
    else:
        return False

def genbank_to_gene_coords(infile, genes):
    """Input file in genbank format. genes = list of gene names to find.
    Returns dict of gene name -> {start: x, end: y}, where x and y are
    zero-based. x<y iff gene is on forwards strand"""
    coords = {}

    for seq_record in SeqIO.parse(infile, "genbank"):
        for feature in seq_record.features:
            if feature.type == 'gene':
                gene_name = feature.qualifiers.get('gene', [None])[0]
                if gene_name not in genes:
                    continue

                if feature.location.strand == 1:
                    coords[gene_name] = {'start': int(feature.location.start), 'end': int(feature.location.end) - 1}
                else:
                    coords[gene_name] = {'end': int(feature.location.start), 'start': int(feature.location.end) - 1}

    return coords

def default_redirect(request, fallback_url, **kwargs):
    """
    Evaluates a redirect url by consulting GET, POST and the session.
    """
    redirect_url = request.GET.get('next', '')
    if not redirect_url:
        redirect_url = request.POST.get('next', '')
    if not redirect_url:
        redirect_url = request.session.get('next', '')
    if not redirect_url:
        redirect_url = fallback_url
    return redirect_url

def start(self, nodes=None):
        """Start one or many nodes.

        :param   nodes: Nodes to be started.
        :type    nodes: ``list``
        """
        if not self.is_connected():
            return None

        nodes = nodes or self.nodes
        result = []

        for node in nodes:
            if node.state == 'running':
                logging.warning('Node %s is already "running".', node.name)
                continue
            try:
                status = self.gce.ex_start_node(node)
                if status:
                    result.append(node)
            except InvalidRequestError as err:
                raise ComputeEngineManagerException(err)

        return result

def start(self, nodes=None):
        """Start one or many nodes.

        :param   nodes: Nodes to be started.
        :type    nodes: ``list``
        """
        if nodes is None:
            nodes = self.nodes
        for node in nodes:
            self.start_node(node)

def conditionally_attach_managed_policies(role_name, sr_entry):
  """
  If 'aws_managed_policies' key lists the names of AWS managed policies to bind to the role,
  attach them to the role
  Args:
    role_name: name of the role to attach the policies to
    sr_entry: service registry entry
  """
  service_type = sr_entry['type']
  if not (service_type in SERVICE_TYPE_ROLE and "aws_managed_policies" in sr_entry):
    print_if_verbose("not eligible for policies; service_type: {} is not valid for policies "
                     "or no 'aws_managed_policies' key in service registry for this role".format(service_type))
    return

  for policy_name in sr_entry['aws_managed_policies']:
    print_if_verbose("loading policy: {} for role: {}".format(policy_name, role_name))

    if CONTEXT.commit:
      try:
        CLIENTS["iam"].attach_role_policy(RoleName=role_name, PolicyArn='arn:aws:iam::aws:policy/' + policy_name)
      except:
        fail("Exception putting policy: {} onto role: {}".format(policy_name, role_name), sys.exc_info())

def locateChild(self, context, segments):
        """
        Return a statically defined child or a child defined by a sessionless
        site root plugin or an avatar from guard.
        """
        shortcut = getattr(self, 'child_' + segments[0], None)
        if shortcut:
            res = shortcut(context)
            if res is not None:
                return res, segments[1:]

        req = IRequest(context)
        for plg in self.siteStore.powerupsFor(ISessionlessSiteRootPlugin):
            spr = getattr(plg, 'sessionlessProduceResource', None)
            if spr is not None:
                childAndSegments = spr(req, segments)
            else:
                childAndSegments = plg.resourceFactory(segments)
            if childAndSegments is not None:
                return childAndSegments

        return self.guardedRoot.locateChild(context, segments)

def locateChild(self, context, segments):
        """
        Return a statically defined child or a child defined by a sessionless
        site root plugin or an avatar from guard.
        """
        if segments:
            if segments[0] == 'sessionless':
                if segments[1] == 'site':
                    if segments[2] == 'root':
                        if segments[3] == 'child':
                            return self.sessionlessSiteRootChild
                        else:
                            return self.sessionlessSiteRoot
                else:
                    return self.sessionlessSiteRoot
            elif segments[0] == 'guard':
                if segments[1] == 'avatar':
                    return self.guardAvatar
                else:
                    return self.guard
            else:
                return self.sessionlessSiteRoot
        else:
            return self.sessionlessSiteRoot

def acquire(self):
        """
        Acquires lock for action.

        :return: True and 0.0 if lock successfully acquired or False and number of seconds to wait before the next try
        """
        if self.lock.acquire(blocking=False):
            return True, 0.0
        else:
            return False, self.wait_time

def _valid_headerline(l):
    """return true if the given string is a valid loadfile header"""

    if not l:
        return False
    headers = l.split('\t')
    first_col = headers[0]

    tsplit = first_col.split(':')
    if len(tsplit) != 2:
        return False

    if tsplit[0] in ('entity', 'update'):
        return tsplit[1] in ('participant_id', 'participant_set_id',
                             'sample_id', 'sample_set_id',
                             'pair_id', 'pair_set_id')
    elif tsplit[0] == 'membership':
        if len(headers) < 2:
            return False
        # membership:sample_set_id   sample_id, e.g.
        return tsplit[1].replace('set_', '') == headers[1]
    else:
        return False

def _valid_headerline(l):
    """return true if the given string is a valid loadfile header"""
    return l.startswith('##')

