def _get_starting_paths(self, curdir):
        """
        Get the starting location.

        For case sensitive paths, we have to "glob" for
        it first as Python doesn't like for its users to
        think about case. By scanning for it, we can get
        the actual casing and then compare.
        """
        if self.case_sensitive:
            for path in glob.glob(curdir):
                if path == curdir:
                    return [path]
        else:
            return [curdir]

def get_dataset(self, key, info):
        """Load a dataset."""
        if self._polarization != key.polarization:
            return

        xml_items = info['xml_item']
        xml_tags = info['xml_tag']

        if not isinstance(xml_items, list):
            xml_items = [xml_items]
            xml_tags = [xml_tags]

        for xml_item, xml_tag in zip(xml_items, xml_tags):
            data_items = self.root.findall(".//" + xml_item)
            if not data_items:
                continue
            data, low_res_coords = self.read_xml_array(data_items, xml_tag)

        if key.name.endswith('squared'):
            data **= 2

        data = self.interpolate_xml_array(data, low_res_coords, data.shape)

def get_dataset(self, key, info):
        """Load a dataset."""
        if key not in self.datasets:
            self.datasets[key] = self.load_dataset(key, info)
        return self.datasets[key]

def align(self, alignraster, how=np.mean, cxsize=None, cysize=None):
        """
        geo.align(geo2, how=np.mean)

        Returns both georasters aligned and with the same pixelsize
        """
        return align_georasters(self, alignraster, how=how, cxsize=cxsize, cysize=cysize)

def align(self, alignraster, how=np.mean, cxsize=None, cysize=None):
        """
        geo.align(geo2, how=np.mean)

        Returns both georasters aligned and with the same pixelsize
        """
        if cxsize is None:
            cxsize = self.cxsize
        if cysize is None:
            cysize = self.cysize
        if alignraster.cxsize != cxsize or alignraster.cysize != cysize:
            alignraster = alignraster.align(self, how=how)
        return alignraster

def stash(self, stash_name: str):
        """
        Stashes the current working tree changes

        :param stash_name: name of the stash
        :type stash_name: str
        """
        if self.stashed:
            LOGGER.error('already stashed')
            sys.exit(-1)
        else:
            if not self.index_is_empty():
                LOGGER.error('cannot stash; index is not empty')
                sys.exit(-1)
            if self.untracked_files():
                LOGGER.error('cannot stash; there are untracked files')
                sys.exit(-1)
            if self.changed_files():
                LOGGER.info('stashing changes')
                self.repo.git.stash('push', '-u', '-k', '-m', f'"{stash_name}"')
                self.stashed = True
            else:
                LOGGER.info('no changes to stash')

