def echo(
    message=None, file=None, nl=True, err=False, color=None, carriage_return=False
):
    """
    Patched click echo function.
    """
    message = message or ""
    if carriage_return and nl:
        click_echo(message + "\r\n", file, False, err, color)
    elif carriage_return and not nl:
        click_echo(message + "\r", file, False, err, color)
    else:
        click_echo(message, file, nl, err, color)

def echo(
    message=None, file=None, nl=True, err=False, color=None, carriage_return=False
):
    """
    Patched click echo function.
    """
    if message is None:
        message = ""
    if file is None:
        file = sys.stdout
    if err:
        file = sys.stderr
    if color is not None:
        message = click.style(message, fg=color)
    if nl:
        message += "\n"
    if carriage_return:
        message = message.rstrip("\n")
    file.write(message)
    if nl:
        file.flush()

def _get_key_values(self, name):
        """Return a dict containing key / values items for a given key, used for items like filters, page, etc.

        :param str name: name of the querystring parameter
        :return dict: a dict of key / values items
        """
        results = {}

        for key, value in self.qs.items():
            try:
                if not key.startswith(name):
                    continue

                key_start = key.index('[') + 1
                key_end = key.index(']')
                item_key = key[key_start:key_end]

                if ',' in value:
                    item_value = value.split(',')
                else:
                    item_value = value
                results.update({item_key: item_value})
            except Exception:
                raise BadRequest("Parse error", source={'parameter': key})

        return results

def _get_key_values(self, name):
        """Return a dict containing key / values items for a given key, used for items like filters, page, etc.

        :param str name: name of the querystring parameter
        :return dict: a dict of key / values items
        """
        return {
            key: value
            for key, value in self.request.GET.items()
            if key.startswith(name)
        }

def updateType(self, dataset, dataset_access_type):
        """
        Used to change the status of a dataset type (production/etc.)
        """
        if( dataset == "" ):
            dbsExceptionHandler("dbsException-invalid-input", "DBSDataset/updateType. dataset is required.")

        conn = self.dbi.connection()
        trans = conn.begin()

        try :
            self.updatetype.execute(conn, dataset, dataset_access_type.upper(), trans)
            trans.commit()
            trans = None
        except SQLAlchemyDatabaseError as ex:
            if str(ex).find("ORA-01407") != -1:
                dbsExceptionHandler("dbsException-invalid-input2", "Invalid Input", None, "DBSDataset/updateType. A Valid dataset_access_type is required.")
        finally:
            if trans:
                trans.rollback()
            if conn:
                conn.close()

def updateType(self, dataset, dataset_access_type):
        """
        Used to change the status of a dataset type (production/etc.)
        """
        if dataset_access_type not in self.dataset_access_types:
            raise ValueError("Invalid dataset access type")

        if dataset not in self.datasets:
            raise ValueError("Invalid dataset")

        self.datasets[dataset]["access_type"] = dataset_access_type

