def _process_param_value(self, value):
        """
        Returns a UTF-8 string representation of the parameter value,
        recursing into lists.
        """
        # Extract IDs from objects
        if isinstance(value, TroveboxObject):
            return str(value.id).encode('utf-8')

        # Ensure strings are UTF-8 encoded
        elif isinstance(value, TEXT_TYPE):
            return value.encode("utf-8")

        # Handle lists
        elif isinstance(value, list):
            # Make a copy of the list, to avoid overwriting the original
            new_list = list(value)
            # Process each item in the list
            for i, item in enumerate(new_list):
                new_list[i] = self._process_param_value(item)
            # new_list elements are UTF-8 encoded strings - simply join up
            return b','.join(new_list)

        # Handle booleans
        elif isinstance(value, bool):
            return b"1" if value else b"0"

        # Unknown - just do our best
        else:
            return str(value).encode("utf-8")

def _process_param_value(self, value):
        """
        Returns a UTF-8 string representation of the parameter value,
        recursing into lists.
        """
        if isinstance(value, list):
            return '[' + ', '.join(self._process_param_value(v) for v in value) + ']'
        elif isinstance(value, dict):
            return '{' + ', '.join(
                '%s: %s' % (k, self._process_param_value(v))
                for k, v in value.items()) + '}'
        elif isinstance(value, bool):
            return str(value).lower()
        elif isinstance(value, int):
            return str(value)
        elif isinstance(value, float):
            return str(value)
        elif isinstance(value, str):
            return value
        else:
            raise TypeError('%s is not a valid parameter value' % value)

def next(self):
        """Get next line, adjust for year rollover and hint datetime format."""
        line = self.file.readline()
        if line == '':
            raise StopIteration
        if line.startswith('20'):
            self.year = int(line[:4])
        return line

def retry(*dargs, **dkw):
    """Wrap a function with a new `Retrying` object.

    :param dargs: positional arguments passed to Retrying object
    :param dkw: keyword arguments passed to the Retrying object
    """
    # support both @retry and @retry() as valid syntax
    if len(dargs) == 1 and callable(dargs[0]):
        return retry()(dargs[0])
    else:
        def wrap(f):
            if asyncio and asyncio.iscoroutinefunction(f):
                r = AsyncRetrying(*dargs, **dkw)
            elif tornado and hasattr(tornado.gen, 'is_coroutine_function') \
                    and tornado.gen.is_coroutine_function(f):
                r = TornadoRetrying(*dargs, **dkw)
            else:
                r = Retrying(*dargs, **dkw)

            return r.wraps(f)

        return wrap

def retry(*dargs, **dkw):
    """Wrap a function with a new `Retrying` object.

    :param dargs: positional arguments passed to Retrying object
    :param dkw: keyword arguments passed to the Retrying object
    """
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kw):
            return Retrying(*dargs, **dkw)(f)(*args, **kw)
        return wrapper
    return decorator

def _write_log(self, log_type, log_time, message):
        """ Private method to abstract log writing for different types of logs """
        if log_type == "error":
            self.error_log.write(log_time + " " + message + "\n")
        elif log_type == "warning":
            self.warning_log.write(log_time + " " + message + "\n")
        elif log_type == "info":
            self.info_log.write(log_time + " " + message + "\n")
        elif log_type == "debug":
            self.debug_log.write(log_time + " " + message + "\n")
        else:
            raise ValueError("Invalid log type")

def DrawIconAndLabel(self, dc, node, x, y, w, h, depth):
        """ Draw the icon, if any, and the label, if any, of the node. """
        if w-2 < self._em_size_//2 or h-2 < self._em_size_ //2:
            return
        dc.SetClippingRegion(x+1, y+1, w-2, h-2) # Don't draw outside the box
        try:
            icon = self.adapter.icon(node, node==self.selectedNode)
            if icon and h >= icon.GetHeight() and w >= icon.GetWidth():
                iconWidth = icon.GetWidth() + 2
                dc.DrawIcon(icon, x+2, y+2)
            else:
                iconWidth = 0
            if self.labels and h >= dc.GetTextExtent('ABC')[1]:
                dc.SetTextForeground(self.TextForegroundForNode(node, depth))
                dc.DrawText(self.adapter.label(node), x + iconWidth + 2, y+2)
        finally:
            dc.DestroyClippingRegion()

def DrawIconAndLabel(self, dc, node, x, y, w, h, depth):
        """ Draw the icon, if any, and the label, if any, of the node. """

        # Draw the icon, if any.
        if node.icon:
            dc.DrawBitmap(node.icon, x, y, True)

        # Draw the label, if any.
        if node.label:
            dc.SetFont(self.GetFont())
            dc.SetTextForeground(self.GetForegroundColour())
            dc.DrawText(node.label, x + self.iconWidth, y)

def create_dns(self):
        """Create DNS for the defined app and environment."""
        if self.app.dns_enabled:
            self.app.dns_create()

def _compute(self):
        """
        Compute parameters necessary for later steps
        within the rendering process
        """
        for serie in self.series:
            serie.points, serie.outliers = \
                self._box_points(serie.values, self.box_mode)

        self._x_pos = [(i + .5) / self._order for i in range(self._order)]

        if self._min:
            self._box.ymin = min(self._min, self.zero)
        if self._max:
            self._box.ymax = max(self._max, self.zero)

def _run_check(self, check_method, ds, max_level):
        """
        Runs a check and appends a result to the values list.
        @param bound method check_method: a given check method
        @param netCDF4 dataset ds
        @param int max_level: check level
        @return list: list of Result objects
        """
        val = check_method(ds)
        if isinstance(val, list):
            check_val = []
            for v in val:
                res = fix_return_value(v, check_method.__func__.__name__,
                                       check_method, check_method.__self__)
                if max_level is None or res.weight > max_level:
                    check_val.append(res)

            return check_val
        else:
            check_val = fix_return_value(val, check_method.__func__.__name__,
                                         check_method, check_method.__self__)
            if max_level is None or check_val.weight > max_level:
                return [check_val]
            else:
                return []

def _run_check(self, check_method, ds, max_level):
        """
        Runs a check and appends a result to the values list.
        @param bound method check_method: a given check method
        @param netCDF4 dataset ds
        @param int max_level: check level
        @return list: list of Result objects
        """
        results = []
        for level in range(max_level + 1):
            result = check_method(ds, level)
            if result is not None:
                results.append(result)
        return results

def connect(self):
        """Initializes a connection to the smtp server

        :return: True on success, False otherwise
        """
        try:
            self.smtp = smtplib.SMTP(self.host, self.port)
            self.smtp.ehlo()
            if self.tls:
                self.smtp.starttls()
                self.smtp.ehlo()
            if self.user:
                self.smtp.login(self.user, self.password)
            return True
        except Exception as e:
            self.logger.error(e)
            return False

def save(self, filename=None, clean_data=False, raw=False, trash=False):
        """
        This will save the data to a filename
        :param clean_data: func call that will clean the data before saving it
        :param raw:        obj of the return object from request
        :param trash:      bool if true puts the file in the Trash folder
        :param filename:   str of the file to save to.
        :return:           str of the full path of the file
        """
        full_path = get_filename(filename or self.filename or self.name, trash)
        data = raw and self.raw_data or self.data

        if clean_data:
            data = self.clean_data(data)

        with open(full_path, 'w') as fn:
            if filename.endswith('.json'):
                fn.write(json.dumps(data, indent=2, separators=(',', ': ')))
            else:
                fn.write(str(data))
        self.filename = full_path
        return full_path

def copy(self, repodir):
        """Copies the static files and folders specified in these settings into the
        locally-cloned repository directory.

        :arg repodir: the full path to the directory with the locally-cloned version
          of the pull request being unit tested.
        """
        for static_file in self.static_files:
            shutil.copy(static_file, repodir)
        for static_folder in self.static_folders:
            shutil.copytree(static_folder, os.path.join(repodir, os.path.basename(static_folder)))

def add_hookspecs(self, module_or_class):
        """ add new hook specifications defined in the given module_or_class.
        Functions are recognized if they have been decorated accordingly. """
        names = []
        for name in dir(module_or_class):
            spec_opts = self.parse_hookspec_opts(module_or_class, name)
            if spec_opts is not None:
                hc = getattr(self.hook, name, None)
                if hc is None:
                    hc = _HookCaller(name, self._hookexec, module_or_class, spec_opts)
                    setattr(self.hook, name, hc)
                else:
                    # plugins registered this hook without knowing the spec
                    hc.set_specification(module_or_class, spec_opts)
                    for hookfunction in hc.get_hookimpls():
                        self._verify_hook(hc, hookfunction)
                names.append(name)

        if not names:
            raise ValueError(
                "did not find any %r hooks in %r" % (self.project_name, module_or_class)
            )

def add_hookspecs(self, module_or_class):
        """ add new hook specifications defined in the given module_or_class.
        Functions are recognized if they have been decorated accordingly. """
        for name, obj in inspect.getmembers(module_or_class):
            if isinstance(obj, HookSpec):
                self.add_hookspec(obj)

def update(self, other):
        """
        Update themeables with those from `other`

        This method takes care of inserting the `themeable`
        into the underlying dictionary. Before doing the
        insertion, any existing themeables that will be
        affected by a new from `other` will either be merged
        or removed. This makes sure that a general themeable
        of type :class:`text` can be added to override an
        existing specific one of type :class:`axis_text_x`.
        """
        for key, value in other.items():
            if key in self:
                if isinstance(value, Themeable):
                    if isinstance(self[key], Themeable):
                        self[key].update(value)
                    else:
                        self[key] = value
                elif isinstance(value, dict):
                    if isinstance(self[key], dict):
                        self[key].update(value)
                    else:
                        self[key] = value
                else:
                    self[key] = value
            else:
                self[key] = value

def click_table_printer(headers, _filter, data):
    """Generate space separated output for click commands."""
    if not data:
        return

    if _filter:
        data = [row for row in data if _filter in row]

    if not data:
        return

    if headers:
        click.echo(
            " ".join(
                [
                    click.style(header, fg="green")
                    for header in headers
                ]
            )
        )

    for row in data:
        click.echo(" ".join([str(cell) for cell in row]))

def graph_to_dot(graph, node_renderer=None, edge_renderer=None):
    """Produces a DOT specification string from the provided graph."""
    if node_renderer is None:
        node_renderer = lambda node: node.name
    if edge_renderer is None:
        edge_renderer = lambda edge: edge.name

    dot = 'digraph {\n'
    for node in graph.nodes:
        dot += '  %s;\n' % node_renderer(node)
    for edge in graph.edges:
        dot += '  %s -> %s;\n' % (edge_renderer(edge.from_node), edge_renderer(edge.to_node))
    dot += '}\n'
    return dot

def get_config_data(self, request, obj, name):
        """
