        except AppHookConfig.DoesNotExist:
            return None

def post_chat(self, msg, is_me=False, is_a=False):
        """Posts a msg to this room's chat. Set me=True if you want to /me"""

        if len(msg) > self.config.max_message:
            raise ValueError(
                f"Chat message must be at most {self.config.max_message} characters."
            )
        while not self.user.nick:
            with ARBITRATOR.condition:
                ARBITRATOR.condition.wait()
        if is_a:
            if not self.admin and not self.staff:
                raise RuntimeError("Can't modchat if you're not a mod or trusted")
            self.conn.make_call("command", self.user.nick, "a", msg)
            return
        if is_me:
            self.conn.make_call("command", self.user.nick, "me", msg)
            return

        self.conn.make_call("chat", self.user.nick, msg)

def post_chat(self, msg, is_me=False, is_a=False):
        """Posts a msg to this room's chat. Set me=True if you want to /me"""
        if is_me:
            msg = "/me " + msg
        if is_a:
            msg = "a " + msg
        self.chat.append(msg)

def get_password(config):
    """Returns the password for a remote server

    It tries to fetch the password from the following
    locations in this order:

     1. config file [remote] section, password option
     2. GNOME keyring
     3. interactively, from the user
    """
    if config.has_option('remote', 'password'):
        return config.get('remote', 'password')

    try:
        import keyring
    except ImportError:
        pass
    else:
        try:
            return keyring.get_password('git-remote-helpers', config.get('remote', 'url'))
        except keyring.errors.PasswordDeleteError:
            pass

    try:
        import getpass
    except ImportError:
        pass
    else:
        return getpass.getpass('Password for %s: ' % config.get('remote', 'url'))

    raise RuntimeError('No password found for %s' % config.get('remote', 'url'))

def get_session(self, token_path=None):
        """ Create a requests Session object

        :param Path token_path: (Only oauth) full path to where the token
         should be load from
        :return: A ready to use requests session
        :rtype: OAuth2Session
        """
        if self.auth_type == 'oauth':
            if token_path is None:
                raise ValueError('token_path must be provided for oauth')
            token = self.load_token(token_path)
            return OAuth2Session(
                client_id=self.client_id,
                token=token,
                auto_refresh_url=self.token_url,
                auto_refresh_kwargs={
                    'client_id': self.client_id,
                    'client_secret': self.client_secret
                },
                token_updater=self.save_token,
                auto_refresh_kwargs={
                    'client_id': self.client_id,
                    'client_secret': self.client_secret
                }
            )
        elif self.auth_type == 'basic':
            return requests.Session()
        else:
            raise ValueError('Unknown auth_type: {}'.format(self.auth_type))

def _get_stream_parameters(kind, device, channels, dtype, latency, samplerate):
    """Generate PaStreamParameters struct."""
    if device is None:
        if kind == 'input':
            device = _pa.Pa_GetDefaultInputDevice()
        elif kind == 'output':
            device = _pa.Pa_GetDefaultOutputDevice()

    info = device_info(device)
    if channels is None:
        channels = info['max_' + kind + '_channels']
    dtype = np.dtype(dtype)
    try:
        sample_format = _np2pa[dtype]
    except KeyError:
        raise ValueError("Invalid " + kind + " sample format")
    if samplerate is None:
        samplerate = info['default_samplerate']
    parameters = ffi.new(
        "PaStreamParameters*",
        (device, channels, sample_format, latency, ffi.NULL))
    return parameters, dtype, samplerate

def _get_stream_parameters(kind, device, channels, dtype, latency, samplerate):
    """Generate PaStreamParameters struct."""
    if kind == 'input':
        direction = paInt16
        device = device or pa_get_default_input_device()
    elif kind == 'output':
        direction = paInt16
        device = device or pa_get_default_output_device()
    else:
        raise ValueError('Invalid stream kind: %s' % kind)

    if channels is None:
        channels = 1

    if dtype is None:
        dtype = np.int16

    if latency is None:
        latency = 0.05

    if samplerate is None:
        samplerate = 44100

    stream_parameters = pa.StreamParameters()
    stream_parameters.device = device
    stream_parameters.channelCount = channels
    stream_parameters.sampleFormat = pa.get_sample_format(dtype)
    stream_parameters.suggestedLatency = latency
    stream_parameters.hostApiSpecificStreamInfo = None

    return stream_parameters

