def run(self):
        """Run the process.

        Iterate the GLib main loop and process the task queue.
        """
        loop = GLib.MainLoop()
        context = loop.get_context()
        while True:
            time.sleep(0.1)
            if context.pending():
                context.iteration()
                self._manager[ATTR_POSITION] = self._position()
            try:
                method, args = self._task_queue.get(False)
                getattr(self, method)(**args)
            except queue.Empty:
                pass
            if self.state != STATE_IDLE:
                continue
            try:
                uri = self._media_queue.get(False)
                self.media(uri)
            except queue.Empty:
                pass

def _unify_sources_and_hashes(source=None, source_hash=None,
                              sources=None, source_hashes=None):
    """
    Silly little function to give us a standard tuple list for sources and
    source_hashes
    """
    if sources is None:
        sources = []

    if source_hashes is None:
        source_hashes = []

    if source and sources:
        return (False,
                "source and sources are mutually exclusive", [])

    if source_hash and source_hashes:
        return (False,
                "source_hash and source_hashes are mutually exclusive", [])

    if source:
        return (True, '', [(source, source_hash)])

    # Make a nice neat list of tuples exactly len(sources) long..
    return True, '', list(zip_longest(sources, source_hashes[:len(sources)]))

def _unionload(l: Loader, value, type_) -> Any:
    """
    Loads a value into a union.

    Basically this iterates all the types inside the
    union, until one that doesn't raise an exception
    is found.

    If no suitable type is found, an exception is raised.
    """
    try:
        args = uniontypes(type_)
    except AttributeError:
        raise TypedloadAttributeError('The typing API for this Python version is unknown')

    # Do not convert basic types, if possible
    if type(value) in args.intersection(l.basictypes):
        return value

    exceptions = []

    # Try all types
    for t in args:
        try:
            return l.load(value, t, annotation=Annotation(AnnotationType.UNION, t))
        except Exception as e:
            exceptions.append(e)
    raise TypedloadValueError(
        'Value could not be loaded into %s' % type_,
            value=value,
            type_=type_,
            exceptions=exceptions
    )

def _unionload(l: Loader, value, type_) -> Any:
    """
    Loads a value into a union.

    Basically this iterates all the types inside the
    union, until one that doesn't raise an exception
    is found.

    If no suitable type is found, an exception is raised.
    """
    for t in type_.__args__:
        try:
            return l.load(value, t)
        except Exception:
            pass

    raise ValueError(f"Could not load value {value} into type {type_}")

def walk(self, top, file_list={}):
        """Walks the walk. nah, seriously: reads the file and stores a hashkey
        corresponding to its content."""
        for root, dirs, files in os.walk(top, topdown=False):
            if os.path.basename(root) in self.ignore_dirs:
                # Do not dig in ignored dirs
                continue

            for name in files:
                full_path = os.path.join(root, name)
                if self.include(full_path):
                    if os.path.isfile(full_path):
                        # preventing fail if the file vanishes
                        content = open(full_path).read()
                        hashcode = hashlib.sha224(content).hexdigest()
                        file_list[full_path] = hashcode
            for name in dirs:
                if name not in self.ignore_dirs:
                    self.walk(os.path.join(root, name), file_list)
        return file_list

def walk(self, top, file_list={}):
        """Walks the walk. nah, seriously: reads the file and stores a hashkey
        corresponding to its content."""
        try:
            names = os.listdir(top)
        except os.error:
            return
        for name in names:
            if name in ['.', '..']:
                continue
            fullname = os.path.join(top, name)
            try:
                st = os.lstat(fullname)
            except os.error:
                continue
            if stat.S_ISDIR(st.st_mode):
                self.walk(fullname, file_list)
            else:
                try:
                    f = open(fullname, 'rb')
                except IOError:
                    continue
                try:
                    file_list[hashlib.md5(f.read()).hexdigest()] = fullname
                finally:
                    f.close()

def hydrate_point(srid, *coordinates):
    """ Create a new instance of a Point subclass from a raw
    set of fields. The subclass chosen is determined by the
    given SRID; a ValueError will be raised if no such
    subclass can be found.
    """
    try:
        point_class, dim = __srid_table[srid]
    except KeyError:
        point = Point(coordinates)
        point.srid = srid
        return point
    else:
        if len(coordinates) != dim:
            raise ValueError("SRID %d requires %d coordinates (%d provided)" % (srid, dim, len(coordinates)))
        return point_class(coordinates)

def hydrate_point(srid, *coordinates):
    """ Create a new instance of a Point subclass from a raw
    set of fields. The subclass chosen is determined by the
    given SRID; a ValueError will be raised if no such
    subclass can be found.
    """
    from django.contrib.gis.db.models.fields import GeometryField
    from django.contrib.gis.db.models.fields import PointField
    from django.contrib.gis.db.models.fields import LineStringField
    from django.contrib.gis.db.models.fields import PolygonField
    from django.contrib.gis.db.models.fields import MultiPointField
    from django.contrib.gis.db.models.fields import MultiLineStringField
    from django.contrib.gis.db.models.fields import MultiPolygonField
    from django.contrib.gis.db.models.fields import GeometryCollectionField

    # Get the GeometryField subclass for the given SRID.
    try:
        field_class = GeometryField.get_geometry_field_for_srid(srid)
    except ValueError:
        raise ValueError("No geometry field subclass for SRID %s" % srid)

    # Get the Point subclass for the given GeometryField subclass.
    if field_class is PointField:
        point_class = Point
    elif field_class is LineStringField:
        point_class = Point
    elif field_class is PolygonField:
        point_class = Point
    elif field_class is MultiPointField:
        point_class = Point
    elif field_class is MultiLineStringField:
        point_class = Point
    elif field_class is MultiPolygonField:
        point_class = Point
    elif field_class is GeometryCollectionField:
        point_class = Point
    else:
        raise ValueError("No point subclass for field class %s" % field_class)

    # Create the Point instance.
    return point_class(*coordinates)

def merge(x, y):
    """
    Merge two dictionaries and raise an error for inconsistencies.

    Parameters
    ----------
    x : dict
        dictionary x
    y : dict
        dictionary y

    Returns
    -------
    x : dict
        merged dictionary

    Raises
    ------
    ValueError
        if `x` and `y` are inconsistent
    """
    if x is None:
        return y
    if y is None:
        return x
    if set(x.keys()) != set(y.keys()):
        raise ValueError("Inconsistent dictionaries")
    for key in x.keys():
        if isinstance(x[key], dict):
            x[key] = merge(x[key], y[key])
        elif isinstance(x[key], list):
            if len(x[key]) != len(y[key]):
                raise ValueError("Inconsistent lists")
            for i in range(len(x[key])):
                x[key][i] = merge(x[key][i], y[key][i])
        else:
            if x[key] != y[key]:
                raise ValueError("Inconsistent values")
    return x

def gatherInput(**Config):
  r"""Helps to interactively get user input.
  """
  _type = Config.get('type')

  while True:
    try:
      got = raw_input('%s: ' % getLabel(Config))

    except EOFError:
      got = None

    if not got and 'default' in Config:
      return Config['default']

    try:
      return _type(got) if _type else got

    except ValueError as e:
      err(str(e) or '<invalid value>')

    except TypeError:
      err(str(e) or '<invalid value>')

def gatherInput(**Config):
  r"""Helps to interactively get user input.
  """
  # Get the input from the user
  input = input(Config['prompt'])

  # Check if the input is valid
  if input == Config['valid']:
    return True
  elif input == Config['invalid']:
    return False
  else:
    print("Invalid input. Please try again.")
    return gatherInput(**Config)

def convert_ids_to_object_ids(obj_map):
    """converts string representations of _id back to ObjectId obj"""
    converted_map = {}
    for key, value in obj_map.items():
        if key == '_id':
            # hacky, but using alias sends back the whole ID string, like
            #   assessment.Item%3A5758326b4a40452d6eee1fa1%40ODL.MIT.EDU
            # so we have to preserve it
            try:
                converted_map[key] = ObjectId(value)
            except InvalidId:
                converted_map[key] = value
        elif isinstance(value, dict):
            converted_map[key] = convert_ids_to_object_ids(value)
        elif isinstance(value, list):
            new_list = []
            for internal_item in value:
                if isinstance(internal_item, dict):
                    new_list.append(convert_ids_to_object_ids(internal_item))
                else:
                    new_list.append(internal_item)
            converted_map[key] = new_list
        else:
            converted_map[key] = value
    return converted_map

def convert_ids_to_object_ids(obj_map):
    """converts string representations of _id back to ObjectId obj"""
    for key, value in obj_map.items():
        if key == '_id':
            obj_map[key] = ObjectId(value)
        elif isinstance(value, dict):
            obj_map[key] = convert_ids_to_object_ids(value)
        elif isinstance(value, list):
            for i in range(len(value)):
                if isinstance(value[i], dict):
                    value[i] = convert_ids_to_object_ids(value[i])
    return obj_map

def portable_hash(x):
    """
    This function returns consistent hash code for builtin types, especially
    for None and tuple with None.

    The algorithm is similar to that one used by CPython 2.7

    >>> portable_hash(None)
    0
    >>> portable_hash((None, 1)) & 0xffffffff
    219750521
    """

    if sys.version_info >= (3, 2, 3) and 'PYTHONHASHSEED' not in os.environ:
        raise Exception("Randomness of hash of string should be disabled via PYTHONHASHSEED")

    if x is None:
        return 0
    if isinstance(x, tuple):
        h = 0x345678
        for i in x:
            h ^= portable_hash(i)
            h *= 1000003
            h &= sys.maxsize
        h ^= len(x)
        if h == -1:
            h = -2
        return int(h)
    return hash(x)

def portable_hash(x):
    """
    This function returns consistent hash code for builtin types, especially
    for None and tuple with None.

    The algorithm is similar to that one used by CPython 2.7

    >>> portable_hash(None)
    0
    >>> portable_hash((None, 1)) & 0xffffffff
    219750521
    """
    if x is None:
        return 0
    elif isinstance(x, tuple):
        return hash(tuple(portable_hash(y) for y in x))
    else:
        return hash(x)

def _decode_caveat_v1(key, caveat):
    """Decode a base64 encoded JSON id.

    @param key the nacl private key to decode.
    @param caveat a base64 encoded JSON string.
    """
    caveat = base64.b64decode(caveat)
    return json.loads(caveat)

def execute(db_name):
    """Execute any pending work in the database stored in `db_name`,
    recording the results.

    This looks for any work in `db_name` which has no results, schedules it to
    be executed, and records any results that arrive.
    """
    db = get_db(db_name)
    for work in db.work.find({'result': None}):
        work_id = work['_id']
        try:
            result = work['fn'](*work['args'], **work['kwargs'])
        except Exception as e:
            db.work.update_one({'_id': work_id}, {'$set': {'result': e}})
        else:
            db.work.update_one({'_id': work_id}, {'$set': {'result': result}})

def set_filter(self, props_filter):
        """
        Changes the current filter for the given one

        :param props_filter: The new requirement filter on service properties
        :raise TypeError: Unknown filter type
        """
        if isinstance(props_filter, str):
            self._filter = props_filter
        elif isinstance(props_filter, dict):
            self._filter = props_filter
        elif isinstance(props_filter, list):
            self._filter = props_filter
        else:
            raise TypeError("Unknown filter type")

def read_case(input, format=None):
    """ Returns a case object from the given input file object. The data
    format may be optionally specified.
    """
    # Map of data file types to readers.
    format_map = {"matpower": MATPOWERReader,
        "psse": PSSEReader, "pickle": PickleReader}

    # Read case data.
    if format_map.has_key(format):
        reader_klass = format_map[format]
        reader = reader_klass()
        case = reader.read(input)
    else:
        # Try each of the readers at random.
        for reader_klass in format_map.values():
            reader = reader_klass()
            try:
                case = reader.read(input)
                if case is not None:
                    break
            except:
                pass
        else:
            case = None

    return case

def read_case(input, format=None):
    """ Returns a case object from the given input file object. The data
    format may be optionally specified.
    """
    if format is None:
        format = input.readline().strip()
    if format == 'json':
        return read_json(input)
    elif format == 'yaml':
        return read_yaml(input)
    elif format == 'xml':
        return read_xml(input)
    elif format == 'csv':
        return read_csv(input)
    elif format == 'tsv':
        return read_tsv(input)
    elif format == 'txt':
        return read_txt(input)
    else:
        raise ValueError('Unknown format: %s' % format)

def make_locations(locations=None, verbose=True):
    """
    Creates folders

    :param locations:
        A list of folders to create (can be a dictionary, see note below)
    :param verbose:
        Warn if any folders were created

    .. note::

        * |params_locations_dict|
        * |param_locations_none|
    """
    if locations is None:
        locations = {}
    elif isinstance(locations, dict):
        locations = [locations]

    for location in locations:
        if not os.path.exists(location):
            if verbose:
                print("Creating folder: {}".format(location))
            os.makedirs(location)

