def _wrap_measure(individual_group_measure_process, group_measure, loaded_processes): 
    """
    Creates a function on a state_collection, which creates analysis_collections for each group in the collection.
    """
    def wrapped_measure(state_collection,overriding_parameters=None,loggers=None):
        if loggers == None:
            loggers = funtool.logger.set_default_loggers()
        if loaded_processes != None :
            if group_measure.grouping_selectors != None:
                for grouping_selector_name in group_measure.grouping_selectors:
                    state_collection= funtool.state_collection.add_grouping(state_collection, grouping_selector_name, loaded_processes) 
                    for group in funtool.state_collection.groups_in_grouping(state_collection, grouping_selector_name):
                        analysis_collection = funtool.analysis.AnalysisCollection(None,group,{},{})
                        if group_measure.analysis_selectors != None:
                            for analysis_selector in group_measure.analysis_selectors:
                                analysis_collection = loaded_processes["analysis_selector"][analysis_selector].process_function(analysis_collection,state_collection)
                        if analysis_collection != None:
                            individual_group_measure_process(analysis_collection,state_collection)
        return state_collection
    return wrapped_measure

def _CallFunc(self, t):
        """ Function call.
        """
        self._dispatch(t.node)
        self._write("(")
        comma = False
        for e in t.args:
            if comma: self._write(", ")
            else: comma = True
            self._dispatch(e)
        if t.star_args:
            if comma: self._write(", ")
            else: comma = True
            self._write("*")
            self._dispatch(t.star_args)
        if t.dstar_args:
            if comma: self._write(", ")
            else: comma = True
            self._write("**")
            self._dispatch(t.dstar_args)
        self._write(")")

def _CallFunc(self, t):
        """ Function call.
        """
        return self._Call(t)

def itemChange( self, change, value ):
        """
        Overloads the base QGraphicsItem itemChange method to block user ability
        to move along the y-axis.

        :param      change      <int>
        :param      value       <variant>

        :return     <variant>
        """
        # only operate when it is a visible, geometric change
        if not (self.isVisible() and change == self.ItemPositionChange):
            return super(XGanttViewItem, self).itemChange( change, value )

        if self.isSyncing():
            return super(XGanttViewItem, self).itemChange(change, value)

        scene = self.scene()
        # only operate when we have a scene
        if not scene:
            return super(XNode, self).itemChange( change, value )

        point = value.toPointF()
        point.setY(self.pos().y())

        # create the return value
        new_value = wrapVariant(point)

        # call the base method to operate on the new point
        return super(XGanttViewItem, self).itemChange(change, new_value)

def itemChange( self, change, value ):
        """
        Overloads the base QGraphicsItem itemChange method to block user ability
        to move along the y-axis.

        :param      change      <int>
        :param      value       <variant>

        :return     <variant>
        """

        if change == self.ItemPositionHasChanged:
            if value.y() != 0:
                value.setY( 0 )

        return super( self.__class__, self ).itemChange( change, value )

def get_migrations_to_up(self, migration_id=None):
        """Find migrations to execute."""
        if migration_id is not None:
            migration_id = MigrationFile.validate_id(migration_id)
            if not migration_id:
                return []

        migrations = self.get_unregistered_migrations()
        if not migrations:
            logger.info(self.NO_MIGRATIONS_MSG)
            return []

        if migration_id:
            try:
                last_migration = [m for m in migrations
                                  if m.id == migration_id][0]
            except IndexError:
                logger.error('Migration is not in unregistered list: %s'
                             % migration_id)
                self.show_status()
                return []
        else:
            last_migration = list(migrations)[-1]

        return [m for m in migrations if m.id <= last_migration.id]

def get_migrations_to_up(self, migration_id=None):
        """Find migrations to execute."""
        if migration_id is None:
            migration_id = self.get_current_revision()
        if migration_id is None:
            return []
        migrations = self.get_migrations()
        migrations_to_up = []
        for migration in migrations:
            if migration.id > migration_id:
                migrations_to_up.append(migration)
        return migrations_to_up

