def uniform(start, end=None, periods=None, freq=None, sc=None):
    """
    Instantiates a uniform DateTimeIndex.

    Either end or periods must be specified.

    Parameters
    ----------
        start : string, long (nanos from epoch), or Pandas Timestamp
        end : string, long (nanos from epoch), or Pandas Timestamp
        periods : int
        freq : a frequency object
        sc : SparkContext
    """
    if end is None and periods is None:
        raise ValueError("Must specify either end or periods")
    if end is not None and periods is not None:
        raise ValueError("Can only specify end or periods, not both")

    if freq is None:
        freq = 'D'

    if isinstance(start, (int, long)):
        start = Timestamp(start)

    if isinstance(end, (int, long)):
        end = Timestamp(end)

    if isinstance(start, Timestamp):
        start = start.value

    if isinstance(end, Timestamp):
        end = end.value

    if periods is not None:
        end = start + periods * to_offset(freq).nanos

    if sc is None:
        sc = SparkContext._active_spark_context

    return sc._jvm.PythonUtils.uniform(start, end, freq)

def warn_about_unmanaged_parameters(self):
        """used to raise warning if the user got parameter
        that we do not manage from now

        :return: None
        """
        properties = self.__class__.properties
        unmanaged = []
        for prop, entry in list(properties.items()):
            if not entry.managed and hasattr(self, prop):
                if entry.help:
                    line = "%s: %s" % (prop, entry.help)
                else:
                    line = prop
                unmanaged.append(line)
        if unmanaged:
            logger.warning("The following Nagios legacy parameter(s) are not currently "
                           "managed by Alignak:")

            for line in unmanaged:
                logger.warning('- %s', line)

            logger.warning("Those are unmanaged configuration statements, do you really need it? "
                           "Create an issue on the Alignak repository or submit a pull "
                           "request: http://www.github.com/Alignak-monitoring/alignak")

def component(iface):
    """
    Marks the decorated class as a component implementing the given ``iface``

    :param iface: the interface to implement
    :type iface: :func:`interface`
    """

    def decorator(cls):
        if not cls:
            return None

        # Run custom verificator if any
        if hasattr(cls, '__verify__'):
            if not cls.__verify__():
                return None

        if not hasattr(iface, 'implementations'):
            log.error('%s is not an @interface', iface)

        log.debug(
            'Registering [%s] (implementation of [%s])' % (
                get_fqdn(cls),
                get_fqdn(iface)
            )
        )
        iface.implementations.append(cls)

        def get(cls, context):
            return context.get_component(cls)
        cls.get = get.__get__(cls)

        return cls

    return decorator

def MakeANSIVersion(fn):
    """
    Decorator that generates an ANSI version of a Unicode (wide) only API call.

    @type  fn: callable
    @param fn: Unicode (wide) version of the API function to call.
    """
    @functools.wraps(fn)
    def wrapper(*argv, **argd):
        t_ansi    = GuessStringType.t_ansi
        t_unicode = GuessStringType.t_unicode
        v_types   = [ type(item) for item in argv ]
        v_types.extend( [ type(value) for (key, value) in compat.iteritems(argd) ] )
        if t_ansi in v_types:
            argv = list(argv)
            for index in compat.xrange(len(argv)):
                if v_types[index] == t_ansi:
                    argv[index] = t_unicode(argv[index])
            for key, value in argd.items():
                if type(value) == t_ansi:
                    argd[key] = t_unicode(value)
        return fn(*argv, **argd)
    return wrapper

def MakeANSIVersion(fn):
    """
    Decorator that generates an ANSI version of a Unicode (wide) only API call.

    @type  fn: callable
    @param fn: Unicode (wide) version of the API function to call.
    """
    def ANSIVersion(*args, **kwargs):
        """
        ANSI version of the Unicode (wide) only API call.
        """
        return fn(*args, **kwargs)
    return ANSIVersion

def list_keys(self):
        """
        Return a dict of managed keys and what the key status are
        """
        key_dirs = self._check_minions_directories()

        ret = {}

        for dir_ in key_dirs:
            if dir_ is None:
                continue
            ret[os.path.basename(dir_)] = []
            try:
                for fn_ in salt.utils.data.sorted_ignorecase(os.listdir(dir_)):
                    if not fn_.startswith('.'):
                        if os.path.isfile(os.path.join(dir_, fn_)):
                            ret[os.path.basename(dir_)].append(
                                salt.utils.stringutils.to_unicode(fn_)
                            )
            except (OSError, IOError):
                # key dir kind is not created yet, just skip
                continue
        return ret

def list_keys(self):
        """
        Return a dict of managed keys and what the key status are
        """
        keys = {}
        for key in self.keys:
            keys[key] = self.get_key_status(key)
        return keys

