def _identify_heterogeneity_blocks_seg(in_file, seg_file, params, work_dir, somatic_info):
    """Identify heterogeneity blocks corresponding to segmentation from CNV input file.
    """
    def _segment_by_cns(target_chrom, freqs, coords):
        with open(seg_file) as in_handle:
            reader = csv.reader(in_handle, dialect="excel-tab")
            next(reader)  # header
            for cur_chrom, start, end in (xs[:3] for xs in reader):
                if cur_chrom == target_chrom:
                    block_freqs = []
                    for i, (freq, coord) in enumerate(zip(freqs, coords)):
                        if coord >= int(start) and coord < int(end):
                            block_freqs.append(freq)
                        elif coord >= int(end):
                            break
                    coords = coords[max(0, i - 1):]
                    freqs = freqs[max(0, i - 1):]
                    if len(block_freqs) > params["hetblock"]["min_alleles"]:
                        yield start, end
    return _identify_heterogeneity_blocks_shared(in_file, _segment_by_cns, params, work_dir, somatic_info)

def player_mode_stats(self, player_handle, game_mode=constants.GAME_MODE_WILDCARD, game_region=constants.GAME_REGION_WILDCARD):
        """Returns the stats for a particular mode of play,
        accepts solo, duo and squad.  Will return both regional
        and global stats.  Default gamemode is solo
        by Zac: Add parameter game_region to extract player stats by region directly
        """
        if game_mode == constants.GAME_MODE_SQUAD:
            game_mode = constants.GAME_MODE_SQUAD_FPP
        elif game_mode == constants.GAME_MODE_SOLO:
            game_mode = constants.GAME_MODE_SOLO_FPP
        elif game_mode == constants.GAME_MODE_DUO:
            game_mode = constants.GAME_MODE_DUO_FPP
        elif game_mode == constants.GAME_MODE_WILDCARD:
            game_mode = constants.GAME_MODE_SOLO_FPP
        else:
            raise ValueError("Invalid game mode")

        if game_region == constants.GAME_REGION_WILDCARD:
            game_region = constants.GAME_REGION_GLOBAL

        if game_region == constants.GAME_REGION_GLOBAL:
            url = constants.PLAYER_MODE_STATS_URL.format(player_handle, game_mode)
        elif game_region == constants.GAME_REGION_EUROPE:
            url = constants.PLAYER_MODE_STATS_EUROPE_URL.format(player_handle, game_mode)
        elif game_region == constants.GAME_REGION_ASIA:
            url = constants.PLAYER_MODE_STATS_ASIA_URL.format(player_handle, game_mode)
        elif game_region == constants.GAME_REGION_AMERICAS:
            url = constants.PLAYER_MODE_STATS_AMERICAS_URL.format(player_handle, game_mode)
        else:
            raise ValueError("Invalid game region")

        return self._get_player_stats(url)

def get_reference_repository(self, reference: Optional[Path], repo: str) -> Optional[Path]:
        """
        Returns a repository to use in clone command, if there is one to be referenced.
        Either provided by the user of generated from already cloned branches (master is preferred).

        :param reference: Path to a local repository provided by the user or None.
        :param repo: Reference for which remote repository.
        """
        if reference is not None:
            return reference.absolute()

        repo_path = self.get_path_to_repo(repo)

        if not repo_path.exists():
            return None

        master = repo_path / "master"

        if master.exists() and master.is_dir():
            return master

        for existing_branch in repo_path.iterdir():
            if not existing_branch.is_dir():
                continue

            return existing_branch.resolve()

        return None

def get_reference_repository(self, reference: Optional[Path], repo: str) -> Optional[Path]:
        """
        Returns a repository to use in clone command, if there is one to be referenced.
        Either provided by the user of generated from already cloned branches (master is preferred).

        :param reference: Path to a local repository provided by the user or None.
        :param repo: Reference for which remote repository.
        """
        if reference is not None:
            return reference
        else:
            return self.get_reference_repository_from_branches(repo)

def find_spec(self, fullname, target=None):
        """Try to find a spec for the specified module.  Returns the
        matching spec, or None if not found."""
        is_namespace = False
        tail_module = fullname.rpartition('.')[2]

        base_path = os.path.join(self.path, tail_module)
        for suffix, loader_class in self._loaders:
            init_filename = '__init__' + suffix
            init_full_path = os.path.join(base_path, init_filename)
            full_path = base_path + suffix
            if os.path.isfile(init_full_path):
                return self._get_spec(loader_class, fullname, init_full_path, [base_path], target)
            if os.path.isfile(full_path):  # maybe we need more checks here (importlib filefinder checks its cache...)
                return self._get_spec(loader_class, fullname, full_path, None, target)
        else:
            # If a namespace package, return the path if we don't
            #  find a module in the next section.
            is_namespace = os.path.isdir(base_path)

        if is_namespace:
            _verbose_message('possible namespace for {}'.format(base_path))
            spec = ModuleSpec(fullname, None)
            spec.submodule_search_locations = [base_path]
            return spec
        return None

def find_spec(self, fullname, target=None):
        """Try to find a spec for the specified module.  Returns the
        matching spec, or None if not found."""
        if fullname in self.modules:
            return self.modules[fullname]
        return None

def find_files(dir_or_filelist, pattern='*'):
    """
    If given a path to a directory, finds files recursively,
    e.g. all *.txt files in a given directory (or its subdirectories).
    If given a list of files, yields all of the files that match the given
    pattern.

    adapted from: http://stackoverflow.com/a/2186673
    """
    import os
    import fnmatch

    if isinstance(dir_or_filelist, str):
        directory = dir_or_filelist

        abspath = os.path.abspath(os.path.expanduser(directory))
        for root, dirs, files in os.walk(abspath):
            for basename in files:
                if fnmatch.fnmatch(basename, pattern):
                    filename = os.path.join(root, basename)
                    yield filename
    else:
        filelist = dir_or_filelist
        for filepath in filelist:
            if fnmatch.fnmatch(filepath, pattern):
                yield filepath

def find_files(dir_or_filelist, pattern='*'):
    """
    If given a path to a directory, finds files recursively,
    e.g. all *.txt files in a given directory (or its subdirectories).
    If given a list of files, yields all of the files that match the given
    pattern.

    adapted from: http://stackoverflow.com/a/2186673
    """
    if isinstance(dir_or_filelist, list):
        for f in dir_or_filelist:
            if os.path.isfile(f) and fnmatch.fnmatch(f, pattern):
                yield f
    else:
        for root, dirs, files in os.walk(dir_or_filelist):
            for f in files:
                if fnmatch.fnmatch(f, pattern):
                    yield os.path.join(root, f)

