def apply_reserve_resource_constraint(machine, constraint):
    """Apply the changes implied by a reserve resource constraint to a
    machine model."""
    if constraint.reservation_id is None:
        raise ValueError("Reserve resource constraint must have a reservation ID")
    if constraint.reservation_id not in machine.reservations:
        machine.reservations[constraint.reservation_id] = {}
    if constraint.resource_id not in machine.reservations[constraint.reservation_id]:
        machine.reservations[constraint.reservation_id][constraint.resource_id] = 0
    machine.reservations[constraint.reservation_id][constraint.resource_id] += constraint.amount

async def find(self, *tracking_numbers: str) -> list:
        """Get tracking info for one or more tracking numbers."""
        if not tracking_numbers:
            raise ValueError("No tracking numbers provided.")

        if len(tracking_numbers) > 10:
            raise ValueError("Too many tracking numbers provided.")

        return self._request(
            "POST",
            "track",
            data={"tracking_numbers": tracking_numbers},
        )

def is_valid_type(self, filepath):
        """
        Returns True if the given filepath is a valid watchable filetype.
        The filepath can be assumed to be a file (not a directory).
        """
        if self.in_repo(filepath):
            return False

        validators = self._validators
        if len(validators) == 0:
            validators = [self.default_validator]

        if any([hasattr(v, 'runnable') for v in self._validators]):
            # case where we select the runnable function by the validator
            for validator in validators:
                if validator(filepath):
                    if hasattr(validator, 'runnable'):
                        self._scent.set_runner(validator.runnable)
                        return True
            return False

        for validator in validators:
            if not validator(filepath):
                return False
        return True

def is_valid_type(self, filepath):
        """
        Returns True if the given filepath is a valid watchable filetype.
        The filepath can be assumed to be a file (not a directory).
        """
        return self.is_valid_filetype(filepath) and self.is_valid_extension(filepath)

def from_string(s):
        """Deserializes a token from a string like one returned by
        `to_string()`."""

        if not len(s):
            raise ValueError("Invalid parameter string.")

        params = parse_qs(u(s), keep_blank_values=False)
        if not len(params):
            raise ValueError("Invalid parameter string.")

        try:
            key = params['oauth_token'][0]
        except Exception:
            raise ValueError("'oauth_token' not found in OAuth request.")

        try:
            secret = params['oauth_token_secret'][0]
        except Exception:
            raise ValueError("'oauth_token_secret' not found in " 
                "OAuth request.")

        token = Token(key, secret)
        try:
            token.callback_confirmed = params['oauth_callback_confirmed'][0]
        except KeyError:
            pass  # 1.0, no callback confirmed.
        return token

def from_string(s):
        """Deserializes a token from a string like one returned by
        `to_string()`."""
        return cls(s)

def copy(self, release):
        """Copy the workfile of the given release to the releasefile location

        This is inteded to be used in a action unit.

        :param release: the release with the release and workfile
        :type release: :class:`Release`
        :returns: an action status
        :rtype: :class:`ActionStatus`
        :raises: None
        """
        if not release.workfile:
            return ActionStatus.fail("No workfile found for release %s" % release)

        if not release.releasefile:
            return ActionStatus.fail("No releasefile found for release %s" % release)

        try:
            shutil.copy(release.workfile, release.releasefile)
        except IOError as e:
            return ActionStatus.fail("Could not copy workfile to releasefile: %s" % e)

        return ActionStatus.success("Copied workfile to releasefile")

