def quote_address(address: str) -> str:
    """
    Quote a subset of the email addresses defined by RFC 821.

    Should be able to handle anything email.utils.parseaddr can handle.
    """
    if not address:
        return ""
    if address[0] in ('"', "'"):
        return address
    if "@" not in address:
        return address
    if address[0] == "(" and address[-1] == ")":
        return address
    if address[0] == "<" and address[-1] == ">":
        return address
    if address[0] == "[" and address[-1] == "]":
        return address
    return f'"{address}"'

def save_dataset(self, dataset, filename=None, fill_value=None,
                     overlay=None, decorate=None, compute=True, **kwargs):
        """Saves the ``dataset`` to a given ``filename``.

        This method creates an enhanced image using `get_enhanced_image`. The
        image is then passed to `save_image`. See both of these functions for
        more details on the arguments passed to this method.

        """
        if filename is None:
            filename = self.get_filename(dataset)
        if filename is None:
            raise ValueError("No filename given and no default filename "
                             "available.")
        if decorate is None:
            decorate = self.decorate
        if overlay is None:
            overlay = self.overlay
        if fill_value is None:
            fill_value = self.fill_value
        if compute:
            image = self.get_enhanced_image(dataset, fill_value=fill_value,
                                            overlay=overlay, decorate=decorate,
                                            **kwargs)
        else:
            image = None
        self.save_image(image, filename, **kwargs)

def robust_isinstance(inst, typ) -> bool:
    """
    Similar to isinstance, but if 'typ' is a parametrized generic Type, it is first transformed into its base generic
    class so that the instance check works. It is also robust to Union and Any.

    :param inst:
    :param typ:
    :return:
    """
    if typ is Any:
        return True
    if is_typevar(typ):
        if hasattr(typ, '__constraints__') and typ.__constraints__ is not None:
            typs = get_args(typ, evaluate=True)
            return any(robust_isinstance(inst, t) for t in typs)
        elif hasattr(typ, '__bound__') and typ.__bound__ is not None:
            return robust_isinstance(inst, typ.__bound__)
        else:
            # a raw TypeVar means 'anything'
            return True
    else:
        if is_union_type(typ):
            typs = get_args(typ, evaluate=True)
            return any(robust_isinstance(inst, t) for t in typs)
        else:
            return isinstance(inst, get_base_generic_type(typ))

def robust_isinstance(inst, typ) -> bool:
    """
    Similar to isinstance, but if 'typ' is a parametrized generic Type, it is first transformed into its base generic
    class so that the instance check works. It is also robust to Union and Any.

    :param inst:
    :param typ:
    :return:
    """
    if isinstance(typ, type):
        return isinstance(inst, typ)
    elif isinstance(typ, type(Union)):
        return any(robust_isinstance(inst, t) for t in typ.__args__)
    elif isinstance(typ, type(Any)):
        return True
    else:
        raise NotImplementedError(f"robust_isinstance not implemented for {typ}")

def get_dictkey(In, k, dtype):
    """
        returns list of given key (k)  from input list of dictionaries (In) in data type dtype.  uses command:
        get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats.
    """

    Out = []
    for d in In:
        if dtype == '':
            Out.append(d[k])
        if dtype == 'f':
            if d[k] == "":
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(float(d[k]))
        if dtype == 'int':
            if d[k] == "":
                Out.append(0)
            elif d[k] == None:
                Out.append(0)
            else:
                Out.append(int(d[k]))
    return Out

def get_dictkey(In, k, dtype):
    """
        returns list of given key (k)  from input list of dictionaries (In) in data type dtype.  uses command:
        get_dictkey(In,k,dtype).  If dtype =="", data are strings; if "int", data are integers; if "f", data are floats.
    """
    if dtype == "":
        return [In[i][k] for i in range(len(In))]
    elif dtype == "int":
        return [int(In[i][k]) for i in range(len(In))]
    elif dtype == "f":
        return [float(In[i][k]) for i in range(len(In))]
    else:
        print("ERROR: get_dictkey: dtype must be either \"\", \"int\", or \"f\"")
        return

def update_children_comments(self):
        """
        Banana banana
        """
        if self.comment is None:
            return

        for sym in self.get_children_symbols():
            if isinstance(sym, ParameterSymbol):
                sym.comment = self.comment.params.get(sym.argname)
            elif isinstance(sym, FieldSymbol):
                if not sym.comment or not sym.comment.description:
                    sym.comment = self.comment.params.get(sym.member_name)
            elif isinstance(sym, EnumMemberSymbol):
                if not sym.comment or not sym.comment.description:
                    sym.comment = self.comment.params.get(sym.unique_name)
            elif isinstance(sym, ReturnItemSymbol):
                tag = self.comment.tags.get('returns')
                sym.comment = comment_from_tag(tag)
            elif type(sym) == Symbol:
                sym.comment = self.comment.params.get(sym.display_name)

def update_children_comments(self):
        """
        Banana banana
        """
        for child in self.children:
            child.update_comments()

def cacheOnSameArgs(timeout=None):
    """ Caches the return of the function until the the specified time has
        elapsed or the arguments change.  If timeout is None it will not
        be considered. """
    if isinstance(timeout, int):
        timeout = datetime.timedelta(0, timeout)

    def decorator(f):
        _cache = [None]

        def wrapper(*args, **kwargs):
            if _cache[0] is not None:
                cached_ret, dt, cached_args, cached_kwargs = _cache[0]
                if (timeout is not None and
                        dt + timeout <= datetime.datetime.now()):
                    _cache[0] = None
                if (cached_args, cached_kwargs) != (args, kwargs):
                    _cache[0] = None
            if _cache[0] is None:
                ret = f(*args, **kwargs)
                _cache[0] = (ret, datetime.datetime.now(), args, kwargs)
            return _cache[0][0]
        return wrapper
    return decorator

def cacheOnSameArgs(timeout=None):
    """ Caches the return of the function until the the specified time has
        elapsed or the arguments change.  If timeout is None it will not
        be considered. """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if timeout is None:
                return func(*args, **kwargs)
            else:
                key = (args, tuple(kwargs.items()))
                if key not in wrapper.cache:
                    wrapper.cache[key] = func(*args, **kwargs)
                return wrapper.cache[key]
        wrapper.cache = {}
        return wrapper

def remove(self, fieldspec):
        """
        Removes fields or subfields according to `fieldspec`.

        If a non-control field subfield removal leaves no other subfields,
        delete the field entirely.
        """

        pattern = r'(?P<field>[^.]+)(.(?P<subfield>[^.]+))?'
        match = re.match(pattern, fieldspec)
        if not match:
            return None

        grp = match.groupdict()
        for field in self.get_fields(grp['field']):
            if grp['subfield']:
                updated = []
                for code, value in pairwise(field.subfields):
                    if not code == grp['subfield']:
                        updated += [code, value]
                # if we removed the last subfield entry,
                # remove the whole field, too
                if not updated:
                    self.remove_field(field)
                else:
                    field.subfields = updated
            else:
                # it is a control field
                self.remove_field(field)

def reprsig(fun, name=None, method=False):
    """Format a methods signature for display."""
    args, varargs, keywords, defs, kwargs = [], [], None, [], {}
    argspec = fun
    if callable(fun):
        name = fun.__name__ if name is None else name
        argspec = getargspec(fun)
    try:
        args = argspec[0]
        varargs = argspec[1]
        keywords = argspec[2]
        defs = argspec[3]
    except IndexError:
        pass
    if defs:
        args, kwkeys = args[:-len(defs)], args[-len(defs):]
        kwargs = dict(zip(kwkeys, defs))
    if varargs:
        args.append('*' + varargs)
    if method:
        args.insert(0, 'self')
    return reprcall(name, map(str, args), kwargs, keywords,
                    argfilter=str)

def reprsig(fun, name=None, method=False):
    """Format a methods signature for display."""
    if name is None:
        name = fun.__name__
    argspec = inspect.getargspec(fun)
    if method:
        args = argspec.args[1:]
    else:
        args = argspec.args
    if argspec.varargs is not None:
        args.append('*%s' % argspec.varargs)
    if argspec.keywords is not None:
        args.append('**%s' % argspec.keywords)
    if argspec.defaults:
        args = list(args)
        for i, val in enumerate(argspec.defaults):
            args.insert(len(args) - i, '%s=%r' % (args.pop(), val))
    return '%s(%s)' % (name, ', '.join(args))

def CleanAff4Hunts(self):
    """Cleans up old hunt data from aff4."""
    self.state.Register("hunts_cleaned", 0)
    self.state.Register("hunts_failed", 0)
    self.state.Register("hunts_deleted", 0)
    self.state.Register("hunts_skipped", 0)

    hunts = aff4.FACTORY.ListChildren(self.client_urn, token=self.token)
    for hunt_urn in hunts:
      try:
        hunt = aff4.FACTORY.Open(hunt_urn, mode="rw", token=self.token)
        if hunt.state == "STARTED":
          hunt.Stop()
          self.state.hunts_cleaned += 1
        elif hunt.state == "STOPPED":
          hunt.Delete()
          self.state.hunts_deleted += 1
        else:
          self.state.hunts_skipped += 1
      except IOError:
        self.state.hunts_failed += 1

    self.Log("Cleaned %d hunts, %d failed, %d deleted, %d skipped.",
             self.state.hunts_cleaned, self.state.hunts_failed,
             self.state.hunts_deleted, self.state.hunts_skipped)

def _parse_out_variable(self):
        """Internal method to parse the tc_playbook_out_variable arg.

        **Example Variable Format**::

            #App:1234:status!String,#App:1234:status_code!String
        """
        self._out_variables = {}
        self._out_variables_type = {}
        if self.tcex.default_args.tc_playbook_out_variables:
            variables = self.tcex.default_args.tc_playbook_out_variables.strip()
            for o in variables.split(','):
                # parse the variable to get individual parts
                parsed_key = self.parse_variable(o)
                variable_name = parsed_key['name']
                variable_type = parsed_key['type']
                # store the variables in dict by name (e.g. "status_code")
                self._out_variables[variable_name] = {'variable': o}
                # store the variables in dict by name-type (e.g. "status_code-String")
                vt_key = '{}-{}'.format(variable_name, variable_type)
                self._out_variables_type[vt_key] = {'variable': o}

def _parse_out_variable(self):
        """Internal method to parse the tc_playbook_out_variable arg.

        **Example Variable Format**::

            #App:1234:status!String,#App:1234:status_code!String
        """
        if self.tc_playbook_out_variable:
            self.tc_playbook_out_variable = self.tc_playbook_out_variable.split(',')
            for var in self.tc_playbook_out_variable:
                if not var.startswith('#'):
                    raise ValueError('Invalid tc_playbook_out_variable format.')
                if not var.endswith('!String'):
                    raise ValueError('Invalid tc_playbook_out_variable format.')
                var = var.replace('#', '')
                var = var.replace('!String', '')
                self.tc_playbook_out_variable.append(var)

def fixed(self):
        """ Moved to MODIFIED and not later moved to ASSIGNED """
        decision = False
        for record in self.history:
            # Completely ignore older changes
            if record["when"] < self.options.since.date:
                continue
            # Look for status change to MODIFIED (unless already found)
            if not decision and record["when"] < self.options.until.date:
                for change in record["changes"]:
                    if (change["field_name"] == "status"
                            and change["added"] == "MODIFIED"
                            and change["removed"] != "CLOSED"):
                        decision = True
            # Make sure that the bug has not been later moved to ASSIGNED.
            # (This would mean the issue has not been fixed properly.)
            else:
                for change in record["changes"]:
                    if (change["field_name"] == "status"
                            and change["added"] == "ASSIGNED"):
                        decision = False
        return decision

def fixed(self):
        """ Moved to MODIFIED and not later moved to ASSIGNED """
        return self.status == 'MODIFIED'

def _request(self, msg):
        """_request

        Override method _request in class ncclient.operations.RPC, so it can
        handle raw rpc requests in string format without validating your rpc
        request syntax. When your rpc-reply is received, in most cases, it
        simply returns rpc-reply again in string format, except one scenario:
        If message-id is missing or message-id received does not match that in
        rpc request, ncclient will raise an OperationError.
        """
        if msg.tag == 'rpc':
            if msg.find('{urn:ietf:params:xml:ns:netconf:base:1.0}message-id') is None:
                raise OperationError(msg)
            else:
                msg_id = msg.find('{urn:ietf:params:xml:ns:netconf:base:1.0}message-id').text
                if msg_id != self.message_id:
                    raise OperationError(msg)
        return super(RPC, self)._request(msg)

def load_user_config(vcs):
    """Load the user config

    Args:
        vcs (easyci.vcs.base.Vcs) - the vcs object for the current project

    Returns:
        dict - the config

    Raises:
        ConfigFormatError
        ConfigNotFoundError
    """
    config_path = os.path.join(vcs.path, 'eci.yaml')
    if not os.path.exists(config_path):
        raise ConfigNotFoundError
    with open(config_path, 'r') as f:
        try:
            config = yaml.safe_load(f)
        except yaml.YAMLError:
            raise ConfigFormatError
    if not isinstance(config, dict):
        raise ConfigFormatError
    for k, v in _default_config.iteritems():
        config.setdefault(k, v)
    for k, v in _config_types.iteritems():
        if not isinstance(config[k], v):
            raise ConfigFormatError
    return config

def poi_coords(poi_id, *, raw=False):
    """
    DVB Map Coordinates
    (GET https://www.dvb.de/apps/map/coordinates)

    :param poi_id: Id of poi
    :param raw: Return raw response
    :return: Coordinates of poi
    """
    try:
        r = requests.get(
            url='https://www.dvb.de/apps/map/coordinates',
            params={
                'id': poi_id,
            },
        )
        if r.status_code == 200:
            response = json.loads(r.content.decode('utf-8'))
        else:
            raise requests.HTTPError('HTTP Status: {}'.format(r.status_code))
    except requests.RequestException as e:
        print('Failed to access DVB map coordinates app. Request Exception', e)
        response = None

    if response is None or raw:
        return response

    coords = [int(i) for i in response.split('|')]
    lat, lng = gk4_to_wgs(coords[0], coords[1])
    return {
        'lat': lat,
        'lng': lng
    }

def nsdeclarations(self):
        """
        Get a string representation for all namespace declarations as xmlns=""
        and xmlns:p="".

        @return: A separated list of declarations.
        @rtype: basestring

        """
        s = []
        myns = None, self.expns
        if self.parent is None:
            pns = Namespace.default
        else:
            pns = None, self.parent.expns
        if myns[1] != pns[1]:
            if self.expns is not None:
                s.append(' xmlns="%s"' % (self.expns,))
        for item in self.nsprefixes.items():
            p, u = item
            if self.parent is not None:
                ns = self.parent.resolvePrefix(p)
                if ns[1] == u:
                    continue
            s.append(' xmlns:%s="%s"' % (p, u))
        return "".join(s)

def nsdeclarations(self):
        """
        Get a string representation for all namespace declarations as xmlns=""
        and xmlns:p="".

        @return: A separated list of declarations.
        @rtype: basestring

        """
        return ' '.join(
            'xmlns:%s="%s"' % (prefix, uri)
            for prefix, uri in self.namespaces.items()
        )

def setup(self, board: Union[chess.Board, str]) -> None:
        """
        Sets up a specific starting position. This sets (or resets) the
        ``FEN``, ``SetUp``, and ``Variant`` header tags.
        """
        try:
            fen = board.fen()
        except AttributeError:
            board = chess.Board(board)
            board.chess960 = board.has_chess960_castling_rights()
            fen = board.fen()

        if fen == type(board).starting_fen:
            self.headers.pop("SetUp", None)
            self.headers.pop("FEN", None)
        else:
            self.headers["SetUp"] = "1"
            self.headers["FEN"] = fen

        if type(board).aliases[0] == "Standard" and board.chess960:
            self.headers["Variant"] = "Chess960"
        elif type(board).aliases[0] != "Standard":
            self.headers["Variant"] = type(board).aliases[0]
            self.headers["FEN"] = board.fen()
        else:
            self.headers.pop("Variant", None)

def _check_task_done(self):
        """Check status queue"""
        cnt = 0
        try:
            while True:
                task = self.status_queue.get_nowait()
                # check _on_get_info result here
                if task.get('taskid') == '_on_get_info' and 'project' in task and 'track' in task:
                    if task['project'] not in self.projects:
                        continue
                    project = self.projects[task['project']]
                    project.on_get_info(task['track'].get('save') or {})
                    logger.info(
                        '%s on_get_info %r', task['project'], task['track'].get('save', {})
                    )
                    continue
                elif not self.task_verify(task):
                    continue
                self.on_task_status(task)
                cnt += 1
        except Queue.Empty:
            pass
        return cnt

def _check_task_done(self):
        """Check status queue"""
        if self.task_done:
            raise RuntimeError("Task is already done")

def update_old_names():
    """Fetches the list of old tz names and returns a mapping"""
    import urllib.request
    import json
    import os
