def load_clients(self, path=None, apis=[]):
        """Generate client libraries for the given apis, without starting an
        api server"""
        if not path:
            path = self.path
        if not apis:
            apis = self.apis
        for api in apis:
            self.load_client(api, path)

def smart_unicode(s, encoding='utf-8', strings_only=False, errors='strict'):
    """
    Returns a unicode object representing 's'. Treats bytestrings using the
    'encoding' codec.

    If strings_only is True, don't convert (some) non-string-like objects.
    """
    # Handle the common case first for performance reasons.
    if isinstance(s, unicode):
        return s
    if strings_only and is_protected_type(s):
        return s
    try:
        if not isinstance(s, basestring,):
            if hasattr(s, '__unicode__'):
                s = unicode(s)
            else:
                try:
                    s = unicode(str(s), encoding, errors)
                except UnicodeEncodeError:
                    s = '[Bad Unicode data]'
        else:
            # Note: We use .decode() here, instead of unicode(s, encoding,
            # errors), so that if s is a SafeString, it ends up being a
            # SafeUnicode at the end.
            s = s.decode(encoding, errors)
    except UnicodeDecodeError:
        s = '[Bad Unicode data]'
    return s

def find_versions():
    """Return a list of MWVersion objects representing installed versions"""
    versions = []
    for version_dir in os.listdir(MW_INSTALL_DIR):
        if version_dir.startswith('.'):
            continue
        version_path = os.path.join(MW_INSTALL_DIR, version_dir)
        if not os.path.isdir(version_path):
            continue
        version = MWVersion(version_dir, version_path)
        if version.is_installed():
            versions.append(version)
    return versions

def walk_up(bottom):
    """  mimic os.walk, but walk 'up' instead of down the directory tree
    :param bottom:
    :return:
    """
    import os
    from os import path

    bottom = path.realpath(bottom)

    # get files in current dir
    try:
        names = os.listdir(bottom)
    except Exception as e:
        raise e

    dirs, nondirs = [], []
    for name in names:
        if path.isdir(path.join(bottom, name)):
            dirs.append(name)
        else:
            nondirs.append(name)

    yield bottom, dirs, nondirs

    new_path = path.realpath(path.join(bottom, '..'))

    # see if we are at the top
    if new_path == bottom:
        return

    for x in walk_up(new_path):
        yield x

def check_user(self, todays_facts):
        """check if we need to notify user perhaps"""
        interval = self.conf_notify_interval
        if interval <= 0 or interval >= 121:
            return

        now = dt.datetime.now()
        message = None

        last_activity = todays_facts[-1] if todays_facts else None

        # update duration of current task
        if last_activity and not last_activity['end_time']:
            delta = now - last_activity['start_time']
            duration = delta.seconds /  60

            if duration and duration % interval == 0:
                message = _("Working on %s") % last_activity['name']
                self.notify_user(message)

        elif self.conf_notify_on_idle:
            #if we have no last activity, let's just calculate duration from 00:00
            if (now.minute + now.hour * 60) % interval == 0:
                self.notify_user(_("No activity"))

def check_user(self, todays_facts):
        """check if we need to notify user perhaps"""
        if self.user_id is None:
            return
        if self.user_id not in todays_facts:
            return
        if self.user_id in self.notified_users:
            return
        self.notified_users.append(self.user_id)
        self.send_message(self.user_id, "You've got a fact!")

def find_video_file(rtdc_dataset):
        """Tries to find a video file that belongs to an RTDC dataset

        Returns None if no video file is found.
        """
        for file in rtdc_dataset.files:
            if file.file_type == 'video':
                return file
        return None

def _add_compounds(self, variant_obj, info_dict):
        """Check if there are any compounds and add them to the variant

            The compounds that are added should be sorted on rank score
        """
        compound_list = []
        compound_entry = info_dict.get('Compounds')
        if compound_entry:
            for family_annotation in compound_entry.split(','):
                compounds = family_annotation.split(':')[-1].split('|')
                for compound in compounds:
                    splitted_compound = compound.split('>')

                    compound_score = None
                    if len(splitted_compound) > 1:
                        compound_id = splitted_compound[0]
                        compound_score = int(splitted_compound[-1])

                    compound_list.append(Compound(
                        variant_id=compound_id,
                        combined_score=compound_score
                        )
                    )

        #Sort the compounds based on rank score
        compound_list.sort(key = operator.attrgetter('combined_score'), reverse=True)

        for compound in compound_list:
            variant_obj.add_compound(compound)

def _add_compounds(self, variant_obj, info_dict):
        """Check if there are any compounds and add them to the variant

            The compounds that are added should be sorted on rank score
        """
        if 'compounds' in info_dict:
            for compound in info_dict['compounds']:
                variant_obj.add_compound(compound)

def append(self, data):
        """Append the given `data` to the output.

        :arg data: If a list, it is formatted as a bullet list with each
            entry in the list being a separate bullet.  Otherwise if it is a
            string, the string is added as a paragraph.

        :raises: ValueError if `data` is not a list or a string.

        """
        if isinstance(data, list):
            for item in data:
                self.append(item)
        elif isinstance(data, str):
            self.append_paragraph(data)
        else:
            raise ValueError('data must be a list or a string')

def free(host, port, timeout=float('Inf')):
	"""
	Wait for the specified port to become free (dropping or rejecting
	requests). Return when the port is free or raise a Timeout if timeout has
	elapsed.

	Timeout may be specified in seconds or as a timedelta.
	If timeout is None or ∞, the routine will run indefinitely.

	>>> free('localhost', find_available_local_port())
	"""
	if timeout is None or timeout == float('Inf'):
		timeout = None
	else:
		timeout = float(timeout)

	start = time.time()
	while True:
		try:
			sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
			sock.settimeout(timeout)
			sock.connect((host, port))
			sock.close()
			return
		except socket.error:
			pass
		if timeout is not None:
			if time.time() - start > timeout:
				raise Timeout('Timeout while waiting for port %s:%s to become free' % (host, port))

def _back_compatible_gemini(conf_files, data):
    """Provide old install directory for configuration with GEMINI supplied tidy VCFs.

    Handles new style (bcbio installed) and old style (GEMINI installed)
    configuration and data locations.
    """
    if vcfanno.is_human(data, builds=["37"]):
        for f in conf_files:
            if f and os.path.basename(f) == "gemini.conf" and os.path.exists(f):
                with open(f) as in_handle:
                    for line in in_handle:
                        if line.startswith("file"):
                            fname = line.strip().split("=")[-1].replace('"', '').strip()
                            if fname.find(".tidy.") > 0:
                                return install.get_gemini_dir(data)
    return None

def _back_compatible_gemini(conf_files, data):
    """Provide old install directory for configuration with GEMINI supplied tidy VCFs.

    Handles new style (bcbio installed) and old style (GEMINI installed)
    configuration and data locations.
    """
    if "gemini" in conf_files:
        gemini_dir = os.path.dirname(conf_files["gemini"])
        if "gemini" in data:
            data["gemini"] = os.path.join(gemini_dir, data["gemini"])
        else:
            data["gemini"] = gemini_dir
    return data

def formatted_str(self, format):
        """Return formatted str.

        :param format: one of 'json', 'csv' are supported
        """
        assert(format in ('json', 'csv'))
        ret_str_list = []
        for rec in self._records:
            if format == 'json':
                ret_str_list.append('{')
                for i in xrange(len(rec)):
                    colname, colval = self._rdef[i].name, rec[i]
                    ret_str_list.append('"%s":"%s"' % (colname, str(colval).replace('"', r'\"')))
                    ret_str_list.append(',')
                ret_str_list.pop()  # drop last comma
                ret_str_list.append('}%s' % (os.linesep))
            elif format == 'csv':
                for i in xrange(len(rec)):
                    colval = rec[i]
                    ret_str_list.append('"%s"' % (str(colval).replace('"', r'\"')))
                    ret_str_list.append(',')
                ret_str_list.pop()  # drop last comma
                ret_str_list.append('%s' % (os.linesep))
            else:
                assert(False)
        return ''.join(ret_str_list)

def formatted_str(self, format):
        """Return formatted str.

        :param format: one of 'json', 'csv' are supported
        """
        if format == 'json':
            return json.dumps(self.to_dict(), indent=4)
        elif format == 'csv':
            return self.to_csv()
        else:
            raise ValueError('format must be one of "json", "csv"')

def update_scalar_bar_range(self, clim, name=None):
        """Update the value range of the active or named scalar bar.

        Parameters
        ----------
        2 item list
            The new range of scalar bar. Example: ``[-1, 2]``.

        name : str, optional
            The title of the scalar bar to update
        """
        if isinstance(clim, float) or isinstance(clim, int):
            clim = [-clim, clim]
        if len(clim) != 2:
            raise TypeError('clim argument must be a length 2 iterable of values: (min, max).')
        if name is None:
            if not hasattr(self, 'mapper'):
                raise RuntimeError('This plotter does not have an active mapper.')
            return self.mapper.SetScalarRange(*clim)
        # Use the name to find the desired actor
        def update_mapper(mapper):
            return mapper.SetScalarRange(*clim)
        try:
            for m in self._scalar_bar_mappers[name]:
                update_mapper(m)
        except KeyError:
            raise KeyError('Name ({}) not valid/not found in this plotter.')
        return

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    path_parts = path.split("/")
    try:
        sub_elms = tuple(
            el
            for el in data
            if isinstance(el, (tuple, list)) and el[0] == path_parts[0]
        )
    except IndexError:
        return None
    if len(path_parts) > 1:
        ret = []
        for sub_elm in sub_elms:
            for x in data_find_all(sub_elm, "/".join(path_parts[1:])):
                ret.append(x)
        ret = tuple(ret)
    else:
        ret = sub_elms
    if ret and dyn_cls:
        cls = generate_element_class(ret[0])
        return tuple(cls(data=tuple_) for tuple_ in ret)
    return ret

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    if dyn_cls:
        return data_find_all_dyn_cls(data, path)
    else:
        return data_find_all_static_cls(data, path)

def _match_serializers_by_accept_headers(self, serializers,
                                             default_media_type):
        """Match serializer by `Accept` headers."""
        # Bail out fast if no accept headers were given.
        if len(request.accept_mimetypes) == 0:
            return serializers[default_media_type]

        # Determine best match based on quality.
        best_quality = -1
        best = None
        has_wildcard = False
        for client_accept, quality in request.accept_mimetypes:
            if quality <= best_quality:
                continue
            if client_accept == '*/*':
                has_wildcard = True
            for s in serializers:
                if s in ['*/*', client_accept] and quality > 0:
                    best_quality = quality
                    best = s

        # If no match found, but wildcard exists, them use default media
        # type.
        if best is None and has_wildcard:
            best = default_media_type

        if best is not None:
            return serializers[best]
        return None

def _match_serializers_by_accept_headers(self, serializers,
                                             default_media_type):
        """Match serializer by `Accept` headers."""
        if not serializers:
            return None

        if not self.request.accept_mimetypes:
            return serializers[0]

        for media_type, serializer in serializers:
            if media_type in self.request.accept_mimetypes:
                return serializer

        # If no match was found, return the default serializer
        return serializers[0][1]

def check_online(stream):
    """
    Used to check user's online opponents and show their online/offline status on page on init
    """
    online_opponents = []
    for opponent in stream.opponents:
        if opponent.is_online:
            online_opponents.append(opponent)
