def load_file(path):
    """
    Load file

    :param path: Path to file
    :type path: str | unicode
    :return: Loaded data
    :rtype: None | int | float | str | unicode | list | dict
    :raises IOError: If file not found or error accessing file
    """
    res = {}

    if not path:
        IOError("No path specified to save")

    if not os.path.isfile(path):
        raise IOError("File not found {}".format(path))

    try:
        with io.open(path, "r", encoding="utf-8") as f:
            if path.endswith(".json"):
                res = load_json_file(f)
            elif path.endswith(".yaml") or path.endswith(".yml"):
                res = load_yaml_file(f)
    except IOError:
        raise
    except Exception as e:
        raise IOError(e)
    return res

def find_by(self, column=None, value=None, order_by=None, limit=0):
        """
            Find all items that matches your a column/value.

            :param column: column to search.
            :param value: value to look for in `column`.
            :param limit: How many rows to fetch.
            :param order_by: column on which to order the results. \
            To change the sort, prepend with < or >.

        """
        if column is None:
            raise ValueError("column is required")
        if value is None:
            raise ValueError("value is required")
        if order_by is None:
            order_by = column
        if not isinstance(order_by, str):
            raise ValueError("order_by must be a string")
        if not isinstance(limit, int):
            raise ValueError("limit must be an integer")
        if limit < 0:
            raise ValueError("limit must be greater than 0")

        if order_by.startswith(">"):
            order_by = order_by[1:]
            order = "DESC"
        elif order_by.startswith("<"):
            order_by = order_by[1:]
            order = "ASC"
        else:
            order = "ASC"

        query = "SELECT * FROM %s WHERE %s = ? ORDER BY %s %s LIMIT %s" % (
            self.table_name,
            column,
            order_by,
            order,
            limit,
        )
        return self.execute(query, (value,))

def _reconnect_internal(self):
        """
        Tries to connect to each host in the query plan until one succeeds
        or every attempt fails. If successful, a new Connection will be
        returned.  Otherwise, :exc:`NoHostAvailable` will be raised
        with an "errors" arg that is a dict mapping host addresses
        to the exception that was raised when an attempt was made to open
        a connection to that host.
        """
        errors = {}
        lbp = (
            self._cluster.load_balancing_policy
            if self._cluster._config_mode == _ConfigMode.LEGACY else
            self._cluster._default_load_balancing_policy
        )

        for host in lbp.make_query_plan():
            try:
                return self._try_connect(host)
            except ConnectionException as exc:
                errors[str(host.endpoint)] = exc
                log.warning("[control connection] Error connecting to %s:", host, exc_info=True)
                self._cluster.signal_connection_failure(host, exc, is_host_addition=False)
            except Exception as exc:
                errors[str(host.endpoint)] = exc
                log.warning("[control connection] Error connecting to %s:", host, exc_info=True)
            if self._is_shutdown:
                raise DriverException("[control connection] Reconnection in progress during shutdown")

        raise NoHostAvailable("Unable to connect to any servers", errors)

def _reconnect_internal(self):
        """
        Tries to connect to each host in the query plan until one succeeds
        or every attempt fails. If successful, a new Connection will be
        returned.  Otherwise, :exc:`NoHostAvailable` will be raised
        with an "errors" arg that is a dict mapping host addresses
        to the exception that was raised when an attempt was made to open
        a connection to that host.
        """
        errors = {}
        for host in self.hosts:
            try:
                return self.cluster.connect(self.keyspace, host=host)
            except Exception as exc:
                errors[host] = exc
        raise NoHostAvailable(errors)

def main_with_metrics():
    """
    Runs main() and reports success and failure metrics
    """
    try:
        main()
    except Exception:
        report_metric("bus.lizzy-client.failed", 1)
        raise
    except SystemExit as sys_exit:
        if sys_exit.code == 0:
            report_metric("bus.lizzy-client.success", 1)
        else:
            report_metric("bus.lizzy-client.failed", 1)
        raise
    else:
        report_metric("bus.lizzy-client.success", 1)

