def do_types_conflict(type1: GraphQLOutputType, type2: GraphQLOutputType) -> bool:
    """Check whether two types conflict

    Two types conflict if both types could not apply to a value simultaneously.
    Composite types are ignored as their individual field types will be compared later
    recursively. However List and Non-Null types must match.
    """
    if is_list_type(type1):
        return (
            do_types_conflict(
                cast(GraphQLList, type1).of_type, cast(GraphQLList, type2).of_type
            )
            if is_list_type(type2)
            else True
        )
    if is_list_type(type2):
        return True
    if is_non_null_type(type1):
        return (
            do_types_conflict(
                cast(GraphQLNonNull, type1).of_type, cast(GraphQLNonNull, type2).of_type
            )
            if is_non_null_type(type2)
            else True
        )
    if is_non_null_type(type2):
        return True
    if is_leaf_type(type1) or is_leaf_type(type2):
        return type1 is not type2
    return False

def do_types_conflict(type1: GraphQLOutputType, type2: GraphQLOutputType) -> bool:
    """Check whether two types conflict

    Two types conflict if both types could not apply to a value simultaneously.
    Composite types are ignored as their individual field types will be compared later
    recursively. However List and Non-Null types must match.
    """
    if isinstance(type1, GraphQLList) and isinstance(type2, GraphQLList):
        return do_types_conflict(type1.of_type, type2.of_type)
    if isinstance(type1, GraphQLNonNull) and isinstance(type2, GraphQLNonNull):
        return do_types_conflict(type1.of_type, type2.of_type)
    if isinstance(type1, GraphQLNonNull) or isinstance(type2, GraphQLNonNull):
        return False
    return type1 != type2

def _convert_point(self, metric, ts, point, sd_point):
        """Convert an OC metric point to a SD point."""
        if metric.type == "gauge":
            return self._convert_gauge(metric, ts, point, sd_point)
        elif metric.type == "counter":
            return self._convert_counter(metric, ts, point, sd_point)
        elif metric.type == "histogram":
            return self._convert_histogram(metric, ts, point, sd_point)
        elif metric.type == "summary":
            return self._convert_summary(metric, ts, point, sd_point)
        elif metric.type == "untyped":
            return self._convert_untyped(metric, ts, point, sd_point)
        else:
            raise ValueError("Unknown metric type: %s" % metric.type)

def get_relname_and_parent(self, treepos):
        """Return the (relation name, parent ID) tuple that a node is in.
        Return None if this node is not in a relation.
        """
        if treepos.is_leaf():
            return None, None
        else:
            return self.get_relname_and_parent(treepos.parent())

def get_variant_id(variant_dict=None, variant_line=None):
    """Build a variant id

        The variant id is a string made of CHROM_POS_REF_ALT

        Args:
            variant_dict (dict): A variant dictionary

        Returns:
            variant_id (str)
    """
    if variant_dict is not None:
        return "{0}_{1}_{2}_{3}".format(variant_dict['CHROM'], variant_dict['POS'], variant_dict['REF'], variant_dict['ALT'])
    elif variant_line is not None:
        return "{0}_{1}_{2}_{3}".format(variant_line.split('\t')[0], variant_line.split('\t')[1], variant_line.split('\t')[3], variant_line.split('\t')[4])
    else:
        raise ValueError("Either variant_dict or variant_line must be provided")

def from_api_repr(cls, resource):
        """Factory: construct parameter from JSON resource.

        :type resource: dict
        :param resource: JSON mapping of parameter

        :rtype: :class:`~google.cloud.bigquery.query.StructQueryParameter`
        :returns: instance
        """
        return cls(
            name=resource["name"],
            fields=[
                cls.Field.from_api_repr(field) for field in resource["parameterValue"]["structValues"]
            ],
        )

def get_issuers(self):
        """
        Gets the issuers (from message and from assertion)

        :returns: The issuers
        :rtype: list
        """
        issuers = set()

        message_issuer_nodes = OneLogin_Saml2_XML.query(self.document, '/samlp:Response/saml:Issuer')
        if len(message_issuer_nodes) > 0:
            if len(message_issuer_nodes) == 1:
                issuer_value = OneLogin_Saml2_XML.element_text(message_issuer_nodes[0])
                if issuer_value:
                    issuers.add(issuer_value)
            else:
                raise OneLogin_Saml2_ValidationError(
                    'Issuer of the Response is multiple.',
                    OneLogin_Saml2_ValidationError.ISSUER_MULTIPLE_IN_RESPONSE
                )

        assertion_issuer_nodes = self.__query_assertion('/saml:Issuer')
        if len(assertion_issuer_nodes) == 1:
            issuer_value = OneLogin_Saml2_XML.element_text(assertion_issuer_nodes[0])
            if issuer_value:
                issuers.add(issuer_value)
        else:
            raise OneLogin_Saml2_ValidationError(
                'Issuer of the Assertion not found or multiple.',
                OneLogin_Saml2_ValidationError.ISSUER_NOT_FOUND_IN_ASSERTION
            )

        return list(set(issuers))

def _delete_dead_service_vm_hosting_device(self, context, hosting_device):
        """Deletes a presumably dead <hosting_device> service VM.

        This will indirectly make all of its hosted resources unscheduled.
        """
        LOG.info(_LI("Deleting dead service VM %s"), hosting_device.id)
        try:
            self.plugin.delete_hosting_device(context, hosting_device.id)
        except Exception:
            LOG.exception(_LE("Failed to delete dead service VM %s"),
                          hosting_device.id)

def setup_environment():
    """Ensures that the environmental variable RAFCON_LIB_PATH is existent
    """
    try:
        from gi.repository import GLib
        user_data_folder = GLib.get_user_data_dir()
    except ImportError:
        user_data_folder = join(os.path.expanduser("~"), ".local", "share")
    rafcon_root_path = dirname(realpath(rafcon.__file__))
    user_library_folder = join(user_data_folder, "rafcon", "libraries")

    # The RAFCON_LIB_PATH points to a path with common RAFCON libraries
    # If the env variable is not set, we have to determine it. In the future, this should always be
    # ~/.local/share/rafcon/libraries, but for backward compatibility, also a relative RAFCON path is supported
    if not os.environ.get('RAFCON_LIB_PATH', None):
        if exists(user_library_folder):
            os.environ['RAFCON_LIB_PATH'] = user_library_folder
        else:
            os.environ['RAFCON_LIB_PATH'] = join(dirname(dirname(rafcon_root_path)), 'share', 'libraries')

    # Install dummy _ builtin function in case i18.setup_l10n() is not called
    if sys.version_info >= (3,):
        import builtins as builtins23
    else:
        import __builtin__ as builtins23
    if "_" not in builtins23.__dict__:
        builtins23.__dict__["_"] = lambda s: s

def setup_environment():
    """Ensures that the environmental variable RAFCON_LIB_PATH is existent
    """
    if 'RAFCON_LIB_PATH' not in os.environ:
        os.environ['RAFCON_LIB_PATH'] = os.path.join(os.path.dirname(__file__), 'lib')

def delimiter_groups(line, begin_delim=begin_delim,
                     end_delim=end_delim):
    """Split a line into alternating groups.
       The first group cannot have a line feed inserted,
       the next one can, etc.
    """
    text = []
    line = iter(line)
    while True:
        # First build and yield an unsplittable group
        for item in line:
            text.append(item)
            if item in begin_delim:
                break
        if not text:
            break
        yield text

        # Now build and yield a splittable group
        level = 0
        text = []
        for item in line:
            if item in begin_delim:
                level += 1
            elif item in end_delim:
                level -= 1
                if level < 0:
                    yield text
                    text = [item]
                    break
            text.append(item)
        else:
            assert not text, text
            break

def delimiter_groups(line, begin_delim=begin_delim,
                     end_delim=end_delim):
    """Split a line into alternating groups.
       The first group cannot have a line feed inserted,
       the next one can, etc.
    """
    groups = []
    group = []
    for i, c in enumerate(line):
        if c == begin_delim:
            if group:
                groups.append(group)
                group = []
        elif c == end_delim:
            group.append(c)
            groups.append(group)
            group = []
        else:
            group.append(c)
    if group:
        groups.append(group)
    return groups

def add_host(host):
    """ Put your host information in the prefix object. """
    p = new_prefix()
    p.prefix = str(host['ipaddr'])
    p.type = "host"
    p.description = host['description']
    p.node = host['fqdn']
    p.avps = {}

    # Use remaining data from ipplan to populate comment field.
    if 'additional' in host:
        p.comment = host['additional']

    # Use specific info to create extra attributes.
    if len(host['location']) > 0:
        p.avps['location'] = host['location']

    if len(host['mac']) > 0:
        p.avps['mac'] = host['mac']

    if len(host['phone']) > 0:
        p.avps['phone'] = host['phone']

    if len(host['user']) > 0:
        p.avps['user'] = host['user']

    return p

def add_host(host):
    """ Put your host information in the prefix object. """
    prefix = host.split('.')[0]
    if prefix not in hosts:
        hosts[prefix] = []
    hosts[prefix].append(host)

def message(self, category, subject, msg_file):
        """Send message to all users in `category`."""
        users = getattr(self.sub, category)
        if not users:
            print('There are no {} users on {}.'.format(category, self.sub))
            return

        if msg_file:
            try:
                msg = open(msg_file).read()
            except IOError as error:
                print(str(error))
                return
        else:
            print('Enter message:')
            msg = sys.stdin.read()

        print('You are about to send the following message to the users {}:'
              .format(', '.join([str(x) for x in users])))
        print('---BEGIN MESSAGE---\n{}\n---END MESSAGE---'.format(msg))
        if input('Are you sure? yes/[no]: ').lower() not in ['y', 'yes']:
            print('Message sending aborted.')
            return
        for user in users:
            user.send_message(subject, msg)
            print('Sent to: {}'.format(user))

def message(self, category, subject, msg_file):
        """Send message to all users in `category`."""
        self.send_message(self.users_in_category(category), subject, msg_file)

def order(self, *args):
    """Return a new Query with additional sort order(s) applied."""
    # q.order(Employee.name, -Employee.age)
    if not args:
      return self
    orders = []
    o = self.orders
    if o:
      orders.append(o)
    for arg in args:
      if isinstance(arg, model.Property):
        orders.append(datastore_query.PropertyOrder(arg._name, _ASC))
      elif isinstance(arg, datastore_query.Order):
        orders.append(arg)
      else:
        raise TypeError('order() expects a Property or query Order; '
                        'received %r' % arg)
    if not orders:
      orders = None
    elif len(orders) == 1:
      orders = orders[0]
    else:
      orders = datastore_query.CompositeOrder(orders)
    return self.__class__(kind=self.kind, ancestor=self.ancestor,
                          filters=self.filters, orders=orders,
                          app=self.app, namespace=self.namespace,
                          default_options=self.default_options,
                          projection=self.projection, group_by=self.group_by)

def order(self, *args):
    """Return a new Query with additional sort order(s) applied."""
    return self.clone(order_by=self.order_by + list(args))

def move_entry(self, entry = None, group = None):
        """Move an entry to another group.

        A v1Group group and a v1Entry entry are needed.

        """
        if entry is None:
            raise ValueError("No entry given.")
        if group is None:
            raise ValueError("No group given.")
        if not isinstance(entry, v1Entry):
            raise TypeError("entry is not a v1Entry.")
        if not isinstance(group, v1Group):
            raise TypeError("group is not a v1Group.")
        if entry.group != self:
            raise ValueError("entry is not in this group.")
        if group.vault != self.vault:
            raise ValueError("group is not in the same vault.")
        if group.id == self.id:
            raise ValueError("group is the same as this group.")
        if entry.id in group.entries:
            raise ValueError("entry is already in group.")
        if entry.id in self.entries:
            self.entries.remove(entry.id)
        group.entries.append(entry.id)
        self.vault.db.execute("UPDATE v1_entry SET group_id = ? WHERE id = ?", (group.id, entry.id))
        self.vault.db.commit()

def _pep425_get_abi():
    """
    :return:
        A unicode string of the system abi. Will be something like: "cp27m",
        "cp33m", etc.
    """

    try:
        soabi = sysconfig.get_config_var('SOABI')
        if soabi:
            if soabi.startswith('cpython-'):
                return 'cp%s' % soabi.split('-')[1]
            return soabi.replace('.', '_').replace('-', '_')
    except (IOError, NameError):
        pass

    impl = _pep425_implementation()
    suffix = ''
    if impl == 'cp':
        suffix += 'm'
    if sys.maxunicode == 0x10ffff and sys.version_info < (3, 3):
        suffix += 'u'
    return '%s%s%s' % (impl, ''.join(map(str_cls, _pep425_version())), suffix)

def symlink_list(self, load):
        """
        Return a list of symlinked files and dirs
        """
        if 'env' in load:
            # "env" is not supported; Use "saltenv".
            load.pop('env')

        ret = {}
        if 'saltenv' not in load:
            return {}
        if not isinstance(load['saltenv'], six.string_types):
            load['saltenv'] = six.text_type(load['saltenv'])

        for fsb in self.backends(load.pop('fsbackend', None)):
            symlstr = '{0}.symlink_list'.format(fsb)
            if symlstr in self.servers:
                ret = self.servers[symlstr](load)
        # some *fs do not handle prefix. Ensure it is filtered
        prefix = load.get('prefix', '').strip('/')
        if prefix != '':
            ret = dict([
                (x, y) for x, y in six.iteritems(ret) if x.startswith(prefix)
            ])
        return ret

def traverse(self, fn=None, specs=None, full_breadth=True):
        """
        Traverses any nested DimensionedPlot returning a list
        of all plots that match the specs. The specs should
        be supplied as a list of either Plot types or callables,
        which should return a boolean given the plot class.
        """
        accumulator = []
        matches = specs is None
        if not matches:
            for spec in specs:
                matches = self.matches(spec)
                if matches: break
        if matches:
            accumulator.append(fn(self) if fn else self)

        # Assumes composite objects are iterables
        if hasattr(self, 'subplots') and self.subplots:
            for el in self.subplots.values():
                if el is None:
                    continue
                accumulator += el.traverse(fn, specs, full_breadth)
                if not full_breadth: break
        return accumulator

def traverse(self, fn=None, specs=None, full_breadth=True):
        """
        Traverses any nested DimensionedPlot returning a list
        of all plots that match the specs. The specs should
        be supplied as a list of either Plot types or callables,
        which should return a boolean given the plot class.
        """
        if specs is None:
            specs = []
        if fn is None:
            fn = lambda x: True
        if not isinstance(specs, list):
            specs = [specs]
        if not isinstance(fn, list):
            fn = [fn]
        if not isinstance(full_breadth, list):
            full_breadth = [full_breadth]
        plots = []
        for spec in specs:
            if isinstance(spec, type):
                plots.extend([p for p in self.plots if isinstance(p, spec)])
            elif callable(spec):
                plots.extend([p for p in self.plots if spec(p)])
            else:
                raise ValueError("Specs must be a list of Plot types or callables")
        for plot in plots:
            if fn(plot):
                yield plot
            if isinstance(plot, DimensionedPlot):
                for p in plot.traverse(fn, specs, full_breadth):
                    if fn(p):
                        yield p
        if full_breadth[0]:
            for plot in self.plots:
                if not isinstance(plot, DimensionedPlot):
                    if fn(plot):
                        yield plot

def update(self, result, spec):
        """Replace elements with results of calling callables."""
        if isinstance(spec, dict):
            if spec:
                spec_value = next(iter(spec.values()))
                for key, value in result.items():
                    result[key] = self.update(value, spec_value)
        if isinstance(spec, list):
            if spec:
                for i, value in enumerate(result):
                    result[i] = self.update(value, spec[0])
        if isinstance(spec, tuple):
            return tuple(self.update(value, s)
                         for s, value in zip(spec, result))
        if callable(spec):
            return spec(result)
        return result

def update(self, result, spec):
        """Replace elements with results of calling callables."""
        if isinstance(result, dict):
            for key, value in result.items():
                if key in spec:
                    self.update(value, spec[key])
                else:
                    self[key] = value
        elif isinstance(result, list):
            for i, value in enumerate(result):
                if i < len(spec):
                    self.update(value, spec[i])
                else:
                    self.append(value)
        else:
            self[:] = result

def _apply_concretization_strategies(self, addr, strategies, action):
        """
        Applies concretization strategies on the address until one of them succeeds.
        """
        for strategy in strategies:
            if strategy.apply(addr, action):
                return True
        return False

def serialize_on_parent(
            self,
            parent,  # type: ET.Element
            value,  # type: Any
            state  # type: _ProcessorState
    ):
        # type: (...) -> None
        """Serialize the value and adds it to the parent."""
        if value is None:
            return

        if isinstance(value, str):
            parent.text = value
        elif isinstance(value, bool):
            parent.text = str(value).lower()
        elif isinstance(value, int):
            parent.text = str(value)
        elif isinstance(value, float):
            parent.text = str(value)
        elif isinstance(value, list):
            for item in value:
                self.serialize_on_parent(parent, item, state)
        elif isinstance(value, dict):
            for key, item in value.items():
                self.serialize_on_parent(parent, item, state)
        else:
            raise ValueError(
                "Unsupported type: {0}".format(type(value).__name__)
            )

def is_erroneous(self, field, sources):
