def _add_log2_depth(in_file, out_file, data):
    """Create a CNVkit cnn file with depths
    http://cnvkit.readthedocs.io/en/stable/fileformats.html?highlight=cnn#target-and-antitarget-bin-level-coverages-cnn
    """
    with open(out_file, 'w') as out:
        out.write('target\tantitarget\tlog2_target_depth\tlog2_antitarget_depth\n')
        for i, row in enumerate(data):
            if i == 0:
                continue
            out.write('\t'.join([str(x) for x in row]) + '\n')

def process_data(self, data):
        """Convert an unknown data input into a geojson dictionary."""
        if isinstance(data, dict):
            self.embed = True
            return data
        elif isinstance(data, str):
            if data.lower().startswith(('http:', 'ftp:', 'https:')):
                if not self.embed:
                    self.embed_link = data
                return requests.get(data).json()
            elif data.lstrip()[0] in '[{':  # This is a GeoJSON inline string
                self.embed = True
                return json.loads(data)
            else:  # This is a filename
                if not self.embed:
                    self.embed_link = data
                with open(data) as f:
                    return json.loads(f.read())
        elif hasattr(data, '__geo_interface__'):
            self.embed = True
            if hasattr(data, 'to_crs'):
                data = data.to_crs(epsg='4326')
            return json.loads(json.dumps(data.__geo_interface__))
        else:
            raise ValueError('Cannot render objects with any missing geometries'
                             ': {!r}'.format(data))

def process_data(self, data):
        """Convert an unknown data input into a geojson dictionary."""
        if isinstance(data, dict):
            return data
        elif isinstance(data, str):
            return self.parse_geojson(data)
        elif isinstance(data, bytes):
            return self.parse_geojson(data.decode('utf-8'))
        elif isinstance(data, list):
            return self.parse_geojson(json.dumps(data))
        else:
            raise ValueError('Unknown data type: {}'.format(type(data)))

