def NS(domain, resolve=True, nameserver=None):
    """
    Return a list of IPs of the nameservers for ``domain``

    If ``resolve`` is False, don't resolve names.

    CLI Example:

    .. code-block:: bash

        salt ns1 dig.NS google.com
    """
    dig = ['dig', '+short', six.text_type(domain), 'NS']

    if nameserver is not None:
        dig.append('@{0}'.format(nameserver))

    cmd = __salt__['cmd.run_all'](dig, python_shell=False)
    # In this case, 0 is not the same as False
    if cmd['retcode'] != 0:
        log.warning(
            'dig returned exit code \'%s\'. Returning empty list as fallback.',
            cmd['retcode']
        )
        return []

    if resolve:
        ret = []
        for ns_host in cmd['stdout'].split('\n'):
            for ip_addr in A(ns_host, nameserver):
                ret.append(ip_addr)
        return ret

    return cmd['stdout'].split('\n')

def NS(domain, resolve=True, nameserver=None):
    """
    Return a list of IPs of the nameservers for ``domain``

    If ``resolve`` is False, don't resolve names.

    CLI Example:

    .. code-block:: bash

        salt ns1 dig.NS google.com
    """
    if not nameserver:
        nameserver = __salt__["dns.get_ns"]()
    if not nameserver:
        return []
    if not isinstance(nameserver, list):
        nameserver = [nameserver]
    ret = []
    for ns in nameserver:
        ret.extend(__salt__["dns.query"](domain, "NS", nameserver=ns))
    if not resolve:
        return ret
    return [x.address for x in ret]

def filesystem_from_config_dict(config_fs):
    """ Given a dict containing an entry "module" which contains a FSProvider identifier, parse the configuration and returns a fs_provider.
        Exits if there is an error.
    """
    if "module" not in config_fs:
        print("Key 'module' should be defined for the filesystem provider ('fs' configuration option)", file=sys.stderr)
        exit(1)

    filesystem_providers = get_filesystems_providers()
    if config_fs["module"] not in filesystem_providers:
        print("Unknown filesystem provider "+config_fs["module"], file=sys.stderr)
        exit(1)

    fs_class = filesystem_providers[config_fs["module"]]
    fs_args_needed = fs_class.get_needed_args()

    fs_args = {}
    for arg_name, (arg_type, arg_required, _) in fs_args_needed.items():
        if arg_name in config_fs:
            fs_args[arg_name] = arg_type(config_fs[arg_name])
        elif arg_required:
            print("fs option {} is required".format(arg_name), file=sys.stderr)
            exit(1)

    try:
        return fs_class.init_from_args(**fs_args)
    except:
        print("Unable to load class " + config_fs["module"], file=sys.stderr)
        raise

def resolve(items, run_parallel):
    """Combine aligned and split samples into final set of disambiguated reads.
    """
    if run_parallel:
        return _resolve_parallel(items)
    else:
        return _resolve_serial(items)

def _read_dict(self, f):
        """ Converts h5 groups to dictionaries
        """
        d = {}
        for k, item in f.items():
            if type(item) == h5py._hl.dataset.Dataset:
                v = item.value
                if type(v) == np.string_:
                    v = str(v)
                if type(v) == str and v == "NONE":
                    d[k] = None
                elif type(v) == str and v == "EMPTYARR":
                    d[k] = np.array([])
                elif isinstance(v, bytes):
                    d[k] = v.decode('utf-8')
                else:
                    d[k] = v

            elif k[:5] == "DICT_":
                d[k[5:]] = self._read_dict(item)
            elif k[:5] == "LIST_":
                tmpD = self._read_dict(item)
                d[k[5:]] = [tmpD[str(i)] for i in range(len(tmpD))]
        return d

def _read_dict(self, f):
        """ Converts h5 groups to dictionaries
        """
        d = {}
        for key in f.keys():
            if isinstance(f[key], h5py.Group):
                d[key] = self._read_dict(f[key])
            else:
                d[key] = f[key][()]
        return d

def enqueue(self, item, queue=None):
        """
        Enqueue items.
        If you define "self.filter" (sequence),
        this method put the item to queue after filtering.
        "self.filter" operates as blacklist.

        This method expects that
        "item" argument has dict type "data" attribute.
        """
        if queue is None:
            queue = self.queue
        is_enqueue_item = True

        if self.invalid_key_list is not None:
            for entry in self.invalid_key_list:
                if entry in item.data['key']:
                    is_enqueue_item = False
                    log_message = (
                        '{key} is filtered by "invalid_key_list".'
                        ''.format(key=item.data['key'],
                                  plugin=__name__)
                    )
                    self.logger.debug(log_message)
                    break

        if is_enqueue_item:
            try:
                queue.put(item, block=False)
                return True
            except Full:
                self.logger.error('Blackbird item Queue is Full!!!')
                return False

        else:
            return False

def add(self, variant, arch, image):
        """
        Assign an :class:`.Image` object to variant and arch.

        :param variant: compose variant UID
        :type  variant: str
        :param arch:    compose architecture
        :type  arch:    str
        :param image:   image
        :type  image:   :class:`.Image`
        """

        if arch not in productmd.common.RPM_ARCHES:
            raise ValueError("Arch not found in RPM_ARCHES: %s" % arch)
        if arch in ["src", "nosrc"]:
            raise ValueError("Source arch is not allowed. Map source files under binary arches.")
        if self.header.version_tuple >= (1, 1):
            # disallow adding a different image with same 'unique'
            # attributes. can't do this pre-1.1 as we couldn't truly
            # identify images before subvariant
            for checkvar in self.images:
                for checkarch in self.images[checkvar]:
                    for curimg in self.images[checkvar][checkarch]:
                        if identify_image(curimg) == identify_image(image) and curimg.checksums != image.checksums:
                            raise ValueError("Image {0} shares all UNIQUE_IMAGE_ATTRIBUTES with "
                                             "image {1}! This is forbidden.".format(image, curimg))
        self.images.setdefault(variant, {}).setdefault(arch, set()).add(image)

def __serve_forever(self):
        """Main client loop."""
        # No need to update the server list
        # It's done by the GlancesAutoDiscoverListener class (autodiscover.py)
        # Or define staticaly in the configuration file (module static_list.py)
        # For each server in the list, grab elementary stats (CPU, LOAD, MEM, OS...)
        thread_list = {}
        while self.screen.is_end == False:
            logger.debug("Iter through the following server list: {}".format(self.get_servers_list()))
            for v in self.get_servers_list():
                key = v["key"]
                thread = thread_list.get(key, None)
                if thread is None or thread.is_alive() == False:
                    thread = threading.Thread(target=self.__update_stats, args=[v])
                    thread_list[key] = thread
                    thread.start()

            # Update the screen (list or Glances client)
            if self.screen.active_server is None:
                #  Display the Glances browser
                self.screen.update(self.get_servers_list())
            else:
                # Display the active server
                self.__display_server(self.get_servers_list()[self.screen.active_server])

        # exit key pressed
        for thread in thread_list.values():
            thread.join()

def __serve_forever(self):
        """Main client loop."""
        self.log.info("Starting client loop")
        while True:
            try:
                self.serve_once()
            except Exception:
                self.log.exception("Exception in client loop")

def cmd_devop(self, args):
        """device operations"""
        usage = "Usage: devop <read|write> <spi|i2c> name bus address"
        if len(args) < 5:
