def subset(data, sel0, sel1):
    """Apply selections on first and second axes."""

    # check inputs
    data = np.asarray(data)
    if data.ndim < 2:
        raise ValueError('data must have 2 or more dimensions')
    sel0 = asarray_ndim(sel0, 1, allow_none=True)
    sel1 = asarray_ndim(sel1, 1, allow_none=True)

    # ensure indices
    if sel0 is not None and sel0.dtype.kind == 'b':
        sel0, = np.nonzero(sel0)
    if sel1 is not None and sel1.dtype.kind == 'b':
        sel1, = np.nonzero(sel1)

    # ensure leading dimension indices can be broadcast correctly
    if sel0 is not None and sel1 is not None:
        sel0 = sel0[:, np.newaxis]

    # deal with None arguments
    if sel0 is None:
        sel0 = _total_slice
    if sel1 is None:
        sel1 = _total_slice

    return data[sel0, sel1]

def subset(data, sel0, sel1):
    """Apply selections on first and second axes."""
    return data[sel0, :][:, sel1]

def get_pages(self, include_draft=False):
        """
        Get all custom pages
        (supported formats, excluding other files like '.js', '.css', '.html').

        :param include_draft: return draft page or not
        :return: an iterable of Page objects
        """

        def pages_generator(pages_root_path):
            for file_path in traverse_directory(pages_root_path,
                                                yield_dir=False):
                rel_path = os.path.relpath(file_path, pages_root_path)
                rel_path, ext = os.path.splitext(rel_path)
                if not ext or ext == '.' or get_standard_format_name(
                        ext[1:]) is None:
                    continue  # pragma: no cover

                if rel_path.endswith(os.path.sep + 'index'):
                    rel_path = rel_path[:-len('index')]
                else:
                    rel_path += '.html'
                page = self.get_page(rel_path.replace(os.path.sep, '/'),
                                     include_draft=include_draft)
                if page is not None:
                    yield page

        pages_path = os.path.join(current_app.instance_path, 'pages')
        return list(pages_generator(pages_path))

def lookup_synonyms(self, lems):
        """Requires a list of lemmata, not tokens. Feed tokens through a
        Lemmata object's lookup() and isolate() methods first.
        """
        final_synonyms = []
        if type(lems) == list:
            for lemma in lems:
                if lemma.lower() in self.synonyms.keys():
                    syns = self.synonyms[lemma.lower()]
                    synlist = []
                    for syn in syns:
                        synlist.append((syn, 1/len(syns)))
                    synobj = (lemma, synlist)
                    final_synonyms.append(synobj)
                else:
                    pass
        if type(lems) == str:
            if lems.lower() in self.synonyms.keys():
                syns = self.synonyms[lems.lower()]
                synlist = []
                for syn in syns:
                    synlist.append((syn, 1/len(syns)))
                synobj = (lems, synlist)
                final_synonyms.append(synobj)
            else:
                pass
        return final_synonyms

def _from_python_type(self, obj, field, pytype):
        """Get schema definition from python type."""
        json_schema = {
            'title': field.attribute or field.name,
        }

        for key, val in TYPE_MAP[pytype].items():
            json_schema[key] = val

        if field.dump_only:
            json_schema['readonly'] = True

        if field.default is not missing:
            json_schema['default'] = field.default

        # NOTE: doubled up to maintain backwards compatibility
        metadata = field.metadata.get('metadata', {})
        metadata.update(field.metadata)

        for md_key, md_val in metadata.items():
            if md_key == 'metadata':
                continue
            json_schema[md_key] = md_val

        if isinstance(field, fields.List):
            json_schema['items'] = self._get_schema_for_field(
                obj, field.container
            )
        return json_schema

def _from_python_type(self, obj, field, pytype):
        """Get schema definition from python type."""
        if pytype is str:
            return self._from_string(obj, field)
        elif pytype is int:
            return self._from_integer(obj, field)
        elif pytype is float:
            return self._from_float(obj, field)
        elif pytype is bool:
            return self._from_boolean(obj, field)
        elif pytype is dict:
            return self._from_dict(obj, field)
        elif pytype is list:
            return self._from_list(obj, field)
        elif pytype is datetime.datetime:
            return self._from_datetime(obj, field)
        elif pytype is datetime.date:
            return self._from_date(obj, field)
        elif pytype is datetime.time:
            return self._from_time(obj, field)
        elif pytype is uuid.UUID:
            return self._from_uuid(obj, field)
        elif pytype is decimal.Decimal:
            return self._from_decimal(obj, field)
        elif pytype is bytes:
            return self._from_bytes(obj, field)
        elif pytype is bytearray:
            return self._from_bytearray(obj, field)
        elif pytype is memoryview:
            return self._from_memoryview(obj, field)
        elif pytype is object:
            return self._from_object(obj, field)
        else:
            raise ValueError(
                "Unsupported type: {0}".format(pytype.__name__))

def get_bootdev(self):
        """Get current boot device override information.

        :raises: PyghmiException on error
        :returns: dict
        """
        result = self._do_web_request(self.sysurl)
        overridestate = result.get('Boot', {}).get(
            'BootSourceOverrideEnabled', None)
        if overridestate == 'Disabled':
            return {'bootdev': 'default', 'persistent': True}
        persistent = None
        if overridestate == 'Once':
            persistent = False
        elif overridestate == 'Continuous':
            persistent = True
        else:
            raise exc.PyghmiException('Unrecognized Boot state: '
                                      + repr(overridestate))
        uefimode = result.get('Boot', {}).get('BootSourceOverrideMode', None)
        if uefimode == 'UEFI':
            uefimode = True
        elif uefimode == 'Legacy':
            uefimode = False
        else:
            raise exc.PyghmiException('Unrecognized mode: ' + uefimode)
        bootdev = result.get('Boot', {}).get('BootSourceOverrideTarget', None)
        if bootdev not in boot_devices_read:
            raise exc.PyghmiException('Unrecognized boot target: '
                                      + repr(bootdev))
        bootdev = boot_devices_read[bootdev]
        return {'bootdev': bootdev, 'persistent': persistent,
                'uefimode': uefimode}

def get_bootdev(self):
        """Get current boot device override information.

        :raises: PyghmiException on error
        :returns: dict
        """
        return self._get_bootdev()

def render(self, container, rerender=False):
        """Flow the flowables into the containers that have been added to this
        chain."""
        if rerender:
            container.clear()
            if not self._rerendering:
                # restore saved state on this chain's 1st container on this page
                self._state = copy(self._fresh_page_state)
                self._rerendering = True
        try:
            self.done = False
            self.flowables.flow(container, last_descender=None,
                                state=self._state)
            # all flowables have been rendered
            if container == self.last_container:
                self._init_state()    # reset state for the next rendering loop
            self.done = True
        except PageBreakException as exc:
            self._state = exc.flowable_state
            self._fresh_page_state = copy(self._state)
            raise
        except EndOfContainer as e:
            self._state = e.flowable_state
            if container == self.last_container:
                # save state for when ReflowRequired occurs
                self._fresh_page_state = copy(self._state)
        except ReflowRequired:
            self._rerendering = False
            raise

def render(self, container, rerender=False):
        """Flow the flowables into the containers that have been added to this
        chain."""
        if rerender:
            self.flowed = False
        if not self.flowed:
            self.flow(container)
            self.flowed = True

def show_management_certificate(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Return information about a management_certificate

    CLI Example:

    .. code-block:: bash

        salt-cloud -f get_management_certificate my-azure name=my_management_certificate \\
            thumbalgorithm=sha1 thumbprint=0123456789ABCDEF
    """
    if call != 'function':
        raise SaltCloudSystemExit(
            'The get_management_certificate function must be called with -f or --function.'
        )

    if not conn:
        conn = get_conn()

    if kwargs is None:
        kwargs = {}

    if 'thumbprint' not in kwargs:
        raise SaltCloudSystemExit('A thumbprint must be specified as "thumbprint"')

    data = conn.get_management_certificate(kwargs['thumbprint'])
    return object_to_dict(data)

def show_management_certificate(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Return information about a management_certificate

    CLI Example:

    .. code-block:: bash

        salt-cloud -f get_management_certificate my-azure name=my_management_certificate \\
            thumbalgorithm=sha1 thumbprint=0123456789ABCDEF
    """
    if call != "function":
        raise SaltCloudSystemExit(
            "The get_management_certificate function must be called with -f or --function."
        )

    if not conn:
        conn = get_conn(**kwargs)

    thumbalgorithm = kwargs.get("thumbalgorithm", None)
    thumbprint = kwargs.get("thumbprint", None)
    name = kwargs.get("name", None)

    if not name:
        raise SaltCloudSystemExit("A name must be specified.")

    if not thumbalgorithm:
        raise SaltCloudSystemExit("A thumbalgorithm must be specified.")

    if not thumbprint:
        raise SaltCloudSystemExit("A thumbprint must be specified.")

    try:
        management_certificate = conn.get_management_certificate(
            name, thumbalgorithm, thumbprint
        )
    except WindowsAzureMissingCertError:
        log.error("Management certificate not found.")
        return False

    return management_certificate

def batch_query_state_changes(
            self,
            batch_size: int,
            filters: List[Tuple[str, Any]] = None,
            logical_and: bool = True,
    ) -> Iterator[List[StateChangeRecord]]:
        """Batch query state change records with a given batch size and an optional filter

        This is a generator function returning each batch to the caller to work with.
        """
        if filters is None:
            filters = []

        if logical_and:
            filter_str = ' AND '.join(
                f'{key} = {value}' for key, value in filters
            )
        else:
            filter_str = ' OR '.join(
                f'{key} = {value}' for key, value in filters
            )

        query = f"""
            SELECT *
            FROM state_change_record
            WHERE {filter_str}
            ORDER BY block_number, block_timestamp
            LIMIT {batch_size}
        """

        while True:
            records = self.query(query)
            if not records:
                break
            yield records

async def _service_task(self):  # pragma: no cover
        """Monitor connected clients and clean up those that time out."""
        while True:
            if len(self.sockets) == 0:
                # nothing to do
                await self.sleep(self.ping_timeout)
                continue

            # go through the entire client list in a ping interval cycle
            sleep_interval = self.ping_timeout / len(self.sockets)

            try:
                # iterate over the current clients
                for socket in self.sockets.copy().values():
                    if not socket.closing and not socket.closed:
                        await socket.check_ping_timeout()
                    await self.sleep(sleep_interval)
            except (SystemExit, KeyboardInterrupt, asyncio.CancelledError):
                self.logger.info('service task canceled')
                break
            except:
                if asyncio.get_event_loop().is_closed():
                    self.logger.info('event loop is closed, exiting service '
                                     'task')
                    break

                # an unexpected exception has occurred, log it and continue
                self.logger.exception('service task exception')

def _cmp_by_origin(path1, path2):
    """Select the best path based on origin attribute.

    IGP is preferred over EGP; EGP is preferred over Incomplete.
    If both paths have same origin, we return None.
    """
    def get_origin_pref(origin):
        if origin.value == BGP_ATTR_ORIGIN_IGP:
            return 3
        elif origin.value == BGP_ATTR_ORIGIN_EGP:
            return 2
        elif origin.value == BGP_ATTR_ORIGIN_INCOMPLETE:
            return 1
        else:
            LOG.error('Invalid origin value encountered %s.', origin)
            return 0

    origin1 = path1.get_pattr(BGP_ATTR_TYPE_ORIGIN)
    origin2 = path2.get_pattr(BGP_ATTR_TYPE_ORIGIN)
    assert origin1 is not None and origin2 is not None

    # If both paths have same origins
    if origin1.value == origin2.value:
        return None

    # Translate origin values to preference.
    origin1 = get_origin_pref(origin1)
    origin2 = get_origin_pref(origin2)
    # Return preferred path.
    if origin1 == origin2:
        return None
    elif origin1 > origin2:
        return path1
    return path2

def _cmp_by_origin(path1, path2):
    """Select the best path based on origin attribute.

    IGP is preferred over EGP; EGP is preferred over Incomplete.
    If both paths have same origin, we return None.
    """
    if path1.origin == path2.origin:
        return None
    elif path1.origin == 'IGP':
        return path1
    elif path2.origin == 'IGP':
        return path2
    elif path1.origin == 'EGP':
        return path1
    elif path2.origin == 'EGP':
        return path2
    elif path1.origin == 'Incomplete':
        return path1
    elif path2.origin == 'Incomplete':
        return path2

def upload_current_script():
    """upload current python script to EV3"""
    current_editor = get_workbench().get_editor_notebook().get_current_editor()
    code = current_editor.get_text_widget().get("1.0", "end")
    try:
        filename= current_editor.get_filename()
        if (not filename) or (not filename.endswith(".py")):
            return

        ast.parse(code)

        if not code.startswith('#!'):
            if tkMessageBox.askokcancel("Shebang", "To make a python file on the EV3 executable Thonny prepends the shebang line:\n\n      !#/usr/bin/env python3\n"):
                current_editor.get_text_widget().direct_insert("1.0", "#!/usr/bin/env python3\n")
            else:
               return

        # automatically save file (without confirm dialog, nor dialog for asking filename )
        # save_file does return None, if script is not saved and user closed file saving window, otherwise return file name.
        py_file = current_editor.save_file(False)
        if py_file is None:
            return

        upload(py_file)
    except Exception:
        error_msg = traceback.format_exc(0)+'\n'
        showerror("Error", error_msg)

def copyFuncVersionedLib(dest, source, env):
    """Install a versioned library into a destination by copying,
    (including copying permission/mode bits) and then creating
    required symlinks."""
    if not os.path.exists(dest):
        os.makedirs(dest)
    for root, dirs, files in os.walk(source):
        for d in dirs:
            os.mkdir(os.path.join(dest, root, d))
        for f in files:
            shutil.copy2(os.path.join(root, f), os.path.join(dest, root, f))
    for root, dirs, files in os.walk(source):
        for d in dirs:
            os.symlink(os.path.join(root, d), os.path.join(dest, root, d))
    for root, dirs, files in os.walk(source):
        for f in files:
            os.symlink(os.path.join(root, f), os.path.join(dest, root, f))

def is_used(self, regs, i, top=None):
        """ Checks whether any of the given regs are required from the given point
        to the end or not.
        """
        if i < 0:
            i = 0

        if self.lock:
            return True

        regs = list(regs)  # make a copy
        if top is None:
            top = len(self)
        else:
            top -= 1

        for ii in range(i, top):
            for r in self.mem[ii].requires:
                if r in regs:
                    return True

            for r in self.mem[ii].destroys:
                if r in regs:
                    regs.remove(r)

            if not regs:
                return False

        self.lock = True
        result = self.goes_requires(regs)
        self.lock = False

        return result

def is_used(self, regs, i, top=None):
        """ Checks whether any of the given regs are required from the given point
        to the end or not.
        """
        if top is None:
            top = self.top
        for i in range(i, top):
            if self.is_used_at(regs, i):
                return True
        return False

def set_margins(self, top=None, bottom=None):
        """Select top and bottom margins for the scrolling region.

        :param int top: the smallest line number that is scrolled.
        :param int bottom: the biggest line number that is scrolled.
        """
        if top is not None:
            self.top = top
        if bottom is not None:
            self.bottom = bottom

