def top_submissions(self):
        """Return a markdown representation of the top submissions."""
        num = min(10, len(self.submissions))
        if num <= 0:
            return ''

        top_submissions = sorted(
            [x for x in self.submissions.values() if self.distinguished or
             x.distinguished is None],
            key=lambda x: (-x.score, -x.num_comments, x.title))[:num]

        if not top_submissions:
            return ''

        retval = self.post_header.format('Top Submissions')
        for sub in top_submissions:
            title = self._safe_title(sub)
            if sub.permalink in sub.url:
                retval += tt('1. {}').format(title)
            else:
                retval += tt('1. [{}]({})').format(title, sub.url)

            retval += ' by {} ({}, [{} comment{}]({}))\n'.format(
                self._user(sub.author), self._points(sub.score),
                sub.num_comments, 's' if sub.num_comments != 1 else '',
                self._permalink(sub))
        return tt('{}\n').format(retval)

def top_submissions(self):
        """Return a markdown representation of the top submissions."""
        return self._top_submissions()

def v_type_base(ctx, stmt, no_error_report=False):
    """verify that the referenced identity exists."""
    # Find the identity
    name = stmt.arg
    stmt.i_identity = None
    if name.find(":") == -1:
        prefix = None
    else:
        [prefix, name] = name.split(':', 1)
    if prefix is None or stmt.i_module.i_prefix == prefix:
        # check local identities
        pmodule = stmt.i_module
    else:
        # this is a prefixed name, check the imported modules
        pmodule = prefix_to_module(stmt.i_module, prefix, stmt.pos, ctx.errors)
        if pmodule is None:
            return
    if name in pmodule.i_identities:
        i = pmodule.i_identities[name]
        if prefix is None and not is_submodule_included(stmt, i):
            pass
        else:
            stmt.i_identity = i
            v_type_identity(ctx, stmt.i_identity)
    if stmt.i_identity is None and no_error_report == False:
        err_add(ctx.errors, stmt.pos,
                'IDENTITY_NOT_FOUND', (name, pmodule.arg))

def v_type_base(ctx, stmt, no_error_report=False):
    """verify that the referenced identity exists."""
    if stmt.identity.name not in ctx.identities:
        if not no_error_report:
            ctx.error(stmt, "identity '{}' not found".format(stmt.identity.name))
        return False
    return True

def alter(self, interfaces):
        """
        Used to provide the ability to alter the interfaces dictionary before
        it is returned from self.parse().

        Required Arguments:

            interfaces
                The interfaces dictionary.

        Returns: interfaces dict

        """
        # fixup some things
        for device, device_dict in interfaces.items():
            if len(device_dict['inet4']) > 0:
                device_dict['inet'] = device_dict['inet4'][0]
            if 'inet' in device_dict and not device_dict['inet'] is None:
                try:
                    host = socket.gethostbyaddr(device_dict['inet'])[0]
                    interfaces[device]['hostname'] = host
                except (socket.herror, socket.gaierror):
                    interfaces[device]['hostname'] = None

            # To be sure that hex values and similar are always consistent, we
            # return everything in lowercase. For instance, Windows writes
            # MACs in upper-case.
            for key, device_item in device_dict.items():
                if hasattr(device_item, 'lower'):
                    interfaces[device][key] = device_dict[key].lower()

        return interfaces

def remove_dependency(self, p_from_todo, p_to_todo, p_leave_tags=False):
        """ Removes a dependency between two todos. """
        dep_id = p_from_todo.tag_value('id')

        if dep_id:
            self._depgraph.remove_edge(hash(p_from_todo), hash(p_to_todo))
            self.dirty = True

        # clean dangling dependency tags
        if dep_id and not p_leave_tags:
            p_to_todo.remove_tag('p', dep_id)

            if not self.children(p_from_todo, True):
                p_from_todo.remove_tag('id')
                del self._parentdict[dep_id]

def remove_dependency(self, p_from_todo, p_to_todo, p_leave_tags=False):
        """ Removes a dependency between two todos. """
        if p_from_todo.id == p_to_todo.id:
            return
        if p_from_todo.id not in self.dependencies:
            return
        if p_to_todo.id not in self.dependencies[p_from_todo.id]:
            return
        if p_leave_tags:
            self.dependencies[p_from_todo.id].remove(p_to_todo.id)
        else:
            self.dependencies[p_from_todo.id].remove(p_to_todo.id)
        if not self.dependencies[p_from_todo.id]:
            del self.dependencies[p_from_todo.id]
        if not self.dependencies:
            del self.dependencies

def _list_records_in_zone(self, zone, rdtype=None, name=None, content=None):
        """
        Iterates over all records of the zone and returns a list of records filtered
        by record type, name and content. The list is empty if no records found.
        """
        records = []
        for record in self.list_records(zone):
            if rdtype and record.type != rdtype:
                continue
            if name and record.name != name:
                continue
            if content and record.content != content:
                continue
            records.append(record)
        return records

def _normalize_sort_SQL(self, field_name, field_vals, sort_dir_str):
        """
        allow sorting by a set of values

        http://stackoverflow.com/questions/3303851/sqlite-and-custom-order-by
        """
        if sort_dir_str == 'desc':
            sort_dir_str = 'desc'
        else:
            sort_dir_str = 'asc'

        if field_name == 'id':
            field_name = 'id'
        else:
            field_name = 'name'

        if field_vals == 'all':
            field_vals = 'all'
        else:
            field_vals = '(' + ','.join(field_vals) + ')'

        return ' '.join([field_name, field_vals, sort_dir_str])

def _check_for_default_values(fname, arg_val_dict, compat_args):
    """
    Check that the keys in `arg_val_dict` are mapped to their
    default values as specified in `compat_args`.

    Note that this function is to be called only when it has been
    checked that arg_val_dict.keys() is a subset of compat_args

    """
    for arg in compat_args:
        if arg in arg_val_dict:
            if arg_val_dict[arg] == compat_args[arg]['default']:
                continue
            else:
                raise ValueError(
                    "The value of argument '%s' in function '%s' is not "
                    "compatible with the default value '%s'." %
                    (arg, fname, compat_args[arg]['default']))

def start(name, call=None):
    """
    Start a node.

    CLI Example:

    .. code-block:: bash

        salt-cloud -a start mymachine
    """
    if call != 'action':
        raise SaltCloudSystemExit(
            'The show_instance action must be called with -a or --action.'
        )

    data = query(action='ve', command='{0}/start'.format(name), method='PUT')

    if 'error' in data:
        return data['error']

    return {'Started': '{0} was started.'.format(name)}

def start(name, call=None):
    """
    Start a node.

    CLI Example:

    .. code-block:: bash

        salt-cloud -a start mymachine
    """
    if call != "action":
        raise SaltCloudSystemExit(
            "The start action must be called with -a or --action."
        )

    node = _get_node(name)
    if node is None:
        raise SaltCloudSystemExit("No node found with the name {}".format(name))

    if node["state"] == "running":
        log.info("Node %s is already running", name)
        return {"node": name, "action": "start", "result": True, "comment": ""}

    if node["state"] == "stopped":
        log.info("Starting node %s", name)
        try:
            node.start()
        except SaltCloudSystemExit as exc:
            return {"node": name, "action": "start", "result": False, "comment": str(exc)}
        return {"node": name, "action": "start", "result": True, "comment": ""}

    log.info("Node %s is not running or stopped", name)
    return {"node": name, "action": "start", "result": False, "comment": ""}

def _configure_context(ctx, opts, skip=()):
        """
        Configures context of public key operations
        @param ctx - context to configure
        @param opts - dictionary of options (from kwargs of calling
            function)
        @param skip - list of options which shouldn't be passed to
            context
        """

        for oper in opts:
            if oper in skip:
                continue
            if isinstance(oper,chartype):
                op = oper.encode("ascii")
            else:
                op = oper
            if isinstance(opts[oper],chartype):
                value = opts[oper].encode("ascii")
            elif isinstance(opts[oper],bintype):
                value = opts[oper]
            else:
                if pyver == 2:
                    value = str(opts[oper])
                else:
                    value = str(opts[oper]).encode('ascii')
            ret = libcrypto.EVP_PKEY_CTX_ctrl_str(ctx, op, value)
            if ret == -2:
                raise PKeyError("Parameter %s is not supported by key" % oper)
            if ret < 1:
                raise PKeyError("Error setting parameter %s" % oper)

def _configure_context(ctx, opts, skip=()):
        """
        Configures context of public key operations
        @param ctx - context to configure
        @param opts - dictionary of options (from kwargs of calling
            function)
        @param skip - list of options which shouldn't be passed to
            context
        """
        for k, v in opts.items():
            if k not in skip:
                ctx.set_option(k, v)

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    status = {'type': []}
    if os.path.ismount(full_path):
        status['type'] += ['mount-point']
    elif os.path.islink(full_path):
        status['type'] += ['symlink']
    if os.path.isfile(full_path):
        status['type'] += ['file']
    elif os.path.isdir(full_path):
        status['type'] += ['dir']
    if not status['type']:
        if os.stat.S_ISSOCK(status['mode']):
            status['type'] += ['socket']
        elif os.stat.S_ISCHR(status['mode']):
            status['type'] += ['special']
        elif os.stat.S_ISBLK(status['mode']):
            status['type'] += ['block-device']
        elif os.stat.S_ISFIFO(status['mode']):
            status['type'] += ['pipe']
    if not status['type']:
        status['type'] += ['unknown']
    elif status['type'] and status['type'][-1] == 'symlink':
        status['type'] += ['broken']
    return status['type']

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    if os.path.isdir(full_path):
        return 'dir'
    elif os.path.isfile(full_path):
        return 'file'
    elif os.path.islink(full_path):
        return 'symlink'
    elif os.path.ismount(full_path):
        return 'mount'
    elif os.path.issocket(full_path):
        return 'socket'
    elif os.path.isblockdev(full_path):
        return 'blockdev'
    elif os.path.ischardev(full_path):
        return 'chardev'
    else:
        return 'unknown'

def _discretize_check(self, table, att, col):
        """
        Replaces the value with an appropriate interval symbol, if available.
        """
        label = "'%s'" % col
        if table in self.discr_intervals and att in self.discr_intervals[table]:
            intervals = self.discr_intervals[table][att]
            n_intervals = len(intervals)

            prev_value = None
            for i, value in enumerate(intervals):

                if i > 0:
                    prev_value = intervals[i - 1]

                if not prev_value and col <= value:
                    label = "'=<%.2f'" % value
                    break
                elif prev_value and col <= value:
                    label = "'(%.2f;%.2f]'" % (prev_value, value)
                    break
                elif col > value and i == n_intervals - 1:
                    label = "'>%.2f'" % value
                    break
        else:
            # For some reason using [ and ] crashes TreeLiker
            label = label.replace('[', 'I')
            label = label.replace(']', 'I')

        return label

def _discretize_check(self, table, att, col):
        """
        Replaces the value with an appropriate interval symbol, if available.
        """
        if att in self.discretize_dict:
            if col in self.discretize_dict[att]:
                if table[att] in self.discretize_dict[att][col]:
                    return self.discretize_dict[att][col][table[att]]
                else:
                    return table[att]
            else:
                return table[att]
        else:
            return table[att]

def deprecated(context):
    """Handle deprecated context input."""
    if context.get('deprecated'):
        return context['deprecated']
    return False

def _on_run(self):
        """ just loop and write responses """

        try:
            while True:
                try:
                    try:
                        cmd = self.cmdQueue.get(1, 0.1)
                    except _queue.Empty:
                        if self.killReceived:
                            try:
                                self.sock.shutdown(SHUT_WR)
                                self.sock.close()
                            except:
                                pass

                            return  # break if queue is empty and killReceived
                        else:
                            continue
                except:
                    # pydev_log.info('Finishing debug communication...(1)')
                    # when liberating the thread here, we could have errors because we were shutting down
                    # but the thread was still not liberated
                    return
                cmd.send(self.sock)

                if cmd.id == CMD_EXIT:
                    break
                if time is None:
                    break  # interpreter shutdown
                time.sleep(self.timeout)
        except Exception:
            GlobalDebuggerHolder.global_dbg.finish_debugging_session()
            if DebugInfoHolder.DEBUG_TRACE_LEVEL >= 0:
                pydev_log_exception()

def _on_run(self):
        """ just loop and write responses """
        while True:
            try:
                self.write_response()
            except Exception as e:
                self.logger.error(e)
                self.logger.error(traceback.format_exc())
                self.logger.error("Exiting...")
                break

def register_endpoint(self, path, app=None):
        """
        Register the metrics endpoint on the Flask application.

        :param path: the path of the endpoint
        :param app: the Flask application to register the endpoint on
            (by default it is the application registered with this class)
        """

        if is_running_from_reloader() and not os.environ.get('DEBUG_METRICS'):
            return

        if app is None:
            app = self.app or current_app

        @app.route(path)
        @self.do_not_track()
        def prometheus_metrics():
            # import these here so they don't clash with our own multiprocess module
            from prometheus_client import multiprocess, CollectorRegistry

            if 'prometheus_multiproc_dir' in os.environ:
                registry = CollectorRegistry()
            else:
                registry = self.registry

            if 'name[]' in request.args:
                registry = registry.restricted_registry(request.args.getlist('name[]'))

            if 'prometheus_multiproc_dir' in os.environ:
                multiprocess.MultiProcessCollector(registry)

            headers = {'Content-Type': CONTENT_TYPE_LATEST}
            return generate_latest(registry), 200, headers

def has_antibnd_states_below_efermi(self, spin=None, limit=0.01):
        """
        Returns dict indicating if there are antibonding states below the Fermi level depending on the spin
            spin: Spin
            limit: -COHP smaller -limit will be considered.

        """
        warnings.warn("This method has not been tested on many examples. Check the parameter limit, pls!")

        populations = self.cohp
        number_energies_below_efermi = len([x for x in self.energies if x <= self.efermi])

        if populations is None:
            return None
        elif spin is None:
            dict_to_return = {}
            for spin, cohpvalues in populations.items():
                if (max(cohpvalues[0:number_energies_below_efermi])) > limit:
                    dict_to_return[spin] = True
                else:
                    dict_to_return[spin] = False
        else:
            dict_to_return = {}
            if isinstance(spin, int):
                spin = Spin(spin)
            elif isinstance(spin, str):
                s = {"up": 1, "down": -1}[spin.lower()]
                spin = Spin(s)
            if (max(populations[spin][0:number_energies_below_efermi])) > limit:
                dict_to_return[spin] = True
            else:
                dict_to_return[spin] = False

        return dict_to_return

def has_antibnd_states_below_efermi(self, spin=None, limit=0.01):
        """
        Returns dict indicating if there are antibonding states below the Fermi level depending on the spin
            spin: Spin
            limit: -COHP smaller -limit will be considered.

        """
        if spin is None:
            spin = self.spin
        if spin == 'up':
            spin = 1
        elif spin == 'down':
            spin = 2
        else:
            raise ValueError('Spin must be either up or down')

        if self.has_cohp_data:
            if self.has_cohp_data_up and self.has_cohp_data_down:
                if spin == 1:
                    cohp_data = self.cohp_data_up
                elif spin == 2:
                    cohp_data = self.cohp_data_down
            else:
                raise ValueError('No cohp data for spin ' + str(spin))
        else:
            raise ValueError('No cohp data')

        if self.has_efermi:
            efermi = self.efermi
        else:
            raise ValueError('No Fermi level')

        antibnd_states = {}
        for i in range(len(cohp_data)):
            if cohp_data[i][0] < efermi:
                if cohp_data[i][1] < -limit:
                    antibnd_states[i] = cohp_data[i]

        return antibnd_states

