            for m in app['models']:
                if m['name'] == capfirst(model._meta.verbose_name_plural):
                    mod = '%s.%s' % (model.__module__, model.__name__)
                    model_list.append(mod)

    # if an app has registered its own dashboard, use it
    if app_label is not None and app_label in Registry.registry:
        return Registry.registry[app_label](app_title, model_list)

    # try to discover a general app_index dashboard (with fallback to the
    # default dashboard)
    return _get_dashboard_cls(getattr(
        settings,
        'ADMIN_TOOLS_APP_INDEX_DASHBOARD',
        'admin_tools.dashboard.dashboards.DefaultAppIndexDashboard'
    ), context)(app_title, model_list)

def get_app_index_dashboard(context):
    """
    Returns the admin dashboard defined by the user or the default one.
    """
    try:
        return context['request'].user.get_profile().app_index_dashboard
    except (AttributeError, KeyError):
        return 'default'

def extract_endpoints(api_module):
    """Return the endpoints from an API implementation module.

    The results returned by this are used to populate your HTTP layer's
    route handler, as well as by the documentation generator.
    """
    endpoints = []
    for name, obj in api_module.__dict__.items():
        if isinstance(obj, Endpoint):
            endpoints.append(obj)
    return endpoints

def _validate_indexers(self, key):
        """ Make sanity checks """
        for dim, k in zip(self.dims, key):
            if isinstance(k, BASIC_INDEXING_TYPES):
                pass
            else:
                if not isinstance(k, Variable):
                    k = np.asarray(k)
                    if k.ndim > 1:
                        raise IndexError(
                            "Unlabeled multi-dimensional array cannot be "
                            "used for indexing: {}".format(k))
                if k.dtype.kind == 'b':
                    if self.shape[self.get_axis_num(dim)] != len(k):
                        raise IndexError(
                            "Boolean array size {0:d} is used to index array "
                            "with shape {1:s}.".format(len(k),
                                                       str(self.shape)))
                    if k.ndim > 1:
                        raise IndexError("{}-dimensional boolean indexing is "
                                         "not supported. ".format(k.ndim))
                    if getattr(k, 'dims', (dim, )) != (dim, ):
                        raise IndexError(
                            "Boolean indexer should be unlabeled or on the "
                            "same dimension to the indexed array. Indexer is "
                            "on {0:s} but the target dimension is "
                            "{1:s}.".format(str(k.dims), dim))

def _validate_indexers(self, key):
        """ Make sanity checks """
        if not isinstance(key, tuple):
            raise TypeError("key must be a tuple")
        if len(key) != self.ndim:
            raise ValueError("key must be of length %d" % self.ndim)
        for i, k in enumerate(key):
            if not isinstance(k, slice):
                raise TypeError("key[%d] must be a slice" % i)

def comic_archive_uncompress(filename, image_format):
    """
    Uncompress comic archives.

    Return the name of the working directory we uncompressed into.
    """
    if not Settings.comics:
        report = ['Skipping archive file: {}'.format(filename)]
        return None, ReportStats(filename, report=report)

    if Settings.verbose:
        truncated_filename = stats.truncate_cwd(filename)
        print("Extracting {}...".format(truncated_filename), end='')

    # create the tmpdir
    tmp_dir = _get_archive_tmp_dir(filename)
    if os.path.isdir(tmp_dir):
        shutil.rmtree(tmp_dir)
    os.mkdir(tmp_dir)

    # extract archvie into the tmpdir
    if image_format == _CBZ_FORMAT:
        with zipfile.ZipFile(filename, 'r') as zfile:
            zfile.extractall(tmp_dir)
    elif image_format == _CBR_FORMAT:
        with rarfile.RarFile(filename, 'r') as rfile:
            rfile.extractall(tmp_dir)
    else:
        report = '{} {} is not a good format'.format(filename, image_format)
        return None, ReportStats(filename, report=report)

    if Settings.verbose:
        print('done')

    return tmp_dir, None

def comic_archive_uncompress(filename, image_format):
    """
    Uncompress comic archives.

    Return the name of the working directory we uncompressed into.
    """
    if filename.endswith('.zip'):
        return comic_archive_unzip(filename, image_format)
    elif filename.endswith('.rar'):
        return comic_archive_unrar(filename, image_format)
    elif filename.endswith('.7z'):
        return comic_archive_un7z(filename, image_format)
    else:
        raise ValueError('Unknown comic archive format: %s' % filename)

def run(self):
        """
        Load and start all available api modules
        """
        if not len(self.netapi):
            log.error("Did not find any netapi configurations, nothing to start")

        kwargs = {}
        if salt.utils.platform.is_windows():
            kwargs['log_queue'] = salt.log.setup.get_multiprocessing_logging_queue()
            kwargs['log_queue_level'] = salt.log.setup.get_multiprocessing_logging_level()

        for fun in self.netapi:
            if fun.endswith('.start'):
                log.info('Starting %s netapi module', fun)
                self.process_manager.add_process(
                    RunNetapi,
                    args=(self.opts, fun),
                    kwargs=kwargs,
                    name='RunNetapi'
                )

        # Install the SIGINT/SIGTERM handlers if not done so far
        if signal.getsignal(signal.SIGINT) is signal.SIG_DFL:
            # No custom signal handling was added, install our own
            signal.signal(signal.SIGINT, self._handle_signals)

        if signal.getsignal(signal.SIGTERM) is signal.SIG_DFL:
            # No custom signal handling was added, install our own
            signal.signal(signal.SIGTERM, self._handle_signals)

        self.process_manager.run()

def _get_input_schema(self):
        """Arbitrarily picks an object in input and reads the Avro schema from it."""
        if self.input_schema:
            return self.input_schema
        if not self.input_data:
            raise ValueError("No input data provided.")
        if isinstance(self.input_data, list):
            if not self.input_data:
                raise ValueError("No input data provided.")
            return self.input_data[0].schema
        return self.input_data.schema

def update_combobox(self):
        """Recreates the combobox contents."""
        index = self.current_scheme_index
        self.schemes_combobox.blockSignals(True)
        names = self.get_option("names")
        try:
            names.pop(names.index(u'Custom'))
        except ValueError:
            pass
        custom_names = self.get_option("custom_names", [])

        # Useful for retrieving the actual data
        for n in names + custom_names:
            self.scheme_choices_dict[self.get_option('{0}/name'.format(n))] = n

        if custom_names:
            choices = names + [None] + custom_names
        else:
            choices = names

        combobox = self.schemes_combobox
        combobox.clear()

        for name in choices:
            if name is None:
                continue
            combobox.addItem(self.get_option('{0}/name'.format(name)), name)

        if custom_names:
            combobox.insertSeparator(len(names))

        self.schemes_combobox.blockSignals(False)
        self.schemes_combobox.setCurrentIndex(index)

def is_in_range(self, values, unit=None, raise_exception=True):
        """Check if a list of values is within physically/mathematically possible range.

        Args:
            values: A list of values.
            unit: The unit of the values.  If not specified, the default metric
                unit will be assumed.
            raise_exception: Set to True to raise an exception if not in range.
        """
        self._is_numeric(values)
        if unit is None or unit == self.units[0]:
            minimum = self.min
            maximum = self.max
        else:
            namespace = {'self': self}
            self.is_unit_acceptable(unit, True)
            min_statement = "self._{}_to_{}(self.min)".format(
                self._clean(self.units[0]), self._clean(unit))
            max_statement = "self._{}_to_{}(self.max)".format(
                self._clean(self.units[0]), self._clean(unit))
            minimum = eval(min_statement, namespace)
            maximum = eval(max_statement, namespace)

        for value in values:
            if value < minimum or value > maximum:
                if not raise_exception:
                    return False
                else:
                    raise ValueError(
                        '{0} should be between {1} and {2}. Got {3}'.format(
                            self.__class__.__name__, self.min, self.max, value
                        )
                    )
        return True

def is_in_range(self, values, unit=None, raise_exception=True):
        """Check if a list of values is within physically/mathematically possible range.

        Args:
            values: A list of values.
            unit: The unit of the values.  If not specified, the default metric
                unit will be assumed.
            raise_exception: Set to True to raise an exception if not in range.
        """
        if unit is None:
            unit = self.default_unit
        if not isinstance(values, list):
            values = [values]
        for value in values:
            if not self.is_in_range_single(value, unit, raise_exception):
                return False
        return True

def launchBrowser(url, brow_bin='mozilla', subj=None):
    """ Given a URL, try to pop it up in a browser on most platforms.
    brow_bin is only used on OS's where there is no "open" or "start" cmd.
    """
    if subj is None:
        subj = url
    if sys.platform == 'darwin':
        os.system('open %s' % url)
    elif sys.platform == 'win32':
        os.system('start %s' % url)
    elif sys.platform == 'linux2':
        if os.path.exists(brow_bin):
            os.system('%s %s' % (brow_bin, url))
        else:
            os.system('xdg-open %s' % url)
    else:
        os.system('xdg-open %s' % url)
    return subj

def fetch(self, _filter=None, ignore_incremental=False):
        """ Fetch the items from raw or enriched index. An optional _filter
        could be provided to filter the data collected """
        if self.raw_index:
            return self.fetch_from_raw_index(_filter, ignore_incremental)
        else:
            return self.fetch_from_enriched_index(_filter, ignore_incremental)

def enc_setup(self, enc_alg, msg, auth_data=b'', key=None, iv=""):
        """ Encrypt JWE content.

        :param enc_alg: The JWE "enc" value specifying the encryption algorithm
        :param msg: The plain text message
        :param auth_data: Additional authenticated data
        :param key: Key (CEK)
        :return: Tuple (ciphertext, tag), both as bytes
        """
        if key is None:
            key = self.key
        if iv == "":
            iv = self.iv
        if enc_alg == "A128CBC-HS256":
            return self.enc_a128cbc_hs256(msg, key, iv, auth_data)
        elif enc_alg == "A192CBC-HS384":
            return self.enc_a192cbc_hs384(msg, key, iv, auth_data)
        elif enc_alg == "A256CBC-HS512":
            return self.enc_a256cbc_hs512(msg, key, iv, auth_data)
        elif enc_alg == "A128GCM":
            return self.enc_a128gcm(msg, key, iv, auth_data)
        elif enc_alg == "A192GCM":
            return self.enc_a192gcm(msg, key, iv, auth_data)
        elif enc_alg == "A256GCM":
            return self.enc_a256gcm(msg, key, iv, auth_data)
        else:
            raise ValueError("Unsupported encryption algorithm")

def validateSignal(self, policy=None):
        """
        Validates that this view is part of the group that was emitting
        the signal.  Views that are not in any viewing group will accept
        all signals.

        :param      policy | <XView.SignalPolicy> || None

        :return     <bool>
        """
        if policy is None:
            return True

        if policy == XView.SignalPolicy.ALL:
            return True

        if policy == XView.SignalPolicy.GROUP:
            if self.viewingGroup is None:
                return False

            return self.viewingGroup.isSignalValid(self)

        if policy == XView.SignalPolicy.VIEW:
            if self.viewingGroup is None:
                return True

            return self.viewingGroup.isSignalValid(self)

        return False

def _handle_heartbeat(self, sender, data):
        """
        Handles a raw heart beat

        :param sender: Sender (address, port) tuple
        :param data: Raw packet data
        """
        if self.debug:
            print("[DEBUG] Heartbeat received from %s:%s" % sender)

        # Check if the sender is in the list of known clients
        if sender in self.clients:
            # Check if the client is still alive
            if self.clients[sender]["last_seen"] + self.heartbeat_timeout < time.time():
                # Remove the client from the list of known clients
                del self.clients[sender]
                if self.debug:
                    print("[DEBUG] Client %s:%s removed from list of known clients" % sender)

        # Check if the sender is not in the list of known clients
        if sender not in self.clients:
            # Add the client to the list of known clients
            self.clients[sender] = {"last_seen": time.time()}
            if self.debug:
                print("[DEBUG] Client %s:%s added to list of known clients" % sender)

        # Send a heartbeat back to the sender
        self.send_heartbeat(sender)

def convert_block_dicts_to_string(self, block_1st2nd, block_1st, block_2nd, block_3rd):
        """Takes into account whether we need to output all codon positions."""
        out = ""
        # We need 1st and 2nd positions
        if self.codon_positions in ['ALL', '1st-2nd']:
            for gene_code, seqs in block_1st2nd.items():
                out += '>{0}_1st-2nd\n----\n'.format(gene_code)
                for seq in seqs:
                    out += seq
        elif self.codon_positions == '1st':
            for gene_code, seqs in block_1st.items():
                out += '>{0}_1st\n----\n'.format(gene_code)
                for seq in seqs:
                    out += seq
        elif self.codon_positions == '2nd':
            for gene_code, seqs in block_2nd.items():
                out += '>{0}_2nd\n----\n'.format(gene_code)
                for seq in seqs:
                    out += seq

        # We also need 3rd positions
        if self.codon_positions in ['ALL', '3rd']:
            for gene_code, seqs in block_3rd.items():
                out += '\n>{0}_3rd\n----\n'.format(gene_code)
                for seq in seqs:
                    out += seq
        return out

def convert_block_dicts_to_string(self, block_1st2nd, block_1st, block_2nd, block_3rd):
        """Takes into account whether we need to output all codon positions."""
        if self.output_all_codons:
            return block_1st2nd + block_1st + block_2nd + block_3rd
        else:
            return block_1st2nd + block_1st + block_2nd

def _compute_bgid(self, bg=None):
        """Return a unique identifier for the background data"""
        if bg is None:
            bg = self._bgdata
        if isinstance(bg, qpimage.QPImage):
            # Single QPImage
            if "identifier" in bg:
                return bg["identifier"]
            else:
                data = [bg.amp, bg.pha]
                for key in sorted(list(bg.meta.keys())):
                    val = bg.meta[key]
                    data.append("{}={}".format(key, val))
                return hash_obj(data)
        elif (isinstance(bg, list) and
              isinstance(bg[0], qpimage.QPImage)):
            # List of QPImage
            data = []
            for bgii in bg:
                data.append(self._compute_bgid(bgii))
            return hash_obj(data)
        elif (isinstance(bg, SeriesData) and
              (len(bg) == 1 or
               len(bg) == len(self))):
            # DataSet
            return bg.identifier
        else:
            raise ValueError("Unknown background data type: {}".format(bg))

def _compute_bgid(self, bg=None):
        """Return a unique identifier for the background data"""
        if bg is None:
            bg = self.bg
        if bg is None:
            return None
        if isinstance(bg, str):
            return bg
        if isinstance(bg, dict):
            return tuple(sorted(bg.items()))
        if isinstance(bg, (list, tuple)):
            return tuple(sorted(bg))
        raise ValueError("Unknown type for background data: %s" % type(bg))

def cached(cache, key=keys.hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def _update_resource_view(self, log=False):
        # type: () -> bool
        """Check if resource view exists in HDX and if so, update resource view

        Returns:
            bool: True if updated and False if not
        """
        update = False
        if 'id' in self.data and self._load_from_hdx('resource view', self.data['id']):
            update = True
        else:
            if 'resource_id' in self.data:
                resource_views = self.get_all_for_resource(self.data['resource_id'])
                for resource_view in resource_views:
                    if self.data['title'] == resource_view['title']:
                        self.old_data = self.data
                        self.data = resource_view.data
                        update = True
                        break
        if update:
            if log:
                logger.warning('resource view exists. Updating %s' % self.data['id'])
            self._merge_hdx_update('resource view', 'id')
        return update

def _update_resource_view(self, log=False):
        # type: () -> bool
        """Check if resource view exists in HDX and if so, update resource view

        Returns:
            bool: True if updated and False if not
        """
        if self.resource_view_id:
            if log:
                self.log.info(
                    "Updating resource view {}".format(self.resource_view_id)
                )
            try:
                resource_view = self.hdx_service.update_resource_view(
                    self.resource_view_id, self.resource_view_dict
                )
                if log:
                    self.log.info(
                        "Updated resource view {}".format(self.resource_view_id)
                    )
                return True
            except HDXError as e:
                if log:
                    self.log.error(
                        "Error updating resource view {}".format(
                            self.resource_view_id
                        )
                    )
                self.log.error(e)
                return False
        else:
            if log:
                self.log.info(
                    "Creating resource view {}".format(self.resource_view_id)
                )
            try:
                resource_view = self.hdx_service.create_resource_view(
                    self.resource_view_dict
                )
                if log:
                    self.log.info(
                        "Created resource view {}".format(self.resource_view_id)
                    )
                return True
            except HDXError as e:
                if log:
                    self.log.error(
                        "Error creating resource view {}".format(
                            self.resource_view_id
                        )
                    )
                self.log.error(e)
                return False

def parse_cldr_json(directory, language_codes=DEFAULT_LANGUAGE_CODES,
                    massage=True):
    """Parse CLDR JSON datasets to for date time things."""
    data = {}
    for language_code in language_codes:
        data[language_code] = {}
        for filename in os.listdir(directory):
            if filename.endswith('.json'):
                with open(os.path.join(directory, filename)) as f:
                    data[language_code][filename[:-5]] = json.load(f)
    if massage:
        data = massage_data(data)
    return data

def _build_msg_content(self, msgtype='text', **kwargs):
        """
        构造消息内容

        :param content: 消息内容，最长不超过2048个字节
        :param msgtype: 消息类型，可以为text/image/voice/video/file/textcard/news/mpnews/markdown
        :param kwargs: 具体消息类型的扩展参数
