def _build_msg_content(self, msgtype='text', **kwargs):
        """
        构造消息内容

        :param content: 消息内容，最长不超过2048个字节
        :param msgtype: 消息类型，可以为text/image/voice/video/file/textcard/news/mpnews/markdown
        :param kwargs: 具体消息类型的扩展参数
        :return:
        """
        if msgtype == 'text':
            return {
                'msgtype': msgtype,
                'text': kwargs
            }
        elif msgtype == 'image':
            return {
                'msgtype': msgtype,
                'image': kwargs
            }
        elif msgtype == 'voice':
            return {
                'msgtype': msgtype,
                'voice': kwargs
            }
        elif msgtype == 'video':
            return {
                'msgtype': msgtype,
                'video': kwargs
            }
        elif msgtype == 'file':
            return {
                'msgtype': msgtype,
                'file': kwargs
            }
        elif msgtype == 'textcard':
            return {
                'msgtype': msgtype,
                'textcard': kwargs
            }
        elif msgtype == 'news':
            return {
                'msgtype': msgtype,
                'news': kwargs
            }
        elif msgtype == 'mpnews':
            return {
                'msgtype': msgtype,
                'mpnews': kwargs
            }
        elif msgtype == 'markdown':
            return {
                'msgtype': msgtype,
                'markdown': kwargs
            }
        else:
            raise ValueError('msgtype must be text/image/voice/video/file/textcard/news/mpnews/markdown')

async def discover_slave(self, service, timeout, **kwargs):
        """Perform Slave discovery for specified service."""
        return self.discover_service(service, timeout, **kwargs)

def strip_tree(node,
               # Runtime optimization
               iter_node=iter_node, special=ast.AST,
               list=list, isinstance=isinstance, type=type, len=len):
    """Strips an AST by removing all attributes not in _fields.

    Returns a set of the names of all attributes stripped.

    This canonicalizes two trees for comparison purposes.
    """
    if isinstance(node, special):
        return node
    if isinstance(node, list):
        return [strip_tree(n, iter_node, special, list, isinstance, type, len)
                for n in node]
    if isinstance(node, type(node)):
        return type(node)(
            *[strip_tree(n, iter_node, special, list, isinstance, type, len)
              for n in iter_node(node)])
    return node

def _find_init_change(name, ret, **kwargs):
    """
    look for changes from any previous init of machine.

    :return: modified ret and kwargs
    """
    kwargs = salt.utils.args.clean_kwargs(**kwargs)
    if 'vm' in kwargs:
        kwargs.update(kwargs.pop('vm'))
    # the state processing eats 'runas' so we rename
    kwargs['runas'] = kwargs.pop('vagrant_runas', '')
    try:
        vm_ = __salt__['vagrant.get_vm_info'](name)
    except SaltInvocationError:
        vm_ = {}
        for key, value in kwargs.items():
            ret['changes'][key] = {'old': None, 'new': value}
    if vm_:  # test for changed values
        for key in vm_:
            value = vm_[key] or ''  # supply a blank if value is None
            if key != 'name':  # will be missing in kwargs
                new = kwargs.get(key, '')
                if new != value:
                    if key == 'machine' and new == '':
                        continue  # we don't know the default machine name
                    ret['changes'][key] = {'old': value, 'new': new}
    return ret, kwargs

def _find_init_change(name, ret, **kwargs):
    """
    look for changes from any previous init of machine.

    :return: modified ret and kwargs
    """
    if __opts__["test"]:
        return ret, kwargs

    if not __salt__["mc_cloud.is_vm_running"](name):
        return ret, kwargs

    if not __salt__["mc_cloud.is_vm_init"](name):
        return ret, kwargs

    if __salt__["mc_cloud.is_vm_init_changed"](name):
        ret["changes"]["init"] = True
        ret["comment"] = "init changed"
        return ret, kwargs

    return ret, kwargs

def aesCCM(key, key_handle, nonce, data, decrypt=False):
    """
    Function implementing YubiHSM AEAD encrypt/decrypt in software.
    """
    if decrypt:
        (data, saved_mac) = _split_data(data, len(data) - pyhsm.defines.YSM_AEAD_MAC_SIZE)

    nonce = pyhsm.util.input_validate_nonce(nonce, pad = True)
    mac = _cbc_mac(key, key_handle, nonce, len(data))

    counter = _ctr_counter(key_handle, nonce, value = 0)
    ctr_aes = AES.new(key, AES.MODE_CTR, counter = counter.next)
    out = []
    while data:
        (thisblock, data) = _split_data(data, pyhsm.defines.YSM_BLOCK_SIZE)

        # encrypt/decrypt and CBC MAC
        if decrypt:
            aes_out = ctr_aes.decrypt(thisblock)
            mac.update(aes_out)
        else:
            mac.update(thisblock)
            aes_out = ctr_aes.encrypt(thisblock)

        out.append(aes_out)

    # Finalize MAC
    counter.value = 0
    mac.finalize(counter.pack())
    if decrypt:
        if mac.get() != saved_mac:
            raise pyhsm.exception.YHSM_Error('AEAD integrity check failed')
    else:
        out.append(mac.get())
    return ''.join(out)

def _get_deps(deps, tree_base, saltenv='base'):
    """
    Get include string for list of dependent rpms to build package
    """
    deps_list = ''
    if deps is None:
        return deps_list
    if not isinstance(deps, list):
        raise SaltInvocationError(
            '\'deps\' must be a Python list or comma-separated string'
        )
    for deprpm in deps:
        parsed = _urlparse(deprpm)
        depbase = os.path.basename(deprpm)
        dest = os.path.join(tree_base, depbase)
        if parsed.scheme:
            __salt__['cp.get_url'](deprpm, dest, saltenv=saltenv)
        else:
            shutil.copy(deprpm, dest)

        deps_list += ' {0}'.format(dest)

    return deps_list

def _get_deps(deps, tree_base, saltenv='base'):
    """
    Get include string for list of dependent rpms to build package
    """
    ret = ''
    for dep in deps:
        if dep in tree_base:
            ret += ' --include={0}'.format(dep)
        else:
            ret += ' --include={0}'.format(dep)
    return ret

def get_string(self, input_string):
        """
		Return string type user input
		"""

        if input_string in ('--input', '--outname', '--framework'):

            # was the flag set?
            try:
                index = self.args.index(input_string) + 1
            except ValueError:
                # it wasn't, so if it's required, exit
                if input_string in self.required:
                    print("\n {flag} is required".format(input_string))
                    print_short_help()
                    sys.exit(1)
                # it wasn't, if its optional, return the default
                else:
                    return None

                    # the flag was set, so check if a value was set, otherwise exit
            try:
                if self.args[index] in self.flags:
                    print("\n {flag} was set but a value was not specified".format(flag=input_string))
                    print_short_help()
                    sys.exit(1)
            except IndexError:
                print("\n {flag} was set but a value was not specified".format(input_string))
                print_short_help()
                sys.exit(1)

            # a value was set, so check and assign the appropriate value or exit
            if input_string == '--input':
                return os.path.abspath(self.args[index])
            elif input_string == '--outname':
                return format(self.args[index])

def get_string(self, input_string):
        """
		Return string type user input
		"""
        return str(input(input_string))

