def match(tgt, delimiter=DEFAULT_TARGET_DELIM, opts=None):
    """
    Matches a grain based on regex
    """
    if not opts:
        opts = __opts__
    log.debug('grains pcre target: %s', tgt)
    if delimiter not in tgt:
        log.error('Got insufficient arguments for grains pcre match '
                  'statement from master')
        return False

    return salt.utils.data.subdict_match(
        opts['grains'], tgt, delimiter=delimiter, regex_match=True)

def match(tgt, delimiter=DEFAULT_TARGET_DELIM, opts=None):
    """
    Matches a grain based on regex
    """
    if not tgt:
        return False
    if delimiter not in tgt:
        return False
    if not opts:
        opts = {}
    if "match" not in opts:
        opts["match"] = True
    if "delimiter" not in opts:
        opts["delimiter"] = delimiter
    if "regex" not in opts:
        opts["regex"] = True
    if "ignorecase" not in opts:
        opts["ignorecase"] = True
    if "flags" not in opts:
        opts["flags"] = 0
    if opts["ignorecase"]:
        opts["flags"] |= re.IGNORECASE
    if opts["regex"]:
        regex = re.compile(tgt, opts["flags"])
    else:
        regex = re.compile(re.escape(tgt), opts["flags"])
    if opts["match"]:
        return regex.match(opts["delimiter"])
    else:
        return regex.search(opts["delimiter"])

def generate(self, nameformat=None, capitalize=None, formatters=None, **kwargs):
        """Pick a random name form a specified list of name parts"""

        nameformat = nameformat or self.nameformat
        capitalize = capitalize or self.capitalize
        formatters = formatters or {}

        lines = self._get_lines(kwargs)
        names = dict((k, v['name']) for k, v in list(lines.items()))

        if capitalize:
            names = dict((k, n.capitalize()) for k, n in list(names.items()))

        merged_formatters = dict()

        try:
            merged_formatters = dict(
                (k, self.formatters.get(k, []) + formatters.get(k, [])) for k in set(list(self.formatters.keys()) + list(formatters.keys()))
            )
        except AttributeError:
            raise TypeError("keyword argument 'formatters' for Censusname.generate() must be a dict")

        if merged_formatters:
            for key, functions in list(merged_formatters.items()):
                # 'surname', [func_a, func_b]
                for func in functions:
                    # names['surname'] = func_a(name['surname'])
                    names[key] = func(names[key])

        return nameformat.format(**names)

def generate(self, nameformat=None, capitalize=None, formatters=None, **kwargs):
        """Pick a random name form a specified list of name parts"""
        if nameformat is None:
            nameformat = self.nameformat
        if capitalize is None:
            capitalize = self.capitalize
        if formatters is None:
            formatters = self.formatters
        if not isinstance(nameformat, list):
            nameformat = [nameformat]
        if not isinstance(capitalize, list):
            capitalize = [capitalize]
        if not isinstance(formatters, list):
            formatters = [formatters]
        if len(nameformat) != len(capitalize):
            raise ValueError("nameformat and capitalize must be the same length")
        if len(nameformat) != len(formatters):
            raise ValueError("nameformat and formatters must be the same length")
        name = []
        for i in range(len(nameformat)):
            if formatters[i] is None:
                name.append(nameformat[i])
            else:
                name.append(formatters[i](nameformat[i]))
        if capitalize[0]:
            name[0] = name[0].capitalize()
        if capitalize[1]:
            name[1] = name[1].capitalize()
        if capitalize[2]:
            name[2] = name[2].capitalize()
        return " ".join(name)

def _post_build(self, module, encoding):
        """Handles encoding and delayed nodes after a module has been built"""
        module.file_encoding = encoding
        self._manager.cache_module(module)
        # post tree building steps after we stored the module in the cache:
        for from_node in module._import_from_nodes:
            if from_node.modname == "__future__":
                for symbol, _ in from_node.names:
                    module.future_imports.add(symbol)
            self.add_from_names_to_locals(from_node)
        # handle delayed assattr nodes
        for delayed in module._delayed_assattr:
            self.delayed_assattr(delayed)

        # Visit the transforms
        if self._apply_transforms:
            module = self._manager.visit_transforms(module)
        return module

def _post_build(self, module, encoding):
        """Handles encoding and delayed nodes after a module has been built"""
        if encoding is not None:
            self.encoding = encoding
        if self.delayed_nodes:
            self.delayed_nodes = []
            for node in self.nodes:
                if node.delayed:
                    self.delayed_nodes.append(node)
                    node.delayed = False

def scrape_file(self, file, encoding=None, base_url=None):
        """Scrape a file for links.

        See :meth:`scrape` for the return value.
        """
        if encoding is None:
            encoding = self.encoding
        if base_url is None:
            base_url = self.base_url
        return self.scrape(file.read(), encoding, base_url)

def export_to_dict(self, recursive=True, include_parent_ref=False,
                       include_defaults=False):
        """Export obj to dictionary"""
        cls = self.__class__
        parent_excludes = {}
        if recursive and not include_parent_ref:
            parent_ref = cls.__mapper__.relationships.get(cls.export_parent)
            if parent_ref:
                parent_excludes = {c.name for c in parent_ref.local_columns}
        dict_rep = {c.name: getattr(self, c.name)
                    for c in cls.__table__.columns
                    if (c.name in self.export_fields and
                        c.name not in parent_excludes and
                        (include_defaults or (
                            getattr(self, c.name) is not None and
                            (not c.default or
                                getattr(self, c.name) != c.default.arg))))
                    }
        if recursive:
            for c in self.export_children:
                # sorting to make lists of children stable
                dict_rep[c] = sorted(
                    [
                        child.export_to_dict(
                            recursive=recursive,
                            include_parent_ref=include_parent_ref,
                            include_defaults=include_defaults,
                        ) for child in getattr(self, c)
                    ],
                    key=lambda k: sorted(k.items()))

        return dict_rep

def export_to_dict(self, recursive=True, include_parent_ref=False,
                       include_defaults=False):
        """Export obj to dictionary"""
        if recursive:
            return self._export_to_dict(include_parent_ref, include_defaults)
        else:
            return self._export_to_dict_no_recursive(include_parent_ref,
                                                    include_defaults)

def add_mutex_switch(parser, dest, arguments=set(), default=None,
                         single_arg=False, required=False):
        """Adds mutually exclusive switch arguments.

        Args:
            arguments: a dictionary that maps switch name to helper text. Use
                sets to skip help texts.
        """

        if default is not None:
            assert default in arguments

        if isinstance(arguments, set):
            arguments = {k: None for k in arguments}

        if not single_arg:
            mg = parser.add_mutually_exclusive_group(required=required)

            for name, help_text in arguments.items():
                kwargs = {
                    "action": "store_const",
                    "dest": dest,
                    "const": name,
                    "help": help_text
                }

                if default == name:
                    kwargs["default"] = name

                mg.add_argument("--{}".format(name), **kwargs)

            return mg
        else:
            kwargs = {
                "dest": dest,
                "type": str,
                "default": default,
                "help": "\n".join("{}: {}".format(k, v)
                                  for k, v in arguments.items()),
                "choices": list(arguments.keys())
            }

            return parser.add_argument("--{}".format(dest), **kwargs)

def files_set_public_or_private(self, request, set_public, files_queryset, folders_queryset):
        """
        Action which enables or disables permissions for selected files and files in selected folders to clipboard (set them private or public).
        """

        if not self.has_change_permission(request):
            raise PermissionDenied

        if request.method != 'POST':
            return None

        check_files_edit_permissions(request, files_queryset)
        check_folder_edit_permissions(request, folders_queryset)

        # We define it like that so that we can modify it inside the set_files
        # function
        files_count = [0]

        def set_files(files):
            for f in files:
                if f.is_public != set_public:
                    f.is_public = set_public
                    f.save()
                    files_count[0] += 1

        def set_folders(folders):
            for f in folders:
                set_files(f.files)
                set_folders(f.children.all())

        set_files(files_queryset)
        set_folders(folders_queryset)

        if set_public:
            self.message_user(request, _("Successfully disabled permissions for %(count)d files.") % {
                "count": files_count[0],
            })
        else:
            self.message_user(request, _("Successfully enabled permissions for %(count)d files.") % {
                "count": files_count[0],
            })

        return None

def files_set_public_or_private(self, request, set_public, files_queryset, folders_queryset):
        """
        Action which enables or disables permissions for selected files and files in selected folders to clipboard (set them private or public).
        """
        if not files_queryset and not folders_queryset:
            return

        if set_public:
            self.set_public(request, files_queryset, folders_queryset)
        else:
            self.set_private(request, files_queryset, folders_queryset)

def retrieve(self, request, *args, **kwargs):
        """
        If the URL slug doesn't match an object, try slugifying the URL param
        and searching alt_url for that.
        If found, redirect to the canonical URL.
        If still not found, raise 404.
        """

        try:
            instance = self.get_object()
            serializer = self.get_serializer(instance)
            return Response(serializer.data)
        except Http404:
            pass

        lookup_url_kwarg = self.lookup_url_kwarg or self.lookup_field
        slug = self.kwargs[lookup_url_kwarg]

        # fall back to accession_temp_fallback
        try:
            tmp = get_object_or_404(
                self.queryset, accession_temp_fallback=slug)
            return HttpResponseRedirect(
                reverse(self.redirect_view_name, (tmp.slug, ))
            )
        except (Http404, FieldError):
            pass

        # fall back to embark ID
        try:
            embark = get_object_or_404(self.queryset, id=int(slug))
            return HttpResponseRedirect(
                reverse(self.redirect_view_name, (embark.slug, ))
            )
        except (Http404, ValueError):
            pass

        # fall back to alt slug
        try:
            from glamkit_collections.utils import alt_slugify
            alt_slug = alt_slugify(slug)
            alt = get_object_or_404(self.queryset, alt_slug=alt_slug)
            return HttpResponseRedirect(
                reverse(self.redirect_view_name, (alt.slug, ))
            )
        except Http404:
            pass

        # well, we tried
        raise Http404

def retrieve(self, request, *args, **kwargs):
        """
        If the URL slug doesn't match an object, try slugifying the URL param
        and searching alt_url for that.
        If found, redirect to the canonical URL.
        If still not found, raise 404.
        """
        try:
            return super(SlugOrURLMixin, self).retrieve(request, *args, **kwargs)
        except Http404:
            slug = kwargs.get('slug')
            url = request.query_params.get('url')
            if url:
                try:
                    obj = self.get_object()
                    if obj.alt_url == url:
                        return redirect(obj.get_absolute_url())
                except Http404:
                    pass
            raise Http404

def span_case(self, i, case):
        """Uppercase or lowercase the next range of characters until end marker is found."""

        # A new \L, \C or \E should pop the last in the stack.
        if self.span_stack:
            self.span_stack.pop()
        if self.single_stack:
            self.single_stack.pop()
        self.span_stack.append(case)
        count = len(self.span_stack)
        self.end_found = False
        try:
            while not self.end_found:
                t = next(i)
                if self.use_format and t in _CURLY_BRACKETS:
                    self.handle_format(t, i)
                elif t == '\\':
                    try:
                        t = next(i)
                        self.reference(t, i)
                    except StopIteration:
                        self.result.append(t)
                        raise
                else:
                    self.result.append(self.convert_case(t, case))
                if self.end_found or count > len(self.span_stack):
                    self.end_found = False
                    break
        except StopIteration:
            pass
        if count == len(self.span_stack):
            self.span_stack.pop()

def span_case(self, i, case):
        """Uppercase or lowercase the next range of characters until end marker is found."""
        if case == "upper":
            self.text[i:self.text.find("]]", i)] = self.text[i:self.text.find("]]", i)].upper()
        elif case == "lower":
            self.text[i:self.text.find("]]", i)] = self.text[i:self.text.find("]]", i)].lower()
        else:
            raise ValueError("Invalid case value.")

def play(self, name, streamUrl, encoding = ''):
        """ use a multimedia player to play a stream """
        if encoding == '':
            encoding = self.encoding
        if encoding == 'mp3':
            self.play_mp3(name, streamUrl)
        elif encoding == 'ogg':
            self.play_ogg(name, streamUrl)
        elif encoding == 'wav':
            self.play_wav(name, streamUrl)
        else:
            raise Exception('Unknown encoding: ' + encoding)

def parse_request(cls, sock):
    """Parse the request (the pre-execution) section of the nailgun protocol from the given socket.

    Handles reading of the Argument, Environment, Working Directory and Command chunks from the
    client which represents the "request" phase of the exchange. Working Directory and Command are
    required and must be sent as the last two chunks in this phase. Argument and Environment chunks
    are optional and can be sent more than once (thus we aggregate them).
    """

    command = None
    working_dir = None
    arguments = []
    environment = {}

    while not all((working_dir, command)):
      chunk_type, payload = cls.read_chunk(sock)

      if chunk_type == ChunkType.ARGUMENT:
        arguments.append(payload)
      elif chunk_type == ChunkType.ENVIRONMENT:
        key, val = payload.split(cls.ENVIRON_SEP, 1)
        environment[key] = val
      elif chunk_type == ChunkType.WORKING_DIR:
        working_dir = payload
      elif chunk_type == ChunkType.COMMAND:
        command = payload
      else:
        raise cls.ProtocolError('received non-request chunk before header was fully received!')

    return working_dir, command, arguments, environment

def login(self, username, password, application, application_url):
        """Login to anaconda cloud."""
