                                   application_url)

def _query_filter(search, urlkwargs, definitions):
    """Ingest query filter in query."""
    filters, urlkwargs = _create_filter_dsl(urlkwargs, definitions)

    for filter_ in filters:
        search = search.filter(filter_)

    return (search, urlkwargs)

def _query_filter(search, urlkwargs, definitions):
    """Ingest query filter in query."""
    if not search:
        return

    for key, value in search.items():
        if key not in definitions:
            raise ValueError(f"Invalid filter: {key}")

        if value is None:
            continue

        if definitions[key]["type"] == "string":
            urlkwargs[key] = value
        elif definitions[key]["type"] == "integer":
            urlkwargs[key] = int(value)
        elif definitions[key]["type"] == "boolean":
            urlkwargs[key] = value.lower() == "true"
        elif definitions[key]["type"] == "date":
            urlkwargs[key] = value
        elif definitions[key]["type"] == "enum":
            urlkwargs[key] = value
        elif definitions[key]["type"] == "list":
            urlkwargs[key] = value
        elif definitions[key]["type"] == "object":
            urlkwargs[key] = value
        else:
            raise ValueError(f"Invalid filter: {key}")

def get_group_list(value):
    """ group-list = mailbox-list / CFWS / obs-group-list
        obs-group-list = 1*([CFWS] ",") [CFWS]

    """
    if value.startswith('"'):
        return value
    else:
        return value.replace(',', '","')

def get_correctness_for_response(self, response):
        """get measure of correctness available for a particular response"""
        for answer in self.my_osid_object.get_answers():
            if self._is_match(response, answer):
                try:
                    return answer.get_score()
                except AttributeError:
                    return 100
        for answer in self.my_osid_object.get_wrong_answers():
            if self._is_match(response, answer):
                try:
                    return answer.get_score()
                except AttributeError:
                    return 0
        return 0

def get_correctness_for_response(self, response):
        """get measure of correctness available for a particular response"""
        if response.correct:
            return 1
        else:
            return 0

def _find_control_structure(self, start_address, search_length):
        """Find the control structure in RAM for this device.

        Returns:
            ControlStructure: The decoded contents of the shared memory control structure
                used for communication with this IOTile device.
        """

        words = self._read_memory(start_address, search_length, chunk_size=4, join=False)
        found_offset = None

        for i, word in enumerate(words):
            if word == ControlStructure.CONTROL_MAGIC_1:
                if (len(words) - i) < 4:
                    continue

                if words[i + 1] == ControlStructure.CONTROL_MAGIC_2 and words[i + 2] == ControlStructure.CONTROL_MAGIC_3 and words[i + 3] == ControlStructure.CONTROL_MAGIC_4:
                    found_offset = i
                    break

        if found_offset is None:
            raise HardwareError("Could not find control structure magic value in search area")

        struct_info = words[found_offset + 4]
        _version, _flags, length = struct.unpack("<BBH", struct.pack("<L", struct_info))

        if length % 4 != 0:
            raise HardwareError("Invalid control structure length that was not a multiple of 4", length=length)

        word_length = length // 4
        control_data = struct.pack("<%dL" % word_length, *words[found_offset:found_offset + word_length])

        logger.info("Found control stucture at address 0x%08X, word_length=%d", start_address + 4*found_offset, word_length)

        return ControlStructure(start_address + 4*found_offset, control_data)

def _unlock(self, closing=False):
        """Remove lock file to the target root folder.

        """
        # write("_unlock", closing)
        try:
            if self.cur_dir != self.root_dir:
                if closing:
                    write(
                        "Changing to ftp root folder to remove lock file: {}".format(
                            self.root_dir
                        )
                    )
                    self.cwd(self.root_dir)
                else:
                    write_error(
                        "Could not remove lock file, because CWD != ftp root: {}".format(
                            self.cur_dir
                        )
                    )
                    return

            if self.lock_data is False:
                if self.get_option("verbose", 3) >= 4:
                    write("Skip remove lock file (was not written).")
            else:
                # direct delete, without updating metadata or checking for target access:
                try:
                    self.ftp.delete(DirMetadata.LOCK_FILE_NAME)
                    # self.remove_file(DirMetadata.LOCK_FILE_NAME)
                except Exception as e:
                    # I have seen '226 Closing data connection' responses here,
                    # probably when a previous command threw another error.
                    # However here, 2xx response should be Ok(?):
                    # A 226 reply code is sent by the server before closing the
                    # data connection after successfully processing the previous client command
                    if e.args[0][:3] == "226":
                        write_error("Ignoring 226 response for ftp.delete() lockfile")
                    else:
                        raise

            self.lock_data = None
        except Exception as e:
            write_error("Could not remove lock file: {}".format(e))
            raise

def _unlock(self, closing=False):
        """Remove lock file to the target root folder.

        """
        if self.lock_file is None:
            return
        if closing:
            self.lock_file.close()
        os.remove(self.lock_file.name)
        self.lock_file = None

def updateParams(self, newvalues, update_all=False):
        """See docs for `Model` abstract base class."""
        assert all(map(lambda x: x in self.freeparams, newvalues.keys())),\
                "Invalid entry in newvalues: {0}\nfreeparams: {1}".format(
                ', '.join(newvalues.keys()), ', '.join(self.freeparams))
        changed = set([]) # contains string names of changed params
        for (name, value) in newvalues.items():
            _checkParam(name, value, self.PARAMLIMITS, self.PARAMTYPES)
            if isinstance(value, scipy.ndarray):
                if (value != getattr(self, name)).any():
                    changed.add(name)
                    setattr(self, name, value.copy())
            else:
                if value != getattr(self, name):
                    changed.add(name)
                    setattr(self, name, copy.copy(value))

        if update_all or changed:
            self._cached = {}

        # The order of the updating below is important.
        # If you change it, you may break either this class
        # **or** classes that inherit from it.
        # Note also that not all attributes need to be updated
        # for all possible parameter changes, but just doing it
        # this way is much simpler and adds negligible cost.
        if update_all or (changed and changed != set(['mu'])):
            self._update_Pxy()
            self._update_Pxy_diag()
            self._update_dPxy()
            self._update_B()

def updateParams(self, newvalues, update_all=False):
        """See docs for `Model` abstract base class."""
        if update_all:
            self.params = newvalues
        else:
            for key, value in newvalues.items():
                if key in self.params:
                    self.params[key] = value

def GET(self, courseid, taskid, path):  # pylint: disable=arguments-differ
        """ GET request """
        try:
            course = self.course_factory.get_course(courseid)
            if not self.user_manager.course_is_open_to_user(course):
                return self.template_helper.get_renderer().course_unavailable()

            path_norm = posixpath.normpath(urllib.parse.unquote(path))

            if taskid == "$common":
                public_folder = course.get_fs().from_subfolder("$common").from_subfolder("public")
            else:

                task = course.get_task(taskid)
                if not self.user_manager.task_is_visible_by_user(task):  # ignore LTI check here
                    return self.template_helper.get_renderer().task_unavailable()

                public_folder = task.get_fs().from_subfolder("public")
            (method, mimetype_or_none, file_or_url) = public_folder.distribute(path_norm, False)

            if method == "local":
                web.header('Content-Type', mimetype_or_none)
                return file_or_url
            elif method == "url":
                raise web.redirect(file_or_url)
            else:
                raise web.notfound()
        except web.HTTPError as error_or_redirect:
            raise error_or_redirect
        except:
            if web.config.debug:
                raise
            else:
                raise web.notfound()

def GET(self, courseid, taskid, path):  # pylint: disable=arguments-differ
        """ GET request """
        return self.get_task(courseid, taskid, path)

def set_extern (self, url):
        """
        Match URL against extern and intern link patterns. If no pattern
        matches the URL is extern. Sets self.extern to a tuple (bool,
        bool) with content (is_extern, is_strict).

        @return: None
        """
        if self.extern is not None:
            return

        if url.startswith('http://') or url.startswith('https://'):
            self.extern = (True, False)
        else:
            self.extern = (False, False)

        for pattern in self.intern_patterns:
            if pattern.match(url):
                self.extern = (False, True)
                break

        for pattern in self.extern_patterns:
            if pattern.match(url):
                self.extern = (True, True)
                break

def get_phi_comps_from_recfile(recfile):
    """read the phi components from a record file by iteration

    Parameters
    ----------
    recfile : str
        pest record file name

    Returns
    -------
    iters : dict
        nested dictionary of iteration number, {group,contribution}

    """
    iters = {}
    with open(recfile, 'r') as f:
        for line in f:
            if line.startswith('Iteration'):
                iters[int(line.split()[1])] = {}
            elif line.startswith('  Group'):
                iters[int(line.split()[1])][line.split()[2]] = {}
            elif line.startswith('    Contribution'):
                iters[int(line.split()[1])][line.split()[2]][line.split()[3]] = {}
            elif line.startswith('      Component'):
                iters[int(line.split()[1])][line.split()[2]][line.split()[3]][line.split()[4]] = {}
            elif line.startswith('        Value'):
                iters[int(line.split()[1])][line.split()[2]][line.split()[3]][line.split()[4]][line.split()[5]] = float(line.split()[6])
    return iters

def _replace_pg_hba(self):
        """
        Replace pg_hba.conf content in the PGDATA if hba_file is not defined in the
        `postgresql.parameters` and pg_hba is defined in `postgresql` configuration section.

        :returns: True if pg_hba.conf was rewritten.
        """

        # when we are doing custom bootstrap we assume that we don't know superuser password
        # and in order to be able to change it, we are opening trust access from a certain address
        if self._running_custom_bootstrap:
            addresses = {'': 'local'}
            if 'host' in self._local_address and not self._local_address['host'].startswith('/'):
                for _, _, _, _, sa in socket.getaddrinfo(self._local_address['host'], self._local_address['port'],
                                                         0, socket.SOCK_STREAM, socket.IPPROTO_TCP):
                    addresses[sa[0] + '/32'] = 'host'

            with open(self._pg_hba_conf, 'w') as f:
                f.write(self._CONFIG_WARNING_HEADER)
                for address, t in addresses.items():
                    f.write((
                        '{0}\treplication\t{1}\t{3}\ttrust\n'
                        '{0}\tall\t{2}\t{3}\ttrust\n'
                    ).format(t, self._replication['username'], self._superuser.get('username') or 'all', address))
        elif not self._server_parameters.get('hba_file') and self.config.get('pg_hba'):
            with open(self._pg_hba_conf, 'w') as f:
                f.write(self._CONFIG_WARNING_HEADER)
                for line in self.config['pg_hba']:
                    f.write('{0}\n'.format(line))
            return True

def reply_to_mentions(self):
        """
        For every mention since since_id, create a message with the provider and use it to
        reply to the mention
        :return: Number of mentions processed
        """
        mentions = self.get_mentions()
        if not mentions:
            return 0

        for mention in mentions:
            if mention.id < self.since_id:
                continue

            if mention.id > self.until_id:
                break

            self.since_id = mention.id
            self.until_id = mention.id

            message = self.get_message(mention.id)
            if not message:
                continue

            if not message.text:
                continue

            if not message.text.startswith(self.prefix):
                continue

            provider = message.text[len(self.prefix):]
            if not provider:
                continue

            if provider not in self.providers:
                continue

            self.reply_to_mention(mention, provider)

        return len(mentions)

def _line(self, text, indent=0):
        """Write 'text' word-wrapped at self.width characters."""
        if indent:
            text = ' ' * indent + text
        self.write(text)

def supported_currencies(self, project='moneywagon', level="full"):
        """
        Returns a list of all currencies that are supported by the passed in project.
        and support level. Support level can be: "block", "transaction", "address"
        or "full".
        """
        ret = []
        if project == 'multiexplorer-wallet':
            for currency, data in self.sorted_crypto_data:
                if not data.get("bip44_coin_type"):
                    continue
                if len(data.get('services', {}).get("push_tx", [])) < 1:
                    continue
                if len(data.get('services', {}).get("historical_transactions", [])) < 1:
                    continue
                if len(data.get('services', {}).get("single_transaction", [])) < 1:
                    continue
                if len(data.get('services', {}).get("unspent_outputs", [])) < 1:
                    continue
                ret.append(currency)

            altcore_tx = self.supported_currencies('altcore', level="transaction")
            return [x for x in ret if x in altcore_tx]

        for symbol, data in self.sorted_crypto_data:
            if symbol == '': # template
                continue
            if self.is_all_supported(data, project, level):
                ret.append(symbol)
        return ret

def supported_currencies(self, project='moneywagon', level="full"):
        """
        Returns a list of all currencies that are supported by the passed in project.
        and support level. Support level can be: "block", "transaction", "address"
        or "full".
        """
        if level not in ["block", "transaction", "address", "full"]:
            raise ValueError("Support level must be one of: block, transaction, address, full")
        if level == "full":
            level = "address"
        return self.get_request(
            "/projects/{project}/currencies?level={level}".format(
                project=project, level=level
            )
        )

