            ax.set_ylabel(dos_label)

def process_request(self, request):
        """
        Checks whether the page is already cached and returns the cached
        version if available.
        """
        if request.method == 'GET':
            cache_key = self.get_cache_key(request)
            if cache_key is None:
                return None
            response = self.cache.get(cache_key)
            if response is None:
                return None
            if self.cache_timeout is not None:
                self.cache.set(cache_key, response, self.cache_timeout)
            return response
        else:
            return None

def _normalize_orders(self):
        """Helper:  adjust orders based on cursors, where clauses."""
        orders = list(self._orders)
        _has_snapshot_cursor = False

        if self._start_at:
            if isinstance(self._start_at[0], document.DocumentSnapshot):
                _has_snapshot_cursor = True

        if self._end_at:
            if isinstance(self._end_at[0], document.DocumentSnapshot):
                _has_snapshot_cursor = True

        if _has_snapshot_cursor:
            should_order = [
                _enum_from_op_string(key)
                for key in _COMPARISON_OPERATORS
                if key not in (_EQ_OP, "array_contains")
            ]
            order_keys = [order.field.field_path for order in orders]
            for filter_ in self._field_filters:
                field = filter_.field.field_path
                if filter_.op in should_order and field not in order_keys:
                    orders.append(self._make_order(field, "ASCENDING"))
            if not orders:
                orders.append(self._make_order("__name__", "ASCENDING"))
            else:
                order_keys = [order.field.field_path for order in orders]
                if "__name__" not in order_keys:
                    direction = orders[-1].direction  # enum?
                    orders.append(self._make_order("__name__", direction))

        return orders

def _normalize_orders(self):
        """Helper:  adjust orders based on cursors, where clauses."""
        if self.cursor_mark:
            self.orders = [
                (self.cursor_mark, self.cursor_direction)
            ] + self.orders
        if self.where:
            self.orders = [
                (self.where, self.cursor_direction)
            ] + self.orders

def ensembl_request(self, ext, headers):
        """ obtain sequence via the ensembl REST API
        """

        self.attempt += 1
        if self.attempt > 5:
            raise ValueError("too many attempts, figure out why its failing")

        response, status, requested_headers = self.open_url(self.server + ext, headers=headers)

        # we might end up passing too many simultaneous requests, or too many
        # requests per hour, just wait until the period is finished before
        # retrying
        if status == 429:
            if "retry-after" in requested_headers:
                time.sleep(float(requested_headers["retry-after"]))
            elif "x-ratelimit-reset" in requested_headers:
                time.sleep(int(requested_headers["x-ratelimit-reset"]))

            return self.ensembl_request(ext, headers)
        # retry after 30 seconds if we get service unavailable error
        elif status in [500, 503, 504]:
            time.sleep(30)
            return self.ensembl_request(ext, headers)
        elif status != 200:
            raise ValueError("Invalid Ensembl response for {}\nheaders: {}\nresponse: {}".format(\
                    self.server + ext, requested_headers, response))

        # sometimes ensembl returns odd data. I don't know what it is, but the
        # json interpreter can't handle it. Rather than trying to catch it,
        # simply re-request the data
        if requested_headers["content-type"] == "application/json":
            try:
                json.loads(response)
            except ValueError:
                now = time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime())
                logging.warning("{}\t{}\t{}\t{}\t{}".format(now,
                    status, self.server + ext,
                    "cannot obtain json output"))
                return self.ensembl_request(ext, requested_headers)

        self.cache.cache_url_data(self.server + ext, response)

        return response

def ensembl_request(self, ext, headers):
        """ obtain sequence via the ensembl REST API
        """
        url = self.ensembl_url + ext
        try:
            response = requests.get(url, headers=headers)
            if response.status_code == 200:
                return response.text
            else:
                raise Exception("Error: %s" % response.status_code)
        except Exception as e:
            raise Exception("Error: %s" % e)

def lower_backtrack_blocks(match_query, location_types):
    """Lower Backtrack blocks into (QueryRoot, MarkLocation) pairs of blocks."""
    blocks = []
    for block in match_query.blocks:
        if block.type == 'Backtrack':
            blocks.append((match_query.root, block.location))
        else:
            blocks.append(block)
    return blocks

def is_method(arg, min_arity=None, max_arity=None):
    """Check if argument is a method.

    Optionally, we can also check if minimum or maximum arities
    (number of accepted arguments) match given minimum and/or maximum.
    """
    if not callable(arg):
        return False

    if not any(is_(arg) for is_ in (inspect.ismethod,
                                    inspect.ismethoddescriptor,
                                    inspect.isbuiltin)):
        return False

    try:
        argnames, varargs, kwargs, defaults = getargspec(arg)
    except TypeError:
        # On CPython 2.x, built-in methods of file aren't inspectable,
        # so if it's file.read() or file.write(), we can't tell it for sure.
        # Given how this check is being used, assuming the best is probably
        # all we can do here.
        return True
    else:
        if argnames and argnames[0] == 'self':
            argnames = argnames[1:]

    if min_arity is not None:
        actual_min_arity = len(argnames) - len(defaults or ())
        assert actual_min_arity >= 0, (
            "Minimum arity of %r found to be negative (got %s)!" % (
                arg, actual_min_arity))
        if int(min_arity) != actual_min_arity:
            return False

    if max_arity is not None:
        actual_max_arity = sys.maxsize if varargs or kwargs else len(argnames)
        if int(max_arity) != actual_max_arity:
            return False

    return True

def is_method(arg, min_arity=None, max_arity=None):
    """Check if argument is a method.

    Optionally, we can also check if minimum or maximum arities
    (number of accepted arguments) match given minimum and/or maximum.
    """
    if not isinstance(arg, MethodType):
        return False
    if min_arity is not None and arg.arity < min_arity:
        return False
    if max_arity is not None and arg.arity > max_arity:
        return False
    return True

