    elif s == 'excel-comma-space-tab':
        return excel.excel_comma_space_tab
    elif s == 'excel-comma-space-semicolon':
        return excel.excel_comma_space_semicolon
    elif s == 'excel-comma-space-semicolon-tab':
        return excel.excel_comma_space_semicolon_tab
    elif s == 'excel-comma-space-semicolon-tab-comma':
        return excel.excel_comma_space_semicolon_tab_comma
    elif s == 'excel-comma-space-semicolon-tab-comma-semicolon':
