def cli(ctx, stage):
    """listen to push requests for src and pull requests from target (experimental)"""
    if stage == 'src':
        return ctx.run('git push origin HEAD:refs/for/master')
    elif stage == 'target':
        return ctx.run('git fetch origin')

def push(self, statsDict=None, prefix=None, path=None):
    """Push stat values out to Graphite."""
    if statsDict is None:
      statsDict = scales.getStats()
    prefix = prefix or self.prefix
    path = path or '/'

    for name, value in list(statsDict.items()):
      name = str(name)
      subpath = os.path.join(path, name)

      if self._pruned(subpath):
        continue

      if hasattr(value, '__call__'):
        try:
          value = value()
        except:                       # pylint: disable=W0702
          value = None
          log.exception('Error when calling stat function for graphite push')

      if hasattr(value, 'items'):
        self.push(value, '%s%s.' % (prefix, self._sanitize(name)), subpath)
      elif self._forbidden(subpath, value):
        continue

      if six.PY3:
        type_values = (int, float)
      else:
        type_values = (int, long, float)

      if type(value) in type_values and len(name) < 500:
        self.graphite.log(prefix + self._sanitize(name), value)

def push(self, statsDict=None, prefix=None, path=None):
    """Push stat values out to Graphite."""
    if not self.enabled:
        return

    if statsDict is None:
        statsDict = self.statsDict

    if prefix is None:
        prefix = self.prefix

    if path is None:
        path = self.path

    for key, value in statsDict.items():
        if isinstance(value, dict):
            self.push(value, prefix + key + '.', path + key + '.')
        else:
            self.push_value(prefix + key, value, path + key)

    self.statsDict = {}

    return

