    elif gflp_method == "GFPL4":
        gflp = GFPL4(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL5":
        gflp = GFPL5(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL6":
        gflp = GFPL6(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL7":
        gflp = GFPL7(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL8":
        gflp = GFPL8(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL9":
        gflp = GFPL9(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL10":
        gflp = GFPL10(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL11":
        gflp = GFPL11(scale=scale, normalize=normalize, smoothing=smoothing)
    elif gflp_method == "GFPL12":
        gflp = GF

def load(self):
        """ Method which loads data from the file
        """
        # pylint: disable=too-many-return-statements
        if not os.path.isdir(self.patch_path):
            raise OSError('EOPatch does not exist in path {} anymore'.format(self.patch_path))

        path = self.get_file_path()
        if not os.path.exists(path):
            raise OSError('Feature in path {} does not exist anymore'.format(path))

        file_formats = FileFormat.split_by_extensions(path)[1:]

        if not file_formats or file_formats[-1] is FileFormat.PICKLE:
            with open(path, "rb") as infile:
                data = pickle.load(infile)

                if isinstance(data, sentinelhub.BBox) and not hasattr(data, 'crs'):
                    return self._correctly_load_bbox(data, path)
                return data

        if file_formats[-1] is FileFormat.NPY:
            if self.mmap:
                return np.load(path, mmap_mode='r')
            return np.load(path)

        if file_formats[-1] is FileFormat.GZIP:
            if file_formats[-2] is FileFormat.NPY:
                return np.load(gzip.open(path))

            if len(file_formats) == 1 or file_formats[-2] is FileFormat.PICKLE:
                data = pickle.load(gzip.open(path))

                if isinstance(data, sentinelhub.BBox) and not hasattr(data, 'crs'):
                    return self._correctly_load_bbox(data, path, is_zipped=True)
                return data

        raise ValueError('Could not load data from unsupported file format {}'.format(file_formats[-1]))

def _getDirection(coord1, coord2):
    """
    Return the direction the line formed by the (x, y)
    points in `coord1` and `coord2`.
    """
    x1, y1 = coord1
    x2, y2 = coord2

    if x1 == x2 and y1 == y2:
        return None # two coordinates are the same.
    elif x1 == x2 and y1 > y2:
        return UP
    elif x1 == x2 and y1 < y2:
        return DOWN
    elif x1 > x2 and y1 == y2:
        return LEFT
    elif x1 < x2 and y1 == y2:
        return RIGHT

    slope = float(y2 - y1) / float(x2 - x1)

    # Figure out which quadrant the line is going in, and then
    # determine the closest direction by calculating the slope
    if x2 > x1 and y2 < y1: # up right quadrant
        if slope > -0.4142:
            return RIGHT # slope is between 0 and 22.5 degrees
        elif slope < -2.4142:
            return UP # slope is between 67.5 and 90 degrees
        else:
            return UPRIGHT # slope is between 22.5 and 67.5 degrees
    elif x2 > x1 and y2 > y1: # down right quadrant
        if slope > 2.4142:
            return DOWN
        elif slope < 0.4142:
            return RIGHT
        else:
            return DOWNRIGHT
    elif x2 < x1 and y2 < y1: # up left quadrant
        if slope < 0.4142:
            return LEFT
        elif slope > 2.4142:
            return UP
        else:
            return UPLEFT
    elif x2 < x1 and y2 > y1: # down left quadrant
        if slope < -2.4142:
            return DOWN
        elif slope > -0.4142:
            return LEFT
        else:
            return DOWNLEFT

def _getDirection(coord1, coord2):
    """
    Return the direction the line formed by the (x, y)
    points in `coord1` and `coord2`.
    """
    if coord1[0] == coord2[0]:
        return "vertical"
    elif coord1[1] == coord2[1]:
        return "horizontal"
    else:
        return "diagonal"

def _make_query_from_terms(self, terms, limit=None):
        """ Creates a query for dataset from decomposed search terms.

        Args:
            terms (dict or unicode or string):

        Returns:
            tuple of (TextClause, dict): First element is FTS query, second is parameters
                of the query. Element of the execution of the query is pair: (vid, score).

        """
        if isinstance(terms, basestring):
            terms = self.decompose_query(terms)

        if not terms:
            return None, None

        # TODO: add support for multiple fields
        field = terms.keys()[0]
        value = terms[field]

        if isinstance(value, basestring):
            value = [value]

        if not value:
            return None, None

        if isinstance(value, list):
            value = [unicode(v) for v in value]

        if isinstance(value, unicode):
            value = [value]

        if isinstance(value, list):
            value = [unicode(v) for v in value]

        if isinstance(value, list):
            value = [v.strip() for v in value]

        if not value:
            return None, None

        if len(value) == 1:
            value = value[0]

        if isinstance(value, unicode):
            value = [value]

        if isinstance(value, list):
            value = [v.strip() for v in value]

        if not value:
            return None, None

        if len(value) == 1:
            value = value[0]

        if isinstance(value, unicode):
            value = [value]

        if isinstance(value, list):
            value = [v.strip() for v in value]

        if not value:
            return None, None

        if len(value) == 1:
            value = value[0]

        if isinstance(value, unicode):
            value = [value]

        if isinstance(value, list):
            value = [v.strip() for v in value]

        if not value:
            return None, None

        if len(value) == 1:
            value = value[0]

        if isinstance(value, unicode):
            value = [value]

        if isinstance(value, list):
            value = [v.strip() for v in value]

        if not value:
            return

def PrependUnique(self, delete_existing=0, **kw):
        """Prepend values to existing construction variables
        in an Environment, if they're not already there.
        If delete_existing is 1, removes existing values first, so
        values move to front.
        """
        kw = copy_non_reserved_keywords(kw)
        for key, val in kw.items():
            if SCons.Util.is_List(val):
                val = _delete_duplicates(val, not delete_existing)
            if key not in self._dict or self._dict[key] in ('', None):
                self._dict[key] = val
            elif SCons.Util.is_Dict(self._dict[key]) and \
                 SCons.Util.is_Dict(val):
                self._dict[key].update(val)
            elif SCons.Util.is_List(val):
                dk = self._dict[key]
                if not SCons.Util.is_List(dk):
                    dk = [dk]
                if delete_existing:
                    dk = [x for x in dk if x not in val]
                else:
                    val = [x for x in val if x not in dk]
                self._dict[key] = val + dk
            else:
                dk = self._dict[key]
                if SCons.Util.is_List(dk):
                    # By elimination, val is not a list.  Since dk is a
                    # list, wrap val in a list first.
                    if delete_existing:
                        dk = [x for x in dk if x not in val]
                        self._dict[key] = [val] + dk
                    else:
                        if not val in dk:
                            self._dict[key] = [val] + dk
                else:
                    if delete_existing:
                        dk = [x for x in dk if x not in val]
                    self._dict[key] = val + dk
        self.scanner_map_delete(kw)

def PrependUnique(self, delete_existing=0, **kw):
        """Prepend values to existing construction variables
        in an Environment, if they're not already there.
        If delete_existing is 1, removes existing values first, so
        values move to front.
        """
        for k, v in kw.items():
            if k in self:
                if delete_existing:
                    self[k] = v
                else:
                    self[k] = v + self[k]
            else:
                self[k] = v

def _write_tree(self, tree: dict, output: Union[str, BinaryIO], file_mode: int=0o666) -> None:
        """
        Write the model to disk.

        :param tree: The data dict - will be the ASDF tree.
        :param output: The output file path or a file object.
        :param file_mode: The output file's permissions.
        :return: None
        """
        self.meta["created_at"] = get_datetime_now()
        meta = self.meta.copy()
        meta["environment"] = collect_environment()
        final_tree = {}
        final_tree.update(tree)
        final_tree["meta"] = meta
        isfileobj = not isinstance(output, str)
        if not isfileobj:
            self._source = output
            path = output
            output = open(output, "wb")
            os.chmod(path, file_mode)
            pos = 0
        else:
            pos = output.tell()
        try:
            with asdf.AsdfFile(final_tree) as file:
                queue = [("", tree)]
                while queue:
                    path, element = queue.pop()
                    if isinstance(element, dict):
                        for key, val in element.items():
                            queue.append((path + "/" + key, val))
                    elif isinstance(element, (list, tuple)):
                        for child in element:
                            queue.append((path, child))
                    elif isinstance(element, numpy.ndarray):
                        path += "/"
                        if path not in self._compression_prefixes:
                            self._log.debug("%s -> %s compression", path, self.ARRAY_COMPRESSION)
                            file.set_array_compression(element, self.ARRAY_COMPRESSION)
                        else:
                            self._log.debug("%s -> compression disabled", path)
                file.write_to(output)
            self._size = output.seek(0, os.SEEK_END) - pos
        finally:
            if not isfileobj:
                output.close()

def connect(self, frame, response=None):
        """
        Handle CONNECT command: Establishes a new connection and checks auth (if applicable).
        """
        if self.state != self.CONNECTING:
            raise ProtocolError("Invalid state: %s" % self.state)

        if response is None:
            response = self.read_frame()

        if response.command != 'CONNACK':
            raise ProtocolError("Expected CONNACK, got %s" % response.command)

        if response.code != 0:
            raise ConnectError(response.code)

        self.state = self.CONNECTED

        return response

